INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "血液是在心脏和血管中循环流动的红色液体，负责运输氧气、营养物质，并帮助排除废物、调节体温和防御疾病。", "primary_collocate": null, "pronunciation": "xuè yè", "ipa": "ɕɥɛ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "血液", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "心脏推动血液流向全身。", "target_word": "血液", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红细胞在血液里运送氧气。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生抽取了一些血液做检查。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "献血时，血液会流进专用的血袋里。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白细胞是血液中防御疾病的细胞。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动以后，血液流动得更快，身体也会变热。", "target_word": "血液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫血的人，血液里缺少红细胞。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "血液在血管里循环流动，不会停下来。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士正在检查他的血液里有没有细菌。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一滴血液", "label": "量词"}], "register": "书面", "sense_fingerprint": "血液|心脏血管中循环流动的红色液体，运输氧气营养、排除废物、防御疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是人体内循环的液体，不能进入脑部的血管。"}, {"text": "血液", "is_correct": true, "explanation": "正确：血液在血管中循环，能够流入脑部，与句中的冷却、热调控语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不会流进脑部，句中讲的是流动的液体。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“进入脑部的”后应接在体内循环的液体，颜料不能这样搭配。"}], "explanations": {"汽油": "语义：汽油不是人体内循环的液体，不能进入脑部的血管。", "血液": "正确：血液在血管中循环，能够流入脑部，与句中的冷却、热调控语境相合。", "石头": "语义：石头是固体，不会流进脑部，句中讲的是流动的液体。", "颜料": "搭配：“进入脑部的”后应接在体内循环的液体，颜料不能这样搭配。"}, "sentence_index": 0, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤口还在流血液。", "explanation": "这里应该用〈血〉。“流血”是固定说法，“血液”是书面的整体概念，不说“流血液”。"}, {"text": "医生抽了一条血液做检查。", "explanation": "量词：〈条〉用于细长的东西，血液是液体，应说“一管血液”或“一些血液”。"}, {"text": "他每天喝一杯血液补身体。", "explanation": "语义：血液在血管里循环，不是可以喝的饮品，“喝”与血液搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": false, "explanation": "语义：河水流动与运动后身体变热无关，而且不是人体内的液体。"}, {"text": "血液", "is_correct": true, "explanation": "正确：血液在运动时流动加快，身体也随之变热，与句意相合。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不能“流动得更快”而使身体变热，句意不通。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“流动”多用于液体、人群、资金，不说“公路流动”。"}], "explanations": {"河水": "语义：河水流动与运动后身体变热无关，而且不是人体内的液体。", "血液": "正确：血液在运动时流动加快，身体也随之变热，与句意相合。", "人口": "语义：人口不能“流动得更快”而使身体变热，句意不通。", "公路": "搭配：“流动”多用于液体、人群、资金，不说“公路流动”。"}, "sentence_index": 6, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血液很快就愈合了。", "explanation": "这里应该用〈伤口〉。“愈合”说的是伤口或皮肤，血液是液体，不会愈合。"}, {"text": "这家餐厅的招牌菜是血液。", "explanation": "语义：血液是人体里的液体，不是可以上桌的菜品，“招牌菜”与血液不搭。"}, {"text": "护士一个一个地数着他的血液。", "explanation": "语义：血液是液体，不能逐个计数，“一个一个地数”与血液搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士给他抽了一个血液做检查。", "corrected_sentence": "护士给他抽了一管血液做检查。", "error_description": "错误形式“一个血液”，正确形式“一管血液”。血液是液体，计量要用“管”“滴”等容器或份量词，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士抽了他的血液们去化验。", "corrected_sentence": "护士抽了他的血液去化验。", "error_description": "错误形式“血液们”，正确形式“血液”。“们”只附在指人的名词或代词后面，血液是物质名词，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
