INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下丘脑是大脑的一部分，负责调节体温、饥饿、口渴、情绪和激素分泌等基本生理功能。", "primary_collocate": null, "pronunciation": "xià qiū nǎo", "ipa": "ɕja˥˩ tɕʰjoʊ˥ naʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "当个体处于轻度认知疲劳状态时，大脑的代谢活动减缓，局部温度可能轻微上升，而深长的哈欠通过促进大量空气流经鼻腔与口腔，能够有效冷却进入脑部的血液，从而实现对下丘脑等关键区域的热调控。", "target_word": "下丘脑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "下丘脑位于大脑的底部。", "target_word": "下丘脑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下丘脑能调节体温，让身体不太冷也不太热。", "target_word": "下丘脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子饿了的感觉来自下丘脑。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑出了问题，人可能会一直很口渴。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑还能控制身体分泌激素。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查他的下丘脑有没有问题。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑很小，但它的作用很大。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人什么时候想睡觉，也和下丘脑有关。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情绪紧张时，下丘脑会让心跳变快。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下丘腦", "label": "繁体"}], "register": "书面", "sense_fingerprint": "下丘脑|大脑的一部分，调节体温、饥渴、情绪和激素分泌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哈欠", "is_correct": false, "explanation": "语义：哈欠是一种动作，不是可以进行热调控的区域，与“关键区域”不符。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：下丘脑是调节体温的脑区，与前文“热调控”的语境相合。"}, {"text": "激素", "is_correct": false, "explanation": "语义：激素是化学物质，不是区域，“对激素等关键区域的热调控”说不通。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液是体液，不是区域，不能说“血液等关键区域”。"}], "explanations": {"哈欠": "语义：哈欠是一种动作，不是可以进行热调控的区域，与“关键区域”不符。", "下丘脑": "正确：下丘脑是调节体温的脑区，与前文“热调控”的语境相合。", "激素": "语义：激素是化学物质，不是区域，“对激素等关键区域的热调控”说不通。", "血液": "语义：血液是体液，不是区域，不能说“血液等关键区域”。"}, "sentence_index": 0, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下丘脑由左右两个半球组成。", "explanation": "这里应该用〈大脑〉。左右两个半球指的是整个大脑；下丘脑只是大脑底部的一个小区域，不能这样说。"}, {"text": "下丘脑负责传递感觉信息。", "explanation": "这里应该用〈丘脑〉。传递感觉信息是丘脑的功能；下丘脑主要负责调节体温和饥饿。"}, {"text": "下丘脑分泌生长激素。", "explanation": "这里应该用〈脑垂体〉。生长激素由脑垂体分泌；下丘脑是释放激素来调控脑垂体，本身不分泌生长激素。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：医生检查的是身体，“天气”不是可以检查有没有问题的对象。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：“他的下丘脑”指人体器官，与“医生检查”的语境相合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：医生不检查作业，“检查他的作业”与医疗语境不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“检查”与医生搭配的对象是人体，“汽车”不能与之搭配。"}], "explanations": {"天气": "语义：医生检查的是身体，“天气”不是可以检查有没有问题的对象。", "下丘脑": "正确：“他的下丘脑”指人体器官，与“医生检查”的语境相合。", "作业": "语义：医生不检查作业，“检查他的作业”与医疗语境不符。", "汽车": "搭配：“检查”与医生搭配的对象是人体，“汽车”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体检报告显示，他的一只下丘脑有些异常。", "explanation": "这里应该用〈个〉。下丘脑是不成对的器官，“只”多用于动物或成对的器官。"}, {"text": "医生在图上指着一条下丘脑说明位置。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，下丘脑是块状结构，不能用“条”。"}, {"text": "老师在图上标出了一幅下丘脑的位置。", "explanation": "这里应该用〈个〉。“幅”用于画或图，下丘脑是器官，不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下丘脑在位于大脑底部附近。", "corrected_sentence": "下丘脑位于大脑底部附近。", "error_description": "错误形式“在位于”，正确形式“位于”。“位于”本身已包含处所意义，前面不能再加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在图上指出了这只下丘脑的位置。", "corrected_sentence": "医生在图上指出了这个下丘脑的位置。", "error_description": "错误形式“这只下丘脑”，正确形式“这个下丘脑”。下丘脑是不成对的器官，量词应用“个”，“只”多用于动物或成对的器官。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
