INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种电子设备，能够按照程序运行，自动处理数据，进行高速计算和逻辑运算。", "primary_collocate": null, "pronunciation": "jì suàn jī", "ipa": "tɕi˥˩ swan˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "这种机制类似于计算机的散热系统，在处理器过热时启动风扇以维持最佳运行状态。", "target_word": "计算机", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家有一台计算机。", "target_word": "计算机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "计算机可以很快地算出结果。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师用计算机处理大量数据。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计算机里的程序出错了，所以屏幕不动了。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计算机需要电才能工作。", "target_word": "计算机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台计算机的运算速度非常快。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校机房里有三十台计算机。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早期的计算机又大又重，占了一间房子。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计算机按照程序一步一步地处理数据。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台计算机", "label": "量词"}, {"form": "計算機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "计算机|按程序运行、自动处理数据、高速计算的电子设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园里没有处理器和风扇，不能类比为有散热系统的机制。"}, {"text": "计算机", "is_correct": true, "explanation": "正确：计算机有处理器和散热系统，与句中“处理器过热时启动风扇”的语境相合。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事没有散热系统，句子说的是一种机械或电子装置的散热机制。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体型特征，不是可以装风扇、启动散热的装置。"}], "explanations": {"花园": "语义：花园里没有处理器和风扇，不能类比为有散热系统的机制。", "计算机": "正确：计算机有处理器和散热系统，与句中“处理器过热时启动风扇”的语境相合。", "故事": "语义：故事没有散热系统，句子说的是一种机械或电子装置的散热机制。", "身高": "体貌：“身高”是人的体型特征，不是可以装风扇、启动散热的装置。"}, "sentence_index": 0, "correct_answer": "计算机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师用一只计算机处理大量数据。", "explanation": "这里应该用〈台〉。计算机是器械，量词用“台”；“只”多用于动物或成对的东西。"}, {"text": "工程师用一块计算机处理大量数据。", "explanation": "这里应该用〈台〉。“块”用于块状的东西，计算机是器械，应用“台”。"}, {"text": "工程师用一根计算机处理大量数据。", "explanation": "这里应该用〈台〉。“根”用于细长的东西，计算机不属于这类，应用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车的速度与“运算速度”无关，“汽车的运算速度”说不通。"}, {"text": "计算机", "is_correct": true, "explanation": "正确：“运算速度”是计算机的性能指标，与句中语境相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不做运算，不能说“冰箱的运算速度”。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”是外表特征，与“运算速度”没有关系。"}], "explanations": {"汽车": "语义：汽车的速度与“运算速度”无关，“汽车的运算速度”说不通。", "计算机": "正确：“运算速度”是计算机的性能指标，与句中语境相合。", "冰箱": "语义：冰箱不做运算，不能说“冰箱的运算速度”。", "相貌": "体貌：“相貌”是外表特征，与“运算速度”没有关系。"}, "sentence_index": 6, "correct_answer": "计算机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "计算机只能做加减乘除。", "explanation": "这里应该用〈计算器〉。只能做加减乘除是计算器的功能；计算机能按程序运行，处理数据并进行逻辑运算，不能这样限定。"}, {"text": "计算机靠拨动算珠来计数。", "explanation": "这里应该用〈算盘〉。靠拨动算珠来计数是算盘的工作方式；计算机是电子设备，按程序运行，没有算珠。"}, {"text": "计算机能播放节目，但不能处理数据。", "explanation": "这里应该用〈电视〉。播放节目是电视的功能；计算机能按程序自动处理数据，“不能处理数据”与它的功能相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校买了三只计算机。", "corrected_sentence": "我们学校买了三台计算机。", "error_description": "错误形式“三只计算机”，正确形式“三台计算机”。计算机是器械，量词用“台”，“只”用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把计算机关。", "corrected_sentence": "请把计算机关掉。", "error_description": "错误形式“请把计算机关”，正确形式“请把计算机关掉”。“把”字句中动词后通常要有补语（如“掉”“上”）说明结果，只说“关”不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
