INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "处理器是计算机中执行指令和处理数据的核心部件，负责运行程序和计算。", "primary_collocate": null, "pronunciation": "chǔ lǐ qì", "ipa": "ʈʂʰu˨˩˦ li˨˩˦ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这种机制类似于计算机的散热系统，在处理器过热时启动风扇以维持最佳运行状态。", "target_word": "处理器", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台电脑的处理器很快。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机用了更好的处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器太热，电脑会变慢。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买一个更快的处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩大型游戏需要好的处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器是电脑里最重要的部件。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个处理器是哪家公司做的？", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把新处理器装进了电脑。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器负责计算，内存负责存放数据。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "處理器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处理器：计算机中执行指令、处理数据的核心部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼠标", "is_correct": false, "explanation": "语义：鼠标不是运算核心，不会因运算而过热，句中指的是需要风扇降温的部件。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“过热”用于机器或设备，不能说纸过热。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘不负责运算，“过热时启动风扇”所针对的是运算核心，不是键盘。"}, {"text": "处理器", "is_correct": true, "explanation": "处理器：电脑中执行指令、负责运算的核心部件，运算时发热，需要风扇降温。"}], "explanations": {"鼠标": "语义：鼠标不是运算核心，不会因运算而过热，句中指的是需要风扇降温的部件。", "纸": "搭配：“过热”用于机器或设备，不能说纸过热。", "键盘": "语义：键盘不负责运算，“过热时启动风扇”所针对的是运算核心，不是键盘。", "处理器": "处理器：电脑中执行指令、负责运算的核心部件，运算时发热，需要风扇降温。"}, "sentence_index": 0, "correct_answer": "处理器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块处理器充满电要三个小时。", "explanation": "这里应该用〈电池〉。充电要靠电池，处理器是运算部件，不能充电。"}, {"text": "这个处理器有五百个G，存了很多文件。", "explanation": "这里应该用〈硬盘〉。存放文件要靠硬盘，处理器负责运算，不负责存放。"}, {"text": "这个处理器的屏幕很大，画面很清楚。", "explanation": "这里应该用〈显示器〉。屏幕和画面由显示器负责，处理器只负责运算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：说明书是印刷品，不是电脑的部件。"}, {"text": "包装盒", "is_correct": false, "explanation": "语义：包装盒不属于电脑内部，也谈不上“最重要”。"}, {"text": "螺丝钉", "is_correct": false, "explanation": "搭配：螺丝钉是小零件，不会被称为“最重要的部件”，与句中的判断不搭。"}, {"text": "处理器", "is_correct": true, "explanation": "处理器：电脑里执行指令、负责运算的核心部件，句中说它是最重要的部件。"}], "explanations": {"说明书": "语义：说明书是印刷品，不是电脑的部件。", "包装盒": "语义：包装盒不属于电脑内部，也谈不上“最重要”。", "螺丝钉": "搭配：螺丝钉是小零件，不会被称为“最重要的部件”，与句中的判断不搭。", "处理器": "处理器：电脑里执行指令、负责运算的核心部件，句中说它是最重要的部件。"}, "sentence_index": 6, "correct_answer": "处理器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "处理器负责存放数据，所以容量越大越好。", "explanation": "处理器负责计算，存放数据的容量由内存和硬盘决定，句中把它的功能说错了。"}, {"text": "他的工作是处理器，每天负责审核文件。", "explanation": "“处理器”是电脑中的部件，不能用来指人，句中把它当作职业名称，用法是错的。"}, {"text": "妈妈用处理器洗了一大堆衣服。", "explanation": "这里应该用〈洗衣机〉。处理器是电脑中执行运算的部件，不能用来洗衣服，洗衣要靠洗衣机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们换了一条更快的处理器，电脑运行快多了。", "corrected_sentence": "我们换了一个更快的处理器，电脑运行快多了。", "error_description": "量词错误：“处理器”应用“个”或“块”，“条”用于细长的东西，不能用于处理器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑换了一个的新处理器，速度快了很多。", "corrected_sentence": "这台电脑换了一个新处理器，速度快了很多。", "error_description": "结构错误：数量词“一个”与修饰语“新”之间不能加“的”，应说“一个新处理器”，不说“一个的新处理器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
