INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脑干是位于大脑下方、连接脊髓的神经组织，负责调节呼吸、心跳、血压等基本生命活动。", "primary_collocate": null, "pronunciation": "nǎo gàn", "ipa": "naʊ˨˩˦ kan˥˩", "syllable_count": 2, "sentences": [{"text": "其启动涉及脑干中的特定核团，尤其是孤束核与疑核，这些区域整合来自边缘系统、前扣带回皮层以及自主神经系统的信号。", "target_word": "脑干", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "脑干管呼吸和心跳。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，他的脑干受伤了。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑干在大脑的下面。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑干连着脊髓，能调节血压。", "target_word": "脑干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脑干出了问题，人就不能自己呼吸。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图上画出了人的脑干。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑干虽然很小，却很重要。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了脑干的模型。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉的时候，脑干还在工作。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "腦幹", "label": "繁体"}], "register": "书面", "sense_fingerprint": "连接脊髓、调节呼吸心跳的脑部结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脑干", "is_correct": true, "explanation": "脑干：核团所在的脑部结构，与“核团”搭配，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不是脑部结构。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，与神经核团无关。"}, {"text": "肝脏", "is_correct": false, "explanation": "搭配：“核团”多指神经系统中的结构，肝脏与之不搭。"}], "explanations": {"脑干": "脑干：核团所在的脑部结构，与“核团”搭配，符合句意。", "书包": "语义：书包是装书的袋子，不是脑部结构。", "花园": "语义：花园是种植花草的地方，与神经核团无关。", "肝脏": "搭配：“核团”多指神经系统中的结构，肝脏与之不搭。"}, "sentence_index": 0, "correct_answer": "脑干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑干很灵活，做题又快又准。", "explanation": "这里应该用〈头脑〉。“脑干”是脑的一部分，说人聪明、反应快要用“头脑”。"}, {"text": "他的脑干很发达，考试总是第一。", "explanation": "这里应该用〈大脑〉。“脑干”只指大脑下方的一部分，说大脑发达、聪明要用“大脑”。"}, {"text": "他不小心把脑干撞破了，流了很多血。", "explanation": "这里应该用〈脑袋〉。“脑干”是脑内的神经组织，不是头颅，说头部受伤要用“脑袋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑干", "is_correct": true, "explanation": "脑干：人的脑部结构，符合“画出了人的……”的句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地表水道，与人体结构无关。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不属于人体，不能说“人的月亮”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“人的”后接身体部位或器官，“石头”不能与之组合。"}], "explanations": {"脑干": "脑干：人的脑部结构，符合“画出了人的……”的句意。", "河流": "语义：河流是地表水道，与人体结构无关。", "月亮": "语义：月亮是天体，不属于人体，不能说“人的月亮”。", "石头": "搭配：“人的”后接身体部位或器官，“石头”不能与之组合。"}, "sentence_index": 6, "correct_answer": "脑干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树的脑干很粗，要两个人才能抱住。", "explanation": "这里应该用〈树干〉。“脑干”是脑部结构，说树的主干要用“树干”。"}, {"text": "这个杯子的脑干断了，需要修。", "explanation": "这里应该用〈把手〉。“脑干”是脑部结构，不指杯子的部件；杯子的提手要说“把手”。"}, {"text": "他是我们班的脑干，大家都很信任他。", "explanation": "这里应该用〈骨干〉。“脑干”指脑部结构，比喻团队中的核心成员要说“骨干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在图上看到了一只脑干的剖面。", "corrected_sentence": "医生在图上看到了一个脑干的剖面。", "error_description": "量词错误：“只”多用于动物，人体器官应说“一个脑干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在图上比较了脑干们的大小。", "corrected_sentence": "医生在图上比较了脑干的大小。", "error_description": "“们”只用于指人或拟人的群体，脑干是器官，不能加“们”。错误在“脑干们”，正确为“脑干的大小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
