INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孤束核是位于延髓的神经核团，参与味觉传导和内脏感觉反射。", "primary_collocate": null, "pronunciation": "gū shù hé", "ipa": "ku⁵⁵ ʂu⁵¹ xɤ³⁵", "syllable_count": 3, "sentences": [{"text": "医生比较了孤束核与疑核的位置。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核位于延髓，是一个神经核团。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舌头尝到的味道，先传到孤束核。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核参与味觉传导和内脏感觉反射。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用影像检查了病人的孤束核。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "延髓里的孤束核接收来自舌头的信号。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核受损后，病人可能感觉不到味道。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者发现孤束核对内脏感觉很重要。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究观察了小鼠的孤束核活动。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核和味觉中枢之间有神经联系。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "延髓神经核团，传导味觉和内脏感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤束核", "is_correct": true, "explanation": "正确：孤束核是脑干中的神经核团，与“疑核”同属一类结构，句意成立。"}, {"text": "味觉", "is_correct": false, "explanation": "语义：味觉是感觉，不是脑干中的神经核团，无法与疑核并列。"}, {"text": "手掌", "is_correct": false, "explanation": "语义：手掌位于身体外周，不属于脑干中的结构。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语化，与这句书面语的语体不协调。"}], "explanations": {"孤束核": "正确：孤束核是脑干中的神经核团，与“疑核”同属一类结构，句意成立。", "味觉": "语义：味觉是感觉，不是脑干中的神经核团，无法与疑核并列。", "手掌": "语义：手掌位于身体外周，不属于脑干中的结构。", "玩意儿": "语域：“玩意儿”口语化，与这句书面语的语体不协调。"}, "sentence_index": 0, "correct_answer": "孤束核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一颗孤束核参与味觉传导和内脏感觉反射。", "explanation": "这里应该用〈个〉。“颗”用于谷粒、果实等小而圆的东西，孤束核是神经核团，不能用“颗”来数。"}, {"text": "一只孤束核参与味觉传导和内脏感觉反射。", "explanation": "这里应该用〈个〉。“只”用于动物，孤束核是神经核团，不能用“只”来数。"}, {"text": "一条孤束核参与味觉传导和内脏感觉反射。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，孤束核不能用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孤束核", "is_correct": true, "explanation": "正确：孤束核受损会影响味觉，句意成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，受损后不会影响人的味觉。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，与味觉无关。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”口语化，与这句医学叙述的语体不协调。"}], "explanations": {"孤束核": "正确：孤束核受损会影响味觉，句意成立。", "钥匙": "语义：钥匙是开锁的工具，受损后不会影响人的味觉。", "窗户": "语义：窗户是建筑部件，与味觉无关。", "家伙": "语域：“家伙”口语化，与这句医学叙述的语体不协调。"}, "sentence_index": 6, "correct_answer": "孤束核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孤束核是我们学校的学生会。", "explanation": "这里的“孤束核”被当成一个由人组成的组织，但孤束核是延髓里的神经核团，不指人群。"}, {"text": "孤束核是班上新成立的乐队。", "explanation": "这里的“孤束核”指一个乐队，但孤束核是神经结构，不能用来指人组成的团体。"}, {"text": "孤束核在社区里组织了志愿者活动。", "explanation": "这里的“孤束核”被当成组织活动的团体，但孤束核是神经核团，不能做组织者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生用影像找到了这颗孤束核。", "corrected_sentence": "医生用影像找到了这个孤束核。", "error_description": "量词错误：“颗”用于谷粒、果实等小而圆的东西，孤束核应说“这个”。错误在“这颗”，正确为“这个孤束核”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究结果说明孤束核们很重要。", "corrected_sentence": "研究结果说明孤束核很重要。", "error_description": "“们”只用于指人或拟人的群体，孤束核是神经结构，不能加“们”。错误在“孤束核们”，正确为“孤束核”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
