INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "疑核是位于延髓的神经核团，与舌咽神经和迷走神经相连，负责咽喉肌的运动控制。", "primary_collocate": null, "pronunciation": "yí hé", "ipa": "i³⁵ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "其启动涉及脑干中的特定核团，尤其是孤束核与疑核，这些区域整合来自边缘系统、前扣带回皮层以及自主神经系统的信号。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "疑核位于延髓，与舌咽神经和迷走神经相连。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核负责控制咽喉肌的运动。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核受损后，病人吞咽会很困难。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在脑干图像中找到了疑核。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核发出的神经纤维通向咽喉。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究分析了疑核神经元的活动。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核和孤束核都在延髓里。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核的功能异常会影响发声。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者用染色方法标记了疑核。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "延髓神经核团，控制咽喉肌运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疑核", "is_correct": true, "explanation": "延髓中控制咽喉肌运动的神经核团，即正确答案。"}, {"text": "议和", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是为停战而谈判。"}, {"text": "梨核", "is_correct": false, "explanation": "lí（l-）与 yí（零声母）声母不同，意思是梨子中间的核。"}, {"text": "棋盒", "is_correct": false, "explanation": "qí（q-）与 yí（零声母）声母不同，意思是装棋子的小盒。"}], "explanations": {"疑核": "延髓中控制咽喉肌运动的神经核团，即正确答案。", "议和": "yì（第四声）与 yí（第二声）声调不同，意思是为停战而谈判。", "梨核": "lí（l-）与 yí（零声母）声母不同，意思是梨子中间的核。", "棋盒": "qí（q-）与 yí（零声母）声母不同，意思是装棋子的小盒。"}, "sentence_index": null, "correct_answer": "疑核"}, "level_3": {"options": [{"text": "疑核", "is_correct": true, "explanation": "正确：疑核是延髓中的神经核团，与“孤束核”并列，符合“脑干中的特定核团”。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不在脑干中，也不是神经核团，与上下文不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是建筑，不是可以整合信号的神经结构。"}, {"text": "小玩意儿", "is_correct": false, "explanation": "语域：口语化的词，与书面语体的科学语境不符。"}], "explanations": {"疑核": "正确：疑核是延髓中的神经核团，与“孤束核”并列，符合“脑干中的特定核团”。", "心脏": "语义：心脏不在脑干中，也不是神经核团，与上下文不符。", "图书馆": "语义：图书馆是建筑，不是可以整合信号的神经结构。", "小玩意儿": "语域：口语化的词，与书面语体的科学语境不符。"}, "sentence_index": 0, "correct_answer": "疑核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脑干中有很多疑核，它们都控制咽喉肌的运动。", "explanation": "这里应该用〈核团〉。疑核是特定神经核团的专有名称，只指延髓中的这一对结构，不能泛指脑干中的一类核团。"}, {"text": "这次改革的疑核是提高效率。", "explanation": "这里应该用〈核心〉。疑核是解剖学专名，不能用来比喻事物的中心。"}, {"text": "我在图上看到了一只疑核。", "explanation": "这里的量词不对。〈只〉多用于动物，疑核是脑内结构，应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疑核", "is_correct": true, "explanation": "正确：疑核是神经核团，可以与“神经元”组成这一结构。"}, {"text": "白糖", "is_correct": false, "explanation": "搭配：“白糖神经元”不成立，神经元不能用白糖来修饰。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不是神经细胞，无法作为神经元的修饰对象。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，与神经元活动的研究不相容。"}], "explanations": {"疑核": "正确：疑核是神经核团，可以与“神经元”组成这一结构。", "白糖": "搭配：“白糖神经元”不成立，神经元不能用白糖来修饰。", "足球": "语义：足球不是神经细胞，无法作为神经元的修饰对象。", "窗户": "语义：窗户是建筑构件，与神经元活动的研究不相容。"}, "sentence_index": 6, "correct_answer": "疑核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疑核穿过了延髓，一直通到喉咙。", "explanation": "这里应该用〈神经纤维〉。疑核是固定的神经核团，细胞聚集在一处，不会穿行或延伸。"}, {"text": "疑核从延髓一直向下延伸到腰部。", "explanation": "这里应该用〈脊髓〉。疑核只位于延髓，不会向下延伸到脊柱。"}, {"text": "我们在皮肤上找到了疑核。", "explanation": "这里应该用〈神经末梢〉。疑核位于脑干，不分布在皮肤中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在切片上标出了两只疑核。", "corrected_sentence": "医生在切片上标出了两个疑核。", "error_description": "量词错误：应为“两个疑核”。“只”多用于动物，不用于脑内结构；疑核左右各一，计数用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者在脑干切片上找到了一只疑核。", "corrected_sentence": "研究者在脑干切片上找到了一个疑核。", "error_description": "量词错误：“疑核”是脑内结构，不能用“只”（多用于动物）计量，应说“一个疑核”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
