INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11243, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边缘系统是大脑中一组与情绪、行为、记忆和嗅觉等功能相关的结构，包括海马体、杏仁核等。", "primary_collocate": null, "pronunciation": "biān yuán xì tǒng", "ipa": "pjɛn⁵⁵ ɥɛn³⁵ ɕi⁵¹ tʰʊŋ²¹⁴", "syllable_count": 4, "sentences": [{"text": "其启动涉及脑干中的特定核团，尤其是孤束核与疑核，这些区域整合来自边缘系统、前扣带回皮层以及自主神经系统的信号。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "边缘系统与情绪、行为和记忆有关。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边缘系统包括海马体和杏仁核。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗅觉信息也会传到边缘系统。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边缘系统受损后，病人的情绪会改变。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者观察了小鼠边缘系统的活动。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力过大会影响边缘系统的功能。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海马体是边缘系统的重要结构。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用扫描检查了病人的边缘系统。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边缘系统在大脑中处理情绪反应。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊緣系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "大脑中与情绪、记忆、嗅觉相关的一组结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边缘系统", "is_correct": true, "explanation": "正确：边缘系统是脑中整合情绪与记忆相关信号的结构，符合语境。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，无法整合神经信号。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不属于脑内神经结构。"}, {"text": "大白话", "is_correct": false, "explanation": "语域：口语化说法，与书面语的神经科学语境不符。"}], "explanations": {"边缘系统": "正确：边缘系统是脑中整合情绪与记忆相关信号的结构，符合语境。", "咖啡": "语义：咖啡是饮料，无法整合神经信号。", "小说": "语义：小说是文学作品，不属于脑内神经结构。", "大白话": "语域：口语化说法，与书面语的神经科学语境不符。"}, "sentence_index": 0, "correct_answer": "边缘系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的边缘系统很完善。", "explanation": "这里应该用〈交通系统〉。边缘系统指大脑结构，不能用来指城市设施。"}, {"text": "边缘系统是消化食物的器官。", "explanation": "这里应该用〈胃〉。边缘系统是与情绪、记忆有关的脑结构，不参与消化。"}, {"text": "研究者在显微镜下看到了一只边缘系统。", "explanation": "这里的量词不对。〈只〉用于动物，边缘系统应该用〈套〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边缘系统", "is_correct": true, "explanation": "正确：边缘系统是与情绪、记忆相关的脑结构，压力可影响其功能。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是食物，没有可被压力影响的神经功能。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是体育器材，与神经功能的语境不符。"}, {"text": "小玩意儿", "is_correct": false, "explanation": "语域：口语词，与书面的科学语境不符。"}], "explanations": {"边缘系统": "正确：边缘系统是与情绪、记忆相关的脑结构，压力可影响其功能。", "大米": "语义：大米是食物，没有可被压力影响的神经功能。", "足球": "语义：足球是体育器材，与神经功能的语境不符。", "小玩意儿": "语域：口语词，与书面的科学语境不符。"}, "sentence_index": 6, "correct_answer": "边缘系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他背着边缘系统去学校。", "explanation": "这里应该用〈书包〉。边缘系统在大脑里，不能被背着携带。"}, {"text": "她撑起边缘系统挡雨。", "explanation": "这里应该用〈雨伞〉。边缘系统是脑结构，不能用来遮雨。"}, {"text": "小朋友踢着边缘系统跑。", "explanation": "这里应该用〈皮球〉。边缘系统位于脑中，不能被踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我曾经研究过一条边缘系统。", "corrected_sentence": "我曾经研究过一套边缘系统。", "error_description": "量词错误：“边缘系统”是成套的结构，应配“套”；“条”用于细长的事物，不能用于此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书介绍了一条边缘系统的基本功能。", "corrected_sentence": "这本书介绍了一套边缘系统的基本功能。", "error_description": "量词错误：“系统”应配〈套〉，“条”用于细长的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
