INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "扣带回是大脑皮层的一部分，位于扣带沟和胼胝体沟之间，参与情绪、记忆等功能。", "primary_collocate": null, "pronunciation": "kòu dài huí", "ipa": "kʰou˥˩ tai˥˩ xuei˧˥", "syllable_count": 3, "sentences": [{"text": "其启动涉及脑干中的特定核团，尤其是孤束核与疑核，这些区域整合来自边缘系统、前扣带回皮层以及自主神经系统的信号。", "target_word": "扣带回", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "扣带回在大脑的中间，靠近胼胝体。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，扣带回和情绪有关系。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究表明，扣带回参与注意力的调节。", "target_word": "扣带回", "complexity_tier": "T3", "furigana": "kòu dài huí", "sentence_source": "generated"}, {"text": "研究发现，扣带回参与记忆活动。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做脑部检查时，医生看了扣带回的图像。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回受伤后，病人的情绪变化很大。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，扣带回位于胼胝体上方。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疼痛的时候，扣带回会变得很活跃。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在大脑模型上指出了扣带回的位置。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前扣带回", "label": "复合"}, {"form": "后扣带回", "label": "复合"}, {"form": "扣帶回", "label": "繁体"}], "register": "科技", "sense_fingerprint": "大脑皮层中位于胼胝体上方、参与情绪和记忆的脑区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：“前扣带回皮层”是脑区的规范名称，这里的空缺只能填“扣带回”。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓位于脊柱内，不是大脑皮层的分区，与“前……皮层”的结构不符。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不属于脑内结构，不能与“皮层”组成脑区名称。"}, {"text": "肝脏", "is_correct": false, "explanation": "搭配：肝脏没有皮层结构，“前肝脏皮层”不是可以成立的说法。"}], "explanations": {"扣带回": "正确：“前扣带回皮层”是脑区的规范名称，这里的空缺只能填“扣带回”。", "脊髓": "语义：脊髓位于脊柱内，不是大脑皮层的分区，与“前……皮层”的结构不符。", "心脏": "语义：心脏不属于脑内结构，不能与“皮层”组成脑区名称。", "肝脏": "搭配：肝脏没有皮层结构，“前肝脏皮层”不是可以成立的说法。"}, "sentence_index": 0, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究表明，一座扣带回参与注意力的调节。", "explanation": "这里量词用错。“座”用于山、楼房等大而固定的东西，扣带回是脑区，应数“个”。"}, {"text": "研究表明，一颗扣带回参与注意力的调节。", "explanation": "这里量词用错。“颗”用于小而圆的东西，扣带回是较大的脑区，应数“个”。"}, {"text": "研究表明，一根扣带回参与注意力的调节。", "explanation": "这里量词用错。“根”用于细长的东西，扣带回是脑区，应数“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：扣带回与情绪调节有关，受伤后会引起情绪变化，这与句中语境相符。"}, {"text": "指甲", "is_correct": false, "explanation": "语义：指甲不参与情绪调节，受伤后不会引起“情绪变化很大”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是人体部位，受伤后也不会使病人的情绪变化很大，句意不通。"}, {"text": "肝脏", "is_correct": false, "explanation": "搭配：“……受伤后，病人的情绪变化很大”的主语应是与情绪相关的脑区，肝脏不能这样搭配。"}], "explanations": {"扣带回": "正确：扣带回与情绪调节有关，受伤后会引起情绪变化，这与句中语境相符。", "指甲": "语义：指甲不参与情绪调节，受伤后不会引起“情绪变化很大”。", "手机": "语义：手机不是人体部位，受伤后也不会使病人的情绪变化很大，句意不通。", "肝脏": "搭配：“……受伤后，病人的情绪变化很大”的主语应是与情绪相关的脑区，肝脏不能这样搭配。"}, "sentence_index": 6, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在大脑模型上指出了一把扣带回的位置。", "explanation": "这里量词用错。“把”用于有柄或可握的物件，扣带回是脑区，应数“个”。"}, {"text": "老师在大脑模型上指出了一粒扣带回的位置。", "explanation": "这里量词用错。“粒”用于很小的颗粒，扣带回是较大的脑区，应数“个”。"}, {"text": "老师带我们走进扣带回，参观里面的房间。", "explanation": "用法错误：“参观”的地点应是可以进入的场所，扣带回是脑中的结构，不能走进去参观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员用核磁共振看到了一座扣带回。", "corrected_sentence": "研究人员用核磁共振看到了一个扣带回。", "error_description": "量词错误：应为“一个扣带回”。“座”用于山、楼房等大而固定的东西，扣带回是脑区，不能用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生在报告里描述了一颗扣带回的损伤。", "corrected_sentence": "医生在报告里描述了一个扣带回的损伤。", "error_description": "量词错误：应为“一个扣带回”。“颗”用于小而圆的东西，扣带回是较大的脑区，不能用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
