INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大脑两半球表面覆盖的一层灰质，是神经细胞聚集的地方，主管高级神经活动。", "primary_collocate": null, "pronunciation": "pí céng", "ipa": "pʰi˧˥ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "其启动涉及脑干中的特定核团，尤其是孤束核与疑核，这些区域整合来自边缘系统、前扣带回皮层以及自主神经系统的信号。", "target_word": "皮层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大脑皮层有很多沟和回。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮层是神经细胞聚集的地方。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了病人的大脑皮层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮层在大脑的最外面，是灰色的。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮层负责思考、语言和记忆。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的大脑皮层比老鼠的复杂得多。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，大脑皮层会变薄。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图显示了皮层不同区域的功能。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习新东西时，皮层会很活跃。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大脑皮层", "label": "复合"}, {"form": "皮層", "label": "繁体"}], "register": "科技", "sense_fingerprint": "大脑表面由神经细胞聚集而成、主管高级神经活动的灰质层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮层", "is_correct": true, "explanation": "正确：“前扣带回皮层”是固定说法，这里的空缺应填“皮层”。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓不是大脑皮层的分区，“前扣带回脊髓”不成立。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不属于脑内结构，与“前扣带回”后面的解剖名称不搭。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：“前扣带回”后面只接脑区相关的词，“皮肤”不能这样组合。"}], "explanations": {"皮层": "正确：“前扣带回皮层”是固定说法，这里的空缺应填“皮层”。", "脊髓": "语义：脊髓不是大脑皮层的分区，“前扣带回脊髓”不成立。", "心脏": "语义：心脏不属于脑内结构，与“前扣带回”后面的解剖名称不搭。", "皮肤": "搭配：“前扣带回”后面只接脑区相关的词，“皮肤”不能这样组合。"}, "sentence_index": 0, "correct_answer": "皮层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块土地的皮层很肥沃。", "explanation": "〈表层〉。在此义项中，皮层指大脑等器官表面的灰质层；描述土地的表面应说“表层”。"}, {"text": "医生检查了一颗皮层。", "explanation": "这里量词用错。“皮层”是一层灰质，应数“层”，“颗”用于小而圆的东西。"}, {"text": "橘子的皮层很薄。", "explanation": "〈果皮〉。橘子外面那层皮叫果皮，皮层指大脑表面的灰质层，不用来指水果的皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮层", "is_correct": true, "explanation": "正确：人的大脑皮层比老鼠的复杂，这里的空缺应填“皮层”。"}, {"text": "肝脏", "is_correct": false, "explanation": "语义：肝脏不是大脑的组成部分，与“比老鼠的复杂”的比较对象不相符。"}, {"text": "骨骼", "is_correct": false, "explanation": "语义：骨骼是支撑身体的骨架，不是大脑的组成部分，“大脑骨骼比老鼠的复杂”的比较对象不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“复杂”形容结构或系统，不能形容体重，“体重比老鼠的复杂得多”不成立。"}], "explanations": {"皮层": "正确：人的大脑皮层比老鼠的复杂，这里的空缺应填“皮层”。", "肝脏": "语义：肝脏不是大脑的组成部分，与“比老鼠的复杂”的比较对象不相符。", "骨骼": "语义：骨骼是支撑身体的骨架，不是大脑的组成部分，“大脑骨骼比老鼠的复杂”的比较对象不成立。", "体重": "搭配：“复杂”形容结构或系统，不能形容体重，“体重比老鼠的复杂得多”不成立。"}, "sentence_index": 6, "correct_answer": "皮层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鸡蛋的皮层很薄。", "explanation": "〈外壳〉。鸡蛋外面的硬壳叫蛋壳；在此义项中，皮层指大脑等器官表面的灰质层，不指蛋壳。"}, {"text": "这面墙的皮层脱落了一大片。", "explanation": "〈墙皮〉。墙面的粉刷层通常叫墙皮，此处不用“皮层”。"}, {"text": "他的皮层被晒伤了。", "explanation": "〈表皮〉。人身上被晒伤的是皮肤的表皮，皮层只指大脑等器官的灰质层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在报告里描述了一颗皮层的损伤。", "corrected_sentence": "医生在报告里描述了一层皮层的损伤。", "error_description": "量词错误：应为“一层皮层”。皮层是一层灰质，应数“层”，“颗”用于小而圆的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张图显示了一颗皮层的厚度。", "corrected_sentence": "这张图显示了一层皮层的厚度。", "error_description": "量词错误：应为“一层皮层”。皮层是一层灰质，应数“层”，“颗”不能用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
