INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物身体里负责传递信息、控制活动的系统，包括大脑、脊髓和神经。", "primary_collocate": null, "pronunciation": "shén jīng xì tǒng", "ipa": "ʂən˧˥ tɕiŋ˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "孤束核与疑核是脑干中的核团，它们属于神经系统的一部分，参与调控内脏活动。", "target_word": "神经系统", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "某些研究甚至提出，哈欠的频率可作为神经系统健康的指标，例如在多发性硬化、癫痫或抑郁症患者中，异常频繁的哈欠常被视为疾病活动的前兆。", "target_word": "神经系统", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "神经系统包括大脑、脊髓和神经。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的神经系统控制着身体的活动。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝太多咖啡会影响神经系统。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的神经系统有问题。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物也有神经系统，不过比人简单。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经系统把信息传到大脑。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠对神经系统的健康很重要。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病会伤害人的神经系统。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中枢神经系统", "label": "复合"}, {"form": "自主神经系统", "label": "复合"}, {"form": "神經系統", "label": "繁体"}], "register": "科技", "sense_fingerprint": "人和动物体内由大脑、脊髓和神经组成、传递信息并控制活动的系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经系统", "is_correct": true, "explanation": "正确。孤束核与疑核属于脑干，是神经系统的一部分，句中“属于……的一部分”指向这一意义。"}, {"text": "消化系统", "is_correct": false, "explanation": "语义：消化系统负责分解食物，孤束核与疑核并不属于消化系统。"}, {"text": "循环系统", "is_correct": false, "explanation": "语义：循环系统负责输送血液，脑干核团并不属于循环系统。"}, {"text": "免疫系统", "is_correct": false, "explanation": "语义：免疫系统负责抵御病原体，脑干核团并不属于免疫系统。"}], "explanations": {"神经系统": "正确。孤束核与疑核属于脑干，是神经系统的一部分，句中“属于……的一部分”指向这一意义。", "消化系统": "语义：消化系统负责分解食物，孤束核与疑核并不属于消化系统。", "循环系统": "语义：循环系统负责输送血液，脑干核团并不属于循环系统。", "免疫系统": "语义：免疫系统负责抵御病原体，脑干核团并不属于免疫系统。"}, "sentence_index": 0, "correct_answer": "神经系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的神经系统很聪明，一学就会。", "explanation": "这里应该用〈大脑〉。聪明和学习由大脑负责；神经系统是传递信息、控制活动的整体系统，不能用来形容一个人聪明。"}, {"text": "这个病人的左腿神经系统被压坏了。", "explanation": "这里应该用〈神经〉。神经系统指全身的系统，只受压的是左腿的一段神经，不能说左腿神经系统。"}, {"text": "一个神经系统是一种细胞，有很多细长的突起。", "explanation": "这里应该用〈神经元〉。神经元是有细长突起的细胞；神经系统是由大脑、脊髓和神经组成的整体，不是单个细胞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经系统", "is_correct": true, "explanation": "正确。“神经系统”指人和动物体内传递信息、控制活动的系统，“动物也有”与“比人简单”指向这一意义。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是人类的教育机构，动物没有学校，与“动物也有”的句意矛盾。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是人的身份证件，动物没有，与“动物也有”的句意矛盾。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：油漆是涂在物体表面的涂料，不是动物拥有的结构，“动物也有油漆”不成立。"}], "explanations": {"神经系统": "正确。“神经系统”指人和动物体内传递信息、控制活动的系统，“动物也有”与“比人简单”指向这一意义。", "学校": "语义：学校是人类的教育机构，动物没有学校，与“动物也有”的句意矛盾。", "护照": "语义：护照是人的身份证件，动物没有，与“动物也有”的句意矛盾。", "油漆": "语义：油漆是涂在物体表面的涂料，不是动物拥有的结构，“动物也有油漆”不成立。"}, "sentence_index": 6, "correct_answer": "神经系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种病会伤害人的一座神经系统。", "explanation": "这里应该用〈套〉。“座”用于山、楼房等大而固定的东西，神经系统应说“一套”。"}, {"text": "这种病会伤害人的一把神经系统。", "explanation": "这里应该用〈套〉。“把”用于有柄或可握的物件，神经系统应说“一套”。"}, {"text": "这种病会伤害人的一只神经系统。", "explanation": "这里应该用〈套〉。“只”用于动物或成对器物中的一个，不能用于神经系统，应说“一套神经系统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药能让人的一颗神经系统恢复正常。", "corrected_sentence": "这种药能让人的一整套神经系统恢复正常。", "error_description": "量词错误：神经系统应说“一整套”。“颗”用于小而圆的东西，不能用于此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病把一颗神经系统损伤得很严重。", "corrected_sentence": "这种病把一整套神经系统损伤得很严重。", "error_description": "量词错误：神经系统应说“一整套”。“颗”用于小而圆的东西，不能用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
