INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种利用强磁场和无线电波成像的医学检查技术，用于观察人体内部器官和组织。", "primary_collocate": null, "pronunciation": "cí gòng zhèn", "ipa": "tsʰɨ˧˥ kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 3, "sentences": [{"text": "研究人员常用磁共振观察大脑活动时的血流变化。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振可以清楚显示大脑内部的结构。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做磁共振时，病人必须躺着不动。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振没有辐射，对身体比较安全。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振利用强磁场和无线电波成像。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用磁共振检查膝盖的软组织损伤。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振的检查时间比较长，大约要半小时。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装有心脏起搏器的人不能做磁共振。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振对脑部肿瘤的诊断很有帮助。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给他做了一次磁共振，以便查清脑部的病变。", "target_word": "磁共振", "complexity_tier": "T3", "furigana": "cí gòng zhèn", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "核磁共振", "label": "复合"}, {"form": "磁共振成像", "label": "复合"}], "register": "专业", "sense_fingerprint": "医学成像检查技术，利用强磁场和无线电波观察人体内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磁共振", "is_correct": true, "explanation": "正确。磁共振可以成像，用来观察大脑活动时的血流变化，与句中语境相符。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是气味制品，不能用来观察大脑的血流变化，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是医学成像设备，不能用来观察大脑的血流变化。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的质量指标，不能用来观察大脑血流，句意不通。"}], "explanations": {"磁共振": "正确。磁共振可以成像，用来观察大脑活动时的血流变化，与句中语境相符。", "香水": "语义：香水是气味制品，不能用来观察大脑的血流变化，句意不通。", "手机": "语义：手机不是医学成像设备，不能用来观察大脑的血流变化。", "体重": "语义：体重是身体的质量指标，不能用来观察大脑血流，句意不通。"}, "sentence_index": 0, "correct_answer": "磁共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "磁共振能记录大脑发出的脑电波。", "explanation": "这里应该用〈脑电图〉。脑电图通过电极记录脑电波；磁共振靠强磁场和无线电波成像，不记录脑电波。"}, {"text": "磁共振要用X射线，所以检查时要做好防护。", "explanation": "这里应该用〈计算机断层扫描〉。计算机断层扫描用X射线，需要防护；磁共振靠强磁场和无线电波，不用X射线。"}, {"text": "磁共振用声波成像，医生能看到胎儿的心跳。", "explanation": "这里应该用〈超声〉。超声用声波成像；磁共振靠强磁场和无线电波，不用声波。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磁共振", "is_correct": true, "explanation": "正确。磁共振是医学检查方式，“检查时间比较长，大约要半小时”指医学检查，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“检查”的对象是人体或设备，不说“天气的检查时间”，“天气”不接受“检查”。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不是医学检查对象，与句中的医学检查语境不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是医学检查对象，与句中的医学检查语境不符。"}], "explanations": {"磁共振": "正确。磁共振是医学检查方式，“检查时间比较长，大约要半小时”指医学检查，符合语境。", "天气": "搭配：“检查”的对象是人体或设备，不说“天气的检查时间”，“天气”不接受“检查”。", "游戏": "语义：游戏不是医学检查对象，与句中的医学检查语境不符。", "月亮": "语义：月亮不是医学检查对象，与句中的医学检查语境不符。"}, "sentence_index": 6, "correct_answer": "磁共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他做了一只磁共振。", "explanation": "这里应该用〈次〉。磁共振是一次检查，说“做一次磁共振”；“只”用于动物或成对器物中的一个，不能用于检查。"}, {"text": "医生给他做了一根磁共振。", "explanation": "这里应该用〈次〉。磁共振是一次检查，说“做一次磁共振”；“根”用于细长的东西，不能用于检查。"}, {"text": "医生给他做了一条磁共振。", "explanation": "这里应该用〈次〉。磁共振是一次检查，说“做一次磁共振”；“条”用于长条之物，不能用于检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院用一把磁共振查出了他的病。", "corrected_sentence": "医院用一台磁共振查出了他的病。", "error_description": "量词错误：磁共振是大型机器，应用“台”，不能用“把”；“把”用于有柄或可握的物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院用一把磁共振拍得脑部结构很清楚。", "corrected_sentence": "医院用一台磁共振拍得脑部结构很清楚。", "error_description": "量词错误：磁共振是大型机器，应说“一台”。“把”用于有柄或可握的物件，不能用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
