INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体发出或反射的光线经过光学系统后形成的图像。", "primary_collocate": null, "pronunciation": "chéng xiàng", "ipa": "ʈʂʰɤŋ˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "光线通过镜头后，会在底片上成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体经过凸透镜后会在另一侧成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛里的晶状体能让物体在视网膜上成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光通过小孔后，会在墙上成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜头脏了，照相机就不能清楚地成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线太弱时，相机很难成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平面镜能成像，像和物体大小一样。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显微镜通过两组透镜成像，把小东西放大。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线经过水珠时会弯曲，并在后面成像。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相机的光圈越大，进来的光越多，成像越亮。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成像了", "label": "体标"}, {"form": "成像仪", "label": "复合"}, {"form": "成像技术", "label": "复合"}], "register": "专业", "sense_fingerprint": "光线经过透镜等光学系统后形成图像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11250, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：光线经透镜等光学系统形成图像，即本词的读音和意思。"}, {"text": "城乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是城市与农村。"}, {"text": "呈现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是显现出来。"}, {"text": "承想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是没有想到。"}, {"text": "成效", "is_correct": false, "explanation": "xiào 与 xiàng 韵母不同，意思是效果、成果。"}], "explanations": {"成像": "成像：光线经透镜等光学系统形成图像，即本词的读音和意思。", "城乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是城市与农村。", "呈现": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是显现出来。", "承想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是没有想到。", "成效": "xiào 与 xiàng 韵母不同，意思是效果、成果。"}, "sentence_index": null, "correct_answer": "成像"}, "level_3": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：光线经镜头在底片上形成图像，与句子语境相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "配价：“拍摄”需要人作施事，“光线”不能拍摄底片。"}, {"text": "摄影", "is_correct": false, "explanation": "语义：“摄影”是人的活动，光线本身不会摄影。"}, {"text": "转动", "is_correct": false, "explanation": "搭配：“转动”指物体绕轴旋转，不用于光线在底片上的情况。"}], "explanations": {"成像": "成像：光线经镜头在底片上形成图像，与句子语境相符。", "拍摄": "配价：“拍摄”需要人作施事，“光线”不能拍摄底片。", "摄影": "语义：“摄影”是人的活动，光线本身不会摄影。", "转动": "搭配：“转动”指物体绕轴旋转，不用于光线在底片上的情况。"}, "sentence_index": 0, "correct_answer": "成像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗的影子成像在墙上。", "explanation": "这里应该用〈出现〉。影子是光被遮挡后留下的暗区，不是光学系统形成的像，不能说成像。"}, {"text": "一串脚印成像在雪地上。", "explanation": "这里应该用〈呈现〉。脚印是实物留下的痕迹，不是透镜等光学系统形成的图像，“成像”只用于光学成像。"}, {"text": "小明一走进教室，就在大家面前成像了。", "explanation": "这里应该用〈露面〉。“成像”指光线经光学系统形成图像，人走进教室不能说成像，应说露面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11250, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：光线经光学系统形成图像，即本词的读音和意思。"}, {"text": "长相", "is_correct": false, "explanation": "cháng（第二声）与 chéng（第二声）韵母不同（ang 与 eng），意思是相貌。"}, {"text": "称象", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是称量大象（曹冲称象的典故）。"}, {"text": "长项", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang 与 eng），意思是擅长的方面、长处。"}], "explanations": {"成像": "成像：光线经光学系统形成图像，即本词的读音和意思。", "长相": "cháng（第二声）与 chéng（第二声）韵母不同（ang 与 eng），意思是相貌。", "称象": "chēng（第一声）与 chéng（第二声）声调不同，意思是称量大象（曹冲称象的典故）。", "长项": "cháng 与 chéng 韵母不同（ang 与 eng），意思是擅长的方面、长处。"}, "sentence_index": null, "correct_answer": "成像"}, "level_3": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：平面镜形成的像与物体大小相同，本句说的正是平面镜的成像功能。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”是把物体分开，平面镜没有这一功能，与后句“像和物体大小一样”也不相合。"}, {"text": "加热", "is_correct": false, "explanation": "搭配：“加热”多用于水、食物等，不用于描述平面镜的功能。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是种子或植物的变化，平面镜不会发芽。"}], "explanations": {"成像": "成像：平面镜形成的像与物体大小相同，本句说的正是平面镜的成像功能。", "切割": "语义：“切割”是把物体分开，平面镜没有这一功能，与后句“像和物体大小一样”也不相合。", "加热": "搭配：“加热”多用于水、食物等，不用于描述平面镜的功能。", "发芽": "语义：“发芽”是种子或植物的变化，平面镜不会发芽。"}, "sentence_index": 6, "correct_answer": "成像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边看书一边成像。", "explanation": "这里应该用〈拍照〉。“成像”是光线经光学系统形成图像，人的拍照动作不能说成像。"}, {"text": "孩子的笑声成像在屋子里。", "explanation": "这里应该用〈回荡〉。笑声是声音，不是光学系统形成的图像，“成像”不能用于声音。"}, {"text": "这本书的定价成像在封面上。", "explanation": "这里应该用〈印〉。“成像”指光线经光学系统形成图像，定价是印刷上去的，不能说成像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "烛光穿过透镜后，会屏幕上成像。", "corrected_sentence": "烛光穿过透镜后，会在屏幕上成像。", "error_description": "错误形式：“会屏幕上成像”；正确形式：“会在屏幕上成像”。成像的处所要用介词“在”引出，漏掉“在”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "透镜把光线会聚后，在墙上了成像。", "corrected_sentence": "透镜把光线会聚后，在墙上成像。", "error_description": "错误形式：“在墙上了成像”；正确形式：“在墙上成像”。“了”表示完成，不能放在动词“成像”之前，此处多出的“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
