INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11254, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "广泛地存在。", "primary_collocate": null, "pronunciation": "pǔ biàn cún zài", "ipa": "pʰu˨˩˦ pjɛn˥˩ tsʰwən˧˥ tsaɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这种现象并非普遍存在于所有个体。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种问题在很多国家普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会上普遍存在着贫富差距的现象。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络上普遍存在虚假信息的问题。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料污染在海洋中普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种细菌在自然界普遍存在，并不少见。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力过大的情况在年轻人中普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查发现，这种做法在小城市普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类错误在初学者的作文里普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，睡眠不足的问题普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍存在着", "label": "体标"}, {"form": "普遍存在于", "label": "搭配"}], "register": "书面", "sense_fingerprint": "某种现象或事物广泛地存在于许多地方或群体中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍存在", "is_correct": true, "explanation": "普遍存在：现象并不遍布所有个体，与“并非……于所有个体”的语境相合。"}, {"text": "存放", "is_correct": false, "explanation": "语义：“存放”指把东西放在某处，不能用于“所有个体”这样的人群。"}, {"text": "停放", "is_correct": false, "explanation": "搭配：“停放”多用于车辆，不能用于个体。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”是人的活动，不能说“工作于所有个体”，与句意不符。"}], "explanations": {"普遍存在": "普遍存在：现象并不遍布所有个体，与“并非……于所有个体”的语境相合。", "存放": "语义：“存放”指把东西放在某处，不能用于“所有个体”这样的人群。", "停放": "搭配：“停放”多用于车辆，不能用于个体。", "工作": "语义：“工作”是人的活动，不能说“工作于所有个体”，与句意不符。"}, "sentence_index": 0, "correct_answer": "普遍存在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机普遍存在于书包里。", "explanation": "这里应该用〈放〉。“普遍存在”指同类事物到处都有，不能用来说某一部手机放在书包里。"}, {"text": "这位老师普遍存在于全校的每个班级。", "explanation": "这里应该用〈任教〉。“普遍存在”指现象或问题广泛分布，不能用来说一位老师在全校各班任教。"}, {"text": "这场比赛的冠军普遍存在于前三名里。", "explanation": "这里应该用〈位列〉。“普遍存在”指同类事物到处都有，冠军只有一个，不能用来说它在前三名中分布，应说位列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍存在", "is_correct": true, "explanation": "普遍存在：广泛地存在于年轻人中，与句子语境相合。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”用于活动或比赛，不能说“压力过大的情况”举办。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”需要乐器和乐曲，与“压力过大的情况”无关。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是人或动物的活动，不能用于“情况”。"}], "explanations": {"普遍存在": "普遍存在：广泛地存在于年轻人中，与句子语境相合。", "举办": "搭配：“举办”用于活动或比赛，不能说“压力过大的情况”举办。", "演奏": "语义：“演奏”需要乐器和乐曲，与“压力过大的情况”无关。", "游泳": "语义：“游泳”是人或动物的活动，不能用于“情况”。"}, "sentence_index": 6, "correct_answer": "普遍存在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种情况偶尔发生，却普遍存在。", "explanation": "这里应该用〈罕见〉。“普遍存在”指到处都有，与前半句说的“不常发生”正相反，句子前后矛盾。"}, {"text": "这座城市的地标塔普遍存在于各个街区。", "explanation": "这里应该用〈屹立〉。地标塔只有一座，“普遍存在”指同类事物到处都有，不能用来说它分布在各个街区。"}, {"text": "这种手艺早已消失，却普遍存在于民间。", "explanation": "这里应该用〈残存〉。“普遍存在”指到处都有，与前半句所说的“不复存在”正相反，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种误会普遍存在在农村地区。", "corrected_sentence": "这种误会普遍存在于农村地区。", "error_description": "错误形式：“普遍存在在农村地区”，“在”重复；正确形式：“普遍存在于农村地区”。“存在”后引出处所要用“于”，不用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这类误会在城市里也普遍存在了着。", "corrected_sentence": "这类误会在城市里也普遍存在着。", "error_description": "错误形式：“普遍存在了着”，多加了“了”；正确形式：“普遍存在着”。“着”表示持续状态，与“了”不能同时放在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
