INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11255, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自闭症是一种神经发育障碍，主要表现为社交沟通困难、兴趣狭窄和刻板行为。", "primary_collocate": null, "pronunciation": "zì bì zhèng", "ipa": "tsɨ⁵¹ pi⁵¹ ʈʂɤŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "值得注意的是，这种社会性传染并非普遍存在于所有个体——部分自闭症患者或共情能力较弱者对此反应明显减弱，暗示该行为与社交认知能力密切相关。", "target_word": "自闭症", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "医生说这个孩子得了自闭症。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自闭症的孩子常常不爱看别人的眼睛。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期发现自闭症，对孩子很重要。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究自闭症的专家。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自闭症患者常常重复同一个动作。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师学过怎样帮助自闭症儿童。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多家长不了解自闭症。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院专门治疗自闭症。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自闭症需要长期的训练和陪伴。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自閉症", "label": "繁体"}, {"form": "自闭症谱系障碍", "label": "复合"}], "register": "中性", "sense_fingerprint": "自闭症：神经发育障碍，表现为社交沟通困难、兴趣狭窄、行为刻板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自闭症", "is_correct": true, "explanation": "正确：在社交认知能力的研究语境中，“部分自闭症患者”正合句意。"}, {"text": "近视", "is_correct": false, "explanation": "语义：“近视”是视力问题，与社交认知和社会性传染无关，句意不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是呼吸道疾病，与社交认知和社会性传染无关，句意不通。"}, {"text": "高血压", "is_correct": false, "explanation": "语义：“高血压”属于心血管疾病，与社交认知和社会性传染无关，句意不通。"}], "explanations": {"自闭症": "正确：在社交认知能力的研究语境中，“部分自闭症患者”正合句意。", "近视": "语义：“近视”是视力问题，与社交认知和社会性传染无关，句意不通。", "感冒": "语义：“感冒”是呼吸道疾病，与社交认知和社会性传染无关，句意不通。", "高血压": "语义：“高血压”属于心血管疾病，与社交认知和社会性传染无关，句意不通。"}, "sentence_index": 0, "correct_answer": "自闭症"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在超市买了自闭症，回家给他吃。", "explanation": "这里应该用〈药〉。自闭症是病名，不能买来吃；买来给他吃的应该是「药」。"}, {"text": "他的名字叫自闭症。", "explanation": "这里应该用〈人名〉。自闭症是病名，不能当人名，「叫」后接的应该是人名。"}, {"text": "他是一位自闭症，需要特别照顾。", "explanation": "这里应该用〈病人〉。自闭症是病名，不能用来指人，指人要说「自闭症患者」或「有自闭症的人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自闭症", "is_correct": true, "explanation": "「自闭症」作为对象，与「帮助……儿童」搭配，指需要帮助的一类儿童。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：「钢琴」不是人，「钢琴儿童」说不通，与「帮助」的对象不符。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「数学」是学科，不能修饰「儿童」来表示一类人。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：「灯泡」不是人，「帮助灯泡儿童」不通。"}], "explanations": {"自闭症": "「自闭症」作为对象，与「帮助……儿童」搭配，指需要帮助的一类儿童。", "钢琴": "语义：「钢琴」不是人，「钢琴儿童」说不通，与「帮助」的对象不符。", "数学": "搭配：「数学」是学科，不能修饰「儿童」来表示一类人。", "灯泡": "语义：「灯泡」不是人，「帮助灯泡儿童」不通。"}, "sentence_index": 6, "correct_answer": "自闭症"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格有点自闭症，总把自己关在房间里。", "explanation": "这里应该用〈自闭〉。「自闭」形容性格，「自闭症」是病名，不能说「性格有点自闭症」。"}, {"text": "妈妈说，他的名字叫自闭症，不太爱说话。", "explanation": "这里应该用〈人名〉。自闭症是病名，不能当人名，「叫」后接的应该是人名。"}, {"text": "医生做出了诊断，然后让他喝自闭症。", "explanation": "这里应该用〈药〉。自闭症是病名，不是能喝的东西，让人喝的应该是「药」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说他患有一只自闭症，需要长期治疗。", "corrected_sentence": "医生说他患有一种自闭症，需要长期治疗。", "error_description": "「自闭症」作为病名，应用量词「种」，不能用「只」。「只」用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，他有一把自闭症，所以很少和同学玩。", "corrected_sentence": "老师说，他有自闭症，所以很少和同学玩。", "error_description": "量词用错：“把”用于有柄的器具，不能修饰病名“自闭症”，应删去“一把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
