INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一组有相似特征的发育障碍，程度轻重不一", "primary_collocate": null, "pronunciation": "pǔ xì", "ipa": "pʰu²¹⁴ ɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "值得注意的是，这种社会性传染并非普遍存在于所有个体——处于谱系中的患者或共情能力较弱者对此反应明显减弱，暗示该行为与社交认知能力密切相关。", "target_word": "谱系", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "自闭症是一个谱系，轻重差别很大。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他在自闭症谱系的轻度一端。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谱系里的孩子，表现各不相同。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家用谱系来说明病情的轻重。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谱系两端的孩子，生活能力差别很大。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章介绍了自闭症谱系的新研究。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的症状轻，在谱系中比较靠近正常。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生按谱系判断孩子需要多少帮助。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谱系的说法，让人明白病情有轻有重。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "譜系", "label": "繁体"}, {"form": "谱系图", "label": "复合"}], "register": "书面", "sense_fingerprint": "谱系：特征相似、程度轻重不一的一组发育障碍（如自闭症谱系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：“处于谱系中的患者”指处在一组程度轻重不一的障碍之中，“谱系”正合句意。"}, {"text": "家族", "is_correct": false, "explanation": "语义：“家族”指同一血缘的成员，不能表示一组障碍的程度分布，句意不通。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的时段，与自闭症这种发育障碍无关，句子意思不通。"}, {"text": "血型", "is_correct": false, "explanation": "语义：“血型”是血液的分类，不指发育障碍的类别，放入句中意思不通。"}], "explanations": {"谱系": "正确：“处于谱系中的患者”指处在一组程度轻重不一的障碍之中，“谱系”正合句意。", "家族": "语义：“家族”指同一血缘的成员，不能表示一组障碍的程度分布，句意不通。", "季节": "语义：“季节”指一年中的时段，与自闭症这种发育障碍无关，句子意思不通。", "血型": "语义：“血型”是血液的分类，不指发育障碍的类别，放入句中意思不通。"}, "sentence_index": 0, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个谱系，性格很开朗。", "explanation": "这里应该用〈患者〉。谱系指一组障碍在程度上的分布范围，不能指某一个人；说某人患病要用“患者”。"}, {"text": "这个孩子的谱系很明显。", "explanation": "这里应该用〈症状〉。谱系指一组障碍在程度上的分布范围，不是某人表现出的具体状况；说“症状很明显”要用“症状”。"}, {"text": "医生说他有轻度的谱系。", "explanation": "这里应该用〈障碍〉。谱系是一组障碍在程度上的分布范围，不能直接当作某种障碍；说“有轻度的障碍”要用“障碍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：“自闭症谱系”指一组从轻到重的障碍，正是这篇报道研究的对象。"}, {"text": "食品", "is_correct": false, "explanation": "语义：“食品”指可以吃的东西，自闭症不是食品，句子搭配不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是演奏用的器具，自闭症不是乐器，句子意思不通。"}, {"text": "事儿", "is_correct": false, "explanation": "语域：“事儿”是口语说法，与这篇书面报道的语体不合。"}], "explanations": {"谱系": "正确：“自闭症谱系”指一组从轻到重的障碍，正是这篇报道研究的对象。", "食品": "语义：“食品”指可以吃的东西，自闭症不是食品，句子搭配不通。", "乐器": "语义：“乐器”是演奏用的器具，自闭症不是乐器，句子意思不通。", "事儿": "语域：“事儿”是口语说法，与这篇书面报道的语体不合。"}, "sentence_index": 6, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生带家长参观了谱系，让他们明白病情有轻有重。", "explanation": "这里应该用〈病房〉。谱系是一组障碍在程度上的分布范围，不是可以参观的场所；“参观”的对象要用“病房”等场所。"}, {"text": "他的谱系很温和。", "explanation": "这里应该用〈性格〉。谱系指一组障碍在程度上的分布范围，不是个人的性格；说“性格温和”要用“性格”。"}, {"text": "这间屋子的谱系很大。", "explanation": "这里应该用〈面积〉。谱系指一组障碍在程度上的分布范围，不是物体的大小；说屋子大要用“面积”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者把自闭症看作一颗谱系，患者的表现差别很大。", "corrected_sentence": "研究者把自闭症看作一个谱系，患者的表现差别很大。", "error_description": "“一颗谱系”应改为“一个谱系”。“颗”用于颗粒状或圆形的小东西，不能修饰抽象的“谱系”，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学者把这些障碍归在一颗谱系里。", "corrected_sentence": "学者把这些障碍归在一个谱系里。", "error_description": "“一颗谱系”应改为“一个谱系”。“颗”用于颗粒状或圆形的小东西，不能修饰抽象的“谱系”，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
