INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "障碍指阻挡前进或发展的困难或问题。", "primary_collocate": null, "pronunciation": "zhàng ài", "ipa": "ʈʂɑŋ˥˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "语言不是我们交朋友的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他克服了学习上的很多障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少钱是创业的最大障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "害怕失败常常是成功路上的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题成了我们合作的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮他消除了心理障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到障碍时，不要马上放弃。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年龄不应该成为学习的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要一起努力，越过这些障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交流中的最大障碍是不愿意听别人说话。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道障碍", "label": "量词"}, {"form": "障礙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "阻碍发展或前进的抽象困难、问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84185793-b8d0-46b1-818d-128e201d234b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "障碍", "is_correct": true, "explanation": "“障碍”指阻挡前进的困难，与“交朋友”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是交朋友的事物，“交朋友的天气”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能作为交朋友的阻碍，句子不成立。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“交作业”是常见搭配，但“交朋友的作业”不成立。"}], "explanations": {"障碍": "“障碍”指阻挡前进的困难，与“交朋友”的语境相符。", "天气": "语义：天气不是交朋友的事物，“交朋友的天气”说不通。", "厨房": "语义：厨房是场所，不能作为交朋友的阻碍，句子不成立。", "作业": "搭配：“交作业”是常见搭配，但“交朋友的作业”不成立。"}, "sentence_index": 0, "correct_answer": "障碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的讲话很障碍，大家都听得津津有味。", "explanation": "这里应该用〈生动〉。“障碍”是名词，不能用来形容讲话的好坏，应说“生动”。"}, {"text": "这道菜做得很障碍，大家都说好吃。", "explanation": "这里应该用〈美味〉。“障碍”是名词，不能用来形容菜做得好坏，应说“美味”。"}, {"text": "她的声音很障碍，很适合唱歌。", "explanation": "这里应该用〈动听〉。“障碍”是名词，不能用来形容声音，应说“动听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "障碍", "is_correct": true, "explanation": "“障碍”指阻挡前进的困难，与“遇到……时，不要放弃”相符。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不是需要放弃的事情，“遇到镜子时不要放弃”说不通。"}, {"text": "步伐", "is_correct": false, "explanation": "搭配：“遇到”后接困难、问题，“步伐”是行走的节奏，不能说遇到步伐。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是需要放弃的事情，“遇到窗户时不要放弃”没有意义。"}], "explanations": {"障碍": "“障碍”指阻挡前进的困难，与“遇到……时，不要放弃”相符。", "镜子": "语义：镜子不是需要放弃的事情，“遇到镜子时不要放弃”说不通。", "步伐": "搭配：“遇到”后接困难、问题，“步伐”是行走的节奏，不能说遇到步伐。", "窗户": "语义：窗户不是需要放弃的事情，“遇到窗户时不要放弃”没有意义。"}, "sentence_index": 6, "correct_answer": "障碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们遇到了一本新的障碍，只好暂停讨论。", "explanation": "这里应该用〈道〉。抽象的障碍用量词“道”，“本”用于书册，不用于障碍。"}, {"text": "这件事给我们的合作带来了一支障碍，大家只好暂停。", "explanation": "这里应该用〈道〉。抽象的障碍用量词“道”，“支”用于笔、队伍等，不用于障碍。"}, {"text": "这件事成了两家人之间的一把障碍。", "explanation": "这里应该用〈道〉。抽象的障碍用量词“道”，“把”用于椅子、刀等有柄或有座的物体，不用于障碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于越过了这条障碍。", "corrected_sentence": "他终于越过了这道障碍。", "error_description": "量词错误：“障碍”作抽象的困难时，量词应为“道”，不能用“条”。“这条障碍”应改为“这道障碍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事成了我们之间的一座障碍。", "corrected_sentence": "这件事成了我们之间的一道障碍。", "error_description": "量词错误：抽象的“障碍”用量词“道”，“座”用于山、桥、房屋等大型物体。“一座障碍”应改为“一道障碍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
