INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生病的人，通常指正在接受治疗的人。", "primary_collocate": null, "pronunciation": "huàn zhě", "ipa": "xwan˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "医生正在给患者检查身体。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位患者今天要做手术。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者的家人在门口等着。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士问患者哪里不舒服。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有很多患者。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对患者说：“你要多休息。”", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个患者已经住院三天了。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者吃了药，现在好多了。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把检查结果告诉了患者。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者需要安静，请不要大声说话。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位患者", "label": "量词"}, {"form": "一名患者", "label": "量词"}], "register": "书面", "sense_fingerprint": "患者：正在接受治疗的病人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "患者", "is_correct": true, "explanation": "正确。“患者”指正在接受治疗的病人，可以被医生检查身体，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“检查身体”的对象必须是人，汽车没有身体，句子不成立。"}, {"text": "树", "is_correct": false, "explanation": "语义：树木没有身体，不能作为“检查身体”的对象。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“给……检查身体”要求以人为对象，“书包”不能与之搭配。"}], "explanations": {"患者": "正确。“患者”指正在接受治疗的病人，可以被医生检查身体，符合句意。", "汽车": "语义：“检查身体”的对象必须是人，汽车没有身体，句子不成立。", "树": "语义：树木没有身体，不能作为“检查身体”的对象。", "书包": "搭配：“给……检查身体”要求以人为对象，“书包”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "患者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的患者很多，老板很高兴。", "explanation": "这里应该用〈顾客〉。患者指生病、接受治疗的人，不用于指到店里消费的人。"}, {"text": "这所学校有两千名患者，每天都很热闹。", "explanation": "这里应该用〈学生〉。患者指生病、接受治疗的人，不用于指在学校上课的人。"}, {"text": "这场演唱会的患者都很激动，大声地唱起了歌。", "explanation": "这里应该用〈观众〉。患者指生病、接受治疗的人，不指到场听演唱会的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "患者", "is_correct": true, "explanation": "正确。“患者”是正在住院治疗的人，“住院三天”符合句意。"}, {"text": "医院", "is_correct": false, "explanation": "语义：住院的主体是病人，医院是机构，不能住院。"}, {"text": "病床", "is_correct": false, "explanation": "搭配：“住院”的主语须是人，“病床”不能与“住院三天了”搭配。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是场所，不能作为住院的主体。"}], "explanations": {"患者": "正确。“患者”是正在住院治疗的人，“住院三天”符合句意。", "医院": "语义：住院的主体是病人，医院是机构，不能住院。", "病床": "搭配：“住院”的主语须是人，“病床”不能与“住院三天了”搭配。", "病房": "语义：病房是场所，不能作为住院的主体。"}, "sentence_index": 6, "correct_answer": "患者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园的患者都在拍照，很热闹。", "explanation": "这里应该用〈游客〉。患者指生病、接受治疗的人，不用于指在公园游玩的人。"}, {"text": "这场比赛的患者是三名经验丰富的老裁判。", "explanation": "这里应该用〈裁判〉。患者指生病、接受治疗的人，不指在比赛中执法的人。"}, {"text": "球场上的患者跑得很快，已经进了两个球。", "explanation": "这里应该用〈球员〉。患者指生病、接受治疗的人，不指在球场比赛的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院里来了一条患者，他一直在咳嗽。", "corrected_sentence": "医院里来了一位患者，他一直在咳嗽。", "error_description": "“患者”指人，量词应用“位”或“名”。“条”用于细长的东西，不能用来数人，应改为“一位患者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急诊室里有三患者，医生正在检查。", "corrected_sentence": "急诊室里有三位患者，医生正在检查。", "error_description": "数词“三”与名词之间漏了量词，“患者”指人，应说“三位患者”，不能说“三患者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
