INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指个体能够理解和感受他人情感的能力。", "primary_collocate": null, "pronunciation": "gòng qíng", "ipa": "kʊŋ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "随着神经科学的发展，这一古老而普遍的现象正逐步从日常观察升华为理解意识、共情与脑功能整合的重要切入点。", "target_word": "共情", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好医生要对患者有共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的共情需要慢慢培养。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的共情让朋友觉得很温暖。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有共情的人更容易理解别人。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生缺少共情，学生不愿意说话。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共情是理解别人感受的一种能力。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做客服工作需要很强的共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会听别人说话，共情也很强。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少共情，我们就很难成为好朋友。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共情力", "label": "复合"}, {"form": "共情能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "共情：理解和感受他人情感的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11259, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。gòng qíng，指理解和感受他人情感的能力。"}, {"text": "动情", "is_correct": false, "explanation": "声母不同：dòng（d）与 gòng（g），意思是感情被打动，与“理解他人感受的能力”不同。"}, {"text": "纵情", "is_correct": false, "explanation": "声母不同：zòng（z）与 gòng（g），意思是放纵感情、无拘无束。"}, {"text": "共庆", "is_correct": false, "explanation": "声调不同：qìng（第四声）与 qíng（第二声），意思是共同庆祝。"}], "explanations": {"共情": "正确。gòng qíng，指理解和感受他人情感的能力。", "动情": "声母不同：dòng（d）与 gòng（g），意思是感情被打动，与“理解他人感受的能力”不同。", "纵情": "声母不同：zòng（z）与 gòng（g），意思是放纵感情、无拘无束。", "共庆": "声调不同：qìng（第四声）与 qíng（第二声），意思是共同庆祝。"}, "sentence_index": null, "correct_answer": "共情"}, "level_3": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。与“理解意识”“脑功能整合”并列，指理解他人情感的能力，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于心理或认知功能，不能与“理解意识”并列，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不属于认知功能，不能与脑功能并列。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“与……整合”要求前后都是心理或认知类词语，“价格”不能与之搭配。"}], "explanations": {"共情": "正确。与“理解意识”“脑功能整合”并列，指理解他人情感的能力，符合句意。", "颜色": "语义：颜色不属于心理或认知功能，不能与“理解意识”并列，句子不通。", "体重": "语义：体重是身体的数值，不属于认知功能，不能与脑功能并列。", "价格": "搭配：“与……整合”要求前后都是心理或认知类词语，“价格”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "共情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的共情很强，开机只要三秒。", "explanation": "这里应该用〈速度〉。共情指理解和感受他人情感的能力，不用来说明电脑的运行快慢。"}, {"text": "这张桌子的共情是一米二，正好适合坐。", "explanation": "这里应该用〈高度〉。共情指理解和感受他人情感的能力，不用来说明桌子的高矮。"}, {"text": "这块布料的共情很好，穿起来很舒服。", "explanation": "这里应该用〈质量〉。共情是人理解他人感受的能力，不用来描述布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。作主语，指理解别人感受的能力，与句意一致。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是理解别人感受的能力。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然物，不能是心理能力。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“……的一种能力”的主语须是心理或认知类词语，“作业”不能与之搭配。"}], "explanations": {"共情": "正确。作主语，指理解别人感受的能力，与句意一致。", "冰箱": "语义：冰箱是家电，不是理解别人感受的能力。", "河流": "语义：河流是自然物，不能是心理能力。", "作业": "搭配：“……的一种能力”的主语须是心理或认知类词语，“作业”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "共情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的共情很大，能住下十个人。", "explanation": "这里应该用〈面积〉。共情指理解他人感受的能力，不能描述房屋的大小。"}, {"text": "这个路口的共情很危险，经常出车祸。", "explanation": "这里应该用〈路况〉。共情指理解和感受他人情感的能力，不用来描述路面的状况。"}, {"text": "妈妈做的菜很香，全家人都说她的共情好。", "explanation": "这里应该用〈厨艺〉。共情指理解他人感受的能力，不用来评价做饭的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只很强的共情能力，能很快体会到朋友的难过。", "corrected_sentence": "她有一种很强的共情能力，能很快体会到朋友的难过。", "error_description": "“共情能力”是抽象名词，量词应用“种”。“只”用于动物，不能修饰抽象名词，应改为“一种很强的共情能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一把很强的共情，朋友有困难时总是先理解他们。", "corrected_sentence": "他有一种很强的共情，朋友有困难时总是先理解他们。", "error_description": "错误形式：“一把很强的共情”；正确形式：“一种很强的共情”。“共情”在此作抽象名词，量词用“种”，“把”用于带柄的器具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
