INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指力量、能力、意志等方面比较弱的人。", "primary_collocate": null, "pronunciation": "ruò zhě", "ipa": "ʐuɔ˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们应该帮助弱者，不能看不起他们。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就不想做弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个故事里，小男孩是一个弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人会站出来保护弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人和孩子常常是社会中的弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强者不会欺负弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同情弱者，常常给流浪的人送饭。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弱者只会抱怨，强者会想办法。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门帮助弱者找工作。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，只有弱者才会放弃。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个弱者", "label": "量词"}, {"form": "社会弱者", "label": "复合"}], "register": "中性", "sense_fingerprint": "力量、能力或意志较弱的人，常与强者相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弱者", "is_correct": true, "explanation": "正确：指力量或能力较弱、需要帮助的人，与“帮助”“不能看不起他们”的语境相合。"}, {"text": "强者", "is_correct": false, "explanation": "语义：强者一般不需要别人帮助，与“帮助”的语境相反。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“帮助”的对象须是人，不能说帮助桌子。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能被帮助，后面的“他们”也无法指代它。"}], "explanations": {"弱者": "正确：指力量或能力较弱、需要帮助的人，与“帮助”“不能看不起他们”的语境相合。", "强者": "语义：强者一般不需要别人帮助，与“帮助”的语境相反。", "桌子": "搭配：“帮助”的对象须是人，不能说帮助桌子。", "空气": "搭配：空气不能被帮助，后面的“他们”也无法指代它。"}, "sentence_index": 0, "correct_answer": "弱者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最大的弱者是太心软。", "explanation": "这里应该用〈弱点〉。弱者指力量或能力较弱的人，不能指缺点。"}, {"text": "他是我最亲密的弱者，什么事都愿意和我分享。", "explanation": "这里应该用〈朋友〉。弱者指力量或能力较弱的人，不能用来指亲密的关系。"}, {"text": "他数学很好，但英语是他的弱者。", "explanation": "这里应该用〈弱项〉。弱者指人，不指某门学科上的薄弱之处，那要说弱项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弱者", "is_correct": true, "explanation": "正确：指力量较弱、需要同情和帮助的人，与“同情”“送饭”的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：同情的对象须是有感受的人，石头不能被同情。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不能被同情，“同情窗户”不成话。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军不需要同情，与下文“常常给流浪的人送饭”的语境不合。"}], "explanations": {"弱者": "正确：指力量较弱、需要同情和帮助的人，与“同情”“送饭”的语境相合。", "石头": "搭配：同情的对象须是有感受的人，石头不能被同情。", "窗户": "搭配：窗户不能被同情，“同情窗户”不成话。", "冠军": "语义：冠军不需要同情，与下文“常常给流浪的人送饭”的语境不合。"}, "sentence_index": 6, "correct_answer": "弱者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支队伍的弱者很明显，需要加强训练。", "explanation": "这里应该用〈弱点〉。弱者指人，不指队伍的薄弱之处，要说弱点。"}, {"text": "这本书的弱者是一位著名的学者。", "explanation": "这里应该用〈作者〉。弱者指力量弱的人，不指写书的人，两者不能混用。"}, {"text": "这场比赛的弱者很公正。", "explanation": "这里应该用〈裁判〉。弱者指力量弱的人，不指比赛中负责执法的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是班里的一只弱者，大家都愿意帮助他。", "corrected_sentence": "他是班里的弱者，大家都愿意帮助他。", "error_description": "量词错误：“弱者”指人，前面不能加“一只”（“只”多用于动物）。正确说法是“他是班里的弱者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动是为了帮助很多弱者们，大家都很高兴。", "corrected_sentence": "这次活动是为了帮助很多弱者，大家都很高兴。", "error_description": "“很多”和“们”不能同时用，“弱者”后不加“们”。正确说法是“很多弱者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
