INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11263, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "表示针对前面提到的事情或情况", "primary_collocate": null, "pronunciation": "duì cǐ", "ipa": "tweɪ˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师今天迟到了，对此，同学们都很吃惊。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定明年涨价，对此我没有意见。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己没有错，对此，我不太同意。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法很好，大家对此都很满意。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王要去国外工作，对此，家人都很支持。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想上学，对此，妈妈很着急。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天可能下大雨，请大家对此做好准备。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格越来越高，很多人对此很不满。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了新工作，对此我一点也不知道。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很复杂，我还要对此想一想。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "针对前文提到的事情或情况，引出态度或反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对此", "is_correct": true, "explanation": "正确：指代前文“老师今天迟到了”这件事，引出同学们的反应。"}, {"text": "对于", "is_correct": false, "explanation": "配价：「对于」后须接宾语，“对于，同学们都很吃惊”不成句。"}, {"text": "关于", "is_correct": false, "explanation": "配价：「关于」后须接话题，此处缺少宾语，不成句。"}, {"text": "至于", "is_correct": false, "explanation": "语义：「至于」引出另起的话题，而“对此”是指代前文的事，二者语义不符。"}], "explanations": {"对此": "正确：指代前文“老师今天迟到了”这件事，引出同学们的反应。", "对于": "配价：「对于」后须接宾语，“对于，同学们都很吃惊”不成句。", "关于": "配价：「关于」后须接话题，此处缺少宾语，不成句。", "至于": "语义：「至于」引出另起的话题，而“对此”是指代前文的事，二者语义不符。"}, "sentence_index": 0, "correct_answer": "对此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案很便宜，对此，它也很环保。", "explanation": "这里应该用〈此外〉。“对此”针对前文的事情作出回应，不能用来补充新的情况，补充要说“此外”。"}, {"text": "我们正在吃饭，对此电话响了。", "explanation": "这里应该用〈此时〉。“对此”指针对前文的事情，不能表示时间。"}, {"text": "他走了很远的路，对此累了。", "explanation": "这里应该用〈于是〉。“对此”指针对前文的事情，不能表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对此", "is_correct": true, "explanation": "正确：指代前文“明天可能下大雨”这件事，引出后面的要求。"}, {"text": "根据", "is_correct": false, "explanation": "配价：「根据」后须接依据，“请大家根据做好准备”不成句。"}, {"text": "按照", "is_correct": false, "explanation": "配价：「按照」后须接依据或标准，此处没有宾语，不成句。"}, {"text": "鉴于", "is_correct": false, "explanation": "语义：「鉴于」表示原因，而这里是对大家提出要求，前后意思对不上。"}], "explanations": {"对此": "正确：指代前文“明天可能下大雨”这件事，引出后面的要求。", "根据": "配价：「根据」后须接依据，“请大家根据做好准备”不成句。", "按照": "配价：「按照」后须接依据或标准，此处没有宾语，不成句。", "鉴于": "语义：「鉴于」表示原因，而这里是对大家提出要求，前后意思对不上。"}, "sentence_index": 6, "correct_answer": "对此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书很厚，我对此看了一个星期。", "explanation": "这里“对此”是介词，表示针对前文的事情，不能直接修饰“看”这样的动作。"}, {"text": "他很喜欢唱歌，我们对此去了公园。", "explanation": "这里应去掉〈对此〉。“对此”引出的是对前文事情的态度，不能引出新的动作。"}, {"text": "我们今天很开心，我们对此说了再见。", "explanation": "这里应该用〈向大家〉。“对此”指事情或情况，不能引出说再见的对象（人）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板宣布放假，对此的大家都很高兴。", "corrected_sentence": "老板宣布放假，对此大家都很高兴。", "error_description": "“对此”是介词，后面不能加“的”。正确说法是“对此大家都很高兴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动很成功，对此了我们很骄傲。", "corrected_sentence": "这次活动很成功，对此我们很骄傲。", "error_description": "“对此”后不能加“了”，“了”不能附在介词上。正确说法是“对此我们很骄傲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
