INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11265, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "清楚地显露出来，容易让人看出或感觉到。", "primary_collocate": null, "pronunciation": "míng xiǎn", "ipa": "miŋ˧˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他今天的变化很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张照片的区别非常明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的错误太明显了。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷的迹象很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明显比去年高了。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，他的进步很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药吃了三天，效果还不明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的不高兴很明显，大家都看出来了。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的答案很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的红线特别明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不明显", "label": "否定形式"}, {"form": "明显地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "变化、差别、效果等清楚显露，让人一看就知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明显", "is_correct": true, "explanation": "“明显”指变化清楚可见，与“变化很”搭配，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容声音或环境，不用来形容变化。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的年龄，不能修饰“变化”。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”描述人的身材，不能用来形容“变化”的程度。"}], "explanations": {"明显": "“明显”指变化清楚可见，与“变化很”搭配，符合句意。", "安静": "搭配：“安静”形容声音或环境，不用来形容变化。", "年轻": "语义：“年轻”形容人的年龄，不能修饰“变化”。", "苗条": "体貌：“苗条”描述人的身材，不能用来形容“变化”的程度。"}, "sentence_index": 0, "correct_answer": "明显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对那件事记得很明显。", "explanation": "这里应该用〈清楚〉。“明显”指容易看出，说记忆的清晰程度要用“清楚”，如“记得很清楚”。"}, {"text": "这份实验的测量很明显。", "explanation": "这里应该用〈精确〉。“明显”表示容易看出，测量的准确度要用“精确”。"}, {"text": "他喝完酒以后头脑很明显。", "explanation": "这里应该用〈清醒〉。“明显”指容易看出，形容头脑的清醒状态要用“清醒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明显", "is_correct": true, "explanation": "“明显”指效果清楚可见，与“效果还不”搭配，符合句意。"}, {"text": "舒服", "is_correct": false, "explanation": "搭配：“舒服”描述身体或心理感受，不能用来形容“效果”。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音高亮，不能用来形容“效果”。"}, {"text": "煊赫", "is_correct": false, "explanation": "语域：“煊赫”是书面语，形容声势显赫，口语描述“效果”不用此词。"}], "explanations": {"明显": "“明显”指效果清楚可见，与“效果还不”搭配，符合句意。", "舒服": "搭配：“舒服”描述身体或心理感受，不能用来形容“效果”。", "嘹亮": "语义：“嘹亮”形容声音高亮，不能用来形容“效果”。", "煊赫": "语域：“煊赫”是书面语，形容声势显赫，口语描述“效果”不用此词。"}, "sentence_index": 6, "correct_answer": "明显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做研究很明显。", "explanation": "这里应该用〈严谨〉。“明显”指容易看出，形容做研究的态度和方法要用“严谨”。"}, {"text": "她的数字计算很明显。", "explanation": "这里应该用〈准确〉。“明显”表示容易被看出，计算的正确性要用“准确”。"}, {"text": "这间屋子的空气很明显。", "explanation": "这里应该用〈清新〉。“明显”指容易看出，形容空气的干净爽朗要用“清新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的差距很明显地。", "corrected_sentence": "这次比赛的差距很明显。", "error_description": "“明显”作谓语时句末不能加“地”，应说“很明显”。“地”用于修饰动词，如“明显地增加”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛，他明显的比以前强了。", "corrected_sentence": "这次比赛，他明显比以前强了。", "error_description": "“明显”作状语修饰“比以前强”时，后面不能加“的”，应为“明显比以前强”。“的”只用于修饰名词，如“明显的进步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”指力量、强度变大，与“减弱”意义相反，构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是一种日常活动，与“减弱”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停止工作或活动以恢复精力，与“减弱”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子分析问题，与“减弱”没有反义关系。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”指力量、强度变大，与“减弱”意义相反，构成反义关系。", "散步": "“散步”是一种日常活动，与“减弱”没有反义关系。", "休息": "“休息”指停止工作或活动以恢复精力，与“减弱”没有反义关系。", "思考": "“思考”指用脑子分析问题，与“减弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”指力量、强度变大，与“减弱”意义相反，构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种体育活动，与“减弱”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演歌曲，与“减弱”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“减弱”没有反义关系。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”指力量、强度变大，与“减弱”意义相反，构成反义关系。", "游泳": "“游泳”是一种体育活动，与“减弱”没有反义关系。", "唱歌": "“唱歌”指用声音表演歌曲，与“减弱”没有反义关系。", "旅行": "“旅行”指到外地游览，与“减弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指力量、程度、强度等逐渐变小或降低。", "primary_collocate": null, "pronunciation": "jiǎn ruò", "ipa": "tɕjɛn˨˩˦ ʐwo˧˥", "syllable_count": 2, "sentences": [{"text": "风慢慢减弱了，海面又安静下来。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨渐渐减弱，天空慢慢亮了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了药以后，他的头疼逐渐减弱。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走远以后，音乐的声音渐渐减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风登陆后，风力会逐渐减弱。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳下山以后，阳光的热度开始减弱。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过一个星期的休息，他腿上的疼痛明显减弱了。", "target_word": "减弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药的效果过了几个小时就会减弱。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震过后，震动的力量一点一点减弱。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开以后，我对这件事的兴趣慢慢减弱了。", "target_word": "减弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减弱了", "label": "完成体"}, {"form": "减弱过", "label": "经历体"}, {"form": "減弱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "力量、程度、强度等逐渐变小、变弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减弱", "is_correct": true, "explanation": "“减弱”指风力逐渐变小，与“风慢慢…了”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于“风”。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”是人的书面活动，风不能写作。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要具体的受事宾语（修理某物），单独以“风”作主语不成立。"}], "explanations": {"减弱": "“减弱”指风力逐渐变小，与“风慢慢…了”搭配，符合句意。", "吃": "搭配：“吃”的对象是食物，不能用于“风”。", "写作": "语义：“写作”是人的书面活动，风不能写作。", "修理": "配价：“修理”需要具体的受事宾语（修理某物），单独以“风”作主语不成立。"}, "sentence_index": 0, "correct_answer": "减弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工作量减弱了。", "explanation": "这里应该用〈减少〉。“减弱”说力量、强度变弱，工作量这类数量要用“减少”。"}, {"text": "他的体重减弱了很多。", "explanation": "这里应该用〈减轻〉。“减弱”指力量、强度变小，体重的减少要用“减轻”。"}, {"text": "股票价格减弱了许多。", "explanation": "这里应该用〈下降〉。“减弱”指力量、强度变小，价格、指数的下跌要用“下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减弱", "is_correct": true, "explanation": "“减弱”指疼痛逐渐变轻，与“疼痛明显…了”搭配，符合句意。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物的成长，疼痛不能“生长”。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”用于费用、开支，不能用于疼痛。"}, {"text": "凋零", "is_correct": false, "explanation": "语域：“凋零”是书面语，多指花草衰败，不用来形容疼痛。"}], "explanations": {"减弱": "“减弱”指疼痛逐渐变轻，与“疼痛明显…了”搭配，符合句意。", "生长": "语义：“生长”指生物的成长，疼痛不能“生长”。", "报销": "搭配：“报销”用于费用、开支，不能用于疼痛。", "凋零": "语域：“凋零”是书面语，多指花草衰败，不用来形容疼痛。"}, "sentence_index": 6, "correct_answer": "减弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张图片的面积减弱了。", "explanation": "这里应该用〈缩小〉。“减弱”指力量、强度变弱，面积、体积变小要用“缩小”。"}, {"text": "今年的预算减弱了一半。", "explanation": "这里应该用〈缩减〉。“减弱”指力量或强度变小，经费等数额的削减要用“缩减”。"}, {"text": "他跑步的速度减弱了许多。", "explanation": "这里应该用〈减慢〉。“减弱”指力量、强度变小，速度的变慢要用“减慢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，风力减弱地很快。", "corrected_sentence": "雨停以后，风力减弱得很快。", "error_description": "补语前应用“得”，不用“地”。“地”修饰动词，如“慢慢地减弱”；“减弱得很快”中的“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风慢慢减弱出来了。", "corrected_sentence": "风慢慢减弱下来了。", "error_description": "表示逐渐变弱的结果，补语应用“下来”，不用“出来”；“减弱出来”不符合汉语的搭配习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用含蓄、间接的方式表达意思，使对方领会。", "primary_collocate": null, "pronunciation": "àn shì", "ipa": "an˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "暗示", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他看了看表，是在暗示我该走了。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有明说，只是暗示我早点回家。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师暗示我们，这次考试会有难题。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她冲我笑了笑，暗示事情可以办了。", "target_word": "暗示", "complexity_tier": "T3", "furigana": "tā chōng wǒ xiào le xiào àn shì shì qíng kě yǐ bàn le", "sentence_source": "generated"}, {"text": "他一直看着门口，暗示客人该离开了。", "target_word": "暗示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有直接拒绝，只是暗示这件事很难办。", "target_word": "暗示", "complexity_tier": "T3", "furigana": "tā méi yǒu zhí jiē jù jué zhǐ shì àn shì zhè jiàn shì hěn nán bàn", "sentence_source": "generated"}, {"text": "经理没有直接批评，只是暗示他做得不够好。", "target_word": "暗示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友没有说破，只是暗示我们可以先回去。", "target_word": "暗示", "complexity_tier": "T3", "furigana": "péng yǒu méi yǒu shuō pò zhǐ shì àn shì wǒ men kě yǐ xiān huí qù", "sentence_source": "generated"}, {"text": "她用眼神暗示我，不要说话。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗示了", "label": "体标"}, {"form": "暗示着", "label": "体标"}, {"form": "暗示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用含蓄、间接的方式（话语、眼神、象征）表达意思，让对方自己领会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指含蓄地表达意思。“既暗示物质的无限循环”与后文的语境相符，只有“暗示”能填入。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出缺点，不能用来表达对物质循环的含蓄意思。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是可量度的数值，不能说“测量物质的无限循环”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与图形传递能量感的语境相冲突。"}], "explanations": {"暗示": "暗示指含蓄地表达意思。“既暗示物质的无限循环”与后文的语境相符，只有“暗示”能填入。", "批评": "语义：“批评”指指出缺点，不能用来表达对物质循环的含蓄意思。", "测量": "搭配：“测量”的对象是可量度的数值，不能说“测量物质的无限循环”。", "拒绝": "语义：“拒绝”表示不接受，与图形传递能量感的语境相冲突。"}, "sentence_index": 0, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他直接暗示我，我不同意这个计划。", "explanation": "这里应该用〈直接告诉〉。暗示是含蓄地表达，不能与“直接”搭配。"}, {"text": "校长正式暗示全校，明天停课。", "explanation": "这里应该用〈宣布〉。暗示是含蓄地表达，正式的公开通知不能用暗示。"}, {"text": "他把计划的每一步都逐条暗示了一遍。", "explanation": "这里应该用〈逐条说明〉。暗示只让人领会意思，不能把每一步都明确地逐条讲出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指含蓄地表达。“没有直接拒绝，只是暗示这件事很难办”，只有“暗示”能填入。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“这件事很难办”的意思相反。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”指改动，不能与“表达难办”的意思搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示想不起来，与句子表达的意思不符。"}], "explanations": {"暗示": "暗示指含蓄地表达。“没有直接拒绝，只是暗示这件事很难办”，只有“暗示”能填入。", "赞美": "语义：“赞美”表示称赞，与“这件事很难办”的意思相反。", "修改": "搭配：“修改”指改动，不能与“表达难办”的意思搭配。", "忘记": "语义：“忘记”表示想不起来，与句子表达的意思不符。"}, "sentence_index": 6, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长在黑板上暗示了今天的作业，要大家背完第三课。", "explanation": "这里应该用〈公布〉。暗示是含蓄表达，写在黑板上的作业应直接公布，不能用暗示。"}, {"text": "他在信里暗示了我的名字和地址，写得清清楚楚。", "explanation": "这里应该用〈写明〉。暗示是含蓄表达，不能用来清清楚楚地写明具体信息。"}, {"text": "她大声地暗示了自己的名字，大家都听清楚了。", "explanation": "这里应该用〈报出〉。暗示是含蓄表达，不能与“大声”这样直接的说法搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她没有明说，只是暗示了过我别多嘴。", "corrected_sentence": "她没有明说，只是暗示我别多嘴。", "error_description": "“暗示”后面同时加了“了”和“过”。两种体标不能同时使用，这里应只说“暗示我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没开口，她已经明白我在暗示了什么。", "corrected_sentence": "我还没开口，她已经明白我在暗示什么。", "error_description": "“在”表示动作正在进行，与表示完成的“了”不能搭配。应说“在暗示什么”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
