INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11268, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容彼此间关系非常密切。", "primary_collocate": null, "pronunciation": "mì qiè xiāng guān", "ipa": "mi˥˩ tɕʰjɛ˥˩ ɕjaŋ˥ kwan˥", "syllable_count": 4, "sentences": [{"text": "值得注意的是，这种社会性传染并非普遍存在于所有个体——自闭症谱系障碍患者或共情能力较弱者对此反应明显减弱，暗示该行为与社交认知能力密切相关。", "target_word": "密切相关", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "睡眠和健康密切相关。", "target_word": "密切相关", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃什么与身体好不好密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的成绩和父母的关心密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气质量与人们的生活密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两件事看起来不同，其实密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究发现，运动习惯与心情密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的发展与交通状况密切相关。", "target_word": "密切相关", "complexity_tier": "T3", "furigana": "chéng shì de fā zhǎn yǔ jiāo tōng zhuàng kuàng mì qiè xiāng guān", "sentence_source": "generated"}, {"text": "他的工作和我们的计划密切相关，不能不管。", "target_word": "密切相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜的价格与天气的变化密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "密切相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "两者之间联系紧密，关系非常近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密切相关", "is_correct": true, "explanation": "“密切相关”指两者联系紧密，与“暗示该行为与社交认知能力……”的推断一致。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”说距离远，与句中“暗示该行为与……有关”的推断相反。"}, {"text": "陌生", "is_correct": false, "explanation": "配价：“陌生”要用“对……陌生”的结构，不能用“与……陌生”，意思也与前文不符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，不能用来说明能力之间的关系。"}], "explanations": {"密切相关": "“密切相关”指两者联系紧密，与“暗示该行为与社交认知能力……”的推断一致。", "遥远": "语义：“遥远”说距离远，与句中“暗示该行为与……有关”的推断相反。", "陌生": "配价：“陌生”要用“对……陌生”的结构，不能用“与……陌生”，意思也与前文不符。", "高大": "体貌：“高大”形容人或物的形体，不能用来说明能力之间的关系。"}, "sentence_index": 0, "correct_answer": "密切相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和她是很密切相关的好朋友。", "explanation": "这里应该用〈亲密〉。“密切相关”说的是事物之间的联系，不用来形容人与人之间的感情。"}, {"text": "这两个孩子长得很密切相关。", "explanation": "这里应该用〈相似〉。“密切相关”说的是两件事之间的联系，不用来说两个人外貌相像。"}, {"text": "他对大自然很密切相关。", "explanation": "这里应该用〈熟悉〉。“密切相关”说的是事物之间的联系，不用来说一个人对某事物了解得多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密切相关", "is_correct": true, "explanation": "“密切相关”指运动习惯与心情之间有紧密联系，与“研究发现”的结论一致。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能用来说习惯与心情的关系。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：“笔直”形容形状或姿态，不用于描述心情。"}, {"text": "生硬", "is_correct": false, "explanation": "搭配：“生硬”多用来形容语言或态度，不与“心情”搭配。"}], "explanations": {"密切相关": "“密切相关”指运动习惯与心情之间有紧密联系，与“研究发现”的结论一致。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能用来说习惯与心情的关系。", "笔直": "体貌：“笔直”形容形状或姿态，不用于描述心情。", "生硬": "搭配：“生硬”多用来形容语言或态度，不与“心情”搭配。"}, "sentence_index": 6, "correct_answer": "密切相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事跟我只是有一点密切相关。", "explanation": "这里应该用〈有关〉。“只是有一点”说明关系较弱，与“密切相关”强调联系紧密不符。"}, {"text": "这家饭馆的服务很密切相关。", "explanation": "这里应该用〈亲切〉。“密切相关”说的是两件事之间的联系，不用来形容服务的态度。"}, {"text": "我家离学校很密切相关。", "explanation": "这里应该用〈近〉。说距离远近要用“近”，“密切相关”不用来描述空间距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气的变化被交通的便利密切相关。", "corrected_sentence": "天气的变化与交通的便利密切相关。", "error_description": "错误：“被”表被动，“密切相关”不能用于被动句。正确：应用“与”引出关联对象，即“与……密切相关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市的交通把居民的出行密切相关。", "corrected_sentence": "城市的交通与居民的出行密切相关。", "error_description": "错误：“把”字引出“居民的出行”。正确：应用“与”引出关联对象，“密切相关”不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退化", "is_correct": true, "explanation": "退化：指生物器官或功能由复杂变简单、由高级变低级，与“进化”方向相反。"}, {"text": "学习", "is_correct": false, "explanation": "学习：指获得知识或技能，与“进化”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指到外地游览，与“进化”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用声音表现乐曲，与“进化”没有反义关系。"}], "correct_answer": "退化", "explanations": {"退化": "退化：指生物器官或功能由复杂变简单、由高级变低级，与“进化”方向相反。", "学习": "学习：指获得知识或技能，与“进化”没有反义关系。", "旅行": "旅行：指到外地游览，与“进化”没有反义关系。", "唱歌": "唱歌：指用声音表现乐曲，与“进化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退化", "is_correct": true, "explanation": "退化：指生物器官或功能由复杂变简单、由高级变低级，与“进化”方向相反。"}, {"text": "写作", "is_correct": false, "explanation": "写作：指写文章或文学作品，与“进化”没有反义关系。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰：指美化物品的外观，与“进化”没有反义关系。"}, {"text": "烧毁", "is_correct": false, "explanation": "烧毁：指用火烧坏，与“进化”的变化过程没有对立关系。"}], "correct_answer": "退化", "explanations": {"退化": "退化：指生物器官或功能由复杂变简单、由高级变低级，与“进化”方向相反。", "写作": "写作：指写文章或文学作品，与“进化”没有反义关系。", "装饰": "装饰：指美化物品的外观，与“进化”没有反义关系。", "烧毁": "烧毁：指用火烧坏，与“进化”的变化过程没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物体在长时间里逐渐变化，变得更适应环境的过程。", "primary_collocate": null, "pronunciation": "jìn huà", "ipa": "tɕin˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这种系统级创新使清洁能源从补充性能源，进化为新型电力系统的基石。", "target_word": "进化", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "从进化角度看，打哈欠的传染性可能是一种原始的群体同步机制。", "target_word": "进化", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "鸟是从恐龙慢慢进化来的。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物为了活下去，会不断进化。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长颈鹿的脖子在漫长的时间里进化得越来越长。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类经过几百万年才进化成今天的样子。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究鱼怎样进化成陆地动物。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种昆虫为了躲避天敌，身体逐渐进化得更小。", "target_word": "进化", "complexity_tier": "T3", "furigana": "zhè zhǒng kūnchóng wèile duǒbì tiāndí, shēntǐ zhújiàn jìnhuà de gèng xiǎo.", "sentence_source": "generated"}, {"text": "环境变冷后，这种动物的毛进化得更厚。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒也会进化，所以药要不断更新。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "进化了", "label": "体标"}, {"form": "进化着", "label": "体标"}, {"form": "进化过", "label": "体标"}, {"form": "進化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生物经过很长时间逐渐变化、更适应环境（也可比喻事物逐步发展升级）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化（jìn huà）：生物在长时间里逐渐变化，更适应环境。"}, {"text": "进货", "is_correct": false, "explanation": "进货（jìn huò）：第二音节 huò 与 huà 韵母不同，意思是购进商品。"}, {"text": "净化", "is_correct": false, "explanation": "净化（jìng huà）：第一音节 jìng 与 jìn 韵尾不同（ng 与 n），意思是使干净。"}, {"text": "金花", "is_correct": false, "explanation": "金花（jīn huā）：两个音节的声调都与 jìn huà 不同，意思是金色的花。"}], "explanations": {"进化": "进化（jìn huà）：生物在长时间里逐渐变化，更适应环境。", "进货": "进货（jìn huò）：第二音节 huò 与 huà 韵母不同，意思是购进商品。", "净化": "净化（jìng huà）：第一音节 jìng 与 jìn 韵尾不同（ng 与 n），意思是使干净。", "金花": "金花（jīn huā）：两个音节的声调都与 jìn huà 不同，意思是金色的花。"}, "sentence_index": null, "correct_answer": "进化"}, "level_3": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化：表示从低级到高级的逐渐变化，与“从补充性能源变为基石”的方向一致。"}, {"text": "沦为", "is_correct": false, "explanation": "语义：“沦为”指堕落、变坏，与“基石”的积极地位冲突。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：“缩小”指变小，与能源从补充升为基石的方向相反。"}, {"text": "降低", "is_correct": false, "explanation": "搭配：“降低”多接数值或水平，不能用来说地位从补充变为基石。"}], "explanations": {"进化": "进化：表示从低级到高级的逐渐变化，与“从补充性能源变为基石”的方向一致。", "沦为": "语义：“沦为”指堕落、变坏，与“基石”的积极地位冲突。", "缩小": "语义：“缩小”指变小，与能源从补充升为基石的方向相反。", "降低": "搭配：“降低”多接数值或水平，不能用来说地位从补充变为基石。"}, "sentence_index": 0, "correct_answer": "进化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵小树每年都进化得很快。", "explanation": "这里应该用〈生长〉。进化指物种在漫长时间里的变化，植物个体长高要用生长。"}, {"text": "冬天一到，这个城市的气温进化到了零下十度。", "explanation": "这里应该用〈降〉。进化指生物在长时间里的变化，气温下降要用降。"}, {"text": "这个班的人数进化到了五十人。", "explanation": "这里应该用〈增加〉。进化不用于人数等数量变化，人数增多要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化：指生物长期变化成新的形态，与“鱼变成陆地动物”的语义一致。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象多是食物，“煮成陆地动物”搭配不当。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切成”指把整体切分开，与鱼变为陆地动物的生物演变不符。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织成”指编织成织物，与生物的演变无关。"}], "explanations": {"进化": "进化：指生物长期变化成新的形态，与“鱼变成陆地动物”的语义一致。", "煮": "搭配：“煮”的对象多是食物，“煮成陆地动物”搭配不当。", "切": "语义：“切成”指把整体切分开，与鱼变为陆地动物的生物演变不符。", "织": "语义：“织成”指编织成织物，与生物的演变无关。"}, "sentence_index": 6, "correct_answer": "进化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身体进化得很好，已经能跑步了。", "explanation": "这里应该用〈恢复〉。进化指生物经过很长时间的适应性变化，身体康复要用恢复。"}, {"text": "妈妈一进厨房，锅里的水就进化得滚了起来。", "explanation": "这里应该用〈烧开〉。进化指生物的长期变化，水受热沸腾要用烧开。"}, {"text": "小明进化得很快，已经比我高了。", "explanation": "这里应该用〈成长〉。进化指物种的长期演变，孩子长大要用成长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鸟的脚进化很长，能在水里走路。", "corrected_sentence": "这种鸟的脚进化得很长，能在水里走路。", "error_description": "“进化”后接程度补语时要用“得”。漏掉“得”，应为“进化得很长”，原句不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病毒也会进化的很快，所以药要不断更新。", "corrected_sentence": "病毒也会进化得很快，所以药要不断更新。", "error_description": "程度补语前要用“得”，不能用“的”。应为“进化得很快”，写成“进化的很快”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
