INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由许多同类个体组成的整体。", "primary_collocate": null, "pronunciation": "qún tǐ", "ipa": "tɕʰyn˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "从进化角度看，打哈欠的传染性可能是一种原始的群体同步机制。", "target_word": "群体", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "在群居动物中，哈欠的传播或许曾用于协调休息时间或警戒状态，从而增强群体生存效率。", "target_word": "群体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蚂蚁是一种过着群体生活的动物。", "target_word": "群体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个群体里的每个人都要遵守规则。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老年人是需要社会关心的群体。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟类常常组成群体一起飞行。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个群体中，大家的想法很接近。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青少年群体对新的手机很感兴趣。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狼是靠群体合作来找食物的。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群体的力量比一个人的力量大得多。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "群体性", "label": "复合"}, {"form": "弱势群体", "label": "复合"}, {"form": "群體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由许多同类个体组成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体", "is_correct": true, "explanation": "“群体”指由许多同类个体组成的整体，可以修饰“同步机制”，与句意一致。"}, {"text": "个体", "is_correct": false, "explanation": "语义：“个体”指单个的生物，与“打哈欠的传染性”需要多个体互动的语境相矛盾。"}, {"text": "器官", "is_correct": false, "explanation": "语义：“器官”是身体的组成部分，不能指多个个体之间的同步，与句中的传染性不符。"}, {"text": "单位", "is_correct": false, "explanation": "搭配：“单位”多指机构或计量单位，不能修饰“同步机制”表达生物群体的意思。"}], "explanations": {"群体": "“群体”指由许多同类个体组成的整体，可以修饰“同步机制”，与句意一致。", "个体": "语义：“个体”指单个的生物，与“打哈欠的传染性”需要多个体互动的语境相矛盾。", "器官": "语义：“器官”是身体的组成部分，不能指多个个体之间的同步，与句中的传染性不符。", "单位": "搭配：“单位”多指机构或计量单位，不能修饰“同步机制”表达生物群体的意思。"}, "sentence_index": 0, "correct_answer": "群体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子是一个群体。", "explanation": "这里应该用〈单个物体〉。“群体”指由许多同类个体组成的整体，不能说一张桌子是一个群体。"}, {"text": "他是我们班的一个群体。", "explanation": "这里应该用〈个人〉。“群体”指许多个体组成的整体，不能指单个的人。"}, {"text": "群体同学没有交作业。", "explanation": "这里应该用〈全体〉。“全体同学”指班里所有的同学；“群体”强调由许多同类个体组成的整体，不用来修饰“同学”这样的具体人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体", "is_correct": true, "explanation": "“群体”指许多人组成的整体，“在这个群体中”表示在这些人之中，与“大家的想法很接近”相符。"}, {"text": "物体", "is_correct": false, "explanation": "语义：“物体”没有想法，不能说“大家的想法很接近”。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体”是个人的躯体，不能指许多人组成的整体。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“字体”是字的样式，不能用“在……中”来指人的集合。"}], "explanations": {"群体": "“群体”指许多人组成的整体，“在这个群体中”表示在这些人之中，与“大家的想法很接近”相符。", "物体": "语义：“物体”没有想法，不能说“大家的想法很接近”。", "身体": "语义：“身体”是个人的躯体，不能指许多人组成的整体。", "字体": "搭配：“字体”是字的样式，不能用“在……中”来指人的集合。"}, "sentence_index": 6, "correct_answer": "群体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的群体很好听。", "explanation": "这里应该用〈旋律〉。“群体”指由人组成的整体，不能用来形容歌曲的好听程度。"}, {"text": "这天的群体很冷。", "explanation": "这里应该用〈天气〉。“群体”指由许多同类个体组成的整体，不能用来描述天气的冷热。"}, {"text": "这本书的群体很重。", "explanation": "这里应该说〈重量〉。“群体”指由许多同类个体组成的整体，不能用来形容一本书有多重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个群体们的力量很大。", "corrected_sentence": "这个群体的力量很大。", "error_description": "错误：“群体”后面加了“们”。正确：“群体”本身已表示集合，不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只群体的合作很重要。", "corrected_sentence": "一个群体的合作很重要。", "error_description": "错误：量词用了“只”，“只”指单个动物或物体。正确：“群体”是集合，指许多个体组成的整体，量词应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
