INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11273, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指倾向于群体生活、彼此依赖的社会性动物。", "primary_collocate": null, "pronunciation": "qún jū dòng wù", "ipa": "tɕʰyn˧˥ tɕy˥ tʊŋ˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "在群居动物中，哈欠的传播或许曾用于协调休息时间或警戒状态，从而增强群体生存效率。", "target_word": "群居动物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蚂蚁是典型的群居动物，它们分工合作。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼是群居动物，常常一起捕食。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群居动物需要同伴的陪伴才能安心生活。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象属于群居动物，由母象带领象群。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为群居动物，人类也离不开集体。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些群居动物靠叫声互相联系。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者观察了几种群居动物的行为。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群居动物通常比独居动物更安全。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的群居动物会轮流照看幼崽。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种群居动物", "label": "量词"}, {"form": "群居動物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "群居动物:过群体生活、彼此依赖的社会性动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群居动物", "is_correct": true, "explanation": "正确：“群居动物”指彼此依赖、过群体生活的动物，与“协调”和“增强群体生存效率”相符。"}, {"text": "独居动物", "is_correct": false, "explanation": "语义：独居动物不过群体生活，与句末“增强群体生存效率”相反。"}, {"text": "植物", "is_correct": false, "explanation": "体貌：植物没有打哈欠所需的身体与神经结构，无法参与“哈欠的传播”。"}, {"text": "单细胞生物", "is_correct": false, "explanation": "语义：单细胞生物没有群体协调与警戒行为，与“协调”“警戒状态”的语境不符。"}], "explanations": {"群居动物": "正确：“群居动物”指彼此依赖、过群体生活的动物，与“协调”和“增强群体生存效率”相符。", "独居动物": "语义：独居动物不过群体生活，与句末“增强群体生存效率”相反。", "植物": "体貌：植物没有打哈欠所需的身体与神经结构，无法参与“哈欠的传播”。", "单细胞生物": "语义：单细胞生物没有群体协调与警戒行为，与“协调”“警戒状态”的语境不符。"}, "sentence_index": 0, "correct_answer": "群居动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵大树是群居动物，树枝上住着很多鸟。", "explanation": "“群居动物”只指动物，大树是植物，不能用这个词称呼一棵树。"}, {"text": "这座城市是群居动物，居民大多住在一起。", "explanation": "“群居动物”指有生命的动物，城市是地方，不能用这个词来描述城市。"}, {"text": "这台电脑是群居动物，同时运行着很多程序。", "explanation": "“群居动物”指有生命的动物，这里的“电脑”是人造的机器，不能用这个词来形容它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群居动物", "is_correct": true, "explanation": "正确：“群居动物”指群体生活的动物，能够靠叫声互相联系，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会发出叫声，无法靠叫声互相联系。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵没有发声能力，与“靠叫声”的说法冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "体貌：桌子没有发声器官，不能靠叫声与他人联系。"}], "explanations": {"群居动物": "正确：“群居动物”指群体生活的动物，能够靠叫声互相联系，与句意相符。", "石头": "语义：石头不会发出叫声，无法靠叫声互相联系。", "花朵": "语义：花朵没有发声能力，与“靠叫声”的说法冲突。", "桌子": "体貌：桌子没有发声器官，不能靠叫声与他人联系。"}, "sentence_index": 6, "correct_answer": "群居动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头是群居动物，石缝里挤着很多小石子。", "explanation": "“群居动物”指有生命的动物，这里的“石头”属于无生命的矿物，不能用这个词。"}, {"text": "这间办公室是群居动物，同事们经常一起开会。", "explanation": "“群居动物”指生物，办公室是场所，不能这样称呼它。"}, {"text": "这部手机是群居动物，里面存了很多联系人。", "explanation": "“群居动物”指动物，手机是物品，不能用这个词来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "狼是一只群居动物。", "corrected_sentence": "狼是一种群居动物。", "error_description": "量词错误：“只”用于具体的一只动物，说“群居动物”这一类别时应用“种”。正确说法是“狼是一种群居动物。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种的群居动物通常很友好。", "corrected_sentence": "这种群居动物通常很友好。", "error_description": "多余的“的”：“这种”直接修饰名词，中间不加“的”。正确说法是“这种群居动物通常很友好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
