INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指工作、学习等活动暂停后用于放松、恢复精力的时间段。", "primary_collocate": null, "pronunciation": "xiū xi shí jiān", "ipa": "ɕjoʊ˥ ɕi˧ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "在群居动物中，哈欠的传播或许曾用于协调休息时间或警戒状态，从而增强群体生存效率。", "target_word": "休息时间", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "休息时间到了，大家都去喝茶。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午的休息时间只有一小时。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在休息时间聊天。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在休息时间打电话谈工作。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们利用休息时间复习功课。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给员工留了半小时休息时间。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间开车要安排休息时间。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把休息时间都用来看书了。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生也需要足够的休息时间。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段休息时间", "label": "量词"}, {"form": "休息時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "休息时间:工作学习暂停后用于放松恢复精力的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "休息时间", "is_correct": true, "explanation": "正确：“休息时间”指暂停活动后用于放松的时段，与“协调”搭配，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“协调”的对象应是时间、行动或状态，“协调石头”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以用来协调的对象，与“哈欠的传播”和“警戒状态”无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“协调”不搭配“体重”，句中要求的协调对象应是时间或状态。"}], "explanations": {"休息时间": "正确：“休息时间”指暂停活动后用于放松的时段，与“协调”搭配，符合句意。", "石头": "搭配：“协调”的对象应是时间、行动或状态，“协调石头”不成立。", "天气": "语义：天气不是可以用来协调的对象，与“哈欠的传播”和“警戒状态”无关。", "体重": "搭配：“协调”不搭配“体重”，句中要求的协调对象应是时间或状态。"}, "sentence_index": 0, "correct_answer": "休息时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校每天有一条休息时间，大家都很开心。", "explanation": "这里应该用〈段〉。“休息时间”指一段时间，量词要用“段”，不能用“条”。"}, {"text": "这间卧室是工人们的休息时间，大家都在那儿睡觉。", "explanation": "“休息时间”指时段，不指地点。卧室是地方，不能说成休息时间。"}, {"text": "这家食堂是工人们的休息时间，午饭吃得很快。", "explanation": "“休息时间”指时段，食堂是场所，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "休息时间", "is_correct": true, "explanation": "正确：“留了半小时”后接时段，“休息时间”指可以放松的时段，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“留”后接的是时段，工资不是时段，“留了半小时工资”句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“半小时”修饰时段，不修饰房间，“留了半小时房间”不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物品，不能被“留了半小时”修饰，与句意冲突。"}], "explanations": {"休息时间": "正确：“留了半小时”后接时段，“休息时间”指可以放松的时段，符合句意。", "工资": "语义：“留”后接的是时段，工资不是时段，“留了半小时工资”句意不通。", "房间": "搭配：“半小时”修饰时段，不修饰房间，“留了半小时房间”不成立。", "钥匙": "语义：钥匙是物品，不能被“留了半小时”修饰，与句意冲突。"}, "sentence_index": 6, "correct_answer": "休息时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是医生的休息时间，他每天都用它。", "explanation": "“休息时间”指时段，电脑是物品，不能用“休息时间”来指代它。"}, {"text": "这间办公室是医生的休息时间，他在那里看病。", "explanation": "“休息时间”指时段，办公室是场所，这里不能这样说。"}, {"text": "这辆汽车是医生的休息时间，他每天开它上班。", "explanation": "“休息时间”指时段，汽车是交通工具，这里误用了这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课后有一只休息时间。", "corrected_sentence": "下课后有一段休息时间。", "error_description": "量词错误：“只”用于动物，不能用来计量时间段；表示一段时间应用“段”。正确说法是“下课后有一段休息时间。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司给员工留了一小时地休息时间。", "corrected_sentence": "公司给员工留了一小时的休息时间。", "error_description": "助词错误：修饰名词“休息时间”的定语应用“的”，不能用“地”。正确说法是“公司给员工留了一小时的休息时间。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松懈", "is_correct": true, "explanation": "松懈指放松戒备，与“警戒”（保持警觉、防备危险）构成反义关系。"}, {"text": "启程", "is_correct": false, "explanation": "启程指动身上路，与“警戒”的戒备义没有反义关系。"}, {"text": "歌唱", "is_correct": false, "explanation": "歌唱指用声音唱出曲调，与“警戒”的防范义没有反义关系。"}, {"text": "烘焙", "is_correct": false, "explanation": "烘焙指用烤箱加热食物，与“警戒”的防范义没有反义关系。"}], "correct_answer": "松懈", "explanations": {"松懈": "松懈指放松戒备，与“警戒”（保持警觉、防备危险）构成反义关系。", "启程": "启程指动身上路，与“警戒”的戒备义没有反义关系。", "歌唱": "歌唱指用声音唱出曲调，与“警戒”的防范义没有反义关系。", "烘焙": "烘焙指用烤箱加热食物，与“警戒”的防范义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松懈", "is_correct": true, "explanation": "松懈指放松戒备，与“警戒”（保持警觉、防备危险）构成反义关系。"}, {"text": "播种", "is_correct": false, "explanation": "播种指把种子撒入土中，与“警戒”的戒备义没有反义关系。"}, {"text": "攀登", "is_correct": false, "explanation": "攀登指向上爬，与“警戒”的戒备义没有反义关系。"}, {"text": "挖掘", "is_correct": false, "explanation": "挖掘指向下刨土，与“警戒”的戒备义没有反义关系。"}], "correct_answer": "松懈", "explanations": {"松懈": "松懈指放松戒备，与“警戒”（保持警觉、防备危险）构成反义关系。", "播种": "播种指把种子撒入土中，与“警戒”的戒备义没有反义关系。", "攀登": "攀登指向上爬，与“警戒”的戒备义没有反义关系。", "挖掘": "挖掘指向下刨土，与“警戒”的戒备义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指为防止危险或错误而保持警惕，或对可能发生的危险采取防范措施。", "primary_collocate": null, "pronunciation": "jǐng jiè", "ipa": "tɕiŋ˨˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "哨兵整夜警戒着营地，直到天亮。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，哨兵一直警戒着四周。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水边的鹿时刻警戒，怕有狼来。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路口加强了警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风要来了，海边提高了警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位升高，河边需要警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊群吃草时，有一只羊负责警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡了，妈妈仍然警戒着门外，防止有人闯进来。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "hái zi shuì le，mā ma réng rán jǐng jiè zhe mén wài，fáng zhǐ yǒu rén chuǎng jìn lái。", "sentence_source": "generated"}, {"text": "在陌生的地方，他不敢放松警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封山后，救援队对山口加强警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警戒着", "label": "体标"}, {"form": "警戒过", "label": "体标"}, {"form": "警戒线", "label": "复合"}, {"form": "警戒状态", "label": "复合"}], "register": "书面", "sense_fingerprint": "警戒:为防危险而保持警惕、采取防范措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "正确：“警戒着营地”指哨兵持续保持戒备、防范危险，与“整夜”“直到天亮”的语境相符。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：孤立指脱离群体，不能用来描述哨兵守卫营地的动作。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指把种子撒入土中，与哨兵守卫营地的语境无关。"}, {"text": "交配", "is_correct": false, "explanation": "语义：交配是繁殖行为，与守卫营地的语境完全不符。"}], "explanations": {"警戒": "正确：“警戒着营地”指哨兵持续保持戒备、防范危险，与“整夜”“直到天亮”的语境相符。", "孤立": "语义：孤立指脱离群体，不能用来描述哨兵守卫营地的动作。", "播种": "语义：播种指把种子撒入土中，与哨兵守卫营地的语境无关。", "交配": "语义：交配是繁殖行为，与守卫营地的语境完全不符。"}, "sentence_index": 0, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山顶一起警戒夜景。", "explanation": "这里应该用〈欣赏〉。“欣赏”指观赏美好的景色，可用于夜景；“警戒”针对危险或坏人，不能用来形容观赏景色。"}, {"text": "朋友来我家做客，我一直警戒着他。", "explanation": "这里应该用〈招待〉。“招待”指接待客人，朋友做客时用于待客；“警戒”针对危险或坏人，不能用于接待朋友。"}, {"text": "朋友来我家做客，我热烈地警戒着他。", "explanation": "这里应该用〈招待〉。“警戒”指防备危险，与“热烈”的待客态度矛盾；“招待”指热情接待客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "警戒指守卫放哨、防备危险，符合“负责”一只羊承担的职责。"}, {"text": "吃草", "is_correct": false, "explanation": "语义：负责警戒的羊若在吃草，就无法同时履行警戒职责，与句意矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：负责警戒的羊若睡觉，就失去了警戒的作用，与句意矛盾。"}, {"text": "玩耍", "is_correct": false, "explanation": "搭配：“负责玩耍”不是通常的职责搭配，且与羊群防范危险的分工相冲突。"}], "explanations": {"警戒": "警戒指守卫放哨、防备危险，符合“负责”一只羊承担的职责。", "吃草": "语义：负责警戒的羊若在吃草，就无法同时履行警戒职责，与句意矛盾。", "睡觉": "语义：负责警戒的羊若睡觉，就失去了警戒的作用，与句意矛盾。", "玩耍": "搭配：“负责玩耍”不是通常的职责搭配，且与羊群防范危险的分工相冲突。"}, "sentence_index": 6, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们热烈警戒你的到来。", "explanation": "这里应该用〈欢迎〉。“欢迎”表示热情迎接到来的人；“警戒”是防备危险的意思，不能用来表示迎接。"}, {"text": "他每天警戒办公室的玻璃。", "explanation": "这里应该用〈擦洗〉。“擦洗”用于玻璃等物品；“警戒”针对危险或坏人，玻璃不是防备对象，不能用“警戒”。"}, {"text": "妈妈在厨房里警戒窗外的雨景。", "explanation": "这里应该用〈欣赏〉。“欣赏”指观赏窗外的景色；“警戒”针对危险或坏人，雨景不是防备对象，不能用“警戒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷里的守卫白天黑夜都警戒了四周。", "corrected_sentence": "山谷里的守卫白天黑夜都警戒着四周。", "error_description": "错误：“警戒了四周”；正确：“警戒着四周”。“警戒”表示持续保持戒备的状态，应用“着”表示持续，“了”表示完成，与“白天黑夜都”的持续语境矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，巡逻队在工地周围警戒下来了。", "corrected_sentence": "夜里，巡逻队在工地周围警戒起来了。", "error_description": "错误：“警戒下来了”；正确：“警戒起来了”。“起来”表示动作开始并进入某种状态，“警戒起来”是固定说法，“下来”不能与“警戒”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
