INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灵长类是哺乳动物中的一个目，包括猴子、猿、狐猴和人类，大脑发达，手指和脚趾能抓握。", "primary_collocate": null, "pronunciation": "líng zhǎng lèi", "ipa": "liŋ˧˥ ʈʂaŋ˨˩˦ lei˥˩", "syllable_count": 3, "sentences": [{"text": "灵长类中广泛存在的哈欠传染现象支持了这一理论，尤其是在亲缘关系较近的个体之间，传染概率显著增高，这提示其可能承载着某种隐性的社会联结功能。", "target_word": "灵长类", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "猴子是一种灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类的手指可以抓东西。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人类也属于灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个动物园有很多灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类大多生活在树林里。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究灵长类的大脑。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大猩猩是体形最大的灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类的孩子要跟妈妈住很久。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拍过很多灵长类的照片。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "灵长类动物", "label": "复合"}, {"form": "灵長類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "哺乳动物的一个目，含猴、猿和人类，大脑发达，手脚能抓握", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵长类", "is_correct": true, "explanation": "正确：灵长类是哈欠传染现象被观察到的对象，符合句中所述的研究语境。"}, {"text": "鱼类", "is_correct": false, "explanation": "语义：鱼类是水生脊椎动物，不属于灵长类，与句中讨论的社会联结研究对象不符。"}, {"text": "爬行类", "is_correct": false, "explanation": "语义：爬行类不属于哺乳动物中的灵长目，与句中所述的亲缘关系和社会联结语境不符。"}, {"text": "有袋类", "is_correct": false, "explanation": "搭配：“有袋类”指特定的哺乳类群，与“广泛存在”的泛指说法及句中讨论的灵长类研究不搭。"}], "explanations": {"灵长类": "正确：灵长类是哈欠传染现象被观察到的对象，符合句中所述的研究语境。", "鱼类": "语义：鱼类是水生脊椎动物，不属于灵长类，与句中讨论的社会联结研究对象不符。", "爬行类": "语义：爬行类不属于哺乳动物中的灵长目，与句中所述的亲缘关系和社会联结语境不符。", "有袋类": "搭配：“有袋类”指特定的哺乳类群，与“广泛存在”的泛指说法及句中讨论的灵长类研究不搭。"}, "sentence_index": 0, "correct_answer": "灵长类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的动物园新来了一台灵长类。", "explanation": "这里的量词不对。“台”用于机器、设备，不能用来数“灵长类”；灵长类是动物的一类，应说“一种灵长类”或用“只”数具体动物。"}, {"text": "科学家在森林里发现了一本灵长类。", "explanation": "这里的量词不对。“本”用于书册，不能用来数“灵长类”；灵长类是动物的一类，应说“一种灵长类”。"}, {"text": "这块灵长类跑得很快。", "explanation": "这里的量词不对。“块”用于块状物，不能用来数“灵长类”；灵长类是动物的一类，应说“这种灵长类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵长类", "is_correct": true, "explanation": "灵长类的大脑指灵长类动物的大脑，是科学研究的常见对象，符合句意。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物没有大脑，“植物的大脑”不成立，与科学研究句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不可能有大脑，与句意矛盾。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“雕像的大脑”不是合理的搭配，与科学研究的语境不符。"}], "explanations": {"灵长类": "灵长类的大脑指灵长类动物的大脑，是科学研究的常见对象，符合句意。", "植物": "语义：植物没有大脑，“植物的大脑”不成立，与科学研究句意矛盾。", "石头": "语义：石头是无生命的物体，不可能有大脑，与句意矛盾。", "雕像": "搭配：“雕像的大脑”不是合理的搭配，与科学研究的语境不符。"}, "sentence_index": 6, "correct_answer": "灵长类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车是灵长类，骑起来很轻便。", "explanation": "“灵长类”指动物类别，自行车是交通工具，不能用这个词来称呼它。"}, {"text": "这把椅子是灵长类，坐起来很舒服。", "explanation": "“灵长类”指动物类别，椅子是家具，不能用这个词来称呼它。"}, {"text": "这块石头是灵长类，又硬又重。", "explanation": "“灵长类”指动物类别，石头是矿物，不能用这个词来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家在这座森林里发现了一张灵长类。", "corrected_sentence": "科学家在这座森林里发现了一种灵长类。", "error_description": "错误：“一张灵长类”；正确：“一种灵长类”。“灵长类”是动物的一类，应用“种”来计量，“张”只用于平面的东西，不能用来数动物类别。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员在森林里观察一位灵长类的行为。", "corrected_sentence": "研究人员在森林里观察一种灵长类的行为。", "error_description": "量词错误：“位”用于尊称的人，不能用来计量动物；计量动物类别应用“种”。正确说法是“研究人员在森林里观察一种灵长类的行为。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
