INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用事实或现象来证明某个观点正确", "primary_collocate": null, "pronunciation": "zhī chí", "ipa": "ʈʂɻ̩˥ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这些数据支持他的看法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结果支持了我们的想法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有证据支持这个说法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的发现支持这一理论。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "调查表明，事实支持老师的判断。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片支持了他的说法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究结果不支持这个结论。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有三个例子支持她的看法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些事实能支持你的观点吗？", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "越来越多的证据支持这个想法。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支持了", "label": "体标"}, {"form": "支持着", "label": "体标"}, {"form": "支持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事实、数据等证明观点或理论正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11282, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案，意思是用事实或证据证明观点正确。"}, {"text": "知识", "is_correct": false, "explanation": "zhī shí 与 zhī chí 的第二音节声母不同（sh 与 ch），意思是知识。"}, {"text": "知耻", "is_correct": false, "explanation": "第二音节声调不同（chǐ 第三声，chí 第二声），意思是懂得羞耻。"}, {"text": "直尺", "is_correct": false, "explanation": "两个音节声调都不同（zhí chǐ 与 zhī chí），意思是量直线的尺子。"}, {"text": "智齿", "is_correct": false, "explanation": "两个音节声调都不同（zhì chǐ 与 zhī chí），意思是最里面长出的一对大牙。"}, {"text": "指斥", "is_correct": false, "explanation": "两个音节声调都不同（zhǐ chì 与 zhī chí），意思是指出错误并加以斥责。"}], "explanations": {"支持": "正确答案，意思是用事实或证据证明观点正确。", "知识": "zhī shí 与 zhī chí 的第二音节声母不同（sh 与 ch），意思是知识。", "知耻": "第二音节声调不同（chǐ 第三声，chí 第二声），意思是懂得羞耻。", "直尺": "两个音节声调都不同（zhí chǐ 与 zhī chí），意思是量直线的尺子。", "智齿": "两个音节声调都不同（zhì chǐ 与 zhī chí），意思是最里面长出的一对大牙。", "指斥": "两个音节声调都不同（zhǐ chì 与 zhī chí），意思是指出错误并加以斥责。"}, "sentence_index": null, "correct_answer": "支持"}, "level_3": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案。“支持”指用数据证明看法正确，与“数据”搭配自然。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的施事须是有意识的人，数据无法批评他的看法。"}, {"text": "接受", "is_correct": false, "explanation": "配价：“接受”需要有意愿的施事作主语，“数据”不能接受别人的看法。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是有情感的人对人或事表示称赞，数据不会赞美看法。"}], "explanations": {"支持": "正确答案。“支持”指用数据证明看法正确，与“数据”搭配自然。", "批评": "语义：“批评”的施事须是有意识的人，数据无法批评他的看法。", "接受": "配价：“接受”需要有意愿的施事作主语，“数据”不能接受别人的看法。", "赞美": "语义：“赞美”是有情感的人对人或事表示称赞，数据不会赞美看法。"}, "sentence_index": 0, "correct_answer": "支持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母一直支持我们的梦想。", "explanation": "这里的“支持”是“同意并帮助”的意思，指站在某人一边，不是用事实证明观点。"}, {"text": "这根柱子支持着整个屋顶。", "explanation": "这里的“支持”是“支撑、承受重量”的意思，指物体承重，不是用证据证明观点。"}, {"text": "他靠打工支持全家的生活。", "explanation": "这里的“支持”是“供养、维持”的意思，指负担家庭开销，不是用事实证明观点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案。“支持”与“研究结果”“结论”搭配，表示结果不能证明结论。"}, {"text": "赞同", "is_correct": false, "explanation": "语义：“赞同”的主体须是有意愿的人，研究结果不能赞同结论。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”要求有意愿的施事，“研究结果”作主语不通。"}, {"text": "承认", "is_correct": false, "explanation": "语义：“承认”是人对事实的认定，研究结果不会承认结论。"}], "explanations": {"支持": "正确答案。“支持”与“研究结果”“结论”搭配，表示结果不能证明结论。", "赞同": "语义：“赞同”的主体须是有意愿的人，研究结果不能赞同结论。", "同意": "配价：“同意”要求有意愿的施事，“研究结果”作主语不通。", "承认": "语义：“承认”是人对事实的认定，研究结果不会承认结论。"}, "sentence_index": 6, "correct_answer": "支持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "跑到终点时，他已经支持不住了。", "explanation": "这里的“支持”指勉强撑住、坚持不住，不是用证据证明观点。"}, {"text": "我们都支持这次活动，所以报名参加了。", "explanation": "这里的“支持”指赞同、拥护，是对活动表态，不是用证据证明观点。"}, {"text": "这份工作他勉强支持了三年。", "explanation": "这里的“支持”指勉强维持、坚持下去，不是用证据证明观点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项研究了支持这一假说。", "corrected_sentence": "这项研究支持这一假说。", "error_description": "“了”位置错误：“了”不能放在动词“支持”前面，此句应去掉这个“了”。正确说法是“这项研究支持这一假说。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些证据曾经过支持这个推论。", "corrected_sentence": "这些证据曾经支持这个推论。", "error_description": "“过”位置错误：“过”不能放在动词“支持”前面，此句应去掉这个“过”。正确说法是“这些证据曾经支持这个推论。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
