INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "亲缘指亲属关系，即因血缘或婚姻而形成的亲戚关系；也指生物之间的血缘联系远近。", "primary_collocate": null, "pronunciation": "qīn yuán", "ipa": "tɕʰin˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "灵长类动物中广泛存在的哈欠传染现象支持了这一理论，尤其是在亲缘关系较近的个体之间，传染概率显著增高，这提示其可能承载着某种隐性的社会联结功能。", "target_word": "亲缘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两种动物的亲缘很近。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩的亲缘很远，几乎不来往。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "tā men liǎ de qīn yuán hěn yuǎn, jī hū bù lái wǎng.", "sentence_source": "generated"}, {"text": "科学家用基因分析人类与猩猩的亲缘。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "kē xué jiā yòng jī yīn fēn xī rén lèi yǔ xīng xing de qīn yuán.", "sentence_source": "generated"}, {"text": "亲缘越近，长得越像。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狼和狗的亲缘相当近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "láng hé gǒu de qīn yuán xiāng dāng jìn.", "sentence_source": "generated"}, {"text": "亲缘近的人，常常长得很像。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "qīn yuán jìn de rén, cháng cháng zhǎng de hěn xiàng.", "sentence_source": "generated"}, {"text": "老虎和猫的亲缘比较近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "lǎo hǔ hé māo de qīn yuán bǐ jiào jìn.", "sentence_source": "generated"}, {"text": "这个村子里的人亲缘都很近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "zhè ge cūn zi lǐ de rén qīn yuán dōu hěn jìn.", "sentence_source": "generated"}, {"text": "他们虽然同姓，亲缘却很远。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "tā men suī rán tóng xìng, qīn yuán què hěn yuǎn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲缘关系", "label": "复合"}, {"form": "親緣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "因血缘或婚姻形成的亲属关系；生物之间的血缘联系远近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案，意思是因血缘或婚姻形成的亲属关系。"}, {"text": "情缘", "is_correct": false, "explanation": "qíng yuán 与 qīn yuán 的韵母和声调都不同（ing 与 in，第二声与第一声），意思是感情上的缘分。"}, {"text": "金元", "is_correct": false, "explanation": "jīn yuán 与 qīn yuán 的声母不同（j 与 q），声调相同，意思是金子与货币单位。"}, {"text": "新元", "is_correct": false, "explanation": "xīn yuán 与 qīn yuán 的声母不同（x 与 q），声调相同，意思是新加坡等地的货币单位。"}], "explanations": {"亲缘": "正确答案，意思是因血缘或婚姻形成的亲属关系。", "情缘": "qíng yuán 与 qīn yuán 的韵母和声调都不同（ing 与 in，第二声与第一声），意思是感情上的缘分。", "金元": "jīn yuán 与 qīn yuán 的声母不同（j 与 q），声调相同，意思是金子与货币单位。", "新元": "xīn yuán 与 qīn yuán 的声母不同（x 与 q），声调相同，意思是新加坡等地的货币单位。"}, "sentence_index": null, "correct_answer": "亲缘"}, "level_3": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案。“亲缘关系”指血缘或婚姻形成的亲属联系，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不构成个体之间的亲属联系，“颜色关系较近”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不与“关系较近”搭配，句子无法成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能体现个体之间的血缘或婚姻联系。"}], "explanations": {"亲缘": "正确答案。“亲缘关系”指血缘或婚姻形成的亲属联系，与句意相符。", "颜色": "语义：颜色不构成个体之间的亲属联系，“颜色关系较近”说不通。", "味道": "搭配：“味道”不与“关系较近”搭配，句子无法成立。", "体重": "语义：体重不能体现个体之间的血缘或婚姻联系。"}, "sentence_index": 0, "correct_answer": "亲缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母亲对孩子的亲缘很深。", "explanation": "这里应该用〈感情〉。亲缘指亲属关系的远近，要说“近”或“远”，不用“深”来形容。"}, {"text": "这个亲缘在本地很有名。", "explanation": "这里应该用〈家族〉。亲缘指亲属之间的关系，不指一群人，不能说“这个亲缘在本地很有名”。"}, {"text": "这些亲缘都住在农村。", "explanation": "这里应该用〈亲属〉。亲缘是亲属之间的关系，不指人，不能说“这些亲缘都住在农村”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案。“亲缘近的人”指血缘或婚姻关系近，与句意相符。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”指空间间隔，不能说明人与人之间的亲属关系远近。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格习惯，与“长得很像”无关，句子无法成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用于商品，不说“价格近的人”。"}], "explanations": {"亲缘": "正确答案。“亲缘近的人”指血缘或婚姻关系近，与句意相符。", "距离": "语义：“距离”指空间间隔，不能说明人与人之间的亲属关系远近。", "脾气": "语义：“脾气”指性格习惯，与“长得很像”无关，句子无法成立。", "价格": "搭配：“价格”用于商品，不说“价格近的人”。"}, "sentence_index": 6, "correct_answer": "亲缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的亲缘很甜蜜。", "explanation": "这里应该用〈爱情〉。亲缘指亲属关系，不用来形容甜蜜的感觉。"}, {"text": "他和我在网上相识，真是有亲缘。", "explanation": "这里应该用〈缘分〉。亲缘指血缘或婚姻形成的亲属关系，这两人只是偶然认识，不存在这种关系，不能说“真是有亲缘”。"}, {"text": "他和老朋友的亲缘很深。", "explanation": "这里应该用〈交情〉。亲缘指血缘或婚姻形成的亲属联系，朋友之间没有这种关系，不能说“亲缘很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个部族的亲缘比较大。", "corrected_sentence": "这两个部族的亲缘比较近。", "error_description": "搭配错误：“亲缘”的程度用“近”或“远”来说，不能用“大”。应说“亲缘比较近”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对兄弟的亲缘很高。", "corrected_sentence": "这对兄弟的亲缘很近。", "error_description": "搭配错误：“亲缘”的程度用“近”或“远”来说，不能用“高”。应说“亲缘很近”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
