INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示某件事情发生可能性的数值，范围从0到1。", "primary_collocate": null, "pronunciation": "gài lǜ", "ipa": "kai˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "灵长类动物中广泛存在的哈欠传染现象支持了这一理论，尤其是在亲缘关系较近的个体之间，传染概率显著增高，这提示其可能承载着某种隐性的社会联结功能。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "明天下雨的概率是百分之八十。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个骰子掷出六点的概率是六分之一。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抛硬币时，正面朝上的概率是0.5。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "概率的数值不会大于一，也不会小于零。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先算一算中奖的概率有多大。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一张彩票中大奖的概率非常低。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的发生概率只有万分之一。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，老师教我们怎么算概率。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考试题出错的概率很小。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用0到1之间的数值表示某件事发生可能性的大小（数学、统计意义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概率", "is_correct": true, "explanation": "正确：“传染概率”指传染的可能性大小，与“显著增高”搭配。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”没有数值，不能“显著增高”，与句中传染现象无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，不能用来描述传染现象。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能“显著增高”，与句意的传染现象不相关。"}], "explanations": {"概率": "正确：“传染概率”指传染的可能性大小，与“显著增高”搭配。", "方向": "语义：“方向”没有数值，不能“显著增高”，与句中传染现象无关。", "身高": "体貌：身高是人的身体特征，不能用来描述传染现象。", "颜色": "语义：颜色不能“显著增高”，与句意的传染现象不相关。"}, "sentence_index": 0, "correct_answer": "概率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验中，正面朝上的概率是三十次。", "explanation": "这里应该用〈次数〉。概率是0到1之间的数值，不能用来表示次数。"}, {"text": "他去图书馆的概率是每周三次。", "explanation": "这里应该用〈频率〉。概率表示事件发生的可能性，描述单位时间内发生的次数要用频率。"}, {"text": "这个班的学生概率是四十人。", "explanation": "这里应该用〈数量〉。概率只表示0到1之间的可能性，不能用来说明人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概率", "is_correct": true, "explanation": "正确：“中大奖的概率非常低”指中奖的可能性很低，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，与中奖的可能性无关。"}, {"text": "金额", "is_correct": false, "explanation": "搭配：“大奖”本身说明奖金数额很大，与“金额非常低”自相矛盾。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数不能表示中奖的可能性，与句中的彩票和大奖无关。"}], "explanations": {"概率": "正确：“中大奖的概率非常低”指中奖的可能性很低，与句意相符。", "体重": "体貌：体重是人的身体特征，与中奖的可能性无关。", "金额": "搭配：“大奖”本身说明奖金数额很大，与“金额非常低”自相矛盾。", "字数": "语义：字数不能表示中奖的可能性，与句中的彩票和大奖无关。"}, "sentence_index": 6, "correct_answer": "概率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯果汁的概率很高。", "explanation": "这里应该用〈浓度〉。概率表示事件发生的可能性，不能用来说明果汁中物质的含量。"}, {"text": "这盏灯的概率很亮。", "explanation": "这里应该用〈亮度〉。概率不能用来形容灯光的明暗。"}, {"text": "这块布的概率很长。", "explanation": "这里应该用〈长度〉。概率不能用来形容物体的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试及格的概率很多。", "corrected_sentence": "这次考试及格的概率很大。", "error_description": "错误：“很多”；正确：“很大”。概率的程度用“大、小、高、低”来形容，“很多”只用于可数的数量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事发生的概率小很。", "corrected_sentence": "这件事发生的概率很小。", "error_description": "错误：“小很”；正确：“很小”。程度副词“很”要放在形容词前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
