INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加物体的高度或使身体长高。", "primary_collocate": null, "pronunciation": "zēng gāo", "ipa": "tsəŋ˥ kau˥", "syllable_count": 2, "sentences": [{"text": "为了让孩子能看到黑板，老师把讲台增高了十厘米。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙太矮了，工人想把它增高一米。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了看得更远，他们把塔增高了两层。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长高，每天都喝牛奶来增高。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，多运动可以帮孩子增高。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太低，我们用木块把它增高。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东打算把围墙增高，防止小偷进来。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用厚鞋垫增高，可是效果很小。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人相信吃药能增高，其实不一定。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的堤坝要增高，这样洪水就进不来。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增高了", "label": "体标（了）"}, {"form": "增高过", "label": "体标（过）"}, {"form": "增高鞋", "label": "复合词"}, {"form": "增高垫", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使物体的高度增加，或使人的身高变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "增高", "is_correct": true, "explanation": "zēng gāo（第一声、第一声），指物体高度增加或身体长高，是本词。"}, {"text": "蒸糕", "is_correct": false, "explanation": "zhēng 与 zēng 声母不同（zh 与 z），gāo 相同，zhēng gāo 意思是蒸糕。"}, {"text": "撑高", "is_correct": false, "explanation": "chēng 与 zēng 声母不同（ch 与 z），gāo 相同，chēng gāo 意思是撑高。"}, {"text": "层高", "is_correct": false, "explanation": "céng 与 zēng 声母与声调都不同，céng gāo 意思是层高（楼层的高度）。"}], "explanations": {"增高": "zēng gāo（第一声、第一声），指物体高度增加或身体长高，是本词。", "蒸糕": "zhēng 与 zēng 声母不同（zh 与 z），gāo 相同，zhēng gāo 意思是蒸糕。", "撑高": "chēng 与 zēng 声母不同（ch 与 z），gāo 相同，chēng gāo 意思是撑高。", "层高": "céng 与 zēng 声母与声调都不同，céng gāo 意思是层高（楼层的高度）。"}, "sentence_index": null, "correct_answer": "增高"}, "level_3": {"options": [{"text": "增高", "is_correct": true, "explanation": "正确：“把讲台增高了十厘米”指讲台的高度增加，符合“让孩子能看到黑板”的目的。"}, {"text": "降低", "is_correct": false, "explanation": "语义：“降低”与“增高”相反，与“让孩子能看到黑板”的目的矛盾。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”指人或植物生长，不能与“把讲台”搭配，不能说“把讲台长高”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”不表示高度增减，与“增高了十厘米”不符。"}], "explanations": {"增高": "正确：“把讲台增高了十厘米”指讲台的高度增加，符合“让孩子能看到黑板”的目的。", "降低": "语义：“降低”与“增高”相反，与“让孩子能看到黑板”的目的矛盾。", "长高": "搭配：“长高”指人或植物生长，不能与“把讲台”搭配，不能说“把讲台长高”。", "拆除": "语义：“拆除”不表示高度增减，与“增高了十厘米”不符。"}, "sentence_index": 0, "correct_answer": "增高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试后，我的成绩增高了。", "explanation": "这里应该用〈提高〉。增高指物体高度或身高上升，成绩、水平要用提高。"}, {"text": "这个月我们班的人数增高了。", "explanation": "这里应该用〈增加〉。增高指高度上升，人数的增多要用增加。"}, {"text": "这个房间的面积增高了。", "explanation": "这里应该用〈增大〉。增高指高度上升，面积的变大要用增大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增高", "is_correct": true, "explanation": "正确：“把围墙增高”才能达到“防止小偷进来”的目的。"}, {"text": "推倒", "is_correct": false, "explanation": "语义：推倒围墙会让小偷更容易进来，与“防止小偷进来”的目的相反。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：粉刷围墙并不能阻止小偷进来，与句中的目的不相符。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要受赠对象，句中缺少，且与“防止小偷进来”不相符。"}], "explanations": {"增高": "正确：“把围墙增高”才能达到“防止小偷进来”的目的。", "推倒": "语义：推倒围墙会让小偷更容易进来，与“防止小偷进来”的目的相反。", "粉刷": "语义：粉刷围墙并不能阻止小偷进来，与句中的目的不相符。", "赠送": "配价：“赠送”需要受赠对象，句中缺少，且与“防止小偷进来”不相符。"}, "sentence_index": 6, "correct_answer": "增高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近的体力增高了不少。", "explanation": "这里应该用〈增强〉。增高指物体变高或身高增长，体力的提升要用增强。"}, {"text": "两国的友谊增高了。", "explanation": "这里应该用〈增进〉。增高指物体变高或身高增长，国与国之间感情的发展要用增进。"}, {"text": "他对这门课的兴趣增高了。", "explanation": "这里应该用〈加深〉。增高指物体变高或身高增长，兴趣的增长要用加深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们要把篱笆增高得一些。", "corrected_sentence": "他们要把篱笆增高一些。", "error_description": "错误：“增高得一些”；正确：“增高一些”。数量补语前不用“得”，“得”只用于引出程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河水增高地很快。", "corrected_sentence": "河水增高得很快。", "error_description": "错误：“增高地”；正确：“增高得”。“增高”后面的程度补语要用“得”连接，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
