INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某件事告诉别人，让他们知道该做什么或注意什么。", "primary_collocate": null, "pronunciation": "tí shì", "ipa": "tʰi˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师提示我们，考试时要注意时间。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机提示我明天早上有会。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你提示他一下，别忘了带钥匙。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游提示大家，山上的风很大。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师提示客户，合同里有一个条款要注意。", "target_word": "提示", "complexity_tier": "T3", "furigana": "lǜ shī tí shì kè hù, hé tong lǐ yǒu yí ge tiáo kuǎn yào zhù yì.", "sentence_source": "generated"}, {"text": "医生提示病人，饭后要吃药。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕提示密码错了，请再试一次。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在旁边提示我，我才想起答案。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播提示乘客，火车五分钟后到站。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用眼神提示我，不要说话。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提示了", "label": "体标（了）"}, {"form": "提示过", "label": "体标（过）"}, {"form": "提示着", "label": "体标（着）"}, {"form": "提示音", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把要注意或要做的事告诉、提醒别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是告诉对方该注意或该做的事，与“考试时要注意时间”的叮嘱语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑别人，与句中提醒注意时间的语境无关。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”是骗人，与“考试时要注意时间”的提醒语境相反。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是表扬，不能用来引出注意时间的提醒。"}], "explanations": {"提示": "正确：“提示”是告诉对方该注意或该做的事，与“考试时要注意时间”的叮嘱语境相符。", "嘲笑": "语义：“嘲笑”是取笑别人，与句中提醒注意时间的语境无关。", "欺骗": "语义：“欺骗”是骗人，与“考试时要注意时间”的提醒语境相反。", "夸奖": "语义：“夸奖”是表扬，不能用来引出注意时间的提醒。"}, "sentence_index": 0, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上提示了一张桌子。", "explanation": "这里应该用〈搬〉。提示的对象是要让人注意或去做的事，不能指具体的物体。"}, {"text": "校长提示了一幅画。", "explanation": "这里应该用〈展示〉。提示只用于让人注意或去做某事，不能用来指展示实物。"}, {"text": "工厂提示了一台新机器。", "explanation": "这里应该用〈购进〉。提示的对象是要注意或去做的事，不能指机器等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是告知屏幕显示的错误信息，与“请再试一次”的语境相符。"}, {"text": "记住", "is_correct": false, "explanation": "语义：“记住”是人的记忆动作，屏幕不能“记住”密码错误这件事。"}, {"text": "发送", "is_correct": false, "explanation": "搭配：“发送”的对象是消息或文件，不能接“密码错了”这样的状态。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”是同意，与“密码错了”的报错无关。"}], "explanations": {"提示": "正确：“提示”是告知屏幕显示的错误信息，与“请再试一次”的语境相符。", "记住": "语义：“记住”是人的记忆动作，屏幕不能“记住”密码错误这件事。", "发送": "搭配：“发送”的对象是消息或文件，不能接“密码错了”这样的状态。", "批准": "语义：“批准”是同意，与“密码错了”的报错无关。"}, "sentence_index": 6, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提示了一个笑话。", "explanation": "这里应该用〈讲〉。提示是让别人注意或去做某事，不能用来指讲笑话。"}, {"text": "裁判提示了比赛的快乐。", "explanation": "这里应该用〈带来〉。提示不能用来指比赛带来的情绪。"}, {"text": "我非常提示你的帮助。", "explanation": "这里应该用〈感谢〉。提示是让对方知道该做什么，不能用来表达对别人帮助的感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师提示我们了注意时间。", "corrected_sentence": "老师提示我们注意时间。", "error_description": "错误：“了”放在了宾语“我们”后面。“了”应紧跟动词，但本句不需要“了”，正确写作“老师提示我们注意时间。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我提示他过明天要交作业。", "corrected_sentence": "我提示他明天要交作业。", "error_description": "错误：“过”放在了“他”后面。“过”应紧跟动词，但本句只是提醒将来的事，不需要“过”，正确写作“我提示他明天要交作业。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
