INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物之间相互连接、结合，或指联系、结合的关系。", "primary_collocate": null, "pronunciation": "lián jié", "ipa": "ljɛn˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "因此，设计精良的游戏架构往往内嵌平衡机制，将对抗控制在激发活力而非摧毁联结的阈值之内。", "target_word": "联结", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种矛盾统一性揭示了人类群体行为的本质弹性——社会联结既在对抗中淬炼强度，亦在协作中拓展深度。", "target_word": "联结", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "灵长类动物中广泛存在的哈欠传染现象支持了这一理论，尤其是在亲缘关系较近的个体之间，传染概率显著增高，这提示其可能承载着某种隐性的社会联结功能。", "target_word": "联结", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "共同的爱好让我们之间有了联结。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间的联结要靠时间慢慢建立。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母和孩子有很深的情感联结。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个活动让邻居之间有了更多联结。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络让人们的联结变得更容易。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐能建立人与人之间的联结。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我和老朋友的联结越来越少。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会联结", "label": "复合"}, {"form": "情感联结", "label": "复合"}, {"form": "聯結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物之间相互连接、结合而形成的关系（如社会联结、情感联结）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结（lián jié）：事物之间相互连接、结合，或人与人之间的联系。"}, {"text": "廉价", "is_correct": false, "explanation": "廉价（lián jià）：第二音节韵母 jià 与 jié 不同（ia 与 ie），意思是价格低。"}, {"text": "拦截", "is_correct": false, "explanation": "拦截（lán jié）：第一音节 lán 少了介音 i，与 lián 不同，意思是阻挡。"}, {"text": "两截", "is_correct": false, "explanation": "两截（liǎng jié）：第一音节韵尾 ng 与 n 不同，声调也不同，意思是分成两段。"}], "explanations": {"联结": "联结（lián jié）：事物之间相互连接、结合，或人与人之间的联系。", "廉价": "廉价（lián jià）：第二音节韵母 jià 与 jié 不同（ia 与 ie），意思是价格低。", "拦截": "拦截（lán jié）：第一音节 lán 少了介音 i，与 lián 不同，意思是阻挡。", "两截": "两截（liǎng jié）：第一音节韵尾 ng 与 n 不同，声调也不同，意思是分成两段。"}, "sentence_index": null, "correct_answer": "联结"}, "level_3": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结：指人或事物之间的联系，与“摧毁……的阈值”的语境一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以被摧毁的社会关系，与游戏机制的语境不合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不指关系或结构，与“激发活力”的语境冲突。"}, {"text": "词汇", "is_correct": false, "explanation": "搭配：“词汇”不是社会结构的一部分，与“摧毁……的阈值”搭配不当。"}], "explanations": {"联结": "联结：指人或事物之间的联系，与“摧毁……的阈值”的语境一致。", "颜色": "语义：“颜色”不是可以被摧毁的社会关系，与游戏机制的语境不合。", "温度": "语义：“温度”不指关系或结构，与“激发活力”的语境冲突。", "词汇": "搭配：“词汇”不是社会结构的一部分，与“摧毁……的阈值”搭配不当。"}, "sentence_index": 0, "correct_answer": "联结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的联结很香，大家都想再吃一碗。", "explanation": "这里应该用〈味道〉。联结指事物之间的连接或关系，菜的香气要用味道。"}, {"text": "他说话的联结很快，我一句也没听清。", "explanation": "这里应该用〈速度〉。联结指连接或关系，说话的快慢要用速度。"}, {"text": "这块地的联结很大，可以种很多菜。", "explanation": "这里应该用〈面积〉。联结指连接或关系，土地的大小要用面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结：指邻居之间的人际联系，与句中语境一致。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不能说邻居之间有更多石头。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“数学”不能用来指人与人之间的关系，说“有了更多数学”不通。"}, {"text": "车辆", "is_correct": false, "explanation": "语义：“车辆”与人际关系无关，不能说邻居之间有更多车辆。"}], "explanations": {"联结": "联结：指邻居之间的人际联系，与句中语境一致。", "石头": "语义：“石头”是物体，不能说邻居之间有更多石头。", "数学": "搭配：“数学”不能用来指人与人之间的关系，说“有了更多数学”不通。", "车辆": "语义：“车辆”与人际关系无关，不能说邻居之间有更多车辆。"}, "sentence_index": 6, "correct_answer": "联结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈今天联结了一顿丰盛的晚饭。", "explanation": "这里应该用〈做〉。联结指连接或关系，做饭要用做。"}, {"text": "老师在课堂上联结了一个有趣的故事。", "explanation": "这里应该用〈讲〉。联结指连接或关系，讲故事要用讲。"}, {"text": "她在舞台上联结了一支优美的舞。", "explanation": "这里应该用〈跳〉。联结指连接或关系，跳舞要用跳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们之间有一只联结。", "corrected_sentence": "我们之间有一种联结。", "error_description": "“联结”指抽象关系时，不能用量词“只”（“只”多用于动物或成对物品中的一个）。可用“种”或“个”，如“一种联结”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和弟弟之间有很深地情感联结。", "corrected_sentence": "我和弟弟之间有很深的情感联结。", "error_description": "“很深”修饰“情感”时，中间要用“的”，不用“地”（“地”用于修饰动词或形容词）。应为“很深的情感联结”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
