INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指疾病、问题等频繁出现或发生。", "primary_collocate": null, "pronunciation": "duō fā xìng", "ipa": "tu̯ɔ˥ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "研究发现，这类疾病在老年人身上多发性较强，需要长期观察。", "target_word": "多发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病属于多发性疾病，患者需要长期治疗。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè zhǒng bìng shǔ yú duō fā xìng jí bìng, huàn zhě xū yào cháng qī zhì liáo.", "sentence_source": "generated"}, {"text": "这种皮肤病具有多发性，每年都会发作几次。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè zhǒng pí fū bìng jù yǒu duō fā xìng, měi nián dōu huì fā zuò jǐ cì.", "sentence_source": "generated"}, {"text": "多发性疾病一年里会发作好几次。", "target_word": "多发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个多发性问题，今年已经出现三次了。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè shì yí ge duō fā xìng wèn tí, jīn nián yǐ jīng chū xiàn sān cì le.", "sentence_source": "generated"}, {"text": "他得的是多发性疾病，常常好了又犯。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "tā dé de shì duō fā xìng jí bìng, cháng cháng hǎo le yòu fàn.", "sentence_source": "generated"}, {"text": "夏天的肠胃病具有多发性，大家要注意饮食。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "xià tiān de cháng wèi bìng jù yǒu duō fā xìng, dà jiā yào zhù yì yǐn shí.", "sentence_source": "generated"}, {"text": "这类故障属于多发性问题，要找原因。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè lèi gù zhàng shǔ yú duō fā xìng wèn tí, yào zhǎo yuán yīn.", "sentence_source": "generated"}, {"text": "这家工厂的安全事故属于多发性问题，领导很担心。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè jiā gōng chǎng de ān quán shì gù shǔ yú duō fā xìng wèn tí, lǐng dǎo hěn dān xīn.", "sentence_source": "generated"}, {"text": "这种病多发性很强，一年犯好几次，医生很头疼。", "target_word": "多发性", "complexity_tier": "T3", "furigana": "zhè zhǒng bìng duō fā xìng hěn qiáng, yì nián fàn hǎo jǐ cì, yī shēng hěn tóu téng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "多發性", "label": "繁体"}, {"form": "多发性疾病", "label": "复合"}, {"form": "多发性硬化", "label": "复合"}], "register": "书面语", "sense_fingerprint": "疾病或问题经常反复出现的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多发性", "is_correct": true, "explanation": "正确：“多发性较强”指疾病反复出现的程度高，与“需要长期观察”的语境相符。"}, {"text": "急性", "is_correct": false, "explanation": "搭配：“急性”指发病急、病程短，不指出现的频率，不能说“急性较强”。"}, {"text": "先天性", "is_correct": false, "explanation": "语义：“先天性”指出生时就有，与“在老年人身上”的语境不合。"}, {"text": "一次性", "is_correct": false, "explanation": "搭配：“一次性”多指只用一次，不能用来描述疾病出现的频率。"}], "explanations": {"多发性": "正确：“多发性较强”指疾病反复出现的程度高，与“需要长期观察”的语境相符。", "急性": "搭配：“急性”指发病急、病程短，不指出现的频率，不能说“急性较强”。", "先天性": "语义：“先天性”指出生时就有，与“在老年人身上”的语境不合。", "一次性": "搭配：“一次性”多指只用一次，不能用来描述疾病出现的频率。"}, "sentence_index": 0, "correct_answer": "多发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的多发性很好，吃一次就见效。", "explanation": "这里说的是药的效果，“多发性”只指疾病或问题反复出现，不能用来评价药的效果。"}, {"text": "这幅画的多发性很强，很多人都来看。", "explanation": "这里说的是一幅画，“多发性”只用于疾病或问题反复出现，不能用来形容作品。"}, {"text": "今天的天气多发性很高，很适合出门。", "explanation": "这里说的是天气，“多发性”只指疾病或问题反复出现，不能用来描述天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多发性", "is_correct": true, "explanation": "正确：“具有多发性”指疾病容易反复发生，与“要注意饮食”的提醒相符。"}, {"text": "冬季性", "is_correct": false, "explanation": "语义：“冬季性”指只在冬天出现，与“夏天的肠胃病”矛盾。"}, {"text": "先天性", "is_correct": false, "explanation": "语义：“先天性”指出生时就有，与“夏天的肠胃病”的发病时间不符。"}, {"text": "一过性", "is_correct": false, "explanation": "体貌：“一过性”指短暂出现后很快消失，与“具有……”的持续性特点不合。"}], "explanations": {"多发性": "正确：“具有多发性”指疾病容易反复发生，与“要注意饮食”的提醒相符。", "冬季性": "语义：“冬季性”指只在冬天出现，与“夏天的肠胃病”矛盾。", "先天性": "语义：“先天性”指出生时就有，与“夏天的肠胃病”的发病时间不符。", "一过性": "体貌：“一过性”指短暂出现后很快消失，与“具有……”的持续性特点不合。"}, "sentence_index": 6, "correct_answer": "多发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的多发性很好，服务很热情。", "explanation": "这里说的是餐厅的服务，“多发性”只指疾病或问题反复出现，不能用来评价餐厅。"}, {"text": "这首歌的多发性很高，大家都喜欢听。", "explanation": "这里说的是歌曲的流行程度，“多发性”只指疾病或问题反复出现，不能这样用。"}, {"text": "这双鞋的多发性很强，穿了好几年。", "explanation": "这里说的是鞋子，“多发性”只用于疾病或问题反复出现，不能用来描述鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这类故障多发性的较高，要定期检查。", "corrected_sentence": "这类故障多发性较高，要定期检查。", "error_description": "错误：“多发性”后面多出了“的”，使它成为定语却没有中心语，“较高”前不能接“的”。正确：“多发性较高”，“多发性”作主语，“较高”作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这类问题的多发性很比较高。", "corrected_sentence": "这类问题的多发性比较高。", "error_description": "错误：程度副词“很”与“比较”重复使用，两者不能同时修饰“高”。正确：“多发性比较高”，只用“比较”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "融化指固体受热变为液体，并非由硬变软，与“硬化”没有反义关系。"}, {"text": "腐烂", "is_correct": false, "explanation": "腐烂指有机物分解变质，与“硬化”没有反义关系。"}, {"text": "发酵", "is_correct": false, "explanation": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "融化": "融化指固体受热变为液体，并非由硬变软，与“硬化”没有反义关系。", "腐烂": "腐烂指有机物分解变质，与“硬化”没有反义关系。", "发酵": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "溶解", "is_correct": false, "explanation": "溶解指物质在液体中化开，与“硬化”没有反义关系。"}, {"text": "变质", "is_correct": false, "explanation": "变质指物质性质发生坏的变化，与“硬化”没有反义关系。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结指液体变为固体，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "溶解": "溶解指物质在液体中化开，与“硬化”没有反义关系。", "变质": "变质指物质性质发生坏的变化，与“硬化”没有反义关系。", "冻结": "冻结指液体变为固体，与“硬化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物体由软变硬的过程或性质。", "primary_collocate": null, "pronunciation": "yìng huà", "ipa": "iŋ˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "某些研究甚至提出，哈欠的频率可作为神经系统健康的指标，例如在多发性硬化、癫痫或抑郁症患者中，异常频繁的哈欠常被视为疾病活动的前兆。", "target_word": "硬化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水泥的硬化是由软变硬的过程。", "target_word": "硬化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "混凝土硬化以后，才能在上面走路。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "胶水干了以后会发生硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料遇冷会出现硬化现象。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮革长期不用，就会出现硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团放太久会发生表面硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "橡胶的硬化会让轮胎容易裂开。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤硬化后，种子很难长出来。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验中，我们观察了泥土的硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬化症", "label": "复合"}, {"form": "动脉硬化", "label": "复合"}], "register": "书面语", "sense_fingerprint": "物体由软变硬的过程或性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：“多发性硬化”是一种神经系统疾病的名称，“硬化”在此指组织由软变硬，与“癫痫、抑郁症”并列。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是呼吸道疾病，不属于神经系统疾病，与“癫痫、抑郁症”并列不合句意。"}, {"text": "胃炎", "is_correct": false, "explanation": "语义：胃炎属于消化系统疾病，句子讲的是神经系统健康的指标，不能并列在此。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“多发性”修饰疾病名称，“发烧”是症状，不能说“多发性发烧”。"}], "explanations": {"硬化": "正确：“多发性硬化”是一种神经系统疾病的名称，“硬化”在此指组织由软变硬，与“癫痫、抑郁症”并列。", "感冒": "语义：感冒是呼吸道疾病，不属于神经系统疾病，与“癫痫、抑郁症”并列不合句意。", "胃炎": "语义：胃炎属于消化系统疾病，句子讲的是神经系统健康的指标，不能并列在此。", "发烧": "搭配：“多发性”修饰疾病名称，“发烧”是症状，不能说“多发性发烧”。"}, "sentence_index": 0, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅牛奶冷了以后会硬化。", "explanation": "这里应该用〈凝固〉。硬化指固体由软变硬，液体变成固体要用凝固。"}, {"text": "水蒸气遇冷会硬化成水珠。", "explanation": "这里应该用〈凝结〉。水蒸气变成水珠是由气体变为液体，应说凝结；硬化只指物体变硬。"}, {"text": "冰块遇热会硬化。", "explanation": "这里应该用〈熔化〉。冰块遇热是由固体变成液体，与硬化“由软变硬”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：面团表面变干变硬，是由软变硬的过程，符合“表面硬化”。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体变为液体，面团放久只会变干变硬，不会融化。"}, {"text": "汽化", "is_correct": false, "explanation": "语域：“汽化”是科技术语，描述液体变气体，日常语境中不用于面团。"}, {"text": "液化", "is_correct": false, "explanation": "语义：液化指气体变为液体，面团不是气体，句意不合。"}], "explanations": {"硬化": "正确：面团表面变干变硬，是由软变硬的过程，符合“表面硬化”。", "融化": "语义：融化指固体变为液体，面团放久只会变干变硬，不会融化。", "汽化": "语域：“汽化”是科技术语，描述液体变气体，日常语境中不用于面团。", "液化": "语义：液化指气体变为液体，面团不是气体，句意不合。"}, "sentence_index": 6, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这罐酱油放久了会硬化。", "explanation": "这里应该用〈变质〉。硬化指由软变硬，酱油放久坏掉要说变质。"}, {"text": "铁器在潮湿的空气里会硬化。", "explanation": "这里应该用〈腐蚀〉。铁器受潮被侵蚀要说腐蚀，硬化讲的是材料由软变硬。"}, {"text": "这盆鲜花三天没浇水，就硬化了。", "explanation": "这里应该用〈枯萎〉。植物缺水变蔫要说枯萎，硬化指物体由软变硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "硬化地速度跟温度有关。", "corrected_sentence": "硬化的速度跟温度有关。", "error_description": "“硬化”修饰名词“速度”时应用“的”，写成“地”是错误，“地”用于修饰动词或形容词。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种水泥硬化地很快。", "corrected_sentence": "这种水泥硬化得很快。", "error_description": "错误：“硬化地很快”；正确：“硬化得很快”。补语要用“得”引出，“地”只用于状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
