INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "癫痫是一种脑部疾病，发作时大脑神经元异常放电，导致身体抽搐、意识丧失等症状。", "primary_collocate": null, "pronunciation": "diān xián", "ipa": "tjɛn˥ ɕjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "某些研究甚至提出，哈欠的频率可作为神经系统健康的指标，例如在多发性硬化、癫痫或抑郁症患者中，异常频繁的哈欠常被视为疾病活动的前兆。", "target_word": "癫痫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "癫痫是一种脑部疾病，发作时会抽搐。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生怀疑他得了癫痫，让他做脑电图。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫患者发作时，周围的人要保持冷静。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位孩子从小就有癫痫，需要长期服药。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫发作时，大脑神经元会异常放电。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "治疗癫痫的药物必须按时服用。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫可能由脑外伤或脑部感染引起。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "患有癫痫的人不宜独自游泳或登山。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家介绍了癫痫的常见症状和急救方法。", "target_word": "癫痫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "癲癇", "label": "繁体"}, {"form": "癫痫病", "label": "复合"}, {"form": "癫痫发作", "label": "复合"}], "register": "书面语", "sense_fingerprint": "大脑神经元异常放电导致抽搐、意识丧失的脑部疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "癫痫", "is_correct": true, "explanation": "正确：癫痫是脑部疾病，与“多发性硬化”“抑郁症”同属神经系统相关疾病，可并列。"}, {"text": "胃炎", "is_correct": false, "explanation": "语义：胃炎属于消化系统疾病，不属于神经系统疾病，与句中并列的疾病不合。"}, {"text": "疲劳", "is_correct": false, "explanation": "语义：疲劳是身体状态，不是疾病，不能与“多发性硬化”“抑郁症”并列。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是呼吸道感染，不属于神经系统疾病，与句意不合。"}], "explanations": {"癫痫": "正确：癫痫是脑部疾病，与“多发性硬化”“抑郁症”同属神经系统相关疾病，可并列。", "胃炎": "语义：胃炎属于消化系统疾病，不属于神经系统疾病，与句中并列的疾病不合。", "疲劳": "语义：疲劳是身体状态，不是疾病，不能与“多发性硬化”“抑郁症”并列。", "感冒": "语义：感冒是呼吸道感染，不属于神经系统疾病，与句意不合。"}, "sentence_index": 0, "correct_answer": "癫痫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一生气就癫痫，把桌子都掀了。", "explanation": "这里应该用〈发脾气〉。癫痫是病名，不能用来形容发脾气。"}, {"text": "他一看到血就癫痫。", "explanation": "这里应该用〈晕厥〉。癫痫是病名，不能当动词描述突然失去意识，应说晕厥。"}, {"text": "误食毒蘑菇以后，他很快癫痫了。", "explanation": "这里应该用〈中毒〉。癫痫是慢性神经疾病，不能用来描述误食后的急性状况，应说中毒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "癫痫", "is_correct": true, "explanation": "正确：癫痫是可以治疗的脑部疾病，“治疗癫痫的药物”指治疗该病的药。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是疾病，不能被药物治疗，句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是疾病，不能用药物治疗，句意不合。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“治疗”的对象应为人的病症，不能说“治疗汽车”。"}], "explanations": {"癫痫": "正确：癫痫是可以治疗的脑部疾病，“治疗癫痫的药物”指治疗该病的药。", "音乐": "语义：音乐不是疾病，不能被药物治疗，句意不合。", "天气": "语义：天气不是疾病，不能用药物治疗，句意不合。", "汽车": "搭配：“治疗”的对象应为人的病症，不能说“治疗汽车”。"}, "sentence_index": 6, "correct_answer": "癫痫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他中风以后，半身都癫痫了。", "explanation": "这里应该用〈瘫痪〉。癫痫是发作性疾病，描述肢体失去功能要说瘫痪。"}, {"text": "病人手脚不停地癫痫。", "explanation": "这里应该用〈抽搐〉。癫痫是病名，形容肢体的抽动要说抽搐。"}, {"text": "他因为青光眼而癫痫。", "explanation": "这里应该用〈失明〉。青光眼导致视力丧失，应说失明；癫痫是另一种疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的癫痫发作地很突然。", "corrected_sentence": "他的癫痫发作得很突然。", "error_description": "错误：“发作地很突然”；正确：“发作得很突然”。“很突然”是补语，要用“得”引出，“地”只用于状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候过得癫痫，现在已经控制住了。", "corrected_sentence": "他小时候得过癫痫，现在已经控制住了。", "error_description": "“得过”表示曾经患过某病，“过”应紧跟动词“得”；写成“过得”是错误，“过得”是“生活、度日”的意思，不能接“癫痫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
