INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11297, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "抑郁症是一种常见的精神障碍，主要特征是持续的情绪低落、兴趣减退、思维迟缓，并可能伴随睡眠、食欲等生理功能改变，严重影响日常生活。", "primary_collocate": null, "pronunciation": "yì yù zhèng", "ipa": "i˥˩ y˥˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "某些研究甚至提出，哈欠的频率可作为神经系统健康的指标，例如在多发性硬化、癫痫或抑郁症患者中，异常频繁的哈欠常被视为疾病活动的前兆。", "target_word": "抑郁症", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "抑郁症患者常常觉得很难过。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他得了抑郁症，需要吃药。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抑郁症不是软弱，而是一种需要治疗的病。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得了抑郁症的人常常睡不好，也不想吃饭。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为抑郁症一年多没有工作。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的关心能帮助抑郁症患者好起来。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生认为他的症状符合抑郁症的诊断标准。", "target_word": "抑郁症", "complexity_tier": "T3", "furigana": "yì yù zhèng", "sentence_source": "generated"}, {"text": "医生建议他去医院检查是不是抑郁症。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人也会得抑郁症。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "产后抑郁症", "label": "复合"}, {"form": "抑郁症患者", "label": "复合"}], "register": "书面", "sense_fingerprint": "以持续情绪低落、兴趣减退为主要特征的精神障碍（医学术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑郁症", "is_correct": true, "explanation": "抑郁症是一种精神障碍，与前面的多发性硬化、癫痫并列，指同一类神经或精神疾病患者，符合句中的语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是常见的呼吸道疾病，与前面列出的神经系统疾病不同类，不能并列。"}, {"text": "骨折", "is_correct": false, "explanation": "语义：骨折属于外伤，不是神经系统疾病，与“多发性硬化、癫痫”并列不合。"}, {"text": "毛病", "is_correct": false, "explanation": "语域：“毛病”是口语说法，不是医学病名，不能与“多发性硬化、癫痫”并列。"}], "explanations": {"抑郁症": "抑郁症是一种精神障碍，与前面的多发性硬化、癫痫并列，指同一类神经或精神疾病患者，符合句中的语境。", "感冒": "语义：感冒是常见的呼吸道疾病，与前面列出的神经系统疾病不同类，不能并列。", "骨折": "语义：骨折属于外伤，不是神经系统疾病，与“多发性硬化、癫痫”并列不合。", "毛病": "语域：“毛病”是口语说法，不是医学病名，不能与“多发性硬化、癫痫”并列。"}, "sentence_index": 0, "correct_answer": "抑郁症"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里装着很多抑郁症。", "explanation": "这里应该用〈忧愁〉。抑郁症是临床诊断的疾病名称，不能像心事一样“装着很多”；说心里的愁苦要用忧愁。"}, {"text": "他的抑郁症说忘就忘了，每天都睡不好。", "explanation": "这里应该用〈烦恼〉。烦恼可以说忘就忘；抑郁症是临床诊断的疾病，不能像心事一样说忘就忘。"}, {"text": "他的爱好是抑郁症，每天都在家里待着。", "explanation": "这里应该用〈画画〉。“爱好”指喜欢做的事情，抑郁症是疾病，不能当作爱好来说；说喜欢做的事要用〈画画〉这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑郁症", "is_correct": true, "explanation": "抑郁症指精神障碍，是这里需要的疾病名称，符合“患者好起来”的语境。"}, {"text": "近视", "is_correct": false, "explanation": "语义：近视是视力问题，不会因朋友的关心而“好起来”，与“帮助……好起来”语义冲突。"}, {"text": "色盲", "is_correct": false, "explanation": "语义：色盲是先天辨色能力的问题，关心无法使它“好起来”，语义不合。"}, {"text": "失明", "is_correct": false, "explanation": "搭配：“失明”指视力已经丧失，不说“失明患者好起来”，与句中的“帮助……好起来”搭配不当。"}], "explanations": {"抑郁症": "抑郁症指精神障碍，是这里需要的疾病名称，符合“患者好起来”的语境。", "近视": "语义：近视是视力问题，不会因朋友的关心而“好起来”，与“帮助……好起来”语义冲突。", "色盲": "语义：色盲是先天辨色能力的问题，关心无法使它“好起来”，语义不合。", "失明": "搭配：“失明”指视力已经丧失，不说“失明患者好起来”，与句中的“帮助……好起来”搭配不当。"}, "sentence_index": 6, "correct_answer": "抑郁症"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试没考好，我今天有点抑郁症。", "explanation": "这里应该用〈心情不好〉。抑郁症是临床诊断的精神障碍，不能用来形容一时的烦闷。"}, {"text": "他把抑郁症当作一种乐趣，天天都想去体验。", "explanation": "这里应该用〈娱乐〉。抑郁症是疾病名称，不能当作可以去体验的乐趣；把它说成娱乐活动是误用。"}, {"text": "他是我们班的抑郁症，大家都很喜欢他。", "explanation": "这里应该用〈开心果〉。抑郁症是疾病名称，不能用来称呼一个人或形容他的性格；形容受欢迎的人要说〈开心果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她得着抑郁症，一年多没有上班。", "corrected_sentence": "她得了抑郁症，一年多没有上班。", "error_description": "体标错误：表示患病已经发生，应说“得了抑郁症”，用“了”；“得着”意为获得，不能表示患上疾病。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他过抑郁症，现在已经好多了。", "corrected_sentence": "他得过抑郁症，现在已经好多了。", "error_description": "缺词错误：表示经历的“过”前面要有动词，“过”不能直接接宾语“抑郁症”，应补上动词“得”，说“得过抑郁症”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "“正常”与“异常”是反义词，指符合平常的状态，与“数据出现异常”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“异常”在这一义项上没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”指坚固，与“异常”在这一义项上没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“异常”在这一义项上没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "“正常”与“异常”是反义词，指符合平常的状态，与“数据出现异常”相对。", "清楚": "“清楚”指明白、不模糊，与“异常”在这一义项上没有反义关系。", "结实": "“结实”指坚固，与“异常”在这一义项上没有反义关系。", "明亮": "“明亮”指光线充足，与“异常”在这一义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "“正常”与“异常”是反义词，指符合常态，与“血压异常”相对。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指智力好，与“异常”在这一义项上没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有脏东西，与“异常”在这一义项上没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”指价格低，与“异常”在这一义项上没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "“正常”与“异常”是反义词，指符合常态，与“血压异常”相对。", "聪明": "“聪明”指智力好，与“异常”在这一义项上没有反义关系。", "干净": "“干净”指没有脏东西，与“异常”在这一义项上没有反义关系。", "便宜": "“便宜”指价格低，与“异常”在这一义项上没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不同于平常的、不正常的。", "primary_collocate": null, "pronunciation": "yì cháng", "ipa": "i˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "医生说我的检查结果异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的声音有点异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天的体温异常，要马上去医院。", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据出现异常，请再检查一次。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市最近出现了异常天气。", "target_word": "异常", "complexity_tier": "T3", "furigana": "yì cháng", "sentence_source": "generated"}, {"text": "医生发现他的心跳有些异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到异常情况，请马上告诉老师。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑今天突然出现异常，不能开机。", "target_word": "异常", "complexity_tier": "T3", "furigana": "yì cháng", "sentence_source": "generated"}, {"text": "孩子的检查结果没有异常，不用担心。", "target_word": "异常", "complexity_tier": "T3", "furigana": "yì cháng", "sentence_source": "generated"}, {"text": "一旦发现血压异常，就要去看医生。", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "异常情况", "label": "复合"}, {"form": "异常现象", "label": "复合"}], "register": "中性", "sense_fingerprint": "不同于正常状态的、不正常的（检查、数据、机器等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异常", "is_correct": true, "explanation": "“异常”在这里指检查结果偏离正常，与“检查结果”搭配，符合句意。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”形容表演或比赛，不能形容检查结果，语义不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外表，不修饰“检查结果”，搭配不当。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容心情，检查结果不能说“愉快”，与句意不合。"}], "explanations": {"异常": "“异常”在这里指检查结果偏离正常，与“检查结果”搭配，符合句意。", "精彩": "语义：“精彩”形容表演或比赛，不能形容检查结果，语义不通。", "漂亮": "搭配：“漂亮”多形容外表，不修饰“检查结果”，搭配不当。", "愉快": "语义：“愉快”形容心情，检查结果不能说“愉快”，与句意不合。"}, "sentence_index": 0, "correct_answer": "异常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说我的检查结果很异常，说明我身体非常健康。", "explanation": "这里应该用〈正常〉。异常指偏离正常状态，不能用来说明身体健康；健康时结果应说“正常”。"}, {"text": "他每天按时睡觉，作息很异常，身体也很好。", "explanation": "这里应该用〈规律〉。异常指偏离常态，不能用来形容按时作息的状态；作息有规律要说“规律”。"}, {"text": "这家工厂的生产情况很异常，每天都按计划完成。", "explanation": "这里应该用〈稳定〉。异常指偏离正常，不能用来形容按计划完成的生产；生产平稳应说“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异常", "is_correct": true, "explanation": "“异常”修饰“情况”，指不正常的情形，符合“马上告诉老师”的语境。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不修饰“情况”，搭配不当。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”说外貌或景色，与“情况”不搭，也不符合“告诉老师”的语境。"}, {"text": "活泼", "is_correct": false, "explanation": "体貌：“活泼”形容人或动物的性情样子，不能修饰“情况”。"}], "explanations": {"异常": "“异常”修饰“情况”，指不正常的情形，符合“马上告诉老师”的语境。", "聪明": "搭配：“聪明”形容人的智力，不修饰“情况”，搭配不当。", "美丽": "语义：“美丽”说外貌或景色，与“情况”不搭，也不符合“告诉老师”的语境。", "活泼": "体貌：“活泼”形容人或动物的性情样子，不能修饰“情况”。"}, "sentence_index": 6, "correct_answer": "异常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个路口的车辆很异常，每天都按照规则行驶。", "explanation": "这里应该用〈规范〉。异常指偏离常态，不能用来形容按规则行驶的车辆；守规矩的状态要说“规范”。"}, {"text": "这部电影的结局很异常，大家都觉得是按照老套路写的。", "explanation": "这里应该用〈常规〉。异常指偏离常态，不能用来形容按老套路写的结局；按常规写要说“常规”。"}, {"text": "他的表情很异常，一直没有变化，像平时一样。", "explanation": "这里应该用〈自然〉。异常指偏离平时的状态，不能用来形容一直没有变化、像平时一样的表情；这种表情应说“自然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "如果出现异常地情况，请马上告诉老师。", "corrected_sentence": "如果出现异常的情况，请马上告诉老师。", "error_description": "助词错误：修饰名词“情况”要用“的”，应说“异常的情况”；“地”用于修饰动词，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂的机器前几天异常很，已经停下来了。", "corrected_sentence": "这家工厂的机器前几天异常得很，已经停下来了。", "error_description": "补语错误：表示程度的补语要用“异常得很”，“得”不能省，应说“异常得很”，不说“异常很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "正确。健康指身体没有疾病，与“疾病”意思相对。"}, {"text": "食物", "is_correct": false, "explanation": "与“疾病”没有反义关系：食物指吃的东西，不是身体的状态。"}, {"text": "书本", "is_correct": false, "explanation": "与“疾病”没有反义关系：书本指印刷品，和身体状况无关。"}, {"text": "河流", "is_correct": false, "explanation": "与“疾病”没有反义关系：河流指地面上的水流，不涉及身体状况。"}], "correct_answer": "健康", "explanations": {"健康": "正确。健康指身体没有疾病，与“疾病”意思相对。", "食物": "与“疾病”没有反义关系：食物指吃的东西，不是身体的状态。", "书本": "与“疾病”没有反义关系：书本指印刷品，和身体状况无关。", "河流": "与“疾病”没有反义关系：河流指地面上的水流，不涉及身体状况。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "正确。健康指身体没有疾病，与“疾病”意思相对。"}, {"text": "天气", "is_correct": false, "explanation": "与“疾病”没有反义关系：天气指大气的状况，不涉及身体。"}, {"text": "桌子", "is_correct": false, "explanation": "与“疾病”没有反义关系：桌子是家具，与身体状况无关。"}, {"text": "花园", "is_correct": false, "explanation": "与“疾病”没有反义关系：花园是种花草的地方，不涉及身体。"}], "correct_answer": "健康", "explanations": {"健康": "正确。健康指身体没有疾病，与“疾病”意思相对。", "天气": "与“疾病”没有反义关系：天气指大气的状况，不涉及身体。", "桌子": "与“疾病”没有反义关系：桌子是家具，与身体状况无关。", "花园": "与“疾病”没有反义关系：花园是种花草的地方，不涉及身体。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指身体出现异常状态，通常需要治疗。", "primary_collocate": null, "pronunciation": "jí bìng", "ipa": "tɕi˧˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种疾病需要长时间治疗。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吸烟会带来很多疾病。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生正在研究这种疾病的原因。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人容易得各种疾病。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为疾病离开了学校。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多运动可以少得疾病。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种疾病会从一个人传给另一个人。", "target_word": "疾病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早发现疾病，才能早治疗。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的家人有心脏疾病。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院是治疗疾病的地方。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢性疾病", "label": "复合"}, {"form": "心脏疾病", "label": "复合"}], "register": "书面", "sense_fingerprint": "身体出现异常、通常需要治疗的状态（泛指各种病）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾病", "is_correct": true, "explanation": "正确。疾病是需要长时间治疗的对象。"}, {"text": "药品", "is_correct": false, "explanation": "语义：药品是用来治疗的，本身不需要被治疗，句子不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是进行治疗的场所，不是需要治疗的对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“治疗”的对象应是人或病，不能说天气需要治疗。"}], "explanations": {"疾病": "正确。疾病是需要长时间治疗的对象。", "药品": "语义：药品是用来治疗的，本身不需要被治疗，句子不通。", "医院": "语义：医院是进行治疗的场所，不是需要治疗的对象。", "天气": "搭配：“治疗”的对象应是人或病，不能说天气需要治疗。"}, "sentence_index": 0, "correct_answer": "疾病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "官员应当体恤民间的疾病，不能只顾自己的利益。", "explanation": "这里应该用〈疾苦〉。疾苦指困苦和痛苦，多用于“民间的疾苦”，常与“体恤”搭配；疾病指身体的病，不能用来指生活中的困难。"}, {"text": "这是一只疾病，很难治。", "explanation": "这里应该用〈种〉。疾病用“种”或“类”计量，“只”用于动物等，不能用于疾病。"}, {"text": "医院里躺着很多疾病，等着人来照顾。", "explanation": "这里应该用〈病患〉。病患指患病的人，可以躺在病房里等人照顾；疾病指病本身，不能躺着等人照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疾病", "is_correct": true, "explanation": "正确。疾病可以从一个人传给另一个人。"}, {"text": "伤口", "is_correct": false, "explanation": "语义：伤口不会传染，不能从一个人传给另一个人。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑不能被传染，也不能传给别人，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“传给”一般用于病菌、疾病，颜色不能这样传递。"}], "explanations": {"疾病": "正确。疾病可以从一个人传给另一个人。", "伤口": "语义：伤口不会传染，不能从一个人传给另一个人。", "建筑": "语义：建筑不能被传染，也不能传给别人，句子不通。", "颜色": "搭配：“传给”一般用于病菌、疾病，颜色不能这样传递。"}, "sentence_index": 6, "correct_answer": "疾病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑有疾病，经常死机。", "explanation": "这里应该用〈毛病〉。疾病指人或动植物的病，电脑出了问题要说毛病。"}, {"text": "他的疾病是爱发脾气。", "explanation": "这里应该用〈缺点〉。缺点指性格或行为上的不足；疾病指身体的病，不能用来说性格问题。"}, {"text": "这辆车的疾病修好了。", "explanation": "这里应该用〈故障〉。故障指机器出了问题；疾病只指生物的病，不能用于汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多人都得过这只疾病。", "corrected_sentence": "很多人都得过这种疾病。", "error_description": "量词错误：疾病应搭配量词“种”，“只”用于动物等，应说“这种疾病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只慢性疾病需要长期治疗。", "corrected_sentence": "这种慢性疾病需要长期治疗。", "error_description": "量词错误：疾病应搭配量词“种”，“只”用于动物等，应说“这种慢性疾病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
