INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11301, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事情发生前显现的迹象或征兆。", "primary_collocate": null, "pronunciation": "qián zhào", "ipa": "tɕʰjɛn˧˥ ʈʂaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "某些研究甚至提出，哈欠的频率可作为神经系统健康的指标，例如在多发性硬化、癫痫或抑郁症患者中，异常频繁的哈欠常被视为疾病活动的前兆。", "target_word": "前兆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "头疼可能是感冒的前兆。", "target_word": "前兆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的乌云是大雨的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这种症状可能是重病的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地面突然晃动，往往是地震的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常失眠，这是身体出问题的前兆。", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子低飞是下雨的前兆。", "target_word": "前兆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她没有注意到，这次吵架其实是分手的前兆。", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体温持续升高，可能是感染的前兆。", "target_word": "前兆", "complexity_tier": "T3", "furigana": "qián zhào", "sentence_source": "generated"}, {"text": "公司的订单越来越少，是不是倒闭的前兆？", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "前兆|事情发生前显现的迹象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前兆", "is_correct": true, "explanation": "正确。“疾病活动的前兆”指疾病发作前显现的迹象。"}, {"text": "药物", "is_correct": false, "explanation": "语义：药物用来治病，不是疾病活动的迹象，句意不通。"}, {"text": "器官", "is_correct": false, "explanation": "搭配：“疾病活动的”后面应接表示迹象的名词，“器官”不能这样用。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与疾病活动无关，不能作为迹象。"}], "explanations": {"前兆": "正确。“疾病活动的前兆”指疾病发作前显现的迹象。", "药物": "语义：药物用来治病，不是疾病活动的迹象，句意不通。", "器官": "搭配：“疾病活动的”后面应接表示迹象的名词，“器官”不能这样用。", "乐器": "语义：乐器与疾病活动无关，不能作为迹象。"}, "sentence_index": 0, "correct_answer": "前兆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的前兆很好听。", "explanation": "这里应该用〈前奏〉。前奏指音乐开始的部分；前兆指事情发生前的迹象，不能用于歌曲。"}, {"text": "她的前兆是一名医生。", "explanation": "这里应该用〈前任〉。前任指以前担任某职务的人；前兆是迹象，不指人。"}, {"text": "天边出现了一只前兆。", "explanation": "这里应该用〈种〉。前兆用“种”或“个”计量，“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前兆", "is_correct": true, "explanation": "正确。燕子低飞是下雨前显现的迹象。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是下雨的迹象，句子说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包与下雨无关，不能作为迹象。"}, {"text": "伞", "is_correct": false, "explanation": "搭配：“下雨的”后接的应是天气或现象，伞是用具，搭配不当。"}], "explanations": {"前兆": "正确。燕子低飞是下雨前显现的迹象。", "窗户": "语义：窗户不是下雨的迹象，句子说不通。", "书包": "语义：书包与下雨无关，不能作为迹象。", "伞": "搭配：“下雨的”后接的应是天气或现象，伞是用具，搭配不当。"}, "sentence_index": 6, "correct_answer": "前兆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我工作上的前兆，教了我很多东西。", "explanation": "这里应该用〈前辈〉。前辈指在某方面经验多、资历深的人；前兆指迹象，不指人。"}, {"text": "他有前兆，所以很难找到工作。", "explanation": "这里应该用〈前科〉。前科指以前的犯罪记录；前兆是迹象，不能用来说明一个人的经历。"}, {"text": "我前兆刚出门，他后脚就到了。", "explanation": "这里应该用〈前脚〉。前脚指先迈出的那只脚，表示刚刚发生的事；前兆是迹象，不能表示先后动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "嗓子疼常常是感冒的一只前兆。", "corrected_sentence": "嗓子疼常常是感冒的一种前兆。", "error_description": "量词错误：前兆应搭配“种”或“个”，“只”用于动物等，应说“一种前兆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续好几天打喷嚏，这是感冒的一只前兆。", "corrected_sentence": "连续好几天打喷嚏，这是感冒的一种前兆。", "error_description": "量词错误：前兆应搭配“种”或“个”，“只”用于动物等，应说“感冒的一种前兆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
