INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11302, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容光线充足，天气好；也指心情愉快、没有烦恼。", "primary_collocate": null, "pronunciation": "míng lǎng", "ipa": "miŋ˧˥ laŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "东边的天色逐渐明朗起来，鸟儿也开始叫了。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气很明朗，我们去爬山吧。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停以后，天空变得明朗起来。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月色很明朗，我们在院子里坐了一会儿。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，她的心情一下子明朗了。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说，现在心情比以前明朗多了。", "target_word": "明朗", "complexity_tier": "T3", "furigana": "tā xiào zhe shuō, xiàn zài xīn qíng bǐ yǐ qián míng lǎng duō le.", "sentence_source": "generated"}, {"text": "冬天的早晨，天空明朗而安静。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试结束后，她的心情很明朗。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的天气明朗，适合出去玩。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有了烦恼，他的脸上露出明朗的笑容。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "明朗化", "label": "复合词"}, {"form": "不明朗", "label": "否定式"}], "register": "书面", "sense_fingerprint": "明朗|天气好光线足；心情愉快没烦恼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天色变亮、清楚，与“逐渐”搭配，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容形体或形象，不能说天色“逐渐高大”。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”说质地，不能用来形容天色。"}, {"text": "红火", "is_correct": false, "explanation": "语义：“红火”多指生活或买卖热闹，不能用来形容天色。"}], "explanations": {"明朗": "明朗：天色变亮、清楚，与“逐渐”搭配，符合句意。", "高大": "语义：“高大”形容形体或形象，不能说天色“逐渐高大”。", "柔软": "语义：“柔软”说质地，不能用来形容天色。", "红火": "语义：“红火”多指生活或买卖热闹，不能用来形容天色。"}, "sentence_index": 0, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯很明朗，正适合在桌前看书。", "explanation": "这里应该用〈明亮〉。明朗多形容天气、心情或声音，灯和光源这类发亮的物体要用〈明亮〉。"}, {"text": "这块金属被打磨得很明朗，闪闪发亮。", "explanation": "这里应该用〈光亮〉。形容金属等物体表面发亮要用〈光亮〉，明朗用于天气、心情，不用于描写物体表面。"}, {"text": "这杯茶的味道很明朗，喝起来很清爽。", "explanation": "这里应该用〈醇厚〉。形容茶的滋味要用〈醇厚〉或〈清香〉，明朗不用于描写味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天色清朗、明亮，与“天空”搭配，符合“而安静”的语境。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或声音，不用来形容天空。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”说质地，与天空的样子不相符。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：“尖锐”多用于声音或矛盾，不与“天空”搭配。"}], "explanations": {"明朗": "明朗：天色清朗、明亮，与“天空”搭配，符合“而安静”的语境。", "甜美": "语义：“甜美”形容味道或声音，不用来形容天空。", "坚硬": "语义：“坚硬”说质地，与天空的样子不相符。", "尖锐": "搭配：“尖锐”多用于声音或矛盾，不与“天空”搭配。"}, "sentence_index": 6, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把刀很明朗，一碰就划手。", "explanation": "这里应该用〈锋利〉。形容刀刃锋利要用〈锋利〉，明朗不用于描写刀具。"}, {"text": "山里的空气很明朗，吸一口让人精神一振。", "explanation": "这里应该用〈清新〉。形容空气要用〈清新〉，明朗不用于形容空气。"}, {"text": "这碗饭煮得很明朗，吃起来很松软。", "explanation": "这里应该用〈松软〉。形容饭菜软而不硬要用〈松软〉，明朗不用于描写食物口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明朗的笑了。", "corrected_sentence": "他明朗地笑了。", "error_description": "“明朗”修饰动词“笑”，应该用“地”，不能用“的”。错误形式是“明朗的”，正确形式是“明朗地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的心情地明朗，笑个不停。", "corrected_sentence": "他的心情很明朗，笑个不停。", "error_description": "“明朗”前应用程度副词“很”，不能用结构助词“地”。错误形式是“地明朗”，正确形式是“很明朗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取", "is_correct": true, "explanation": "取：与“存”构成反义，指把存放的东西拿出来。"}, {"text": "买", "is_correct": false, "explanation": "买是购入，与“存”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声，与“存”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑是移动，与“存”没有反义关系。"}], "correct_answer": "取", "explanations": {"取": "取：与“存”构成反义，指把存放的东西拿出来。", "买": "买是购入，与“存”没有反义关系。", "唱": "唱是发声，与“存”没有反义关系。", "跑": "跑是移动，与“存”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
