INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示事物持续存在，或把东西放在某个地方。", "primary_collocate": null, "pronunciation": "cún", "ipa": "tsʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这种药要存在阴凉处，不能见光。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "尽管哈欠的生理功能逐渐明朗，其神经化学基础仍存争议。", "target_word": "存", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他每个月都把一千块钱存进银行。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把这些照片存在电脑里。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个文件你存了吗？", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在冰箱里存了很多水果。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先把行李存在前台。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小就有存钱的习惯。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机里存着很多旧照片。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，这种牛奶存不了太久。", "target_word": "存", "complexity_tier": "T3", "furigana": "tiān qì tài rè, zhè zhǒng niú nǎi cún bù liǎo tài jiǔ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "存了", "label": "完成体"}, {"form": "存着", "label": "持续体"}, {"form": "存过", "label": "经历体"}, {"form": "存放", "label": "复合词"}, {"form": "存款", "label": "复合词"}], "register": "中性", "sense_fingerprint": "存|保存放置；持续存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "存", "is_correct": true, "explanation": "cún，意思是保存、放置，或持续存在。"}, {"text": "村", "is_correct": false, "explanation": "cūn（第一声）与 cún（第二声）声调不同，意思是村庄。"}, {"text": "寸", "is_correct": false, "explanation": "cùn（第四声）与 cún（第二声）声调不同，意思是长度单位寸。"}, {"text": "唇", "is_correct": false, "explanation": "chún 与 cún 声母不同（ch 与 c），意思是嘴唇。"}], "explanations": {"存": "cún，意思是保存、放置，或持续存在。", "村": "cūn（第一声）与 cún（第二声）声调不同，意思是村庄。", "寸": "cùn（第四声）与 cún（第二声）声调不同，意思是长度单位寸。", "唇": "chún 与 cún 声母不同（ch 与 c），意思是嘴唇。"}, "sentence_index": null, "correct_answer": "存"}, "level_3": {"options": [{"text": "存", "is_correct": true, "explanation": "存：表示把东西保存在某处，与“阴凉处”搭配，符合句意。"}, {"text": "活", "is_correct": false, "explanation": "搭配：“活”指活着、生活，“这种药要活在阴凉处”不通。"}, {"text": "灭", "is_correct": false, "explanation": "语义：“灭”表示消失，与“保存”的意思相矛盾。"}, {"text": "亡", "is_correct": false, "explanation": "语义：“亡”表示死亡，与“保存”的意思相矛盾。"}], "explanations": {"存": "存：表示把东西保存在某处，与“阴凉处”搭配，符合句意。", "活": "搭配：“活”指活着、生活，“这种药要活在阴凉处”不通。", "灭": "语义：“灭”表示消失，与“保存”的意思相矛盾。", "亡": "语义：“亡”表示死亡，与“保存”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他存了满分，大家都很佩服。", "explanation": "这里应该用〈得〉。取得成绩要说“得”，“存”不表示获得。"}, {"text": "我想把这些照片存在墙上，就像挂画一样。", "explanation": "这里应该用〈挂〉。把东西固定在墙上要说挂，“存”不表示悬挂或固定。"}, {"text": "这些照片我要存给北京的朋友看。", "explanation": "这里应该用〈发〉。把照片传给别人要说发，“存”不表示传送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "存", "is_correct": true, "explanation": "cún，意思是保存、放置，或持续存在。"}, {"text": "纯", "is_correct": false, "explanation": "chún 与 cún 声母不同（ch 与 c），意思是纯净。"}, {"text": "春", "is_correct": false, "explanation": "chūn 与 cún 声母和声调都不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn 与 cún 声母和声调不同，意思是愚蠢。"}], "explanations": {"存": "cún，意思是保存、放置，或持续存在。", "纯": "chún 与 cún 声母不同（ch 与 c），意思是纯净。", "春": "chūn 与 cún 声母和声调都不同，意思是春天。", "蠢": "chǔn 与 cún 声母和声调不同，意思是愚蠢。"}, "sentence_index": null, "correct_answer": "存"}, "level_3": {"options": [{"text": "存", "is_correct": true, "explanation": "存：表示把东西放在某个地方，与“行李”和“在前台”搭配，符合句意。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”表示购入，不能表示把行李放置在某处。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“在前台”搭配来表示放置行李。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物作宾语，不能带行李作宾语。"}], "explanations": {"存": "存：表示把东西放在某个地方，与“行李”和“在前台”搭配，符合句意。", "买": "语义：“买”表示购入，不能表示把行李放置在某处。", "洗": "搭配：“洗”不与“在前台”搭配来表示放置行李。", "吃": "配价：“吃”要求食物作宾语，不能带行李作宾语。"}, "sentence_index": 6, "correct_answer": "存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天存了一场大雨。", "explanation": "这里应该用〈下〉。雨要说下，“存”不能用于形容天气。"}, {"text": "她去年存了一个女儿，全家都很高兴。", "explanation": "这里应该用〈生〉。生孩子要说生，“存”不表示生育。"}, {"text": "我们在门口存了一棵桃树。", "explanation": "这里应该用〈栽〉。把树苗种进土里要说栽，“存”不表示种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从小就有存了零花钱的习惯。", "corrected_sentence": "她从小就有存零花钱的习惯。", "error_description": "“了”不能放在“存”后面，用在定语“存零花钱”里。错误形式是“存了零花钱”，正确形式是“存零花钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请先把背包存柜台。", "corrected_sentence": "请先把背包存在柜台。", "error_description": "“存”后面要用介词“在”引出存放的地方，不能直接接处所。错误形式是缺少“在”，正确形式是“存在柜台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
