INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种神经递质，在大脑中传递兴奋和奖赏信号，与快乐、动机和成瘾有关。", "primary_collocate": null, "pronunciation": "duō bā àn", "ipa": "tuo˥ pa˥ an˥˩", "syllable_count": 3, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "多巴胺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "多巴胺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "多巴胺是一种神经递质。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑会分泌多巴胺，让人感到兴奋。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动以后，身体会产生更多多巴胺。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃到喜欢的甜点时，大脑会释放多巴胺。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多巴胺太少的人，容易没有动力。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，多巴胺和情绪有关。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者测量了小鼠脑中的多巴胺。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些药物会影响脑中多巴胺的水平。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "多巴胺：大脑中传递兴奋和奖赏信号的神经递质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多巴胺", "is_correct": true, "explanation": "正确：多巴胺是神经递质，与一氧化氮、催产素并列，符合句意。"}, {"text": "咖啡因", "is_correct": false, "explanation": "语义：咖啡因是兴奋剂，不是神经递质，与前面“神经递质”的类别矛盾。"}, {"text": "钙", "is_correct": false, "explanation": "语义：钙是矿物质，不是神经递质，不能与一氧化氮、催产素并列。"}, {"text": "维生素D", "is_correct": false, "explanation": "语义：维生素D是脂溶性维生素，不是神经递质，与前面列出的物质不同类。"}], "explanations": {"多巴胺": "正确：多巴胺是神经递质，与一氧化氮、催产素并列，符合句意。", "咖啡因": "语义：咖啡因是兴奋剂，不是神经递质，与前面“神经递质”的类别矛盾。", "钙": "语义：钙是矿物质，不是神经递质，不能与一氧化氮、催产素并列。", "维生素D": "语义：维生素D是脂溶性维生素，不是神经递质，与前面列出的物质不同类。"}, "sentence_index": 0, "correct_answer": "多巴胺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大脑里的多巴胺会接收奖赏信号，让人感到快乐。", "explanation": "这里应该用〈受体〉。接收信号的是多巴胺受体；多巴胺是传递信号的神经递质，本身不接收信号。"}, {"text": "多巴胺是大脑中一个很小的区域，就在额叶后面。", "explanation": "这里应该用〈脑区〉。多巴胺是一种神经递质，是化学物质，不是大脑中的区域。"}, {"text": "大脑里有一只多巴胺。", "explanation": "这里量词应该用〈种〉。多巴胺是物质，要说“一种”；“只”用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多巴胺", "is_correct": true, "explanation": "正确：“多巴胺太少”指体内这种物质不足，与“没有动力”构成因果，符合句意。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能作“太少的人”的修饰对象，句子读不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生理功能，不会与“太少的人”“没有动力”这类健康表述相关。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是日常器具，不是人体内的物质，与“太少的人”没有关系。"}], "explanations": {"多巴胺": "正确：“多巴胺太少”指体内这种物质不足，与“没有动力”构成因果，符合句意。", "水泥": "语义：水泥是建筑材料，不能作“太少的人”的修饰对象，句子读不通。", "石头": "语义：石头没有生理功能，不会与“太少的人”“没有动力”这类健康表述相关。", "闹钟": "语义：闹钟是日常器具，不是人体内的物质，与“太少的人”没有关系。"}, "sentence_index": 6, "correct_answer": "多巴胺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大脑里有一粒多巴胺，在神经元之间传递信号。", "explanation": "这里量词用错了。“粒”用于颗粒状的东西；多巴胺是一种神经递质，应说〈种〉：一种多巴胺。"}, {"text": "多巴胺是大脑里的一个突触，专门负责传递快乐。", "explanation": "这里应该用〈突触〉。突触是神经元之间的连接结构；多巴胺是在突触间传递信号的化学物质，不是突触。"}, {"text": "多巴胺是大脑中的一种神经细胞，负责传递快乐。", "explanation": "这里应该用〈神经细胞〉。神经细胞是细胞，多巴胺是神经递质，是化学物质，二者不能混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员发现，一颗多巴胺与人的奖赏感受有关。", "corrected_sentence": "研究人员发现，多巴胺与人的奖赏感受有关。", "error_description": "量词错误：“多巴胺”是物质名词，前面不能加量词“颗”（“颗”用于颗粒状的东西）。应直接说“多巴胺”，去掉“一颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有些药物会改变脑中多巴胺得数量。", "corrected_sentence": "有些药物会改变脑中多巴胺的数量。", "error_description": "结构助词错误：“脑中多巴胺的数量”中，修饰名词“数量”的应为“的”，不能用“得”。应说“脑中多巴胺的数量”，把“得”改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
