INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一氧化氮是一种无色无味的气体，化学式为NO，在空气中容易被氧化成二氧化氮。", "primary_collocate": null, "pronunciation": "yī yǎng huà dàn", "ipa": "i˥ jɑŋ˨˩ xua˥˩ tan˥˩", "syllable_count": 4, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "一氧化氮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一氧化氮是一种无色的气体。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一氧化氮遇到空气会变成二氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车尾气里有一氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血管里的一氧化氮能让血管变宽。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，老师写出了一氧化氮的化学式。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排放的一氧化氮会污染空气。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一氧化氮在体内可以传递信号。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用一氧化氮气体治疗某些肺病。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里处理一氧化氮时要注意通风。", "target_word": "一氧化氮", "complexity_tier": "T3", "furigana": "shí yàn shì lǐ chǔ lǐ yī yǎng huà dàn shí yào zhù yì tōng fēng", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "一氧化氮：化学式NO的无色无味气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一氧化氮", "is_correct": true, "explanation": "正确：一氧化氮是体内传递信号的分子，与多巴胺、催产素并列，符合句意。"}, {"text": "葡萄糖", "is_correct": false, "explanation": "语义：葡萄糖是糖类，不是神经递质，不能与多巴胺、催产素并列。"}, {"text": "维生素C", "is_correct": false, "explanation": "语义：维生素C是营养素，不属于神经递质，与“神经递质”的类别矛盾。"}, {"text": "食盐", "is_correct": false, "explanation": "语域：食盐是日常调味用品，与这句科技语体不合，也不是神经递质。"}], "explanations": {"一氧化氮": "正确：一氧化氮是体内传递信号的分子，与多巴胺、催产素并列，符合句意。", "葡萄糖": "语义：葡萄糖是糖类，不是神经递质，不能与多巴胺、催产素并列。", "维生素C": "语义：维生素C是营养素，不属于神经递质，与“神经递质”的类别矛盾。", "食盐": "语域：食盐是日常调味用品，与这句科技语体不合，也不是神经递质。"}, "sentence_index": 0, "correct_answer": "一氧化氮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室里有一座一氧化氮，要小心使用。", "explanation": "这里量词错了。“座”用于山、楼等大而固定的东西；一氧化氮是气体，应说〈瓶〉。"}, {"text": "工厂的烟囱里有一片一氧化氮。", "explanation": "这里量词错了。“片”用于薄片、平面等东西；烟囱里冒出的气体应说〈股〉。"}, {"text": "实验室里有一块一氧化氮。", "explanation": "这里量词应该用〈瓶〉或〈罐〉。一氧化氮是气体，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一氧化氮", "is_correct": true, "explanation": "正确：工厂排放的废气中含有一氧化氮，会污染空气，符合句意。"}, {"text": "清水", "is_correct": false, "explanation": "语义：清水不会污染空气，句子的因果关系不成立。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是空气的成分之一，不是工厂排放的污染物。"}, {"text": "鲜花", "is_correct": false, "explanation": "搭配：“排放”的对象是废气、废水等，“鲜花”不能与之搭配。"}], "explanations": {"一氧化氮": "正确：工厂排放的废气中含有一氧化氮，会污染空气，符合句意。", "清水": "语义：清水不会污染空气，句子的因果关系不成立。", "氧气": "语义：氧气是空气的成分之一，不是工厂排放的污染物。", "鲜花": "搭配：“排放”的对象是废气、废水等，“鲜花”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "一氧化氮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里有一颗一氧化氮，要注意通风。", "explanation": "这里量词用错了。“颗”用于颗粒状的东西；一氧化氮是气体，应说〈瓶〉或〈罐〉。"}, {"text": "焊接车间里有一把一氧化氮。", "explanation": "这里量词用错了。“把”用于有柄的东西；一氧化氮是气体，应说〈瓶〉。"}, {"text": "厂房里有一张一氧化氮，要小心通风。", "explanation": "这里量词用错了。“张”用于纸、桌子等扁平的东西；一氧化氮是气体，应说〈瓶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里有一粒一氧化氮，要小心使用。", "corrected_sentence": "实验室里有一瓶一氧化氮，要小心使用。", "error_description": "量词错误：“一氧化氮”是气体，应说“一瓶”，不能说“一粒”（“粒”用于颗粒状的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂会向空气中排放一个一氧化氮。", "corrected_sentence": "工厂会向空气中排放一氧化氮。", "error_description": "量词错误：“一氧化氮”是气体，不能加量词“个”（“个”不用于气体）。应直接说“排放一氧化氮”，去掉“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
