INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种由脑垂体分泌的激素，能促进子宫收缩、帮助分娩，并促进亲子关系。", "primary_collocate": null, "pronunciation": "cuī chǎn sù", "ipa": "tsʰuei˥ tʂʰan˨˩ su˥˩", "syllable_count": 3, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "催产素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "催产素由脑垂体分泌。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "催产素能促进子宫收缩。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给产妇用了催产素。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈抱着宝宝时，体内的催产素会增加。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "催产素有助于加深亲子关系。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把催产素叫作“爱的激素”。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分娩时，身体会释放大量催产素。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拥抱朋友也会让催产素升高。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少催产素可能会影响分娩。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "催产素：脑垂体分泌、促进分娩和亲子关系的激素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "催产素", "is_correct": true, "explanation": "催产素与多巴胺、一氧化氮并列，都属于句中所说的神经递质，符合语境。"}, {"text": "胰岛素", "is_correct": false, "explanation": "语义：胰岛素是调节血糖的激素，不是神经递质，不能与多巴胺、一氧化氮并列。"}, {"text": "葡萄糖", "is_correct": false, "explanation": "语义：葡萄糖是糖类营养物质，不参与神经信号传递，与句中的神经递质不是同一类。"}, {"text": "小东西", "is_correct": false, "explanation": "语域：“小东西”是口语说法，不适合这种科普句的书面语体。"}], "explanations": {"催产素": "催产素与多巴胺、一氧化氮并列，都属于句中所说的神经递质，符合语境。", "胰岛素": "语义：胰岛素是调节血糖的激素，不是神经递质，不能与多巴胺、一氧化氮并列。", "葡萄糖": "语义：葡萄糖是糖类营养物质，不参与神经信号传递，与句中的神经递质不是同一类。", "小东西": "语域：“小东西”是口语说法，不适合这种科普句的书面语体。"}, "sentence_index": 0, "correct_answer": "催产素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖尿病人需要每天注射催产素。", "explanation": "这里应该用〈胰岛素〉。胰岛素用于调节血糖，催产素与分娩和亲子关系有关，不用于治疗糖尿病。"}, {"text": "免疫细胞会产生催产素来抵抗病毒。", "explanation": "这里应该用〈抗体〉。催产素是脑垂体分泌的激素，不参与抵抗病毒，不能说由免疫细胞产生来对抗病原体。"}, {"text": "医生给发炎的伤口开了催产素。", "explanation": "这里应该用〈抗生素〉。催产素用于促进子宫收缩，不能用来治疗伤口感染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "催产素", "is_correct": true, "explanation": "“爱的激素”指的就是催产素，这个称呼与句中的语境完全吻合。"}, {"text": "咖啡因", "is_correct": false, "explanation": "语义：咖啡因是兴奋中枢神经的生物碱，并不是“爱的激素”，与这个称呼不符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语随意，不能用于给物质命名的科普句。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水是饮用水，不是激素，无法被叫作“爱的激素”。"}], "explanations": {"催产素": "“爱的激素”指的就是催产素，这个称呼与句中的语境完全吻合。", "咖啡因": "语义：咖啡因是兴奋中枢神经的生物碱，并不是“爱的激素”，与这个称呼不符。", "玩意儿": "语域：“玩意儿”口语随意，不能用于给物质命名的科普句。", "矿泉水": "语义：矿泉水是饮用水，不是激素，无法被叫作“爱的激素”。"}, "sentence_index": 6, "correct_answer": "催产素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "拔牙前，牙医给病人打了催产素。", "explanation": "这里应该用〈麻醉剂〉。催产素促进子宫收缩，没有麻醉作用，不能用于拔牙前的局部麻醉。"}, {"text": "红细胞里的催产素能携带氧气。", "explanation": "这里应该用〈血红蛋白〉。催产素参与分娩和亲子关系，不负责运输氧气。"}, {"text": "植物靠催产素进行光合作用。", "explanation": "这里应该用〈叶绿素〉。光合作用依靠叶绿素吸收光能，催产素与植物无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士给产妇注射了一只催产素。", "corrected_sentence": "护士给产妇注射了一针催产素。", "error_description": "错误形式：“一只催产素”；正确形式：“一针催产素”。催产素是注射用药剂，应该用“针”计量；“只”用于动物或成对的东西，不能用于药物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士给产妇注射了一颗催产素。", "corrected_sentence": "护士给产妇注射了一支催产素。", "error_description": "量词错误：催产素是注射用的液体药剂，“颗”用于颗粒状的东西，不能用于此处；应说“一支”（药剂的计量词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
