INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神经递质是神经元之间或神经元与效应器细胞之间传递信息的化学物质，在神经系统中起信号传导作用。", "primary_collocate": null, "pronunciation": "shén jīng dì zhì", "ipa": "ʂən˧˥ tɕiŋ˥ ti˥˩ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "神经递质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "神经递质能在神经细胞之间传递信息。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多巴胺是一种让人高兴的神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他体内的神经递质太少了。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经递质从一个细胞传到另一个细胞。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不好可能和神经递质有关。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药会影响大脑里的神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种神经递质的作用。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血清素也是一种神经递质，能让心情好。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经递质太多或太少，人都会不舒服。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "神经系统中在细胞之间传递信号的化学物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经递质", "is_correct": true, "explanation": "多巴胺、一氧化氮、催产素都属于神经递质，句中用“等”并列，指的正是神经递质。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：维生素是营养素，不传递神经信号，与前面列出的多巴胺、一氧化氮不同类。"}, {"text": "矿物质", "is_correct": false, "explanation": "语义：矿物质是无机营养元素，不参与神经信号传递，与句中并列的物质不属同类。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与这句的科技语体不合。"}], "explanations": {"神经递质": "多巴胺、一氧化氮、催产素都属于神经递质，句中用“等”并列，指的正是神经递质。", "维生素": "语义：维生素是营养素，不传递神经信号，与前面列出的多巴胺、一氧化氮不同类。", "矿物质": "语义：矿物质是无机营养元素，不参与神经信号传递，与句中并列的物质不属同类。", "玩意儿": "语域：“玩意儿”是口语词，与这句的科技语体不合。"}, "sentence_index": 0, "correct_answer": "神经递质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "缺少神经递质容易得坏血病。", "explanation": "这里应该用〈维生素C〉。坏血病由缺乏维生素C引起，神经递质与营养缺乏无关，不能预防坏血病。"}, {"text": "神经递质能帮助身体调节血糖。", "explanation": "这里应该用〈胰岛素〉。胰岛素负责调节血糖，神经递质负责神经信号的传递，不调节血糖。"}, {"text": "大脑由数十亿个神经递质组成。", "explanation": "这里应该用〈神经元〉。大脑由神经元等细胞组成，神经递质是传递信号的化学物质，不是构成大脑的细胞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经递质", "is_correct": true, "explanation": "神经递质在大脑中传递信息，药物会影响它，句子意思通顺。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃位于腹部，不在大脑里，与“大脑里的”范围冲突。"}, {"text": "睡眠", "is_correct": false, "explanation": "搭配：“大脑里的”修饰的应是具体的物质或部位，“睡眠”是状态，不能说“大脑里的睡眠”。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾不在大脑里，与句中的部位范围不符。"}], "explanations": {"神经递质": "神经递质在大脑中传递信息，药物会影响它，句子意思通顺。", "胃": "语义：胃位于腹部，不在大脑里，与“大脑里的”范围冲突。", "睡眠": "搭配：“大脑里的”修饰的应是具体的物质或部位，“睡眠”是状态，不能说“大脑里的睡眠”。", "脚趾": "语义：脚趾不在大脑里，与句中的部位范围不符。"}, "sentence_index": 6, "correct_answer": "神经递质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "神经递质负责把氧气运到全身。", "explanation": "这里应该用〈血红蛋白〉。血红蛋白负责运输氧气，神经递质负责神经信号的传递，不运输氧气。"}, {"text": "神经递质会沿神经纤维传到大脑。", "explanation": "这里应该用〈神经冲动〉。神经冲动沿神经纤维传导，神经递质是在突触间隙起作用的化学物质，不沿神经纤维传播。"}, {"text": "神经递质促进女性第二性征的发育。", "explanation": "这里应该用〈雌激素〉。雌激素促进女性第二性征的发育，神经递质不参与这一过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家发现了一只新的神经递质。", "corrected_sentence": "科学家发现了一种新的神经递质。", "error_description": "错误形式：“一只新的神经递质”；正确形式：“一种新的神经递质”。神经递质是化学物质，应该用“种”计量；“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药会让大脑里地神经递质减少。", "corrected_sentence": "这种药会让大脑里的神经递质减少。", "error_description": "错误形式：“大脑里地神经递质”；正确形式：“大脑里的神经递质”。“大脑里的”作名词性定语修饰“神经递质”，应用“的”；“地”用于修饰动词，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
