INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "诱导、引发；指某个因素导致某种结果出现。", "primary_collocate": null, "pronunciation": "yòu fā", "ipa": "joʊ˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "诱发", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冷空气容易诱发感冒。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜可能诱发心脏病。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度紧张会诱发头痛。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花粉诱发了他的过敏。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力太大，容易诱发各种疾病。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可能诱发胃痛，吃前要问医生。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一件小事诱发了他们的争吵。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太辣的东西会诱发咳嗽。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷诱发了她的旧病。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱发了", "label": "体标"}, {"form": "诱发过", "label": "体标"}], "register": "书面", "sense_fingerprint": "某个因素导致疾病、反应等结果出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」的对象是请求、建议，不能用于「哈欠」这种生理现象。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的宾语须是可买的商品，「哈欠」不能被购买。"}, {"text": "诱发", "is_correct": true, "explanation": "诱发：引起、导致。「哈欠的诱发」指引起哈欠的因素，与「神经递质……扮演关键角色」的句意相符。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：「赞美」的宾语须是人或其优点，不能以「哈欠」作为赞美的对象。"}], "explanations": {"拒绝": "语义：「拒绝」的对象是请求、建议，不能用于「哈欠」这种生理现象。", "购买": "搭配：「购买」的宾语须是可买的商品，「哈欠」不能被购买。", "诱发": "诱发：引起、导致。「哈欠的诱发」指引起哈欠的因素，与「神经递质……扮演关键角色」的句意相符。", "赞美": "配价：「赞美」的宾语须是人或其优点，不能以「哈欠」作为赞美的对象。"}, "sentence_index": 0, "correct_answer": "诱发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个政策诱发了经济发展。", "explanation": "这里应该用〈促进〉。诱发多指疾病、不良事件等负面结果，经济发展这类正面进展要用促进。"}, {"text": "我们从国外诱发了先进技术。", "explanation": "这里应该用〈引进〉。诱发表示由某因素导致某种结果出现，从国外得来技术要用引进。"}, {"text": "考古队诱发了一座古墓。", "explanation": "这里应该用〈发掘〉。诱发的宾语是某种结果，古墓是埋在地下的遗迹，应该用发掘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀念", "is_correct": false, "explanation": "语义：「怀念」指思念过去的人或事，不能用于「胃痛」这种身体感受。"}, {"text": "雇用", "is_correct": false, "explanation": "配价：「雇用」的宾语须是人，不能以「胃痛」作宾语。"}, {"text": "诱发", "is_correct": true, "explanation": "诱发：引起、导致。「药可能诱发胃痛」指药物引起副作用，与「吃前要问医生」的提醒相符。"}, {"text": "推翻", "is_correct": false, "explanation": "搭配：「推翻」用于政权、结论等，不能与「胃痛」搭配。"}], "explanations": {"怀念": "语义：「怀念」指思念过去的人或事，不能用于「胃痛」这种身体感受。", "雇用": "配价：「雇用」的宾语须是人，不能以「胃痛」作宾语。", "诱发": "诱发：引起、导致。「药可能诱发胃痛」指药物引起副作用，与「吃前要问医生」的提醒相符。", "推翻": "搭配：「推翻」用于政权、结论等，不能与「胃痛」搭配。"}, "sentence_index": 6, "correct_answer": "诱发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人诱发了一座大桥。", "explanation": "这里应该用〈建造〉。诱发的宾语是结果或现象，大桥是人工建成的实物，应该用建造。"}, {"text": "爱迪生诱发了电灯。", "explanation": "这里应该用〈发明〉。诱发表示引起某种结果，电灯是爱迪生创造出来的，应该用发明。"}, {"text": "农民诱发了庄稼。", "explanation": "这里应该用〈收获〉。庄稼是种出来后被收割的对象，诱发的宾语应是被引起的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷空气可能诱发把哮喘。", "corrected_sentence": "冷空气可能诱发哮喘。", "error_description": "错误：「诱发把哮喘」在动词和宾语之间多加了「把」。正确：「诱发哮喘」。诱发是及物动词，可直接带宾语，不用「把」字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香料可能诱发得过敏。", "corrected_sentence": "这种香料可能诱发过敏。", "error_description": "错误：「诱发得过敏」在动词后多加了「得」。正确：「诱发过敏」。诱发可直接带宾语，不需要「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
