INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11311, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "化装成某种人物或角色进行表演；引申指在某件事中担任某种角色、起某种作用。", "primary_collocate": null, "pronunciation": "bàn yǎn", "ipa": "pan˥˩ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "多巴胺、一氧化氮与催产素等神经递质被认为在哈欠的诱发中扮演关键角色。", "target_word": "扮演", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在这部电影里扮演医生。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在学校的演出中扮演国王。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红在圣诞节的节目里扮演了天使。", "target_word": "扮演", "complexity_tier": "T3", "furigana": "xiǎo hóng zài shèngdàn jié de jiémù lǐ bànyǎn le tiānshǐ", "sentence_source": "generated"}, {"text": "她曾经扮演过一位老师。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来扮演这个角色？", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧团里他们分别扮演皇帝和大臣。", "target_word": "扮演", "complexity_tier": "T3", "furigana": "jùtuán lǐ tāmen fēnbié bànyǎn huángdì hé dàchén", "sentence_source": "generated"}, {"text": "演员要扮演不同的人。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部话剧里她扮演一位年迈的母亲。", "target_word": "扮演", "complexity_tier": "T3", "furigana": "zhè bù huàjù lǐ tā bànyǎn yí wèi niánmài de mǔqīn", "sentence_source": "generated"}, {"text": "他在舞台上扮演一个老人。", "target_word": "扮演", "complexity_tier": "T3", "furigana": "tā zài wǔtái shàng bànyǎn yí ge lǎorén", "sentence_source": "generated"}], "morphological_forms": [{"form": "扮演了", "label": "体标"}, {"form": "扮演着", "label": "体标"}, {"form": "扮演过", "label": "体标"}], "register": "中性", "sense_fingerprint": "装扮成某个角色进行表演，或在事情中起某种作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11311, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：「修理」用于器物、设备，不能用于「关键角色」。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：「测量」的对象是长度、重量等可量之物，不能用于「角色」。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」的对象是场所或卫生，与「在……中起关键角色」的句意不符。"}, {"text": "扮演", "is_correct": true, "explanation": "扮演：担任某种角色或起某种作用。「扮演关键角色」符合句意。"}], "explanations": {"修理": "搭配：「修理」用于器物、设备，不能用于「关键角色」。", "测量": "搭配：「测量」的对象是长度、重量等可量之物，不能用于「角色」。", "打扫": "语义：「打扫」的对象是场所或卫生，与「在……中起关键角色」的句意不符。", "扮演": "扮演：担任某种角色或起某种作用。「扮演关键角色」符合句意。"}, "sentence_index": 0, "correct_answer": "扮演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校扮演了一场演出。", "explanation": "这里应该用〈举办〉。扮演的宾语是人物或角色，演出是活动，应该用举办。"}, {"text": "他扮演了一首诗。", "explanation": "这里应该用〈朗诵〉。诗是念出来的作品，扮演不能用于诗歌。"}, {"text": "她扮演了一幅风景。", "explanation": "这里应该用〈画〉。风景画是画出来的，扮演的宾语应是人物或角色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扮演", "is_correct": true, "explanation": "扮演：化装成角色进行表演。「分别扮演皇帝和大臣」符合句意。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：「饲养」的对象是动物，不能用于「皇帝和大臣」这类人物。"}, {"text": "批准", "is_correct": false, "explanation": "配价：「批准」的宾语是申请、方案等，不能以人物作宾语。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：「驱赶」指赶走闯入者或动物，与剧团演出的语境不符。"}], "explanations": {"扮演": "扮演：化装成角色进行表演。「分别扮演皇帝和大臣」符合句意。", "饲养": "搭配：「饲养」的对象是动物，不能用于「皇帝和大臣」这类人物。", "批准": "配价：「批准」的宾语是申请、方案等，不能以人物作宾语。", "驱赶": "语义：「驱赶」指赶走闯入者或动物，与剧团演出的语境不符。"}, "sentence_index": 6, "correct_answer": "扮演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乐队扮演了一支曲子。", "explanation": "这里应该用〈演奏〉。曲子是演奏出来的，扮演的宾语应是人物或角色。"}, {"text": "设计师扮演了一座房子。", "explanation": "这里应该用〈盖〉。房子是盖起来的建筑，扮演的宾语只能是人物或角色，不能用于建造房屋。"}, {"text": "老师扮演了一个故事。", "explanation": "这里应该用〈讲〉。故事是讲出来的，扮演的宾语应是人物或角色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在话剧中扮演把女王。", "corrected_sentence": "她在话剧中扮演女王。", "error_description": "错误：「扮演把女王」在动词和宾语之间多加了「把」。正确：「扮演女王」。扮演是及物动词，可直接带宾语，不用「把」字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时扮演了过国王。", "corrected_sentence": "他年轻时扮演过国王。", "error_description": "错误：「扮演了过」在动词后同时用了「了」和「过」。正确：「扮演过」，只用「过」表示曾经有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
