INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在知识、能力、技能等方面达到的高度或程度。", "primary_collocate": null, "pronunciation": "shuǐ píng", "ipa": "ʂweɪ˨˩˦ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的汉语水平提高得很快。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的教学水平很高。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提高自己的英语水平。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的游泳水平比我高。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的数学水平比去年高了很多。", "target_word": "水平", "complexity_tier": "T3", "furigana": "tā de shùxué shuǐ píng bǐ qùnián gāo le hěn duō", "sentence_source": "generated"}, {"text": "他的画水平不错，很多人都喜欢。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的写作水平怎么样？", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的水平大家都知道。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近他的篮球水平进步很大。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛要看你的水平，不是看年龄。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活水平", "label": "复合"}, {"form": "文化水平", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平：知识、能力、技能所达到的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指知识、能力所达到的程度，可以“提高”，也能用在“汉语”后面。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“汉语”是能力，不能有“体重”这样的属性。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“提高”不能与“颜色”搭配，颜色不能被提高。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“汉语”不是房间，“房间”谈不上提高。"}], "explanations": {"水平": "“水平”指知识、能力所达到的程度，可以“提高”，也能用在“汉语”后面。", "体重": "语义：“汉语”是能力，不能有“体重”这样的属性。", "颜色": "搭配：“提高”不能与“颜色”搭配，颜色不能被提高。", "房间": "语义：“汉语”不是房间，“房间”谈不上提高。"}, "sentence_index": 0, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的水平很高。", "explanation": "这里应该用〈高度〉。“水平”指人的知识、能力所达到的程度，不用来说山的高低。"}, {"text": "我有十年的水平。", "explanation": "这里应该用〈经验〉。“水平”不表示持续的年限；“经验”指长期做事积累的东西，可以说“有十年的经验”。"}, {"text": "这台电脑的水平很好。", "explanation": "这里应该用〈性能〉。“水平”用于人的能力，不用于机器的性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指写作达到的程度，用“怎么样”来问正合适。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来评价写作。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来说写作的情况。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“写作”没有年龄，年龄是人的属性。"}], "explanations": {"水平": "“水平”指写作达到的程度，用“怎么样”来问正合适。", "身高": "体貌：“身高”指人的身体高矮，不能用来评价写作。", "身材": "体貌：“身材”指人的体形，不能用来说写作的情况。", "年龄": "语义：“写作”没有年龄，年龄是人的属性。"}, "sentence_index": 6, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把书水平放在桌上。", "explanation": "这里的“水平”取“与地面平行”的意思，是另一个义项；表示能力程度的“水平”不能这样用。"}, {"text": "这批产品的水平很好。", "explanation": "这里应该用〈质量〉。“水平”用于人的知识、能力，不用于产品的好坏。"}, {"text": "今天的水平很高。", "explanation": "这里应该用〈气温〉。“水平”不能用来说天气的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的英语水平比我很高。", "corrected_sentence": "她的英语水平比我高。", "error_description": "比较句错误：「比」字句中，形容词前不能再加程度副词「很」，应说「比我高」，不能说「比我很高」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地汉语水平很高。", "corrected_sentence": "他的汉语水平很高。", "error_description": "助词错误：「地」用于修饰动词、形容词，不能修饰名词性的「汉语水平」；应用「的」，写作「他的汉语水平很高。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "降低：与“升高”反义，指数值减少，可以说体温降低，与句中体温升高相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与“升高”没有反义关系，只是普通动词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与“升高”没有反义关系，二者不构成对立。"}, {"text": "写信", "is_correct": false, "explanation": "写信与“升高”没有反义关系，二者不构成对立。"}], "correct_answer": "降低", "explanations": {"降低": "降低：与“升高”反义，指数值减少，可以说体温降低，与句中体温升高相反。", "唱歌": "唱歌与“升高”没有反义关系，只是普通动词。", "睡觉": "睡觉与“升高”没有反义关系，二者不构成对立。", "写信": "写信与“升高”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "降低：与“升高”反义，指数值减少，可以说血压降低，与句中血压升高相反。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“升高”没有反义关系，只是普通动词。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与“升高”没有反义关系，二者不构成对立。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡与“升高”没有反义关系，二者不构成对立。"}], "correct_answer": "降低", "explanations": {"降低": "降低：与“升高”反义，指数值减少，可以说血压降低，与句中血压升高相反。", "跑步": "跑步与“升高”没有反义关系，只是普通动词。", "吃饭": "吃饭与“升高”没有反义关系，二者不构成对立。", "洗澡": "洗澡与“升高”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使程度、数量等增加。", "primary_collocate": null, "pronunciation": "shēng gāo", "ipa": "ʂɤŋ˥ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "房地产价格有时会升高。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变热，温度会升高。", "target_word": "升高", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水加热以后，水温慢慢升高。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人发烧，体温升高了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着海拔升高，空气越来越冷。", "target_word": "升高", "complexity_tier": "T3", "furigana": "suí zhe hǎi bá shēng gāo, kōng qì yuè lái yuè lěng.", "sentence_source": "generated"}, {"text": "吃了太多盐，血压可能会升高。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开了空调以后，房间的温度没有升高。", "target_word": "升高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年的房价还会继续升高吗？", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞后，高度慢慢升高。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前血压升高过，所以要少吃盐。", "target_word": "升高", "complexity_tier": "T3", "furigana": "tā yǐ qián xuè yā shēng gāo guò, suǒ yǐ yào shǎo chī yán.", "sentence_source": "generated"}], "morphological_forms": [{"form": "升高了", "label": "完成体"}, {"form": "升高过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "升高：温度、价格、血压等程度或数量增加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd209268f-53f6-4de8-8192-9154cf70cf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：价格的数值增加，符合“有时会”后面的语义。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”只说人或植物的身高，不能用于价格。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”描述人或动物的体形，不能用于价格。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：价格不会跳舞，句子讲的是价格的变化。"}], "explanations": {"升高": "升高：价格的数值增加，符合“有时会”后面的语义。", "长高": "搭配：“长高”只说人或植物的身高，不能用于价格。", "变胖": "体貌：“变胖”描述人或动物的体形，不能用于价格。", "跳舞": "语义：价格不会跳舞，句子讲的是价格的变化。"}, "sentence_index": 0, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年龄升高了一岁。", "explanation": "这里应该用〈增长〉。升高用于温度、价格、血压等程度或数量的上升，人的年龄变化说增长。"}, {"text": "他的身高升高了三厘米。", "explanation": "这里应该用〈长高〉。人的身高增加说长高，升高不用于人的身体高度。"}, {"text": "两国的友谊升高了。", "explanation": "这里应该用〈加深〉。升高用于温度、价格等数值，关系或感情的深化要用加深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：温度数值增加，与“没有”构成否定，表示温度没有上升。"}, {"text": "散步", "is_correct": false, "explanation": "语义：温度不能散步，与句子讲的温度变化不符。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，不用于温度。"}, {"text": "变矮", "is_correct": false, "explanation": "体貌：“变矮”描述人或物体的高矮，不用于温度。"}], "explanations": {"升高": "升高：温度数值增加，与“没有”构成否定，表示温度没有上升。", "散步": "语义：温度不能散步，与句子讲的温度变化不符。", "生长": "搭配：“生长”用于生物，不用于温度。", "变矮": "体貌：“变矮”描述人或物体的高矮，不用于温度。"}, "sentence_index": 6, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的规模升高了。", "explanation": "这里应该用〈扩大〉。升高用于温度、价格等数值的上升，规模的扩大要说扩大。"}, {"text": "这次会议升高了一个小时。", "explanation": "这里应该用〈延长〉。升高不用于时间的增加，时长的增加要说延长。"}, {"text": "上班路程升高了十分钟。", "explanation": "这里应该用〈变长〉。升高用于温度、价格等数值的上升，路程或时间的增加要说变长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的气温升高的了。", "corrected_sentence": "今天的气温升高了。", "error_description": "错误形式：“升高的了”；正确形式：“升高了”。“的”多余，完成体“了”应直接接在动补结构“升高”之后，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水温升高的很快。", "corrected_sentence": "水温升高得很快。", "error_description": "错误形式：“升高的很快”；正确形式：“升高得很快”。表示程度的补语前要用结构助词“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
