INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指与某种物质作用相反、能抵消其效应的物质，常用于医学或生物学。", "primary_collocate": null, "pronunciation": "jié kàng jì", "ipa": "tɕje˧˥ kʰaŋ˥˩ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "例如，多巴胺水平的升高可显著增加哈欠频率，而其拮抗剂则能抑制该行为。", "target_word": "拮抗剂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生给病人用了一种拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种拮抗剂可以减弱药物的作用。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃药过量，医院马上用拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拮抗剂能挡住药物对身体的影响。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种拮抗剂主要用在医院里。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究新的拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃错药时，医生会用拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验用了一种拮抗剂来抑制反应。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拮抗剂和药物的作用正好相反。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拮抗劑", "label": "繁体"}, {"form": "受体拮抗剂", "label": "复合"}], "register": "专业", "sense_fingerprint": "拮抗剂：医学、生物学中能抵消另一物质效应的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拮抗剂", "is_correct": true, "explanation": "“拮抗剂”能抵消多巴胺的作用，所以能“抑制该行为”，句意通顺。"}, {"text": "哈欠", "is_correct": false, "explanation": "语义：“哈欠”本身是一种行为，不是能抑制行为的物质。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，与多巴胺和行为的作用无关，不能抑制行为。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“抑制”的主语应是能起作用的物质，“夏天”不能作“抑制”的主语。"}], "explanations": {"拮抗剂": "“拮抗剂”能抵消多巴胺的作用，所以能“抑制该行为”，句意通顺。", "哈欠": "语义：“哈欠”本身是一种行为，不是能抑制行为的物质。", "钢琴": "语义：“钢琴”是乐器，与多巴胺和行为的作用无关，不能抑制行为。", "夏天": "搭配：“抑制”的主语应是能起作用的物质，“夏天”不能作“抑制”的主语。"}, "sentence_index": 0, "correct_answer": "拮抗剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病人开了一只拮抗剂。", "explanation": "这里的量词应用〈种〉。“只”用于动物、成对的器官，不用于药剂。"}, {"text": "这部电影的拮抗剂很大。", "explanation": "这里应该用〈影响〉。“拮抗剂”指医学或生物学中抵消某种物质效应的物质，不能用来说电影的作用。"}, {"text": "他的拮抗剂很高。", "explanation": "这里应该用〈效率〉。“拮抗剂”指物质，不能用来描述人的工作效率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拮抗剂", "is_correct": true, "explanation": "“拮抗剂”是研究的对象之一，指能抵消某种物质效应的物质，句意通顺。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是一个日子，不是科学家研究的物质，句子无法成立。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是一段时间，不能作为“研究”的对象。"}, {"text": "寿星", "is_correct": false, "explanation": "语义：“寿星”指过生日的人，不能被“研究”成“新的”东西。"}], "explanations": {"拮抗剂": "“拮抗剂”是研究的对象之一，指能抵消某种物质效应的物质，句意通顺。", "生日": "语义：“生日”是一个日子，不是科学家研究的物质，句子无法成立。", "清晨": "语义：“清晨”是一段时间，不能作为“研究”的对象。", "寿星": "语义：“寿星”指过生日的人，不能被“研究”成“新的”东西。"}, "sentence_index": 6, "correct_answer": "拮抗剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和他是拮抗剂。", "explanation": "这里应该用〈朋友〉。“拮抗剂”是能抵消某种物质效应的物质，不能用来指人。"}, {"text": "这杯水的拮抗剂太高了。", "explanation": "这里应该用〈温度〉。拮抗剂是物质，不能说它的高低。"}, {"text": "这朵花的拮抗剂很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，拮抗剂不是颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只拮抗剂能减轻副作用。", "corrected_sentence": "这种拮抗剂能减轻副作用。", "error_description": "量词错误：“拮抗剂”应用量词“种”，说“这种拮抗剂”，不能用“只”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家研制了一种的新拮抗剂。", "corrected_sentence": "科学家研制了一种新的拮抗剂。", "error_description": "定语位置错误：“新的”修饰“拮抗剂”，应紧接在数量词之后，说“一种新的拮抗剂”，不能把“的新”放在数量词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
