INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11316, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用于揭示看似如此但实际上不同的情况", "primary_collocate": null, "pronunciation": "zé", "ipa": "tsɤ˧˥", "syllable_count": 1, "sentences": [{"text": "这间小店外观很破旧，里面则非常讲究。", "target_word": "则", "complexity_tier": "T3", "furigana": "zhè jiān xiǎo diàn wài guān hěn pò jiù，lǐ miàn zé fēi cháng jiǎng jiu。", "sentence_source": "generated"}, {"text": "他嘴上说不在乎，心里则很在意。", "target_word": "则", "complexity_tier": "T3", "furigana": "tā zuǐ shàng shuō bú zài hu，xīn lǐ zé hěn zài yì。", "sentence_source": "generated"}, {"text": "天气看着很暖和，风里则夹着寒意。", "target_word": "则", "complexity_tier": "T3", "furigana": "tiān qì kàn zhe hěn nuǎn huo，fēng lǐ zé jiā zhe hán yì。", "sentence_source": "generated"}, {"text": "他看起来很高兴，心里则很难过。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作看似轻松，做起来则十分辛苦。", "target_word": "则", "complexity_tier": "T3", "furigana": "zhè fèn gōng zuò kàn sì qīng sōng，zuò qǐ lái zé shí fēn xīn kǔ。", "sentence_source": "generated"}, {"text": "他表面上不说话，暗地里则在四处打听。", "target_word": "则", "complexity_tier": "T3", "furigana": "tā biǎo miàn shàng bù shuō huà，àn dì lǐ zé zài sì chù dǎ tīng。", "sentence_source": "generated"}, {"text": "这孩子看似懂事，背后则很任性。", "target_word": "则", "complexity_tier": "T3", "furigana": "zhè hái zi kàn sì dǒng shì，bèi hòu zé hěn rèn xìng。", "sentence_source": "generated"}, {"text": "她表面很冷静，内心则非常紧张。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅看着很高档，价格则很亲民。", "target_word": "则", "complexity_tier": "T3", "furigana": "zhè jiā cān tīng kàn zhe hěn gāo dàng，jià gé zé hěn qīn mín。", "sentence_source": "generated"}, {"text": "她说话温和，心里则很有主见。", "target_word": "则", "complexity_tier": "T3", "furigana": "tā shuō huà wēn hé，xīn lǐ zé hěn yǒu zhǔ jiàn。", "sentence_source": "generated"}], "morphological_forms": [{"form": "則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "则：连接前后两部分，表示对比或实际情况不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11316, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，连接前后两部分，表示对比，实际情况不同。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。"}, {"text": "贼", "is_correct": false, "explanation": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。"}, {"text": "哲", "is_correct": false, "explanation": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是蛇。"}, {"text": "德", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是道德。"}], "explanations": {"则": "则 zé，连接前后两部分，表示对比，实际情况不同。", "折": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。", "贼": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。", "哲": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。", "蛇": "shé 与 zé 声母不同（sh 与 z），意思是蛇。", "德": "dé 与 zé 声母不同（d 与 z），意思是道德。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：表示前后对比，“外观很破旧”与“里面非常讲究”形成对比。"}, {"text": "因为", "is_correct": false, "explanation": "语义：因为表示原因，与前后对比的关系不符。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：因此要求前文是原因，“外观破旧”不能作为“里面讲究”的原因。"}, {"text": "从而", "is_correct": false, "explanation": "语义：从而表示结果承接，前后并非因果，不合语境。"}], "explanations": {"则": "则：表示前后对比，“外观很破旧”与“里面非常讲究”形成对比。", "因为": "语义：因为表示原因，与前后对比的关系不符。", "因此": "搭配：因此要求前文是原因，“外观破旧”不能作为“里面讲究”的原因。", "从而": "语义：从而表示结果承接，前后并非因果，不合语境。"}, "sentence_index": 0, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他以身作则，带头遵守制度。", "explanation": "这里的〈则〉是“准则”的意思，不表示前后对比。"}, {"text": "吃完饭则去散步。", "explanation": "这里的〈则〉表示承接，相当于“就”，不表示前后对比。"}, {"text": "快走吧，则要迟到了。", "explanation": "这里应该用〈否则〉。“则”表示对比或承接，不表示“否则”的假设后果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11316, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，连接前后两部分，表示对比，实际情况不同。"}, {"text": "格", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是格子。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是隔开。"}, {"text": "舌", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是舌头。"}, {"text": "得", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是获得。"}], "explanations": {"则": "则 zé，连接前后两部分，表示对比，实际情况不同。", "格": "gé 与 zé 声母不同（g 与 z），意思是格子。", "隔": "gé 与 zé 声母不同（g 与 z），意思是隔开。", "舌": "shé 与 zé 声母不同（sh 与 z），意思是舌头。", "得": "dé 与 zé 声母不同（d 与 z），意思是获得。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：表示前后对比，“看似懂事”与“背后任性”形成对比。"}, {"text": "因而", "is_correct": false, "explanation": "搭配：因而要求前文是原因，“看似懂事”不能导致“背后任性”。"}, {"text": "于是", "is_correct": false, "explanation": "语义：于是表示顺承的结果，前后没有因果关系，不合语境。"}, {"text": "以至", "is_correct": false, "explanation": "语义：以至表示程度或结果，与前后对比的关系不符。"}], "explanations": {"则": "则：表示前后对比，“看似懂事”与“背后任性”形成对比。", "因而": "搭配：因而要求前文是原因，“看似懂事”不能导致“背后任性”。", "于是": "语义：于是表示顺承的结果，前后没有因果关系，不合语境。", "以至": "语义：以至表示程度或结果，与前后对比的关系不符。"}, "sentence_index": 6, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戒烟有两个原因：一则为了健康，二则为了省钱。", "explanation": "这里的〈则〉用于列举，“一则……二则……”，不表示对比。"}, {"text": "昨天的报纸上登了一则广告。", "explanation": "这里的〈则〉是量词，用于广告、新闻等，不表示对比。"}, {"text": "若要成功，则必须努力。", "explanation": "这里的〈则〉表示条件下的结果，相当于“就”，不表示对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话很客气，心里很则冷淡。", "corrected_sentence": "他说话很客气，心里则很冷淡。", "error_description": "错误：“心里很则冷淡”；正确：“心里则很冷淡”。“则”是连词，应放在后一分句主语“心里”之后、程度副词“很”之前，不能插在“很”与谓语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看似温和，心里却则很固执。", "corrected_sentence": "他看似温和，心里则很固执。", "error_description": "错误：“却则”；正确：“则”。“则”本身已表示对比，不能与“却”叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
