INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11318, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指某事物或言论能够引发人们深入思考，具有启发意义。", "primary_collocate": null, "pronunciation": "yǐn rén shēn sī", "ipa": "in˨˩ ɻən˧˥ ʂən˥˥ sɹ̩˥˥", "syllable_count": 4, "sentences": [{"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "引人深思", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影的结局引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的这句话很引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事很简单，却引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得很引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片引人深思，我看了很久。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题引人深思，大家都没有说话。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话不多，但每句都引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗很短，却引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里的这件事让人难过，也引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "成语；形容事物或言论有启发意义，让人深入思考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引人深思", "is_correct": true, "explanation": "正确：“引人深思”指让人深入思考，与“更……的是”后面的论述相符。"}, {"text": "令人捧腹", "is_correct": false, "explanation": "语义：“令人捧腹”指让人大笑，与句中副作用、神经机制的严肃论述相矛盾。"}, {"text": "招人喜爱", "is_correct": false, "explanation": "语义：“招人喜爱”说的是令人喜欢，副作用和研究窗口不是可爱之事，句意不通。"}, {"text": "令人安心", "is_correct": false, "explanation": "语义：「令人安心」指让人放心，与句中关于副作用、神经机制的严肃论述不合，句意不通。"}], "explanations": {"引人深思": "正确：“引人深思”指让人深入思考，与“更……的是”后面的论述相符。", "令人捧腹": "语义：“令人捧腹”指让人大笑，与句中副作用、神经机制的严肃论述相矛盾。", "招人喜爱": "语义：“招人喜爱”说的是令人喜欢，副作用和研究窗口不是可爱之事，句意不通。", "令人安心": "语义：「令人安心」指让人放心，与句中关于副作用、神经机制的严肃论述不合，句意不通。"}, "sentence_index": 0, "correct_answer": "引人深思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件新衣服的颜色很引人深思。", "explanation": "这里应该用〈引人注目〉。引人深思指让人深入思考，颜色只能引人注意，不能引人思考。"}, {"text": "他摔倒的样子很引人深思。", "explanation": "这里应该用〈引人发笑〉。引人深思指引发思考，摔倒的滑稽样子应当引人发笑。"}, {"text": "这个游戏的画面很引人深思。", "explanation": "这里应该用〈引人入胜〉。引人深思指促人思考，画面吸引人要用引人入胜来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引人深思", "is_correct": true, "explanation": "正确：“引人深思”指让人深入思考，与“大家都没有说话”的沉默情境相合。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧腾，与“大家都没有说话”的安静形成矛盾。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能用来形容问题。"}, {"text": "耀眼", "is_correct": false, "explanation": "体貌：“耀眼”形容光亮刺目，用在问题上不合。"}], "explanations": {"引人深思": "正确：“引人深思”指让人深入思考，与“大家都没有说话”的沉默情境相合。", "热闹": "语义：“热闹”形容场面喧腾，与“大家都没有说话”的安静形成矛盾。", "鲜艳": "搭配：“鲜艳”形容颜色，不能用来形容问题。", "耀眼": "体貌：“耀眼”形容光亮刺目，用在问题上不合。"}, "sentence_index": 6, "correct_answer": "引人深思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的香味很引人深思。", "explanation": "这里应该用〈引人垂涎〉。引人深思指让人思考，香味应当用引人垂涎来形容。"}, {"text": "这只新买的小狗很引人深思。", "explanation": "这里应该用〈引人注意〉。引人深思指引发思考，小狗的可爱模样只能引人注意，不能使人深思。"}, {"text": "这位穿红裙子的女士很引人深思。", "explanation": "这里应该用〈引人侧目〉。引人深思指引发思考，人的打扮引人注意要用引人侧目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇论文的结论把引人深思。", "corrected_sentence": "这篇论文的结论很引人深思。", "error_description": "结构错误：「把」字句须带动词谓语，「把引人深思」残缺不成句；应说「这篇论文的结论很引人深思。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题很很引人深思，大家都没有说话。", "corrected_sentence": "这个问题很引人深思，大家都没有说话。", "error_description": "错误：程度副词“很”重复使用，“很”前多加了一个“很”。正确：去掉多余的“很”，写作“这个问题很引人深思，大家都没有说话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
