INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11319, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指药物、方法等具有非常强大的效力或作用。", "primary_collocate": null, "pronunciation": "qiáng xiào", "ipa": "tɕʰjɑŋ˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "强效", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生给他开了强效止痛药。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效消毒液不能直接用手摸。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强效药吃多了对身体不好。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了一种强效方法，三天就瘦了两公斤。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶强效杀菌剂可以马上杀死细菌。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店里有很多强效感冒药，但要先问医生。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咳嗽得很厉害，医生让他吃强效消炎药。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效洗洁精能洗掉厨房里的油。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人睡不着，医生不敢给他开强效安眠药。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强效药", "label": "复合"}, {"form": "強效", "label": "繁体"}], "register": "书面", "sense_fingerprint": "药物、药剂、方法等效力强大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无效", "is_correct": false, "explanation": "语义：“无效”说没有效果，与“影响多巴胺通路、提供临床窗口”的作用相矛盾。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“抗精神病药物”，指药物效力强大。"}, {"text": "强劲", "is_correct": false, "explanation": "搭配：“强劲”多形容力量、风势、体力，不用来形容药物的效力。"}, {"text": "无害", "is_correct": false, "explanation": "语义：“无害”与后文“副作用每日可达数十次”的描述相矛盾。"}], "explanations": {"无效": "语义：“无效”说没有效果，与“影响多巴胺通路、提供临床窗口”的作用相矛盾。", "强效": "正确。“强效”修饰“抗精神病药物”，指药物效力强大。", "强劲": "搭配：“强劲”多形容力量、风势、体力，不用来形容药物的效力。", "无害": "语义：“无害”与后文“副作用每日可达数十次”的描述相矛盾。"}, "sentence_index": 0, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的态度很强效，谁也不敢跟他说话。", "explanation": "这里应该用〈强硬〉。态度、立场要说强硬，强效只用于药物、方法等的效力。"}, {"text": "这场暴雨来得很强效。", "explanation": "这里应该用〈猛烈〉。雨势、风势要说猛烈，强效不用来形容自然现象。"}, {"text": "他的病情很强效。", "explanation": "这里应该用〈严重〉。病情的轻重要说严重，强效只说药物或方法的效力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猛烈", "is_correct": false, "explanation": "搭配：“猛烈”多形容风势、攻势、火势，不用来形容感冒药。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“感冒药”，指药物效力强，所以要先问医生。"}, {"text": "剧烈", "is_correct": false, "explanation": "搭配：“剧烈”多形容疼痛、运动、变化，不用来形容药物。"}, {"text": "慢性", "is_correct": false, "explanation": "语义：感冒多为短期病，“慢性”说病程长，与“感冒药”不合。"}], "explanations": {"猛烈": "搭配：“猛烈”多形容风势、攻势、火势，不用来形容感冒药。", "强效": "正确。“强效”修饰“感冒药”，指药物效力强，所以要先问医生。", "剧烈": "搭配：“剧烈”多形容疼痛、运动、变化，不用来形容药物。", "慢性": "语义：感冒多为短期病，“慢性”说病程长，与“感冒药”不合。"}, "sentence_index": 6, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的拳头很强效。", "explanation": "这里应该用〈有力〉。力量的大小要说有力，强效只用于药物、方法等的效力。"}, {"text": "这只狗很强效。", "explanation": "这里应该用〈凶猛〉。动物的凶猛程度要说凶猛，强效不用来形容动物。"}, {"text": "她对朋友很强效。", "explanation": "这里应该用〈真诚〉。对人的态度要说真诚，强效不能用来形容人的情感与态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给他注射了一针强效地镇痛剂。", "corrected_sentence": "医生给他注射了一针强效的镇痛剂。", "error_description": "错误：“强效”修饰名词“镇痛剂”时须用“的”，“地”用于修饰动词，不能用在名词之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种强效地消炎药要在医生指导下吃。", "corrected_sentence": "这种强效的消炎药要在医生指导下吃。", "error_description": "错误：“强效地消炎药”，“地”应为“的”。强效修饰名词要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "屈服", "is_correct": true, "explanation": "正确：“屈服”指不再抵抗而顺从，是“抗”（抵抗、拒绝）的反义词。"}, {"text": "完成", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“完成”指做好某件事。"}, {"text": "观看", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“观看”指用眼睛看。"}, {"text": "打扫", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“打扫”指清除脏乱。"}], "correct_answer": "屈服", "explanations": {"屈服": "正确：“屈服”指不再抵抗而顺从，是“抗”（抵抗、拒绝）的反义词。", "完成": "与“抗”的抵抗义不构成反义关系，“完成”指做好某件事。", "观看": "与“抗”的抵抗义不构成反义关系，“观看”指用眼睛看。", "打扫": "与“抗”的抵抗义不构成反义关系，“打扫”指清除脏乱。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "屈服", "is_correct": true, "explanation": "正确：“屈服”指不再抵抗而顺从，是“抗”（抵抗、拒绝）的反义词。"}, {"text": "解释", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“解释”指说明道理。"}, {"text": "修理", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“修理”指修复损坏的东西。"}, {"text": "播种", "is_correct": false, "explanation": "与“抗”的抵抗义不构成反义关系，“播种”指把种子撒进土里。"}], "correct_answer": "屈服", "explanations": {"屈服": "正确：“屈服”指不再抵抗而顺从，是“抗”（抵抗、拒绝）的反义词。", "解释": "与“抗”的抵抗义不构成反义关系，“解释”指说明道理。", "修理": "与“抗”的抵抗义不构成反义关系，“修理”指修复损坏的东西。", "播种": "与“抗”的抵抗义不构成反义关系，“播种”指把种子撒进土里。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抵挡，拒绝，反对。", "primary_collocate": null, "pronunciation": "kàng", "ipa": "kʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "敌人太多，我们抗不住了。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人硬抗了很久，最后还是输了。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的风，小树怎么抗得住？", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再抗下去也没有用，还是答应吧。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别硬抗了，有事就跟大家说。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点冷我还抗得住，不用开暖气。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们抗了三天，最后还是没抗住。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上说不怕，其实早就抗不住了。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子抗了半天，还是去上学了。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨来了，他们抗不过大自然。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗着", "label": "体标"}, {"form": "抗过", "label": "体标"}, {"form": "抗拒", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词；抵挡压力、拒绝或不服从，常说“抗不住”“硬抗”“抗下去”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“抗”（kàng）是本词，指抵挡、拒绝。"}, {"text": "扛", "is_correct": false, "explanation": "扛（káng）与抗（kàng）声调不同，意思是用肩膀承担。"}, {"text": "康", "is_correct": false, "explanation": "康（kāng）与抗（kàng）声调不同，意思是健康。"}, {"text": "看", "is_correct": false, "explanation": "看（kàn）与抗（kàng）韵尾不同，一个是 n，一个是 ng，意思是观看。"}, {"text": "糠", "is_correct": false, "explanation": "糠（kāng）与抗（kàng）声调不同，意思是谷物脱下的皮。"}, {"text": "杠", "is_correct": false, "explanation": "杠（káng）与抗（kàng）声调不同，意思是杠杆或棍子。"}], "explanations": {"抗": "正确：“抗”（kàng）是本词，指抵挡、拒绝。", "扛": "扛（káng）与抗（kàng）声调不同，意思是用肩膀承担。", "康": "康（kāng）与抗（kàng）声调不同，意思是健康。", "看": "看（kàn）与抗（kàng）韵尾不同，一个是 n，一个是 ng，意思是观看。", "糠": "糠（kāng）与抗（kàng）声调不同，意思是谷物脱下的皮。", "杠": "杠（káng）与抗（kàng）声调不同，意思是杠杆或棍子。"}, "sentence_index": null, "correct_answer": "抗"}, "level_3": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“抗不住”指抵挡不了，符合敌众我寡、难以支撑的处境。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑不住”指止不住笑，与敌人压境的紧张语境矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭不住”说的是控制不住哭泣，不能用于敌人和局势。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱不住”不成立，唱歌与抵挡敌人毫无关系。"}], "explanations": {"抗": "正确：“抗不住”指抵挡不了，符合敌众我寡、难以支撑的处境。", "笑": "语义：“笑不住”指止不住笑，与敌人压境的紧张语境矛盾。", "哭": "搭配：“哭不住”说的是控制不住哭泣，不能用于敌人和局势。", "唱": "搭配：“唱不住”不成立，唱歌与抵挡敌人毫无关系。"}, "sentence_index": 0, "correct_answer": "抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行李抗在肩上。", "explanation": "这里应该用〈扛〉。抗表示抵挡、对抗，把行李扛在肩上要用扛（káng），不能写作抗。"}, {"text": "他抗着雨伞走进了教室。", "explanation": "这里应该用〈撑〉。撑伞要用撑（chēng），抗表示抵挡、对抗，不能用来说撑伞。"}, {"text": "他把箱子抗上了楼。", "explanation": "这里应该用〈扛〉。抗表示抵挡、对抗，把箱子扛上楼要用扛（káng），不能写作抗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“抗了三天，最后还是没抗住”中的“抗”指坚持抵挡，符合语境。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”后面要带宾语，“没写住”缺少对象，且与抵挡的语境无关。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读住”不成立，“读”与坚持抵挡的语境不搭。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫住”不成立，“扫”指清扫，与抵挡的语境不合。"}], "explanations": {"抗": "正确：“抗了三天，最后还是没抗住”中的“抗”指坚持抵挡，符合语境。", "写": "配价：“写”后面要带宾语，“没写住”缺少对象，且与抵挡的语境无关。", "读": "搭配：“读住”不成立，“读”与坚持抵挡的语境不搭。", "扫": "搭配：“扫住”不成立，“扫”指清扫，与抵挡的语境不合。"}, "sentence_index": 6, "correct_answer": "抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的音调很高抗。", "explanation": "这里应该用〈高亢〉。抗表示抵挡或拒绝，形容声音高而激昂要用高亢，不能写作抗。"}, {"text": "他们是一对恩爱的抗俪。", "explanation": "这里应该用〈伉俪〉。抗表示抵挡或拒绝，指夫妻要用伉俪，不能写作抗。"}, {"text": "他躺在抗上看书。", "explanation": "这里应该用〈炕〉。抗表示抵挡或拒绝，北方睡觉的土台要写作炕，不能写作抗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对这么大的压力，他咬牙抗了住。", "corrected_sentence": "面对这么大的压力，他咬牙抗住了。", "error_description": "错误：“了”放在“抗”和“住”之间，位置错误。正确：补语“住”之后加“了”，写作“抗住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终究很抗不过大自然。", "corrected_sentence": "他们终究抗不过大自然。", "error_description": "错误：程度副词“很”插在“终究”和“抗不过”之间，不能修饰动补结构，多加了“很”。正确：去掉“很”，写作“他们终究抗不过大自然”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
