INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11321, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精神病指大脑功能紊乱，导致思维、情感、行为异常的疾病。", "primary_collocate": null, "pronunciation": "jīng shén bìng", "ipa": "tɕiŋ˥ ʂən˧˥ piŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "精神病", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生说他得了精神病，需要住院治疗。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精神病会影响一个人的思维和情绪。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生专门治疗精神病，经验很丰富。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精神病患者需要家人的理解和照顾。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为精神病，一直在医院里吃药。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精神病的原因很复杂，和大脑有关系。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们常常不了解精神病，对患者有偏见。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哥哥得过精神病，现在已经好多了。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在研究精神病的新治疗方法。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神病人", "label": "复合"}, {"form": "精神病院", "label": "复合"}], "register": "书面", "sense_fingerprint": "精神病：大脑功能紊乱而使思维、情感、行为异常的疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神病", "is_correct": true, "explanation": "精神病指大脑功能紊乱的疾病，“抗精神病药物”是治疗这类疾病的药，与句中“影响多巴胺通路”的语境相符。"}, {"text": "高血压", "is_correct": false, "explanation": "语义：“抗高血压药物”主要用于降压，与句中“影响多巴胺通路、常见副作用为病理性哈欠”的描述不符。"}, {"text": "过敏", "is_correct": false, "explanation": "语义：抗过敏药主要针对组胺引起的过敏反应，与句中“影响多巴胺通路”的神经机制描述不符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒药多针对发热、鼻塞等呼吸道症状，并不作用于多巴胺通路，与句中神经机制的描述不符。"}], "explanations": {"精神病": "精神病指大脑功能紊乱的疾病，“抗精神病药物”是治疗这类疾病的药，与句中“影响多巴胺通路”的语境相符。", "高血压": "语义：“抗高血压药物”主要用于降压，与句中“影响多巴胺通路、常见副作用为病理性哈欠”的描述不符。", "过敏": "语义：抗过敏药主要针对组胺引起的过敏反应，与句中“影响多巴胺通路”的神经机制描述不符。", "感冒": "语义：感冒药多针对发热、鼻塞等呼吸道症状，并不作用于多巴胺通路，与句中神经机制的描述不符。"}, "sentence_index": 0, "correct_answer": "精神病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天精神病很好，一早就去跑步了。", "explanation": "这里应该用〈精神〉。“精神”指人的状态和活力，“精神病”是疾病名称，不能用来形容状态。"}, {"text": "他被送进精神病接受治疗，已经住了一个月。", "explanation": "这里应该用〈精神病院〉。“精神病”指疾病，不指医疗机构，不能作“送进”的地点。"}, {"text": "他患了一只精神病，需要住院观察。", "explanation": "量词误用：“精神病”作病名，量词应用“种”或“个”，“只”一般用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神病", "is_correct": true, "explanation": "精神病指大脑功能紊乱的疾病，句中说它的原因很复杂、与大脑有关，符合这一含义。"}, {"text": "龋齿", "is_correct": false, "explanation": "语义：龋齿由口腔细菌感染造成，与大脑关系不大，不符合句中“和大脑有关系”的说法。"}, {"text": "骨折", "is_correct": false, "explanation": "语义：骨折多由外伤造成，与大脑没有关系，不符合句意。"}, {"text": "脚气", "is_correct": false, "explanation": "语域：“脚气”是口语俗称，与句子的书面叙述不协调，而且它是真菌感染，与大脑无关。"}], "explanations": {"精神病": "精神病指大脑功能紊乱的疾病，句中说它的原因很复杂、与大脑有关，符合这一含义。", "龋齿": "语义：龋齿由口腔细菌感染造成，与大脑关系不大，不符合句中“和大脑有关系”的说法。", "骨折": "语义：骨折多由外伤造成，与大脑没有关系，不符合句意。", "脚气": "语域：“脚气”是口语俗称，与句子的书面叙述不协调，而且它是真菌感染，与大脑无关。"}, "sentence_index": 6, "correct_answer": "精神病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位精神病，每天都喜欢画画。", "explanation": "这里应该用〈精神病人〉。“精神病”是病名，指人要说“精神病人”，不能用“一位精神病”。"}, {"text": "医生做出了精神病，马上开始治疗。", "explanation": "这里应该用〈诊断〉。“精神病”是病名，医生做出的是诊断，不能说“做出精神病”。"}, {"text": "他把精神病放进了冰箱里。", "explanation": "这里应该用〈食物〉。精神病是疾病，不是可以放进冰箱的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人患的是精神病的，需要有人照顾。", "corrected_sentence": "这位老人患的是精神病，需要有人照顾。", "error_description": "“精神病”后多加了“的”。应写作“患的是精神病”，因为“是”后面的宾语已经完整，不需要再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候过精神病，后来治好了。", "corrected_sentence": "他小时候得过精神病，后来治好了。", "error_description": "漏掉动词“得”：“过”不能单独带宾语，应说“得过精神病”，此处少了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生理性", "is_correct": true, "explanation": "生理性指身体正常的功能和反应，与“病理性”相对，符合句中“正常”的语境。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与病理性没有反义关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓形容速度慢，与病理性不构成反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "丰富形容数量多或内容多，与病理性无关，不是它的反义词。"}], "correct_answer": "生理性", "explanations": {"生理性": "生理性指身体正常的功能和反应，与“病理性”相对，符合句中“正常”的语境。", "明亮": "明亮形容光线或颜色，与病理性没有反义关系。", "迟缓": "迟缓形容速度慢，与病理性不构成反义关系。", "丰富": "丰富形容数量多或内容多，与病理性无关，不是它的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生理性", "is_correct": true, "explanation": "生理性指身体正常的功能和反应，与病理性相对，符合句意。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容轮廓或声音分明，与病理性没有反义关系。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂形容光彩耀眼，与病理性无关，不构成反义词。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙形容事务多、很忙碌，与病理性没有反义关系。"}], "correct_answer": "生理性", "explanations": {"生理性": "生理性指身体正常的功能和反应，与病理性相对，符合句意。", "清晰": "清晰形容轮廓或声音分明，与病理性没有反义关系。", "灿烂": "灿烂形容光彩耀眼，与病理性无关，不构成反义词。", "繁忙": "繁忙形容事务多、很忙碌，与病理性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指疾病的发生、发展过程中的原因和变化。", "primary_collocate": null, "pronunciation": "bìng lǐ xìng", "ipa": "piŋ˥˩ li˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "病理性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生说这种变化是病理性的，不是正常的。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查后，医生发现他有病理性变化。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶尔打哈欠是正常的，病理性哈欠不一样。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种头疼是病理性的，要马上去医院。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先要分清这是病理性原因还是心理原因。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人睡不好，有时是病理性因素造成的。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器检查他有没有病理性问题。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种红印不是病理性的，过几天就会好。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上学习病理性变化的特点。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病理学", "label": "复合"}, {"form": "非病理性", "label": "派生"}], "register": "书面", "sense_fingerprint": "病理性：与疾病发生发展的原因和变化有关的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病理性", "is_correct": true, "explanation": "“病理性哈欠”指由疾病或药物副作用引起的哈欠，与“生理性”相对，符合句意。"}, {"text": "偶发性", "is_correct": false, "explanation": "语义：偶发性指偶尔出现，与句中“每日可达数十次之多”的描述矛盾。"}, {"text": "生理性", "is_correct": false, "explanation": "语义：生理性哈欠指正常生理活动引起的哈欠，与“副作用”的说法相悖，不符合句意。"}, {"text": "恶性", "is_correct": false, "explanation": "搭配：“恶性”多修饰肿瘤或病情，很少用来修饰哈欠，不符合习惯搭配。"}], "explanations": {"病理性": "“病理性哈欠”指由疾病或药物副作用引起的哈欠，与“生理性”相对，符合句意。", "偶发性": "语义：偶发性指偶尔出现，与句中“每日可达数十次之多”的描述矛盾。", "生理性": "语义：生理性哈欠指正常生理活动引起的哈欠，与“副作用”的说法相悖，不符合句意。", "恶性": "搭配：“恶性”多修饰肿瘤或病情，很少用来修饰哈欠，不符合习惯搭配。"}, "sentence_index": 0, "correct_answer": "病理性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动后心跳加快是正常的病理性反应，不用担心。", "explanation": "这里应该用〈生理性〉。“病理性”指由疾病引起的变化，不能用来形容正常的身体反应。"}, {"text": "这种腹痛是病理性的，和身体没有关系。", "explanation": "这里应该用〈心理性〉。“病理性”指由疾病引起的身体变化，和身体无关的腹痛应说“心理性”。"}, {"text": "这台电脑的屏幕出现了病理性变化，需要维修。", "explanation": "“病理性”只用于生物体的疾病过程，不能用于电脑屏幕等无生命物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病理性", "is_correct": true, "explanation": "病理性因素指由疾病引起的原因，句中“睡不好”可以由此解释，符合句意。"}, {"text": "致命性", "is_correct": false, "explanation": "语义：致命指能导致死亡，与“睡不好”的程度和语境不符。"}, {"text": "恶性", "is_correct": false, "explanation": "搭配：“恶性”多修饰肿瘤或病情，与“有时是……因素造成的”的搭配不自然，也不符合睡不好的语境。"}, {"text": "致癌性", "is_correct": false, "explanation": "语域：“致癌性”是专业用语，与本句的日常叙述不协调，而且不是导致失眠的常见原因。"}], "explanations": {"病理性": "病理性因素指由疾病引起的原因，句中“睡不好”可以由此解释，符合句意。", "致命性": "语义：致命指能导致死亡，与“睡不好”的程度和语境不符。", "恶性": "搭配：“恶性”多修饰肿瘤或病情，与“有时是……因素造成的”的搭配不自然，也不符合睡不好的语境。", "致癌性": "语域：“致癌性”是专业用语，与本句的日常叙述不协调，而且不是导致失眠的常见原因。"}, "sentence_index": 6, "correct_answer": "病理性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种擦伤是病理性的，是被椅子磨出来的。", "explanation": "这里应该用〈物理性〉。“病理性”指由疾病引起的变化，被椅子磨出的擦伤属于物理性损伤，不能说是病理性的。"}, {"text": "这种眼睛的颜色是病理性的，父母都有可能传给孩子。", "explanation": "这里应该用〈遗传性〉。眼睛颜色不是疾病，“病理性”只用于疾病的原因和变化，应说“遗传性”。"}, {"text": "女性每个月的周期变化是病理性的，很正常。", "explanation": "这里应该用〈生理性〉。“病理性”指疾病引起的变化，月经等正常生理现象应说“生理性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种病理性性腹痛需要马上检查。", "corrected_sentence": "这种病理性腹痛需要马上检查。", "error_description": "“性”多写了一次。“病理性”的词尾“性”只需一个，应写作“病理性腹痛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这是病理性，需要做进一步检查。", "corrected_sentence": "医生说这是病理性的，需要做进一步检查。", "error_description": "“病理性”作谓语时要带“的”，应说“是病理性的”。省去“的”后句子不完整，不符合汉语的谓语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
