INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "药物或某种治疗带来的除主要作用以外的其他作用，通常指不好的影响。", "primary_collocate": null, "pronunciation": "fù zuò yòng", "ipa": "fu˥˩ tswɔ˥˩ jʊŋ˥˩", "syllable_count": 3, "sentences": [{"text": "某些强效抗精神病药物会干扰多巴胺通路，患者出现的手抖常被归为其副作用，这反而为研究其神经机制提供了临床窗口。", "target_word": "副作用", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这有助于提高药物效果，减少副作用。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这种药有一点副作用。", "target_word": "副作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃完药以后，他有头晕的副作用。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种药的副作用很小。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "给孩子吃药前，要先了解副作用。", "target_word": "副作用", "complexity_tier": "T3", "furigana": "gěi hái zi chī yào qián, yào xiān liǎo jiě fù zuò yòng.", "sentence_source": "generated"}, {"text": "药吃多了，副作用也会变大。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药没有什么副作用，你放心吃。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃了药，出现了恶心的副作用。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书上写着药的副作用。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副作用：药物或治疗带来的主要作用以外的不良影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd209268f-53f6-4de8-8192-9154cf70cf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副作用", "is_correct": true, "explanation": "副作用：药物主要作用以外的不良影响，与“手抖”的不良作用相符。"}, {"text": "疗效", "is_correct": false, "explanation": "语义：“疗效”指好的治疗作用，与句中不良作用矛盾。"}, {"text": "好处", "is_correct": false, "explanation": "语义：“好处”指有益的方面，与句子描述的不良影响相反。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”指人的数量，不能用来说明药物的影响。"}], "explanations": {"副作用": "副作用：药物主要作用以外的不良影响，与“手抖”的不良作用相符。", "疗效": "语义：“疗效”指好的治疗作用，与句中不良作用矛盾。", "好处": "语义：“好处”指有益的方面，与句子描述的不良影响相反。", "人数": "搭配：“人数”指人的数量，不能用来说明药物的影响。"}, "sentence_index": 0, "correct_answer": "副作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的副作用见效很快。", "explanation": "这里应该用〈药效〉。副作用指药物带来的不良影响，药物起效快要说药效。"}, {"text": "这种药的副作用很好，吃了两天就退烧了。", "explanation": "这里应该用〈效果〉。副作用指不良影响，不能用“很好”来评价。"}, {"text": "这种药的副作用就是治病。", "explanation": "这里应该用〈主要作用〉。副作用指主要作用以外的不良影响，治病是药物的主要作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副作用", "is_correct": true, "explanation": "副作用：药物带来的不良影响，药吃多了不良影响会变大，符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会随着药量变大，句子讲的是药物的不良影响。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会因为吃药而变大，与句子内容不符。"}, {"text": "手续", "is_correct": false, "explanation": "搭配：“变大”说的是数量或体积，不用于“手续”。"}], "explanations": {"副作用": "副作用：药物带来的不良影响，药吃多了不良影响会变大，符合句意。", "歌曲": "语义：歌曲不会随着药量变大，句子讲的是药物的不良影响。", "窗户": "语义：窗户不会因为吃药而变大，与句子内容不符。", "手续": "搭配：“变大”说的是数量或体积，不用于“手续”。"}, "sentence_index": 6, "correct_answer": "副作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的副作用是维生素。", "explanation": "这里应该用〈成分〉。副作用指药物引起的不良影响，不是药物所含的物质。"}, {"text": "这个副作用能让病人康复。", "explanation": "这里应该用〈治疗〉。副作用是不良影响，不能使病人康复。"}, {"text": "医生给病人打了一针副作用。", "explanation": "这里应该用〈针剂〉。副作用是药物带来的不良影响，不能被注射；“打一针”的对象是针剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药可能会有一些的副作用。", "corrected_sentence": "这种药可能会有一些副作用。", "error_description": "错误形式：“一些的副作用”；正确形式：“一些副作用”。“一些”是数量词，直接修饰名词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要注意一只副作用。", "corrected_sentence": "我们要注意一种副作用。", "error_description": "错误形式：“一只副作用”；正确形式：“一种副作用”。“只”用于动物或成对的物件，“副作用”要用量词“种”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
