INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指医生亲自为病人诊治或与病人直接接触的医学实践。", "primary_collocate": null, "pronunciation": "lín chuáng", "ipa": "lin˧˥ ʈʂʰuaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "更引人深思的是，某些强效抗精神病药物因影响多巴胺通路，常以“病理性哈欠”作为副作用，每日可达数十次之多，这反而为研究其神经机制提供了临床窗口。", "target_word": "临床", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在临床上，这种药物的效果很好。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生有二十年的临床经验。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后一直做临床，没有做过研究。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学生要先学书本，再到医院学临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新药已经用于临床，很多医生开始使用。", "target_word": "临床", "complexity_tier": "T3", "furigana": "zhè ge xīn yào yǐ jīng yòng yú lín chuáng, hěn duō yī shēng kāi shǐ shǐ yòng。", "sentence_source": "generated"}, {"text": "临床上，医生会先问病人哪里不舒服。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻医生需要在临床中不断学习。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但懂理论，而且很有临床能力。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病人的情况在临床中很少见。", "target_word": "临床", "complexity_tier": "T3", "furigana": "zhè ge bìng rén de qíng kuàng zài lín chuáng zhōng hěn shǎo jiàn。", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨床", "label": "繁体"}, {"form": "临床医学", "label": "复合"}, {"form": "临床试验", "label": "复合"}], "register": "书面", "sense_fingerprint": "临床：医生直接接触病人、诊治病人的医学实践", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临床", "is_correct": true, "explanation": "正确。临床指医生直接诊治病人的实践，符合“研究神经机制”的语境。"}, {"text": "农业", "is_correct": false, "explanation": "语义：句子讲的是药物与神经机制的研究，“农业窗口”与医学研究无关。"}, {"text": "市场", "is_correct": false, "explanation": "语义：神经机制的研究不能由“市场窗口”提供，此处不合逻辑。"}, {"text": "服务", "is_correct": false, "explanation": "搭配：“服务窗口”是办事窗口的固定说法，不能指科研的窗口。"}], "explanations": {"临床": "正确。临床指医生直接诊治病人的实践，符合“研究神经机制”的语境。", "农业": "语义：句子讲的是药物与神经机制的研究，“农业窗口”与医学研究无关。", "市场": "语义：神经机制的研究不能由“市场窗口”提供，此处不合逻辑。", "服务": "搭配：“服务窗口”是办事窗口的固定说法，不能指科研的窗口。"}, "sentence_index": 0, "correct_answer": "临床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去临床看望朋友。", "explanation": "这里用错了词义。临床指医生诊治病人的医疗实践，不指场所，这里应该用〈医院〉。"}, {"text": "这位病人每天都做临床，身体很好。", "explanation": "这里用错了主体。“做临床”指医生为病人诊治，动作的主语应是〈医生〉，病人不能“做临床”。"}, {"text": "他常在实验室做临床，很少接触病人。", "explanation": "这里用错了场景。临床要求直接接触病人，实验室里的工作不叫临床，应说〈研究〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临床", "is_correct": true, "explanation": "正确。“临床上”指医生诊治病人的场合，符合后文“医生会先问病人”。"}, {"text": "工地", "is_correct": false, "explanation": "语义：医生在工地上先问病人哪里不舒服，与医疗情境不合。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场不是医生诊治病人的地方，此处语义不通。"}, {"text": "牌桌", "is_correct": false, "explanation": "语域：“牌桌”是口语化的场所词，与这段医学说明的书面语体不合。"}], "explanations": {"临床": "正确。“临床上”指医生诊治病人的场合，符合后文“医生会先问病人”。", "工地": "语义：医生在工地上先问病人哪里不舒服，与医疗情境不合。", "球场": "语义：球场不是医生诊治病人的地方，此处语义不通。", "牌桌": "语域：“牌桌”是口语化的场所词，与这段医学说明的书面语体不合。"}, "sentence_index": 6, "correct_answer": "临床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这家公司做的是临床工作，下个月就换人了。", "explanation": "这里用错了词义。临床指医疗实践，不表示“临时”，这里应该用〈临时〉。"}, {"text": "他得了临床，医生说要住院。", "explanation": "这里用错了类别。临床是诊治病人的工作，不是病名，不能说“得了临床”。"}, {"text": "医生用临床做手术，很有经验。", "explanation": "这里用错了方式。临床是诊治病人的工作，不是工具，不能用来做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在大医院做过一个临床，经验很丰富。", "corrected_sentence": "他在大医院做过临床，经验很丰富。", "error_description": "“临床”是不可数的医疗实践，不能用量词“个”修饰，应说“做过临床”，不能说“做过一个临床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药还没用临床。", "corrected_sentence": "这种药还没用于临床。", "error_description": "漏掉介词“于”：“用于”是固定搭配，“用”后需接“于”引出对象，应说“还没用于临床”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
