INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11327, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度相差很大，远远不是。", "primary_collocate": null, "pronunciation": "yuǎn fēi", "ipa": "ɥɛn˨˩˦ fei˥", "syllable_count": 2, "sentences": [{"text": "综上所述，打哈欠远非一种无意义的生理反射，而是集体温调节、神经同步与社会沟通于一体的多功能行为。", "target_word": "远非", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个问题远非你想的那么简单。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的收入远非大家想象的那样高。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学会几个词远非学好汉语。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点钱远非买房子的首付。", "target_word": "远非", "complexity_tier": "T3", "furigana": "zhè diǎn qián yuǎn fēi mǎi fáng zi de shǒu fù。", "sentence_source": "generated"}, {"text": "事情远非表面看起来那么容易。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次成功远非终点，只是开始。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的名气远非过去可比。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只靠运气远非长久之计。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病远非医生说的那样轻。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，书面，表示程度相差很大，远远不是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示远远不是，与“综上所述”后的转折“而是”相呼应。"}, {"text": "正是", "is_correct": false, "explanation": "语义：“正是”肯定“无意义”，与后文“而是……多功能行为”的结论相反。"}, {"text": "只是", "is_correct": false, "explanation": "搭配：“只是”后接“一种”表示仅仅如此，不能与后面的“而是”形成转折搭配。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示仅仅是，肯定了“无意义”，与全句的结论相反。"}], "explanations": {"远非": "正确。“远非”表示远远不是，与“综上所述”后的转折“而是”相呼应。", "正是": "语义：“正是”肯定“无意义”，与后文“而是……多功能行为”的结论相反。", "只是": "搭配：“只是”后接“一种”表示仅仅如此，不能与后面的“而是”形成转折搭配。", "不过": "语义：“不过”表示仅仅是，肯定了“无意义”，与全句的结论相反。"}, "sentence_index": 0, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校远非我家，所以我每天要坐一个小时的车。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "他远非会说英语，还会说法语。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示递进，“远非会说英语”与后文“还会说法语”前后矛盾，应说〈不仅〉。"}, {"text": "他远非不如我，因为他的成绩比我差很多。", "explanation": "这里前后矛盾。“远非不如我”表示他远不比我差，与后文“成绩比我差很多”矛盾，应说〈远远不如〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示远远不是终点，与后文“只是开始”呼应。"}, {"text": "就是", "is_correct": false, "explanation": "搭配：“就是”肯定“终点”，与后文“只是开始”形成矛盾，不能搭配。"}, {"text": "还是", "is_correct": false, "explanation": "语义：“还是终点”与后文“只是开始”的意思相冲突。"}, {"text": "却是", "is_correct": false, "explanation": "语义：“却是终点”的判断与后文“只是开始”相反。"}], "explanations": {"远非": "正确。“远非”表示远远不是终点，与后文“只是开始”呼应。", "就是": "搭配：“就是”肯定“终点”，与后文“只是开始”形成矛盾，不能搭配。", "还是": "语义：“还是终点”与后文“只是开始”的意思相冲突。", "却是": "语义：“却是终点”的判断与后文“只是开始”相反。"}, "sentence_index": 6, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的汉语远非他，所以我每次考试都能拿第一。", "explanation": "这里前后矛盾。“远非他”表示我远不如他，与“每次考试都能拿第一”矛盾，应说〈远远超过他〉。"}, {"text": "这次旅行远非北京。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "他远非快乐，所以每天都笑个不停。", "explanation": "这里用错了语义。“远非快乐”表示不快乐，与“笑个不停”矛盾，应说〈非常快乐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次成功很远非偶然。", "corrected_sentence": "这次成功远非偶然。", "error_description": "“远非”本身已表示程度，前面不能再加“很”，应说“远非偶然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作远非很轻松，我每天都很累。", "corrected_sentence": "这份工作远非轻松，我每天都很累。", "error_description": "“远非”本身已表示程度，后面的形容词前不能再加“很”，应说“远非轻松”，不能说“远非很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体（尤其是人体）的生命活动规律以及器官系统的功能。", "primary_collocate": null, "pronunciation": "shēng lǐ", "ipa": "ʂɤŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "综上所述，打哈欠远非一种无意义的生理反射，而是集体温调节、神经同步与社会沟通于一体的多功能行为。", "target_word": "生理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "青春期的孩子生理变化很大。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉是人的基本生理需要。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老年人的生理机能会慢慢下降。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这是正常的生理现象。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男女的生理特点不一样。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门课讲人体的生理和心理。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饿了想吃饭是一种生理反应。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "规律运动能改善生理状态。", "target_word": "生理", "complexity_tier": "T3", "furigana": "guī lǜ yùn dòng néng gǎi shàn shēng lǐ zhuàng tài", "sentence_source": "generated"}, {"text": "生理上的累，睡一觉就好了。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生理学", "label": "复合"}, {"form": "生理盐水", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指生物体尤其是人体的生命活动规律和器官功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生理", "is_correct": true, "explanation": "生理：生物体生命活动的规律和器官的功能，就是这里要选的词。"}, {"text": "生梨", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，“生梨”指没有煮过的梨，意思不同。"}, {"text": "升力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，“升力”指使物体向上的力，意思不同。"}, {"text": "省力", "is_correct": false, "explanation": "shěng lì 两个音节的声调都与 shēng lǐ 不同，“省力”指节省力气。"}, {"text": "胜利", "is_correct": false, "explanation": "shèng lì 两个音节的声调都与 shēng lǐ 不同，“胜利”指战胜对手或取得成功。"}], "explanations": {"生理": "生理：生物体生命活动的规律和器官的功能，就是这里要选的词。", "生梨": "lí（第二声）与 lǐ（第三声）声调不同，“生梨”指没有煮过的梨，意思不同。", "升力": "lì（第四声）与 lǐ（第三声）声调不同，“升力”指使物体向上的力，意思不同。", "省力": "shěng lì 两个音节的声调都与 shēng lǐ 不同，“省力”指节省力气。", "胜利": "shèng lì 两个音节的声调都与 shēng lǐ 不同，“胜利”指战胜对手或取得成功。"}, "sentence_index": null, "correct_answer": "生理"}, "level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "“生理反射”指身体对刺激的本能应答，与前文的体温调节、神经同步相合，只有“生理”能填入。"}, {"text": "政治", "is_correct": false, "explanation": "语义：打哈欠是身体行为，“政治反射”与前文讲的生物学行为不符。"}, {"text": "经济", "is_correct": false, "explanation": "语义：“经济反射”说不通，前文描述的是体温调节和神经活动。"}, {"text": "文化", "is_correct": false, "explanation": "搭配：“文化”不与“反射”搭配，反射前一般接“生理”“条件”等修饰语。"}], "explanations": {"生理": "“生理反射”指身体对刺激的本能应答，与前文的体温调节、神经同步相合，只有“生理”能填入。", "政治": "语义：打哈欠是身体行为，“政治反射”与前文讲的生物学行为不符。", "经济": "语义：“经济反射”说不通，前文描述的是体温调节和神经活动。", "文化": "搭配：“文化”不与“反射”搭配，反射前一般接“生理”“条件”等修饰语。"}, "sentence_index": 0, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生理很要强，遇到困难从不认输。", "explanation": "这里应该用〈心理〉。要强、不认输是性格与心理的特点；生理指生物体的生命活动规律和器官功能，不能用来形容性格。"}, {"text": "这次考试的生理很难，大家都没考好。", "explanation": "这里应该用〈难度〉。难度指事情的难易程度；生理只指生命活动的规律和器官功能，不能用来形容考试。"}, {"text": "这台电脑的生理很好，运行很快。", "explanation": "这里应该用〈性能〉。性能指机器的工作能力；生理只用于生物体的生命活动，不能用来形容电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "“人体的生理”指身体的生命活动规律与器官功能，与“心理”正好相对，这里只能填“生理”。"}, {"text": "工业", "is_correct": false, "explanation": "语义：“人体的工业”不成立，课程讲的是人体的生命活动，不是工业。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“人体的足球”不能说，“人体的”后面一般接“结构”“器官”“生理”等词。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影与人体无关，不能与“心理”并列，说明这门课讲的内容。"}], "explanations": {"生理": "“人体的生理”指身体的生命活动规律与器官功能，与“心理”正好相对，这里只能填“生理”。", "工业": "语义：“人体的工业”不成立，课程讲的是人体的生命活动，不是工业。", "足球": "搭配：“人体的足球”不能说，“人体的”后面一般接“结构”“器官”“生理”等词。", "电影": "语义：电影与人体无关，不能与“心理”并列，说明这门课讲的内容。"}, "sentence_index": 6, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个实验室研究各种生理的生存环境。", "explanation": "这里应该用〈生物〉。生物指各种生命体，生理只指生命体的活动规律，不能用来指生命体本身。"}, {"text": "这条路的生理很平整，走起来很舒服。", "explanation": "这里应该用〈路况〉。路况指道路的状况；生理只用于生物体的生命活动，不能用来形容道路。"}, {"text": "这份报告分析了市场的生理变化。", "explanation": "这里应该用〈走势〉。生理只指生命体的活动规律，不能用来说市场的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃饭和睡觉都属于人的很生理需要。", "corrected_sentence": "吃饭和睡觉都属于人的生理需要。", "error_description": "程度副词错误：“生理”是名词性修饰语，不能受“很”修饰，应说“人的生理需要”，删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种累是生理里的，不是心理上的。", "corrected_sentence": "这种累是生理上的，不是心理上的。", "error_description": "方位词错误：“生理”后面应该用“上”，说“生理上的”，不能说“生理里的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
