INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "光线、声波或热波遇到物体表面后折回。", "primary_collocate": null, "pronunciation": "fǎn shè", "ipa": "fan˨˩˦ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "光线照到光滑的金属表面时，大部分会被反射回去，所以人能在上面看到自己的影子。", "target_word": "反射", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "镜子能反射光线。", "target_word": "反射", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "湖面反射着蓝天和白云。", "target_word": "反射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的墙反射阳光，房间很亮。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山谷会反射声音，所以有回声。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪地反射的阳光很刺眼。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮自己不发光，只是反射太阳光。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃窗把阳光反射到我脸上。", "target_word": "反射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浅色衣服能反射热量，夏天更凉快。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水面把灯光反射成一条金线。", "target_word": "反射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反射了", "label": "体标"}, {"form": "反射着", "label": "体标"}, {"form": "反射过", "label": "体标"}, {"form": "反射镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，光线、声波或热波从物体表面折回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反射", "is_correct": true, "explanation": "“被……回去”前接表示光线折回的动词“反射”，只有“反射”能填入。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”指火箭、子弹等被送出去，与光线折回的意思不符。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：“吸收”指光被物体留住，光滑的金属表面主要是把光折回，不是吸收。"}, {"text": "遮挡", "is_correct": false, "explanation": "搭配：“遮挡”指挡住，光线被挡住就不会“回去”，与“被……回去”不搭配。"}], "explanations": {"反射": "“被……回去”前接表示光线折回的动词“反射”，只有“反射”能填入。", "发射": "语义：“发射”指火箭、子弹等被送出去，与光线折回的意思不符。", "吸收": "语义：“吸收”指光被物体留住，光滑的金属表面主要是把光折回，不是吸收。", "遮挡": "搭配：“遮挡”指挡住，光线被挡住就不会“回去”，与“被……回去”不搭配。"}, "sentence_index": 0, "correct_answer": "反射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火箭成功反射升空了。", "explanation": "这里应该用〈发射〉。发射指火箭、卫星被送出去；反射指光线等碰到表面后折回。"}, {"text": "这份报告反射了公司的真实情况。", "explanation": "这里应该用〈反映〉。反映指把情况如实表现出来；反射指光线等碰到表面折回，不能用于报告的内容。"}, {"text": "光线从空气斜射进水里时，方向改变，是因为发生了反射。", "explanation": "这里应该用〈折射〉。光从一种介质斜射进另一种介质时方向改变，是折射；反射是光碰到表面后折回，不是进入另一种介质时的方向改变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反射", "is_correct": true, "explanation": "“反射”指月光是太阳光的折回，与“自己不发光”相合，只有“反射”能填入。"}, {"text": "发出", "is_correct": false, "explanation": "语义：“发出”说明自身发光，与前文“自己不发光”矛盾。"}, {"text": "遮挡", "is_correct": false, "explanation": "语义：“遮挡”指挡住光，与月亮只是把光折回的意思不符。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”的对象多是人造物，不能用来说月亮对太阳光的作用。"}], "explanations": {"反射": "“反射”指月光是太阳光的折回，与“自己不发光”相合，只有“反射”能填入。", "发出": "语义：“发出”说明自身发光，与前文“自己不发光”矛盾。", "遮挡": "语义：“遮挡”指挡住光，与月亮只是把光折回的意思不符。", "制造": "搭配：“制造”的对象多是人造物，不能用来说月亮对太阳光的作用。"}, "sentence_index": 6, "correct_answer": "反射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次任务的卫星会在明天反射。", "explanation": "这里应该用〈发射〉。卫星是被送出去的，应该用发射；反射指光线碰到表面折回。"}, {"text": "他当场反射了对方的观点。", "explanation": "这里应该用〈反驳〉。反驳指用道理否定对方的观点；反射指光线、声波等从表面折回，不能用于观点。"}, {"text": "阳光穿过玻璃杯会反射出彩虹。", "explanation": "这里应该用〈折射〉。阳光穿过玻璃等介质时发生折射才形成彩虹；反射是光碰到表面弹回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "灯光照在镜子上，会反射来。", "corrected_sentence": "灯光照在镜子上，会反射回来。", "error_description": "补语残缺：“反射”后应接趋向补语“回来”，说“反射回来”，只说“反射来”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳光照在湖面上，湖水很反射金色的光。", "corrected_sentence": "阳光照在湖面上，湖水能反射金色的光。", "error_description": "程度副词错误：“很”不能修饰动词“反射”，应改为表示能力的“能”，写作“能反射金色的光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个整体，各部分之间紧密联系，不可分割。", "primary_collocate": null, "pronunciation": "yì tǐ", "ipa": "i˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "综上所述，打哈欠远非一种无意义的生理反射，而是集体温调节、神经同步与社会沟通于一体的多功能行为。", "target_word": "一体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台音箱和底座是一体的，不能分开。", "target_word": "一体", "complexity_tier": "T3", "furigana": "yì tǐ", "sentence_source": "generated"}, {"text": "他和音乐好像已经融为一体了。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一家人从不分彼此，简直是一体的。", "target_word": "一体", "complexity_tier": "T3", "furigana": "yì tǐ", "sentence_source": "generated"}, {"text": "这台电脑把屏幕和主机做成一体，很方便。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山水合为一体，像一幅画。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子和花园设计成一体，看起来很大。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，听、说、读、写是一体的，不能只练一个。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥和路合为一体，走上去很平。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在马背上，人和马好像成了一体。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一體", "label": "繁体"}, {"form": "一体化", "label": "复合"}], "register": "通用", "sense_fingerprint": "多个部分合成不可分的整体，常见于「融为一体」「合为一体」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一体", "is_correct": true, "explanation": "正确：「集……于一体」表示多种功能合为一个整体，与前文相合。"}, {"text": "一线", "is_correct": false, "explanation": "语义：「一线」指前线或第一线，与多种功能合为整体的意思不符。"}, {"text": "一程", "is_correct": false, "explanation": "语义：「一程」指一段路程，与多种功能合为一个整体的意思不符。"}, {"text": "一夜", "is_correct": false, "explanation": "搭配：「集……于」后接整体概念，不接表示时间的词。"}], "explanations": {"一体": "正确：「集……于一体」表示多种功能合为一个整体，与前文相合。", "一线": "语义：「一线」指前线或第一线，与多种功能合为整体的意思不符。", "一程": "语义：「一程」指一段路程，与多种功能合为一个整体的意思不符。", "一夜": "搭配：「集……于」后接整体概念，不接表示时间的词。"}, "sentence_index": 0, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的计划要从一体来考虑。", "explanation": "这里应该用〈整体〉。一体强调各部分连成不可分割的整体，“从整体来考虑”要说整体。"}, {"text": "两国的规定要一体，才能执行。", "explanation": "这里应该用〈统一〉。一体不能表示使规定一致，要说统一。"}, {"text": "我买了一体衣服。", "explanation": "这里应该用〈套〉。一体指连成整体的状态，不作量词；成套的衣服要用套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一体", "is_correct": true, "explanation": "正确：「设计成一体」表示连成整体，与「看起来很大」相合。"}, {"text": "一隅", "is_correct": false, "explanation": "语义：「一隅」指一个角落，与「看起来很大」矛盾。"}, {"text": "一角", "is_correct": false, "explanation": "语义：「一角」指很小的一部分，与「看起来很大」矛盾。"}, {"text": "一间", "is_correct": false, "explanation": "搭配：「设计成一间」不能用于房子和花园这两个独立的部分。"}], "explanations": {"一体": "正确：「设计成一体」表示连成整体，与「看起来很大」相合。", "一隅": "语义：「一隅」指一个角落，与「看起来很大」矛盾。", "一角": "语义：「一角」指很小的一部分，与「看起来很大」矛盾。", "一间": "搭配：「设计成一间」不能用于房子和花园这两个独立的部分。"}, "sentence_index": 6, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩的配合很一体。", "explanation": "这里应该用〈协调〉。一体指部分连成整体，不用来形容配合的和谐程度。"}, {"text": "两人的看法是一体的。", "explanation": "这里应该用〈同一〉。一体说的是连成整体，不指看法相同。"}, {"text": "两个模块彼此一体，可以单独拆下使用。", "explanation": "这里应该用〈独立〉。一体指连在一起、不可分割，“可以单独拆下使用”说明两者是独立的，不能说一体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个部件是一体地，不能拆开。", "corrected_sentence": "这两个部件是一体的，不能拆开。", "error_description": "“是……的”结构中应用“的”，不能用“地”。“地”是状语标记，这里应说「是一体的」，写成「是一体地」是误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上衣和裤子合一体。", "corrected_sentence": "上衣和裤子合为一体。", "error_description": "“合为一体”是固定格式，“为”不能省略，应说「合为一体」，写成「合一体」缺少“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
