INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能被观察到的内部状态的外部表现", "primary_collocate": null, "pronunciation": "biǎo zhēng", "ipa": "pjɑʊ˨˩˦ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "打哈欠既是大脑内在状态的外在表征，也是人类无意识间进行情感共振的一种方式。", "target_word": "表征", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "发烧是身体生病的一种表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脸红常常是紧张的外在表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哭泣是内心难过的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种声音是心脏有问题的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，也许是心情不好的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子爱笑，是心里高兴的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手一直发抖，是害怕的明显表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡不着觉可能是压力太大的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看到学生低头，把它当作不自信的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表徵", "label": "繁体"}], "register": "书面", "sense_fingerprint": "内部状态（心情、身体状况）在外部显现出来的表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "正确：「外在表征」指内在状态的外部显现，与前文「内在状态」相对应。"}, {"text": "工具", "is_correct": false, "explanation": "语义：「外在工具」与内在状态的外部显现意思不合。"}, {"text": "货币", "is_correct": false, "explanation": "语义：「外在货币」在句中没有意义，与内外状态无关。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：「外在数字」不能用来说内在状态的外部表现。"}], "explanations": {"表征": "正确：「外在表征」指内在状态的外部显现，与前文「内在状态」相对应。", "工具": "语义：「外在工具」与内在状态的外部显现意思不合。", "货币": "语义：「外在货币」在句中没有意义，与内外状态无关。", "数字": "搭配：「外在数字」不能用来说内在状态的外部表现。"}, "sentence_index": 0, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "红绿灯是交通的表征。", "explanation": "这里应该用〈标志〉。表征指内在状态的外部显现，交通信号灯应说标志。"}, {"text": "这份报告是他有罪的表征。", "explanation": "这里应该用〈证据〉。表征用于内在状态的外显，不用于证明罪行的材料。"}, {"text": "这道题的表征是三。", "explanation": "这里应该用〈答案〉。表征不能用于数学题的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "正确：「心里高兴的表征」指内在情绪的外部表现，与句意相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：「心里高兴的地图」在句中没有意义，与情绪无关。"}, {"text": "账本", "is_correct": false, "explanation": "语义：「心里高兴的账本」与孩子爱笑的情绪没有关系。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：「心里高兴的文件」不能这样说，文件不表现情绪。"}], "explanations": {"表征": "正确：「心里高兴的表征」指内在情绪的外部表现，与句意相符。", "地图": "语义：「心里高兴的地图」在句中没有意义，与情绪无关。", "账本": "语义：「心里高兴的账本」与孩子爱笑的情绪没有关系。", "文件": "搭配：「心里高兴的文件」不能这样说，文件不表现情绪。"}, "sentence_index": 6, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的表征很好。", "explanation": "这里应该用〈成绩〉。表征指内在状态的外显，考试结果要说成绩。"}, {"text": "这个红灯是停车的表征。", "explanation": "这里应该用〈信号〉。表征不指交通规则的指示，红灯应说信号。"}, {"text": "这本书是研究历史的表征。", "explanation": "这里应该用〈资料〉。表征不指可供研究的书面材料，应说资料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种红色是害羞的一种表征的。", "corrected_sentence": "这种红色是害羞的一种表征。", "error_description": "“表征”作句末名词时不能加“的”，应说「一种表征」。句末多出“的”是语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种沉默是紧张的一只表征。", "corrected_sentence": "这种沉默是紧张的一种表征。", "error_description": "“表征”前的量词用错。“只”多用于动物或个体物件，不搭配这类抽象事物；应说“一种表征”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意识", "is_correct": true, "explanation": "有意识与无意识是反义词，指有自觉意识的状态，与“失去意识”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线，与无意识无反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地，与无意识无反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖形容温度或感受，与无意识无反义关系。"}], "correct_answer": "有意识", "explanations": {"有意识": "有意识与无意识是反义词，指有自觉意识的状态，与“失去意识”相对。", "明亮": "明亮形容光线，与无意识无反义关系。", "坚硬": "坚硬形容质地，与无意识无反义关系。", "温暖": "温暖形容温度或感受，与无意识无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意识", "is_correct": true, "explanation": "有意识与无意识是反义词，指有自觉意识的状态，与“失去意识”相对。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈形容水或眼神等，与无意识无反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与无意识无反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间，与无意识无反义关系。"}], "correct_answer": "有意识", "explanations": {"有意识": "有意识与无意识是反义词，指有自觉意识的状态，与“失去意识”相对。", "清澈": "清澈形容水或眼神等，与无意识无反义关系。", "柔软": "柔软形容质地，与无意识无反义关系。", "狭窄": "狭窄形容空间，与无意识无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指没有自觉意识或失去意识的状态，行为不受主观控制。", "primary_collocate": null, "pronunciation": "wú yì shí", "ipa": "u˧˥ i˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "打哈欠既是大脑内在状态的外在表征，也是人类无意识间进行情感共振的一种方式。", "target_word": "无意识", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "病人昏迷了三天，一直处在无意识中。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头撞到墙，一下子陷入无意识。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻醉药会让人进入短暂的无意识。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从无意识中醒了过来。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车祸后，他有半个小时处于无意识。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问他，无意识的时候发生了什么。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉时，人不会完全陷入无意识。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人在无意识中说了几句话，醒后全忘了。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太累的时候，人可能会短暂地陷入无意识。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无意识状态", "label": "复合"}, {"form": "無意識", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "失去自觉意识的状态，行为不受主观控制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "无意识：没有自觉意识的状态，此处指人类在不自觉中进行情感共振。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想是思维的内容，不是可以发生“情感共振”的时间或状态，与“间”不搭。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情间”不成立，“间”要求时间或状态性的词。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”为口语，与这段书面语的语域不合，且不能表示时间或状态。"}], "explanations": {"无意识": "无意识：没有自觉意识的状态，此处指人类在不自觉中进行情感共振。", "思想": "语义：思想是思维的内容，不是可以发生“情感共振”的时间或状态，与“间”不搭。", "感情": "搭配：“感情间”不成立，“间”要求时间或状态性的词。", "玩意儿": "语域：“玩意儿”为口语，与这段书面语的语域不合，且不能表示时间或状态。"}, "sentence_index": 0, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的无意识很精彩。", "explanation": "这里应该用〈表现〉。“无意识”指失去意识的状态或不受主观控制的行为，不指比赛中的表现；“比赛表现很精彩”要用表现。"}, {"text": "他的无意识很浅，稍有动静就醒。", "explanation": "这里应该用〈睡眠〉。“无意识”指失去知觉的状态，不能说“浅”；睡得浅深要用睡眠。"}, {"text": "这次事故后，他的无意识很清楚，什么都记得。", "explanation": "这里应该用〈记忆〉。「无意识」指失去意识的状态，不能说「很清楚」；「什么都记得」要说记忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "无意识：没有知觉的状态，此处指病人失去知觉的时候。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不能表示人失去知觉的时段。"}, {"text": "脑瓜子", "is_correct": false, "explanation": "语域：“脑瓜子”为口语，与问诊的书面表述不合，且不指一段状态。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指食量，不能与“……的时候”构成表示时段的成分。"}], "explanations": {"无意识": "无意识：没有知觉的状态，此处指病人失去知觉的时候。", "钢笔": "语义：钢笔是书写工具，不能表示人失去知觉的时段。", "脑瓜子": "语域：“脑瓜子”为口语，与问诊的书面表述不合，且不指一段状态。", "饭量": "搭配：“饭量”指食量，不能与“……的时候”构成表示时段的成分。"}, "sentence_index": 6, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他麻醉后终于恢复了无意识。", "explanation": "这里应该用〈知觉〉。“无意识”指失去知觉的状态，恢复的是知觉，不能说“恢复无意识”。"}, {"text": "医生让他把无意识集中在手上。", "explanation": "这里应该用〈意识〉。“集中”的对象是意识，“无意识”指失去意识的状态，不能被集中。"}, {"text": "他的无意识很灵敏，一点声音就醒了。", "explanation": "这里应该用〈听觉〉。「无意识」指失去意识的状态，不能说「灵敏」；「听觉灵敏」要说听觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在无意识说了真心话。", "corrected_sentence": "他在无意识中说了真心话。", "error_description": "“无意识”后的方位词“中”不能省略，应说“在无意识中”；漏掉“中”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他陷入了无意识过，醒来后什么也不记得。", "corrected_sentence": "他陷入了无意识，醒来后什么也不记得。", "error_description": "「过」不能紧接宾语「无意识」之后，也不能与「了」同用；去掉「过」即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体受到与其固有频率相同的外力作用时振幅显著增大的现象；比喻彼此思想、情感的强烈呼应。", "primary_collocate": null, "pronunciation": "gòng zhèn", "ipa": "kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "当外力的频率恰好与物体的固有频率相同时，物体的振幅会显著增大，这一现象在物理学中被称为共振，并常被引申为彼此思想、情感的强烈呼应。", "target_word": "共振", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "模仿他人的动作，既是大脑内在状态的外在表征，也是人类无意识间进行情感共振的一种方式。", "target_word": "共振", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "大桥因为风引起了共振，开始来回摇晃。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵过桥时不能齐步走，以免产生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃杯碎了，是因为声音和杯子发生了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌让很多年轻人产生了情感共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个物体频率相同，就会产生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，音叉能让旁边的音叉发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用磁场让身体里的原子发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器一开，窗户就会发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共振频率", "label": "复合"}, {"form": "磁共振", "label": "复合"}], "register": "书面语", "sense_fingerprint": "物理上的共振现象，也比喻思想情感的强烈呼应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：句中指物理学里振幅显著增大的现象，“被称为”之后应填这一专名“共振”。"}, {"text": "谐波", "is_correct": false, "explanation": "语义：谐波指频率为基频整数倍的振动分量，并非振幅显著增大的现象名称，句中不通。"}, {"text": "回声", "is_correct": false, "explanation": "语义：回声是声音遇障碍物反射回来的现象，与同频振动导致振幅增大无关。"}, {"text": "衰减", "is_correct": false, "explanation": "语义：衰减指振幅逐渐变小，与句中“振幅显著增大”的描述正相反。"}], "explanations": {"共振": "正确：句中指物理学里振幅显著增大的现象，“被称为”之后应填这一专名“共振”。", "谐波": "语义：谐波指频率为基频整数倍的振动分量，并非振幅显著增大的现象名称，句中不通。", "回声": "语义：回声是声音遇障碍物反射回来的现象，与同频振动导致振幅增大无关。", "衰减": "语义：衰减指振幅逐渐变小，与句中“振幅显著增大”的描述正相反。"}, "sentence_index": 0, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山谷里传来了共振，我们都听见了。", "explanation": "这里应该用〈回声〉。回声是声音遇到障碍物反射回来的现象，能从远处传来；共振是物体因频率相同而振幅增大，不是声音的传播。"}, {"text": "两个球迎面共振后，发出了巨响。", "explanation": "这里应该用〈碰撞〉。碰撞指物体猛烈地相互接触；共振指物体因同频振动而振幅增大，不是接触动作，句中用错了。"}, {"text": "他每天按时吃药，病情慢慢共振。", "explanation": "这里应该用〈好转〉。好转指病情向好的方向发展；共振指同频振动或情感的强烈呼应，不能描述病情变化的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：两个物体频率相同时，一个的振动会引起另一个振幅增大，即共振。"}, {"text": "潮汐", "is_correct": false, "explanation": "搭配：“潮汐”一般说“形成”，由天体引力产生，与物体的频率无关，“产生潮汐”放在此处不通。"}, {"text": "日食", "is_correct": false, "explanation": "语义：日食由天体遮挡形成，与物体的频率关系毫无关系，句意不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹由光线折射形成，句中讲的是物体之间的频率关系，彩虹与之不相干。"}], "explanations": {"共振": "正确：两个物体频率相同时，一个的振动会引起另一个振幅增大，即共振。", "潮汐": "搭配：“潮汐”一般说“形成”，由天体引力产生，与物体的频率无关，“产生潮汐”放在此处不通。", "日食": "语义：日食由天体遮挡形成，与物体的频率关系毫无关系，句意不通。", "彩虹": "语义：彩虹由光线折射形成，句中讲的是物体之间的频率关系，彩虹与之不相干。"}, "sentence_index": 6, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个冬天太冷了，他冷得共振。", "explanation": "这里应该用〈颤抖〉。颤抖指人因寒冷或恐惧而身体抖动；共振指物体受同频外力作用时振幅增大，不用来形容人因冷而发抖。"}, {"text": "两根木棍用力一共振，就冒出了火星。", "explanation": "这里应该用〈摩擦〉。摩擦指两个物体接触并相对运动而产生热或火花；共振指物体因同频振动而振幅增大，不是接触运动，句中用错了。"}, {"text": "电锯一转，火花共振。", "explanation": "这里应该用〈飞溅〉。飞溅指火花或液滴向四周散开；共振指物体因同频振动而振幅增大，不能表示火花飞散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风一吹，大桥就共振出来了。", "corrected_sentence": "风一吹，大桥就共振起来了。", "error_description": "补语用错：「共振」后的趋向补语应用「起来」（表示开始并持续），不能用「出来」（指从内向外显露），错误形式为「共振出来」，正确形式为「共振起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗户的固有频率与风声相同时，就会发生一个共振。", "corrected_sentence": "窗户的固有频率与风声相同时，就会发生一次共振。", "error_description": "量词用错：共振指一次振动现象，计量应用「次」，不能用「个」，应改为「发生一次共振」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
