INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11335, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究大脑和神经系统如何控制思想、情感和行为的科学。", "primary_collocate": null, "pronunciation": "shén jīng kē xué", "ipa": "ʂən˧˥ tɕiŋ˥ kʰɤ˥ ɕɥɛ˧˥", "syllable_count": 4, "sentences": [{"text": "随着神经科学的发展，这一古老而普遍的现象正逐步从日常观察升华为理解意识、共情与脑功能整合的重要切入点。", "target_word": "神经科学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "神经科学研究大脑是怎么工作的。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学学习神经科学。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对神经科学很感兴趣，常常看相关的书。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学可以帮助我们理解人为什么会记忆。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学神经科学的人，要先懂一点生物。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本神经科学入门书写得很清楚。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学告诉我们，睡眠对大脑很重要。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用神经科学的方法研究学习问题。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的神经科学课讲了大脑怎么控制手。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经科学家", "label": "复合"}, {"form": "神經科學", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "研究大脑和神经系统如何控制思想、情感和行为的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经科学", "is_correct": true, "explanation": "正确。句子后半讲大脑功能与意识，“神经科学”是研究这些内容的学科。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：“天文学”研究天体，句中讲的是意识与脑功能，两者无关。"}, {"text": "经济学", "is_correct": false, "explanation": "语义：“经济学”研究财富与资源分配，与句中的脑功能整合不相关。"}, {"text": "农学", "is_correct": false, "explanation": "语义：“农学”研究农业生产，与句中讲的意识与脑功能整合无关。"}], "explanations": {"神经科学": "正确。句子后半讲大脑功能与意识，“神经科学”是研究这些内容的学科。", "天文学": "语义：“天文学”研究天体，句中讲的是意识与脑功能，两者无关。", "经济学": "语义：“经济学”研究财富与资源分配，与句中的脑功能整合不相关。", "农学": "语义：“农学”研究农业生产，与句中讲的意识与脑功能整合无关。"}, "sentence_index": 0, "correct_answer": "神经科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她选了一只神经科学。", "explanation": "这里应该用〈门〉。学科作量词用“门”，“只”多用于动物等。"}, {"text": "她每天神经科学两小时。", "explanation": "这里应该用〈研究〉。神经科学是名词，不能直接当动词用。"}, {"text": "他因为脑部受伤，在医院做了神经科学手术。", "explanation": "这里应该用〈神经外科〉。神经科学是研究大脑的学科，不能做手术；“神经外科”是诊治脑部疾病的临床科室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经科学", "is_correct": true, "explanation": "正确。“神经科学”是可以写入门书的学科名称，符合句意。"}, {"text": "神经病", "is_correct": false, "explanation": "语域：“神经病”是口语、带贬义的说法，与这句书面式的表述不合。"}, {"text": "神经末梢", "is_correct": false, "explanation": "搭配：“神经末梢”指神经的末端，是身体结构，不能作入门书的主题。"}, {"text": "脑干", "is_correct": false, "explanation": "搭配：“脑干”是脑的一部分，不是可以入门学习的学科。"}], "explanations": {"神经科学": "正确。“神经科学”是可以写入门书的学科名称，符合句意。", "神经病": "语域：“神经病”是口语、带贬义的说法，与这句书面式的表述不合。", "神经末梢": "搭配：“神经末梢”指神经的末端，是身体结构，不能作入门书的主题。", "脑干": "搭配：“脑干”是脑的一部分，不是可以入门学习的学科。"}, "sentence_index": 6, "correct_answer": "神经科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大脑里的神经科学会传递信号。", "explanation": "这里应该用〈神经元〉。神经科学是学科，不是细胞，不能在大脑里传递信号。"}, {"text": "他花了三年时间训练神经科学。", "explanation": "这里应该用〈神经网络〉。神经科学是学科，不能被训练；“神经网络”是可以训练的计算模型。"}, {"text": "医生说他得了神经科学，需要治疗。", "explanation": "这里应该用〈病〉。神经科学是学科，不是疾病，不能说“得了”它；“得了”后接的是病名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一只神经科学。", "corrected_sentence": "他学了一门神经科学。", "error_description": "“一只神经科学”应为“一门神经科学”。“神经科学”是学科，学科的量词用“门”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父亲是神经科学。", "corrected_sentence": "我父亲是神经科学家。", "error_description": "“神经科学”指学科，指人要加“家”，应为“神经科学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
