INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指解决问题或开始某项工作最先着手的方面或关键之处。", "primary_collocate": null, "pronunciation": "qiē rù diǎn", "ipa": "tɕʰje˥ ɻu˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "随着神经科学的发展，打哈欠这一古老而普遍的现象正逐步从日常观察升华为理解意识、共情与脑功能整合的重要切入点。", "target_word": "切入点", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "写这篇文章，你想从哪个切入点开始？", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到好的切入点，问题就容易解决了。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的切入点很特别。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究这个问题，我们要先找切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从孩子的兴趣找到了教育的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，作文要选一个小的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈判，价格是最好的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保可以作为这个节目的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的问题给了我们一个新的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切入點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处理问题或开展工作时最先着手的关键方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切入点", "is_correct": true, "explanation": "「切入点」指解决问题或开始工作最先着手的关键之处，与「重要」及「理解意识、脑功能整合」的语境相合。"}, {"text": "障碍", "is_correct": false, "explanation": "语义：「障碍」是负面事物，与「升华为」表示提升的语义相反。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：「重要玩具」不能用来指理解意识、脑功能整合这类研究途径。"}, {"text": "噱头", "is_correct": false, "explanation": "语域：「噱头」多为口语或带贬义的说法，不适用于这一学术语境。"}], "explanations": {"切入点": "「切入点」指解决问题或开始工作最先着手的关键之处，与「重要」及「理解意识、脑功能整合」的语境相合。", "障碍": "语义：「障碍」是负面事物，与「升华为」表示提升的语义相反。", "玩具": "搭配：「重要玩具」不能用来指理解意识、脑功能整合这类研究途径。", "噱头": "语域：「噱头」多为口语或带贬义的说法，不适用于这一学术语境。"}, "sentence_index": 0, "correct_answer": "切入点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次研究的切入点是得出结论。", "explanation": "这里应该用〈目标〉。切入点指开始着手的地方，不是最终要达到的目标，所以不能说「切入点是得出结论」。"}, {"text": "他做这件事的切入点是为了帮助朋友。", "explanation": "这里应该用〈出发点〉。出发点指动机或立足点，说做事的动机要用「出发点」；切入点指着手做事的地方，不能用来说动机。"}, {"text": "这次旅行的切入点是北京。", "explanation": "这里应该用〈目的地〉。切入点指着手做事的地方，不指要去的地方；说去哪里要用「目的地」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切入点", "is_correct": true, "explanation": "「切入点」指作文或研究中最先着手的角度，与「选一个小的」搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以挑选的写作对象，与「作文要选」的意思不符。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：「选」后面不能接「字数」，作文要选的是内容角度。"}, {"text": "标点", "is_correct": false, "explanation": "语义：「标点」是符号，不是可以挑选的写作角度，句意不通。"}], "explanations": {"切入点": "「切入点」指作文或研究中最先着手的角度，与「选一个小的」搭配自然。", "天气": "语义：「天气」不是可以挑选的写作对象，与「作文要选」的意思不符。", "字数": "搭配：「选」后面不能接「字数」，作文要选的是内容角度。", "标点": "语义：「标点」是符号，不是可以挑选的写作角度，句意不通。"}, "sentence_index": 6, "correct_answer": "切入点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们来这里的切入点是学习。", "explanation": "这里应该用〈目的〉。切入点指开始着手的地方，不是来做某事的目的，所以不能说「切入点是学习」。"}, {"text": "这道题的切入点是三十。", "explanation": "这里应该用〈答案〉。切入点是着手的地方，不是得出的数值或结果。"}, {"text": "这把刀的切入点很锋利。", "explanation": "这里应该用〈刀刃〉。切入点指着手做事的地方，不指刀的锋口；说锋利要用「刀刃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个案子有一只很好的切入点。", "corrected_sentence": "这个案子有一个很好的切入点。", "error_description": "「切入点」的量词应用「个」。「只」用于动物或成对的东西，不能修饰抽象的切入点，应改为「一个切入点」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于找到了切入点的。", "corrected_sentence": "我们终于找到了切入点。", "error_description": "「的」用错：「切入点」是名词，句末不能加「的」，应删去「的」，改为「我们终于找到了切入点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
