INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "果实中心坚硬、包含种子的部分。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "他把香蕉皮、苹果核放进盒子。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃樱桃的时候，别把核吞下去。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个桃子的核很硬，小孩咬不动。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完枣，把核吐在小盘子里。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种葡萄没有核，孩子很爱吃。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏子吃完了，把核留下来，春天可以种在院子里。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芒果的核又大又扁，肉不多。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完苹果，请把核扔进垃圾桶。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃李子时咬到了核，牙很疼。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟把果子吃了，核却掉在地上。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "果核", "label": "复合"}, {"form": "桃核", "label": "复合"}], "register": "中性", "sense_fingerprint": "水果中心坚硬的果核", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核", "is_correct": true, "explanation": "正确答案。核 hé，指果实中心坚硬的部分。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 hé 声母不同（zh 与 h），意思是折断。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，意思是祝贺。"}, {"text": "蛇", "is_correct": false, "explanation": "shé（第二声）与 hé 声母不同（sh 与 h），意思是蛇。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，意思是喝。"}], "explanations": {"核": "正确答案。核 hé，指果实中心坚硬的部分。", "折": "zhé（第二声）与 hé 声母不同（zh 与 h），意思是折断。", "贺": "hè（第四声）与 hé（第二声）声调不同，意思是祝贺。", "蛇": "shé（第二声）与 hé 声母不同（sh 与 h），意思是蛇。", "喝": "hē（第一声）与 hé（第二声）声调不同，意思是喝。"}, "sentence_index": null, "correct_answer": "核"}, "level_3": {"options": [{"text": "核", "is_correct": true, "explanation": "正确。苹果核指果实中间的硬核，可以放进盒子，与前面的香蕉皮并列。"}, {"text": "树", "is_correct": false, "explanation": "语义：苹果树太大，不能放进盒子，与“放进盒子”的语境矛盾。"}, {"text": "汁", "is_correct": false, "explanation": "搭配：“苹果汁”是液体，应装瓶或装杯，不说放进盒子。"}, {"text": "园", "is_correct": false, "explanation": "语义：“苹果园”是一块地，不能装进盒子。"}], "explanations": {"核": "正确。苹果核指果实中间的硬核，可以放进盒子，与前面的香蕉皮并列。", "树": "语义：苹果树太大，不能放进盒子，与“放进盒子”的语境矛盾。", "汁": "搭配：“苹果汁”是液体，应装瓶或装杯，不说放进盒子。", "园": "语义：“苹果园”是一块地，不能装进盒子。"}, "sentence_index": 0, "correct_answer": "核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "西瓜里有很多核，吃的时候要吐出来。", "explanation": "这里应该用〈籽〉。西瓜里的小种子说“籽”，“核”指桃、杏等果实中心的硬核。"}, {"text": "香蕉核很滑，踩上去容易摔倒。", "explanation": "这里应该用〈皮〉。香蕉外面的一层叫皮，香蕉没有硬核。"}, {"text": "草莓的核很绿，洗的时候要摘掉。", "explanation": "这里应该用〈蒂〉。草莓顶端的绿色部分叫蒂，“核”指果实中心的硬核。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11347, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "核", "is_correct": true, "explanation": "正确答案。核 hé，指果实中心坚硬的部分。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hé 韵母不同（u 与 e），意思是胡乱。"}, {"text": "横", "is_correct": false, "explanation": "héng（第二声）与 hé 韵母不同（eng 与 e），意思是横向。"}, {"text": "鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，意思是仙鹤。"}, {"text": "呵", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，意思是呵（哈）气。"}], "explanations": {"核": "正确答案。核 hé，指果实中心坚硬的部分。", "胡": "hú（第二声）与 hé 韵母不同（u 与 e），意思是胡乱。", "横": "héng（第二声）与 hé 韵母不同（eng 与 e），意思是横向。", "鹤": "hè（第四声）与 hé（第二声）声调不同，意思是仙鹤。", "呵": "hē（第一声）与 hé（第二声）声调不同，意思是呵（哈）气。"}, "sentence_index": null, "correct_answer": "核"}, "level_3": {"options": [{"text": "核", "is_correct": true, "explanation": "正确。芒果核又大又扁，与后句“肉不多”的描述相合。"}, {"text": "肉", "is_correct": false, "explanation": "语义：“肉”又大又扁还说“肉不多”，前后自相矛盾。"}, {"text": "汁", "is_correct": false, "explanation": "搭配：“汁”是液体，不能用“又大又扁”来形容。"}, {"text": "味", "is_correct": false, "explanation": "搭配：“味”不能用“又大又扁”来形容。"}], "explanations": {"核": "正确。芒果核又大又扁，与后句“肉不多”的描述相合。", "肉": "语义：“肉”又大又扁还说“肉不多”，前后自相矛盾。", "汁": "搭配：“汁”是液体，不能用“又大又扁”来形容。", "味": "搭配：“味”不能用“又大又扁”来形容。"}, "sentence_index": 6, "correct_answer": "核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玫瑰花的核很香，花瓣却没什么味道。", "explanation": "这里应该用〈花心〉。花的中心叫花心，“核”指水果中间的硬部分，不能用于花。"}, {"text": "鸡蛋的核很黄，我每天都吃。", "explanation": "这里应该用〈蛋黄〉。鸡蛋中间的黄色部分叫蛋黄，“核”指水果中间的硬部分。"}, {"text": "这块鸡腿的核很硬，要用刀剔掉。", "explanation": "这里应该用〈骨头〉。鸡腿中间的硬骨叫骨头，“核”指水果中间的硬部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我捡到一条桃核。", "corrected_sentence": "我捡到一颗桃核。", "error_description": "错误：“条”用于细长的东西，桃核不是细长条，不能用“条”。应说“一颗桃核”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在桌上看到一根芒果核。", "corrected_sentence": "我在桌上看到一颗芒果核。", "error_description": "错误：“芒果核”的量词应用“颗”，“根”用于细长的东西，不能用于果核。应说“一颗芒果核”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
