INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或哺乳动物乳腺分泌的白色液体，是婴儿的主要食物，也可加工成奶制品。", "primary_collocate": null, "pronunciation": "nǎi", "ipa": "nai˨˩˦", "syllable_count": 1, "sentences": [{"text": "婴儿每天要喝好几次奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早饭只喝了一杯热奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶奶放了很久，已经坏了。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用奶做了一块很香的蛋糕。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的奶有很多种，你想买哪一种？", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，睡觉前喝点热奶，容易睡着。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把奶倒进咖啡里，再加一点糖。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫饿了，正在喝妈妈的奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上我去店里买了两盒奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子每天喝奶，个子长得很快。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "瓶", "label": "量词"}, {"form": "盒", "label": "量词"}, {"form": "牛奶", "label": "复合"}, {"form": "奶粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "乳汁，可以喝的白色液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奶", "is_correct": true, "explanation": "奶（nǎi，第三声）：指乳汁，是正确答案。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 nǎi 声母不同（m/n），意思是购买。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是大脑。"}, {"text": "耐", "is_correct": false, "explanation": "nài（第四声）与 nǎi 声调不同，意思是能够经受。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 nǎi 声母不同（h/n），意思是海洋。"}, {"text": "百", "is_correct": false, "explanation": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是一百。"}], "explanations": {"奶": "奶（nǎi，第三声）：指乳汁，是正确答案。", "买": "mǎi（第三声）与 nǎi 声母不同（m/n），意思是购买。", "脑": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是大脑。", "耐": "nài（第四声）与 nǎi 声调不同，意思是能够经受。", "海": "hǎi（第三声）与 nǎi 声母不同（h/n），意思是海洋。", "百": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是一百。"}, "sentence_index": null, "correct_answer": "奶"}, "level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "搭配：“喝”配液体，不能说“喝饭”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能喝，与婴儿每天喝东西的语境冲突。"}, {"text": "奶", "is_correct": true, "explanation": "正确：“奶”是婴儿喝的乳汁，与“喝”和“好几次”搭配。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包是固体食物，不能说“喝面包”。"}], "explanations": {"饭": "搭配：“喝”配液体，不能说“喝饭”。", "书": "语义：书不能喝，与婴儿每天喝东西的语境冲突。", "奶": "正确：“奶”是婴儿喝的乳汁，与“喝”和“好几次”搭配。", "面包": "搭配：面包是固体食物，不能说“喝面包”。"}, "sentence_index": 0, "correct_answer": "奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只奶。", "explanation": "这里量词用错。“只”用于动物或成对的东西，奶是液体，应说“瓶”“盒”或“杯”。"}, {"text": "我早饭吃了一片奶。", "explanation": "这里应该用〈奶酪〉。奶酪是固体，可以切成片，说“一片奶酪”；奶是液体，不能用“片”来计量。"}, {"text": "妈妈给我倒了一块奶。", "explanation": "这里量词用错。“块”用于块状固体，奶是液体，应说“杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奶", "is_correct": true, "explanation": "奶（nǎi，第三声）：指乳汁，是正确答案。"}, {"text": "摆", "is_correct": false, "explanation": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是摆放。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 nǎi 声母不同（g/n），意思是改变。"}, {"text": "彩", "is_correct": false, "explanation": "cǎi（第三声）与 nǎi 声母不同（c/n），意思是彩色。"}, {"text": "恼", "is_correct": false, "explanation": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是生气。"}], "explanations": {"奶": "奶（nǎi，第三声）：指乳汁，是正确答案。", "摆": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是摆放。", "改": "gǎi（第三声）与 nǎi 声母不同（g/n），意思是改变。", "彩": "cǎi（第三声）与 nǎi 声母不同（c/n），意思是彩色。", "恼": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是生气。"}, "sentence_index": null, "correct_answer": "奶"}, "level_3": {"options": [{"text": "酱油", "is_correct": false, "explanation": "语义：咖啡里不会倒入酱油，与“加一点糖”的语境冲突。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋与咖啡、加糖的语境不合，不会倒进咖啡里。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“倒”配液体，饼干是固体，不能说“倒进咖啡里”。"}, {"text": "奶", "is_correct": true, "explanation": "正确：“奶”是可以倒进咖啡里的液体，符合“再加一点糖”的语境。"}], "explanations": {"酱油": "语义：咖啡里不会倒入酱油，与“加一点糖”的语境冲突。", "醋": "语义：醋与咖啡、加糖的语境不合，不会倒进咖啡里。", "饼干": "搭配：“倒”配液体，饼干是固体，不能说“倒进咖啡里”。", "奶": "正确：“奶”是可以倒进咖啡里的液体，符合“再加一点糖”的语境。"}, "sentence_index": 6, "correct_answer": "奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天喝一根奶。", "explanation": "这里量词用错。“根”用于细长的东西，奶是液体，应说“杯”。"}, {"text": "小狗喝了三条奶。", "explanation": "这里量词用错。“条”用于细长或条状的东西，奶是液体，应说“杯”。"}, {"text": "孩子每天喝一个奶，个子长得很快。", "explanation": "这里量词用错。“个”不能修饰液体，奶要用“杯”“瓶”或“盒”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天早上都喝一只奶。", "corrected_sentence": "我每天早上都喝一杯奶。", "error_description": "错误：量词用“只”。“奶”是液体，应使用容器量词“杯”，说“一杯奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈早上给我热了一杯的奶。", "corrected_sentence": "妈妈早上给我热了一杯奶。", "error_description": "错误：数量短语与名词之间多加了“的”。“一杯”直接修饰“奶”，中间不用“的”，应说“一杯奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
