INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手轻轻拨动或翻开物体，通常指快速查看或寻找。", "primary_collocate": null, "pronunciation": "fān yi fān", "ipa": "fan˥˥ i fan˥˥", "syllable_count": 3, "sentences": [{"text": "你再翻一翻书包，钥匙可能在里面。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想翻一翻这本杂志。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你翻一翻桌子上的文件。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在抽屉里翻一翻，找到了照片。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，老师让我们翻一翻课本。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我随便翻一翻小说，心里很放松。", "target_word": "翻一翻", "complexity_tier": "T3", "furigana": "shuì jiào yǐ qián， wǒ suíbiàn fān yi fān xiǎoshuō， xīnli hěn fàngsōng。", "sentence_source": "generated"}, {"text": "你先翻一翻词典，看看这个字的意思。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在衣柜里翻一翻，想找一件外套。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我随手翻一翻报纸，没有什么新闻。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书太多了，我只能快快地翻一翻。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻翻", "label": "重叠"}, {"form": "翻了翻", "label": "体标"}, {"form": "翻", "label": "单字形式"}], "register": "口语", "sense_fingerprint": "随手翻开书页或物品，快速查看或寻找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10fc90c-0e14-449a-94f1-3095b8172350') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻一翻", "is_correct": true, "explanation": "翻一翻：快速翻动查看，正好符合「钥匙可能在包里」的语境。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭指把表面擦干净，不能用来在包里找钥匙。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：浇灌的对象是植物或土地，不能用于书包。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻使东西变冷变硬，与找钥匙毫无关系。"}], "explanations": {"翻一翻": "翻一翻：快速翻动查看，正好符合「钥匙可能在包里」的语境。", "擦拭": "语义：擦拭指把表面擦干净，不能用来在包里找钥匙。", "浇灌": "搭配：浇灌的对象是植物或土地，不能用于书包。", "冷冻": "语义：冷冻使东西变冷变硬，与找钥匙毫无关系。"}, "sentence_index": 0, "correct_answer": "翻一翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抬头翻一翻天空，看看有没有鸟飞过。", "explanation": "这里应该用〈望〉。翻一翻指用手或随手快速查看可以翻动的物品，不能用于抬头远望天空。"}, {"text": "医生让我张开嘴，仔细翻一翻我的牙齿。", "explanation": "这里应该用〈检查〉。翻一翻指随手快速查看可翻动的东西，检查牙齿这种仔细的专业动作要用检查。"}, {"text": "我们晚上一起翻一翻电影。", "explanation": "这里应该用〈观看〉。翻一翻指快速翻动或查看纸张、物品，不能用来说看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻一翻", "is_correct": true, "explanation": "翻一翻：快速查看，正好符合「看看这个字的意思」的语境。"}, {"text": "背诵", "is_correct": false, "explanation": "语义：背诵指记住原文，不能用来先查看词典。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烧烤是用火烤食物，与看字的意思无关。"}, {"text": "咨询", "is_correct": false, "explanation": "配价：咨询的对象是人或机构（向……咨询），「咨询词典」不成立。"}], "explanations": {"翻一翻": "翻一翻：快速查看，正好符合「看看这个字的意思」的语境。", "背诵": "语义：背诵指记住原文，不能用来先查看词典。", "烧烤": "语义：烧烤是用火烤食物，与看字的意思无关。", "咨询": "配价：咨询的对象是人或机构（向……咨询），「咨询词典」不成立。"}, "sentence_index": 6, "correct_answer": "翻一翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在森林里翻一翻迷路的孩子。", "explanation": "这里应该用〈寻找〉。翻一翻指快速翻动或查看物品、书页，不用于找人。"}, {"text": "科学家在显微镜下翻一翻细胞。", "explanation": "这里应该用〈观察〉。翻一翻只是随手快速查看，不用于在显微镜下仔细观察研究对象。"}, {"text": "老师让我们翻一翻音乐。", "explanation": "这里应该用〈听〉。翻一翻指翻动或快速查看，不能用于音乐等声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才翻着一翻书包，没有找到钥匙。", "corrected_sentence": "我刚才翻了一翻书包，没有找到钥匙。", "error_description": "「着」表示动作持续，与「翻一翻」这种短时动作矛盾。应把「着」改为「了」，说「翻了一翻书包」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你翻再一翻这个柜子，说不定能找到钥匙。", "corrected_sentence": "你再翻一翻这个柜子，说不定能找到钥匙。", "error_description": "「再」是修饰动作的状语，要放在动词之前，应说「你再翻一翻」，不能说「翻再一翻」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变白", "is_correct": true, "explanation": "正确：“变白”与“变黑”是一对反义的颜色变化。"}, {"text": "融化", "is_correct": false, "explanation": "不是反义：融化指固体变成液体，与颜色变化无关。"}, {"text": "生长", "is_correct": false, "explanation": "不是反义：生长指生物长大，与颜色变化无关。"}, {"text": "扩大", "is_correct": false, "explanation": "不是反义：扩大指范围或规模变大，与颜色变化无关。"}], "correct_answer": "变白", "explanations": {"变白": "正确：“变白”与“变黑”是一对反义的颜色变化。", "融化": "不是反义：融化指固体变成液体，与颜色变化无关。", "生长": "不是反义：生长指生物长大，与颜色变化无关。", "扩大": "不是反义：扩大指范围或规模变大，与颜色变化无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变白", "is_correct": true, "explanation": "正确：“变白”与“变黑”是一对反义的颜色变化。"}, {"text": "发芽", "is_correct": false, "explanation": "不是反义：发芽指种子或植物长出芽，与颜色变化无关。"}, {"text": "扩展", "is_correct": false, "explanation": "不是反义：扩展指范围向外伸展，与颜色变化无关。"}, {"text": "腐烂", "is_correct": false, "explanation": "不是反义：腐烂指物质变质分解，它常伴随变黑，但与“变黑”不构成反义。"}], "correct_answer": "变白", "explanations": {"变白": "正确：“变白”与“变黑”是一对反义的颜色变化。", "发芽": "不是反义：发芽指种子或植物长出芽，与颜色变化无关。", "扩展": "不是反义：扩展指范围向外伸展，与颜色变化无关。", "腐烂": "不是反义：腐烂指物质变质分解，它常伴随变黑，但与“变黑”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体颜色由其他颜色转变为黑色的过程。", "primary_collocate": null, "pronunciation": "biàn hēi", "ipa": "pjɛn˥˩ xeɪ˥", "syllable_count": 2, "sentences": [{"text": "几周后，东西变黑变小。", "target_word": "变黑", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "过几星期，厨余会变黑，变成土一样的东西。", "target_word": "变黑", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "香蕉放了几天，皮慢慢变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银勺子放久了，表面会变黑。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苹果切开以后放一会儿，果肉就会变黑。", "target_word": "变黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了很多黑芝麻，头发好像变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白衬衫洗得不好，领子慢慢变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头烧过以后，颜色会变黑。", "target_word": "变黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块白布放在烟里，一会儿就变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片放了很多年，边上都变黑了。", "target_word": "变黑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变黑了", "label": "体标（了）"}, {"form": "变黑过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "物体颜色逐渐转为黑色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：biàn hēi，意思是颜色变成黑色。"}, {"text": "变灰", "is_correct": false, "explanation": "huī（第一声）与 hēi（第一声）韵母不同（ui 与 ei），意思是变成灰色。"}, {"text": "变回", "is_correct": false, "explanation": "huí（第二声）与 hēi（第一声）韵母与声调都不同，意思是恢复原样。"}, {"text": "偏黑", "is_correct": false, "explanation": "piān（第一声）与 biàn（第四声）声母与声调都不同，意思是略微发黑。"}], "explanations": {"变黑": "正确：biàn hēi，意思是颜色变成黑色。", "变灰": "huī（第一声）与 hēi（第一声）韵母不同（ui 与 ei），意思是变成灰色。", "变回": "huí（第二声）与 hēi（第一声）韵母与声调都不同，意思是恢复原样。", "偏黑": "piān（第一声）与 biàn（第四声）声母与声调都不同，意思是略微发黑。"}, "sentence_index": null, "correct_answer": "变黑"}, "level_3": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：“变黑”指颜色变成黑色，与后面的“变小”并列，描述东西的变化。"}, {"text": "变大", "is_correct": false, "explanation": "语义：“变大”与后面的“变小”方向相反，同一句中互相矛盾。"}, {"text": "变长", "is_correct": false, "explanation": "语义：“变长”与“变小”描述的是相反的大小变化，句中不能并列。"}, {"text": "消失", "is_correct": false, "explanation": "搭配：“消失”不能与“变小”并列来描述同一物体逐渐变化。"}], "explanations": {"变黑": "正确：“变黑”指颜色变成黑色，与后面的“变小”并列，描述东西的变化。", "变大": "语义：“变大”与后面的“变小”方向相反，同一句中互相矛盾。", "变长": "语义：“变长”与“变小”描述的是相反的大小变化，句中不能并列。", "消失": "搭配：“消失”不能与“变小”并列来描述同一物体逐渐变化。"}, "sentence_index": 0, "correct_answer": "变黑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天黑以后，房间里的光线慢慢变黑了。", "explanation": "这里应该用〈变暗〉。光线、亮度的减弱用“变暗”，“变黑”用于物体表面的颜色，不说光线变黑。"}, {"text": "春天到了，风慢慢变黑了。", "explanation": "这里应该用〈变暖〉。风没有颜色，不能说变黑；“变黑”只用于物体的颜色。"}, {"text": "新换的白窗帘挂了一年以后，颜色变黑了。", "explanation": "这里应该用〈变黄〉。白窗帘用久了会泛黄，“变黑”指颜色变成黑色，不是这种老化的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变黑", "is_correct": true, "explanation": "正确：“变黑”指颜色变成黑色，符合领子因洗得不好而脏、颜色变深的情况。"}, {"text": "变亮", "is_correct": false, "explanation": "语义：句中“洗得不好”说明领子会变脏，不会变亮。"}, {"text": "变干净", "is_correct": false, "explanation": "语义：句中“洗得不好”，领子不可能变干净。"}, {"text": "烧焦", "is_correct": false, "explanation": "语义：句中讲的是洗涤和污渍，没有烧焦的语境。"}], "explanations": {"变黑": "正确：“变黑”指颜色变成黑色，符合领子因洗得不好而脏、颜色变深的情况。", "变亮": "语义：句中“洗得不好”说明领子会变脏，不会变亮。", "变干净": "语义：句中“洗得不好”，领子不可能变干净。", "烧焦": "语义：句中讲的是洗涤和污渍，没有烧焦的语境。"}, "sentence_index": 6, "correct_answer": "变黑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张海报晒了一夏天，颜色变黑了。", "explanation": "这里应该用〈变淡〉。海报长时间暴晒后颜色会褪淡，“变黑”指颜色加深为黑色，与褪色的方向相反。"}, {"text": "他喝了酒，声音慢慢变黑了。", "explanation": "这里应该用〈变哑〉。声音没有颜色，不能说变黑；“变黑”只用于物体的颜色。"}, {"text": "这杯水加了蓝墨水，颜色变黑了。", "explanation": "这里应该用〈变蓝〉。加入蓝墨水后水会变蓝，“变黑”指颜色变成黑色，与墨水的颜色不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的时候，香蕉皮很快就很变黑了。", "corrected_sentence": "夏天的时候，香蕉皮很快就变黑了。", "error_description": "“很”是程度副词，不能直接修饰动作性的“变黑”。应去掉多出的“很”，说“香蕉皮很快就变黑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "白衬衫穿久了，把领子就变黑了。", "corrected_sentence": "白衬衫穿久了，领子就变黑了。", "error_description": "“变黑”是不及物的变化动词，不能用“把”字句，应去掉“把”，说“领子就变黑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
