INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11357, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机肥料是指含有有机物质，经过微生物分解腐熟后，能为植物提供养分的肥料，通常来源于动植物残体或排泄物。", "primary_collocate": null, "pronunciation": "yǒu jī féi liào", "ipa": "iou˨˩ tɕi˥ feɪ˧˥ liɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "农民在菜地里施了很多有机肥料。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥料来自动物粪便和植物残体。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用有机肥料种出来的菜更健康。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋有机肥料要放在干燥的地方。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥料能让土壤变得更肥沃。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物把残体分解后，就成了有机肥料。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果园每年秋天都要给果树加有机肥料。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学肥料见效快，有机肥料对土壤更好。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台的花都是用有机肥料养的。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用有机肥料可以减少对环境的污染。", "target_word": "有机肥料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有機肥料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由动植物残体腐熟而成、为植物提供养分的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机肥料", "is_correct": true, "explanation": "正确。“施”的对象是肥料，有机肥料由动植物残体腐熟而成，符合“菜地里”的语境。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“施”的宾语须是肥料、农药一类，不能说“施电脑”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，与“菜地”和“施”都无关。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是读书用的书，不能施在菜地里。"}], "explanations": {"有机肥料": "正确。“施”的对象是肥料，有机肥料由动植物残体腐熟而成，符合“菜地里”的语境。", "电脑": "搭配：“施”的宾语须是肥料、农药一类，不能说“施电脑”。", "作业": "语义：作业是学生的功课，与“菜地”和“施”都无关。", "课本": "语义：课本是读书用的书，不能施在菜地里。"}, "sentence_index": 0, "correct_answer": "有机肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有机肥料是构成生命的基础。", "explanation": "这里应该用〈有机物〉。有机肥料专指由动植物残体腐熟而成的肥料，不能泛指构成生物体的全部有机物质。"}, {"text": "这批有机肥料是由工厂用化学原料合成的。", "explanation": "这里应该用〈化学肥料〉。有机肥料由动植物残体经微生物分解腐熟而成，不是工厂用化学原料合成的；这类产品是化学肥料。"}, {"text": "有机肥料能改善土壤结构，但不提供养分。", "explanation": "这里应该用〈土壤改良剂〉。有机肥料的作用是给植物提供养分，只改善土壤结构、不供养分的是土壤改良剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机肥料", "is_correct": true, "explanation": "正确。“加”的对象是可以添入果树的肥料，有机肥料与“果园”“果树”的语境相符。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖是食品调料，不能加给果树。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“加”的宾语须是可以添入的物质，不能说“加手机”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本与给果树施肥毫无关系。"}], "explanations": {"有机肥料": "正确。“加”的对象是可以添入果树的肥料，有机肥料与“果园”“果树”的语境相符。", "糖": "语义：糖是食品调料，不能加给果树。", "手机": "搭配：“加”的宾语须是可以添入的物质，不能说“加手机”。", "课本": "语义：课本与给果树施肥毫无关系。"}, "sentence_index": 6, "correct_answer": "有机肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有机肥料是用来盖房子的材料。", "explanation": "这里应该用〈水泥〉。有机肥料是给植物提供养分的肥料，不是建筑材料；盖房子用的是水泥。"}, {"text": "这种有机肥料是用来杀虫的，喷在叶子上就能灭蚜虫。", "explanation": "这里应该用〈农药〉。有机肥料是给植物补充养分的肥料，不能用来杀虫；杀虫用的是农药。"}, {"text": "这袋有机肥料可以直接喝，味道很甜。", "explanation": "这里应该用〈饮料〉。有机肥料是施给植物的肥料，不能饮用；可以直接喝的是饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了三只有机肥料。", "corrected_sentence": "我们买了三袋有机肥料。", "error_description": "量词错误：“只”用于动物，有机肥料是袋装的，应说“三袋有机肥料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落里放着一只有机肥料。", "corrected_sentence": "院子角落里放着一袋有机肥料。", "error_description": "量词错误：“只”用于动物，有机肥料是袋装的，应说“一袋有机肥料”，不能说“一只有机肥料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿去", "is_correct": true, "explanation": "正确。“拿去”与“拿来”方向相反，指把东西从说话人这里带到别处。"}, {"text": "看见", "is_correct": false, "explanation": "不构成反义：“看见”表示视觉感知，与“拿来”的取物方向无关。"}, {"text": "写完", "is_correct": false, "explanation": "不构成反义：“写完”表示动作完成，与“拿来”的方向无关。"}, {"text": "买到", "is_correct": false, "explanation": "不构成反义：“买到”表示获得物品，并不表示方向相反的取物动作。"}], "correct_answer": "拿去", "explanations": {"拿去": "正确。“拿去”与“拿来”方向相反，指把东西从说话人这里带到别处。", "看见": "不构成反义：“看见”表示视觉感知，与“拿来”的取物方向无关。", "写完": "不构成反义：“写完”表示动作完成，与“拿来”的方向无关。", "买到": "不构成反义：“买到”表示获得物品，并不表示方向相反的取物动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拿去", "is_correct": true, "explanation": "正确。“拿去”与“拿来”方向相反，指把东西带到别处。"}, {"text": "遇到", "is_correct": false, "explanation": "不构成反义：“遇到”表示偶然碰见，与取物方向无关。"}, {"text": "写下", "is_correct": false, "explanation": "不构成反义：“写下”表示用笔记录，与“拿来”的方向无关。"}, {"text": "唱完", "is_correct": false, "explanation": "不构成反义：“唱完”表示歌唱结束，与“拿来”的取物动作无关。"}], "correct_answer": "拿去", "explanations": {"拿去": "正确。“拿去”与“拿来”方向相反，指把东西带到别处。", "遇到": "不构成反义：“遇到”表示偶然碰见，与取物方向无关。", "写下": "不构成反义：“写下”表示用笔记录，与“拿来”的方向无关。", "唱完": "不构成反义：“唱完”表示歌唱结束，与“拿来”的取物动作无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将物品从别处取到说话者所在的位置。", "primary_collocate": null, "pronunciation": "ná lái", "ipa": "na˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "请把你的笔记本拿来给我看看。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“把作业拿来。”", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去厨房把刀拿来。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快把药拿来，奶奶不舒服。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从家里拿来了一些水果。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把那把椅子拿来吗？", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿来了一本很旧的书。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把你的照片拿来，让我们看看。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员，请把菜单拿来。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从楼下拿来了今天的报纸。", "target_word": "拿来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿来了", "label": "体标"}, {"form": "拿来过", "label": "体标"}, {"form": "拿來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把东西从别处取到说话人所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3a831af-5367-40ed-841f-74e0e251ef1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿来", "is_correct": true, "explanation": "正确。“请把笔记本……给我看看”要求对方把东西拿到说话人这里，与“拿来”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：笔记本不是食物，“吃”的对象须能吃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、身体等，不能说“洗笔记本给我看看”。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”后须带处所宾语，不能说“放给我看看”。"}], "explanations": {"拿来": "正确。“请把笔记本……给我看看”要求对方把东西拿到说话人这里，与“拿来”相符。", "吃": "语义：笔记本不是食物，“吃”的对象须能吃。", "洗": "搭配：“洗”一般搭配衣物、身体等，不能说“洗笔记本给我看看”。", "放": "配价：“放”后须带处所宾语，不能说“放给我看看”。"}, "sentence_index": 0, "correct_answer": "拿来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿来了一个好消息。", "explanation": "这里应该用〈带来〉。拿来指把具体物品取到说话人这里，不能用于消息等抽象事物。"}, {"text": "我在家里，把这本书拿来了图书馆。", "explanation": "这里应该用〈拿去〉。图书馆不在说话人这里，应说“拿去”，不能说“拿来”。"}, {"text": "我在家里，把礼物拿来了朋友家。", "explanation": "这里应该用〈送去〉。说话人在家，礼物要送到朋友家，东西应朝离开说话人的方向移动，应说“送去”，“拿来”指朝说话人方向取物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿来", "is_correct": true, "explanation": "正确。“弟弟……了一本很旧的书”表示弟弟把书取来，与“拿来”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：书不能吃，“吃”的对象须是食物。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“书”作宾语，不能说“唱了一本书”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：书不能煮，与“很旧的书”的语境冲突。"}], "explanations": {"拿来": "正确。“弟弟……了一本很旧的书”表示弟弟把书取来，与“拿来”相符。", "吃": "语义：书不能吃，“吃”的对象须是食物。", "唱": "搭配：“唱”不能带“书”作宾语，不能说“唱了一本书”。", "煮": "语义：书不能煮，与“很旧的书”的语境冲突。"}, "sentence_index": 6, "correct_answer": "拿来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在上海，把包裹拿来了北京。", "explanation": "这里应该用〈寄去〉。包裹要送到北京，说话人不在北京，应说“寄去”，不能用“拿来”。"}, {"text": "我在家里拿来一些水果，去看望老师。", "explanation": "这里应该用〈带去〉。说话人要前往老师处，东西应随人离开，应说“带去”。"}, {"text": "工人把沙发拿来了远方的新家。", "explanation": "这里应该用〈搬去〉。沙发要搬到远方的新家，说话人不在那里，应说“搬去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你把消息拿来，我开门。", "corrected_sentence": "你把钥匙拿来，我开门。", "error_description": "语义错误：“拿来”指把具体物品取到说话人这里，“消息”是抽象事物，不能用“拿来”取。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐拿来了一个消息。", "corrected_sentence": "姐姐拿来了一个包裹。", "error_description": "语义错误：“拿来”指把具体物品取到说话人这里，“消息”是抽象事物，不能用“拿来”取。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb2e2b7a-01b3-47e1-baf0-11629f8173b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
