INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叶子是植物进行光合作用的主要器官，通常呈扁平状。", "primary_collocate": null, "pronunciation": "yè zi", "ipa": "jɛ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "菜叶子、果皮都可以放。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "把香蕉皮、菜叶子放进箱子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "植物用叶子吸收阳光。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子是绿色的，因为里面有叶绿素。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的叶子又大又宽。", "target_word": "叶子", "complexity_tier": "T3", "furigana": "zhè kē shù de yè zi yòu dà yòu kuān", "sentence_source": "generated"}, {"text": "叶子在阳光下制造养分。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子太少，这棵植物长不大。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用湿布擦花的叶子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌的叶子变成了刺。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子上有一些小虫子。", "target_word": "叶子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "叶片", "label": "复合词"}, {"form": "葉子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植物的光合作用器官，扁平的叶片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：植物进行光合作用的扁平器官，即听到的词。"}, {"text": "刻子", "is_correct": false, "explanation": "kè 与 yè 声母不同（k 与 y），意思是麻将中三张相同的牌。"}, {"text": "椰子", "is_correct": false, "explanation": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。"}, {"text": "个子", "is_correct": false, "explanation": "gè 与 yè 声母不同（g 与 y），意思是身材高矮。"}, {"text": "册子", "is_correct": false, "explanation": "cè 与 yè 声母不同（c 与 y），意思是小本子。"}, {"text": "义子", "is_correct": false, "explanation": "yì 与 yè 韵母不同（i 与 e），意思是收养的儿子。"}], "explanations": {"叶子": "叶子：植物进行光合作用的扁平器官，即听到的词。", "刻子": "kè 与 yè 声母不同（k 与 y），意思是麻将中三张相同的牌。", "椰子": "yē（第一声）与 yè（第四声）声调不同，意思是椰子。", "个子": "gè 与 yè 声母不同（g 与 y），意思是身材高矮。", "册子": "cè 与 yè 声母不同（c 与 y），意思是小本子。", "义子": "yì 与 yè 韵母不同（i 与 e），意思是收养的儿子。"}, "sentence_index": null, "correct_answer": "叶子"}, "level_3": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：菜叶是可以放进去的废弃物，与果皮并列，符合语境。"}, {"text": "园子", "is_correct": false, "explanation": "配价：“菜园子”指种菜的地方，是场所，不能与果皮并列作被放的东西。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“菜花朵”不成词，“菜”之后不接“花朵”，也不是可以丢弃的废弃物。"}, {"text": "纸巾", "is_correct": false, "explanation": "语义：“菜纸巾”不是可以放进去的废弃物，纸巾是擦拭用品。"}], "explanations": {"叶子": "叶子：菜叶是可以放进去的废弃物，与果皮并列，符合语境。", "园子": "配价：“菜园子”指种菜的地方，是场所，不能与果皮并列作被放的东西。", "花朵": "搭配：“菜花朵”不成词，“菜”之后不接“花朵”，也不是可以丢弃的废弃物。", "纸巾": "语义：“菜纸巾”不是可以放进去的废弃物，纸巾是擦拭用品。"}, "sentence_index": 0, "correct_answer": "叶子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他翻到书的第三叶子。", "explanation": "这里应该用〈页〉。书的一面要用页，叶子只指植物的器官。"}, {"text": "我在路上捡到一只叶子。", "explanation": "这里应该用〈片〉。叶子是扁平的，不能用〈只〉来数，〈只〉多用于动物等。"}, {"text": "院子里的树下落着一条叶子。", "explanation": "这里应该用〈片〉。〈条〉用于细长的东西，叶子不能这样数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11368, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：植物进行光合作用的扁平器官，即听到的词。"}, {"text": "乐子", "is_correct": false, "explanation": "lè 与 yè 声母不同（l 与 y），意思是玩笑、乐趣。"}, {"text": "色子", "is_correct": false, "explanation": "sè 与 yè 声母不同（s 与 y），口语中指骰子。"}, {"text": "月子", "is_correct": false, "explanation": "yuè 比 yè 多一个介音 u，意思是坐月子的时期。"}], "explanations": {"叶子": "叶子：植物进行光合作用的扁平器官，即听到的词。", "乐子": "lè 与 yè 声母不同（l 与 y），意思是玩笑、乐趣。", "色子": "sè 与 yè 声母不同（s 与 y），口语中指骰子。", "月子": "yuè 比 yè 多一个介音 u，意思是坐月子的时期。"}, "sentence_index": null, "correct_answer": "叶子"}, "level_3": {"options": [{"text": "叶子", "is_correct": true, "explanation": "叶子：太少的叶子会影响光合作用，使植物长不大，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，与植物生长无关，说“太少”不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，不是植物生长的部件，说“太少”不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园太少”语法上可以成立，但花园与“这棵植物长不大”没有因果关系，句意不通。"}], "explanations": {"叶子": "叶子：太少的叶子会影响光合作用，使植物长不大，符合语境。", "桌子": "语义：桌子是家具，与植物生长无关，说“太少”不通。", "大海": "语义：大海是水域，不是植物生长的部件，说“太少”不通。", "花园": "语义：“花园太少”语法上可以成立，但花园与“这棵植物长不大”没有因果关系，句意不通。"}, "sentence_index": 6, "correct_answer": "叶子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一棵叶子。", "explanation": "这里应该用〈片〉。〈棵〉用于树、草等整株植物，叶子不能这样数。"}, {"text": "他手里拿着一朵叶子。", "explanation": "这里应该用〈片〉。〈朵〉用于花、云等，叶子不能这样数。"}, {"text": "他在桌上放了一颗叶子。", "explanation": "这里应该用〈片〉。〈颗〉用于粒状、圆形的小东西，叶子不能这样数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风把一只叶子吹到了窗前。", "corrected_sentence": "风把一片叶子吹到了窗前。", "error_description": "错误：“一只叶子”。正确：“一片叶子”。叶子是扁平的薄片，量词用“片”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片叶子了黄。", "corrected_sentence": "这片叶子黄了。", "error_description": "错误：“叶子了黄”。正确：“叶子黄了”。“了”应放在表示变化结果的“黄”之后，表示变化已完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
