INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "箱子，指用木头、塑料、金属等材料制成的方形或矩形收纳容器，通常有盖子。", "primary_collocate": null, "pronunciation": "xiāng zi", "ipa": "ɕjɑŋ˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "在箱子的底部和侧面扎一些小孔。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "把香蕉皮、菜叶子放进箱子。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "箱子要放在热的地方。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小箱子放在阳台就可以。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我的箱子很重，拿不动。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书放进了大箱子里。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸箱子可以装很多水果。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子的盖子打开了。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我带了一个小箱子。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在箱子里放了几件旧衣服。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "纸箱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "木、塑料、金属制的带盖方形收纳容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11369, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：带盖的方形收纳容器，即听到的词。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。"}, {"text": "仙子", "is_correct": false, "explanation": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。"}, {"text": "橡子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}], "explanations": {"箱子": "箱子：带盖的方形收纳容器，即听到的词。", "巷子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。", "仙子": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。", "橡子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}, "sentence_index": null, "correct_answer": "箱子"}, "level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：有底部和侧面的带盖容器，在底部和侧面扎小孔符合语境。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭不是有底部和侧面的容器，在它的底部和侧面扎小孔与句意不符。"}, {"text": "房间", "is_correct": false, "explanation": "配价：扎孔的对象应是物体，房间是处所，不能被扎孔。"}, {"text": "信纸", "is_correct": false, "explanation": "语义：信纸是薄纸，没有底部和侧面，扎小孔与语境不符。"}], "explanations": {"箱子": "箱子：有底部和侧面的带盖容器，在底部和侧面扎小孔符合语境。", "米饭": "语义：米饭不是有底部和侧面的容器，在它的底部和侧面扎小孔与句意不符。", "房间": "配价：扎孔的对象应是物体，房间是处所，不能被扎孔。", "信纸": "语义：信纸是薄纸，没有底部和侧面，扎小孔与语境不符。"}, "sentence_index": 0, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他搬来一条箱子，放在门口。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，箱子不能这样数。"}, {"text": "阳台上放着一朵箱子。", "explanation": "这里应该用〈个〉。〈朵〉用于花、云等，箱子不能这样数。"}, {"text": "卧室里有一棵箱子，很重。", "explanation": "这里应该用〈个〉。〈棵〉用于树、草等植物整体，箱子不能这样数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：带盖的容器，纸箱子可以装很多水果，符合语境。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“纸房子”是建筑或玩具，是场所，不能用来装水果。"}, {"text": "扇子", "is_correct": false, "explanation": "语义：纸扇子是用来扇风的，不是装东西的容器。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：纸帽子是戴在头上的，不用来装水果。"}], "explanations": {"箱子": "箱子：带盖的容器，纸箱子可以装很多水果，符合语境。", "房子": "配价：“纸房子”是建筑或玩具，是场所，不能用来装水果。", "扇子": "语义：纸扇子是用来扇风的，不是装东西的容器。", "帽子": "语义：纸帽子是戴在头上的，不用来装水果。"}, "sentence_index": 6, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一根箱子。", "explanation": "这里应该用〈个〉。〈根〉用于细长的东西，箱子不能这样数。"}, {"text": "桌上摆着一颗箱子。", "explanation": "这里应该用〈个〉。〈颗〉用于粒状、圆形的小东西，箱子不能这样数。"}, {"text": "走廊里有一片箱子。", "explanation": "这里应该用〈个〉。〈片〉用于扁平的薄片，箱子不是这样的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一条箱子搬到了阳台。", "corrected_sentence": "我把一个箱子搬到了阳台。", "error_description": "错误：“一条箱子”。正确：“一个箱子”。箱子是块状容器，量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把箱子打了开。", "corrected_sentence": "妈妈把箱子打开了。", "error_description": "错误：“打了开”。正确：“打开了”。“打开”是动补结构，不能拆开，“了”应放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
