INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泛指具体的物品、物件。", "primary_collocate": null, "pronunciation": "dōng xi", "ipa": "tʊŋ˥˥ ɕi", "syllable_count": 2, "sentences": [{"text": "它们是有机的东西，会慢慢变少。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "过几周，这些东西会变成黑色的土。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "桌子上有很多东西，你先收拾一下。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天去超市买了很多东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里的东西都坏了，快扔掉吧。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，别忘了带上要用的东西。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个东西叫什么名字，我从来没见过。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子里装着什么东西，你猜猜看。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧东西没用了，我们拿去送给别人吧。", "target_word": "东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子什么东西都想摸一摸。", "target_word": "东西", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "样", "label": "量词"}, {"form": "東西", "label": "繁体"}], "register": "通用", "sense_fingerprint": "泛指物品、物件，口语常用，可用量词“件”“样”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确。“东西”泛指有机的事物，与“会慢慢变少”相符。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属属于无机物，与“有机的”相矛盾。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：矿物是无机物，不能说“有机的矿物”。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“有机的”修饰化学物质或生物，不修饰“机器”。"}], "explanations": {"东西": "正确。“东西”泛指有机的事物，与“会慢慢变少”相符。", "金属": "语义：金属属于无机物，与“有机的”相矛盾。", "矿物": "语义：矿物是无机物，不能说“有机的矿物”。", "机器": "搭配：“有机的”修饰化学物质或生物，不修饰“机器”。"}, "sentence_index": 0, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只东西。", "explanation": "这里应该用〈件〉。“东西”不能用“只”计量，“只”多用于动物或成对器物中的一个。"}, {"text": "桌上放着一朵东西。", "explanation": "这里应该用〈件〉。〈朵〉用于花、云等，“东西”不能用“朵”计量。"}, {"text": "我买了一本东西。", "explanation": "这里应该用〈件〉。〈本〉用于书册，“东西”不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东西", "is_correct": true, "explanation": "正确。“东西”指说不出名字的具体物件，与“叫什么名字”“见过”相符。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的心理状态，没有具体形态，不能说“从来没见过”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以“叫什么名字”的物件。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“这个时间”指当下的时刻，不说“叫什么名字”。"}], "explanations": {"东西": "正确。“东西”指说不出名字的具体物件，与“叫什么名字”“见过”相符。", "感情": "语义：感情是抽象的心理状态，没有具体形态，不能说“从来没见过”。", "天气": "语义：天气是自然现象，不是可以“叫什么名字”的物件。", "时间": "搭配：“这个时间”指当下的时刻，不说“叫什么名字”。"}, "sentence_index": 6, "correct_answer": "东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些体育东西很贵。", "explanation": "这里应该用〈器材〉。“体育器材”是固定说法，“东西”不能修饰“体育”。"}, {"text": "救灾东西已经运到了。", "explanation": "这里应该用〈物资〉。救灾用的是“物资”，“东西”不能这样修饰“救灾”。"}, {"text": "这家店卖卫生东西。", "explanation": "这里应该用〈用品〉。“卫生用品”是固定说法，不说“卫生东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱子里有很多东西们。", "corrected_sentence": "箱子里有很多东西。", "error_description": "词缀错误：“东西”后不能加“们”，“们”只用于人。正确形式是“东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我东西，请还给我。", "corrected_sentence": "这是我的东西，请还给我。", "error_description": "“我的东西”中的“的”不能省，“我”后接名词要用“的”连接，应说“我的东西”，不能说“我东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
