INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地面上的沙、泥等混合物，是植物生长的基础。", "primary_collocate": null, "pronunciation": "tǔ", "ipa": "tʰu˨˩", "syllable_count": 1, "sentences": [{"text": "过几周，这些东西会变成黑色的土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "花盆里的土很干，要浇水了。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里挖了一些土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花以前，先把土放进花盆。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩的鞋上都是土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种土很软，适合种菜。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，土变湿了。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把种子放好，再盖上土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给这盆花加一点土。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，地上的土都飞起来了。", "target_word": "土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆", "label": "量词"}, {"form": "一袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "地面上可以让植物生长的泥土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指地面上的泥沙混合物，是正确答案。"}, {"text": "苦", "is_correct": false, "explanation": "k 与 t 声母不同，苦 kǔ 意思是味道苦，与所听到的 tǔ 不同。"}, {"text": "堵", "is_correct": false, "explanation": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然、突出。"}], "explanations": {"土": "土（tǔ）指地面上的泥沙混合物，是正确答案。", "苦": "k 与 t 声母不同，苦 kǔ 意思是味道苦，与所听到的 tǔ 不同。", "堵": "d 与 t 声母不同，堵 dǔ 意思是堵塞、堵车。", "图": "tú（第二声）与 tǔ（第三声）声调不同，图 tú 意思是图画、地图。", "兔": "tù（第四声）与 tǔ（第三声）声调不同，兔 tù 意思是兔子。", "突": "tū（第一声）与 tǔ（第三声）声调不同，突 tū 意思是突然、突出。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：土指泥土，“变成黑色的土”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“黑色的”用于有颜色的东西，不能修饰声音。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间没有颜色，不会变成黑色的东西。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“黑色的”只能修饰有形的东西，不能说歌曲是黑色的。"}], "explanations": {"土": "正确：土指泥土，“变成黑色的土”符合句意。", "声音": "搭配：“黑色的”用于有颜色的东西，不能修饰声音。", "时间": "语义：时间没有颜色，不会变成黑色的东西。", "歌曲": "搭配：“黑色的”只能修饰有形的东西，不能说歌曲是黑色的。"}, "sentence_index": 0, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在汤里加了一点土。", "explanation": "这里应该用〈盐〉。盐是调味品，土不能用来调味。"}, {"text": "炉子里的土每天都要清理。", "explanation": "这里应该用〈灰〉。炉子里清出来的是烧过的灰烬，不是泥土。"}, {"text": "烧锅炉要先买好土。", "explanation": "这里应该用〈煤〉。锅炉要烧能燃烧的煤，土不能用来燃烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11374, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "土", "is_correct": true, "explanation": "土（tǔ）指地面上的泥沙混合物，是正确答案。"}, {"text": "补", "is_correct": false, "explanation": "b 与 t 声母不同，补 bǔ 意思是补充、修补。"}, {"text": "赌", "is_correct": false, "explanation": "d 与 t 声母不同，赌 dǔ 意思是打赌、赌博。"}, {"text": "途", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路、途中。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是头上没有头发。"}], "explanations": {"土": "土（tǔ）指地面上的泥沙混合物，是正确答案。", "补": "b 与 t 声母不同，补 bǔ 意思是补充、修补。", "赌": "d 与 t 声母不同，赌 dǔ 意思是打赌、赌博。", "途": "tú（第二声）与 tǔ（第三声）声调不同，途 tú 意思是道路、途中。", "秃": "tū（第一声）与 tǔ（第三声）声调不同，秃 tū 意思是头上没有头发。"}, "sentence_index": null, "correct_answer": "土"}, "level_3": {"options": [{"text": "土", "is_correct": true, "explanation": "正确：下雨后地面上的土会变湿，符合句意。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的，不能被雨淋湿。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“湿”说的是物体沾了水，不能说名字变湿了。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的心理，不会被雨淋湿变湿。"}], "explanations": {"土": "正确：下雨后地面上的土会变湿，符合句意。", "道理": "语义：道理是抽象的，不能被雨淋湿。", "名字": "搭配：“湿”说的是物体沾了水，不能说名字变湿了。", "感情": "语义：感情是抽象的心理，不会被雨淋湿变湿。"}, "sentence_index": 6, "correct_answer": "土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇窗户是用土做的，很透亮。", "explanation": "这里应该用〈玻璃〉。窗户要透光，土不透明，不能用来做窗户。"}, {"text": "这把椅子是用土做的，很结实。", "explanation": "这里应该用〈木头〉。椅子通常用木头做，土不能用来做椅子。"}, {"text": "夏天很热，我把一块土放进杯子里降温。", "explanation": "这里应该用〈冰〉。降温要用冰块，土没有降温的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人从车上卸下了两只土。", "corrected_sentence": "工人从车上卸下了两袋土。", "error_description": "量词错误：土是散状的，应说“两袋土”，不能说“两只土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把土翻了松，准备播种。", "corrected_sentence": "农民把土翻松了，准备播种。", "error_description": "补语错误：结果补语“松”要紧跟动词，应说“翻松了”，不说“翻了松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
