INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用于存放物品的小型容器，通常由木、塑料或金属制成。", "primary_collocate": null, "pronunciation": "xiǎo xiāng zi", "ipa": "ɕiɑʊ˨˩ ɕiɑŋ˥ tsɿ", "syllable_count": 3, "sentences": [{"text": "小箱子放在阳台就可以。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把旧书都放进了小箱子里。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小箱子是木头做的，很轻。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我一个红色的小箱子，用来放玩具。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开小箱子，拿出一支笔。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小箱子太小，装不下这么多衣服。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的小箱子里有很多老照片。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把小箱子搬到桌子上来。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的小箱子里装着三双袜子。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个塑料小箱子可以装水果。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小箱子", "label": "量词"}, {"form": "一只小箱子", "label": "量词"}], "register": "口语", "sense_fingerprint": "存放物品的小型容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0818d17e-d628-4110-8069-5cbf9f1c9288') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是可以放在阳台的小型容器，放在阳台符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不能被“放在阳台”，句子不通。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：“放在阳台”针对物品，不能用来说一个小孩子。"}, {"text": "小路", "is_correct": false, "explanation": "搭配：“放在”后接可搬动的物品，“小路”是地面道路，不能放在阳台。"}], "explanations": {"小箱子": "正确：小箱子是可以放在阳台的小型容器，放在阳台符合句意。", "大象": "语义：大象是动物，不能被“放在阳台”，句子不通。", "小孩子": "语义：“放在阳台”针对物品，不能用来说一个小孩子。", "小路": "搭配：“放在”后接可搬动的物品，“小路”是地面道路，不能放在阳台。"}, "sentence_index": 0, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开着一个小箱子去上班，一路上很顺利。", "explanation": "这里应该用〈汽车〉。汽车是交通工具，可以驾驶；小箱子是装东西的容器，开不了车。"}, {"text": "他渴了，拿起小箱子喝了一大口。", "explanation": "这里应该用〈水〉。水可以喝；小箱子是装东西的容器，不能拿来喝。"}, {"text": "他把小箱子放到耳边，对着它大声说话。", "explanation": "这里应该用〈手机〉。手机能打电话；小箱子是装东西的容器，没有通话功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是装东西的容器，奶奶的小箱子里可以装老照片。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用于冷藏食物，不会用来装老照片。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶用来插花，不是存放照片的容器，句子不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是存放照片的容器，句子不通。"}], "explanations": {"小箱子": "正确：小箱子是装东西的容器，奶奶的小箱子里可以装老照片。", "冰箱": "语义：冰箱用于冷藏食物，不会用来装老照片。", "花瓶": "语义：花瓶用来插花，不是存放照片的容器，句子不通。", "面包": "语义：面包是食物，不是存放照片的容器，句子不通。"}, "sentence_index": 6, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把小箱子放在炉子上，用来煮面条。", "explanation": "这里应该用〈锅〉。锅能加热烹煮；小箱子是装东西的容器，不能用来煮东西。"}, {"text": "他把小箱子扣在头上，戴着它走出了家门。", "explanation": "这里应该用〈帽子〉。帽子戴在头上起遮挡作用；小箱子是容器，不能当帽子戴。"}, {"text": "他把小箱子裹在身上御寒，冷得直发抖。", "explanation": "这里应该用〈大衣〉。大衣穿在身上保暖；小箱子是容器，不能当衣服穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一根小箱子给妹妹。", "corrected_sentence": "我买了一个小箱子给妹妹。", "error_description": "量词错误：箱子应说“一个”或“一只”，不能说“一根”；“根”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有两小箱子，都是木头做的。", "corrected_sentence": "我家有两个小箱子，都是木头做的。", "error_description": "量词缺失：数词后面要加量词，应说“两个小箱子”，不能直接说“两小箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
