INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11386, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不困难，容易做到，也指容易看出或想到。", "primary_collocate": null, "pronunciation": "bù nán", "ipa": "pu˥˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "这道数学题不难，我五分钟就做完了。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会做中国菜不难，你也可以试试。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了他的笔记，不难发现他很认真。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要每天听一点，学好汉语并不难。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不难回答，大家都知道。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很慢，所以听懂不难。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁去那儿不难，只要换一次车。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不难看出，这家店的东西很便宜。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不难走，沿着河边一直走就行。", "target_word": "不难", "complexity_tier": "T3", "furigana": "bù nán", "sentence_source": "generated"}, {"text": "做饭不难，难的是洗碗。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不难：事情不困难，容易做到或容易看出、想到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很贵", "is_correct": false, "explanation": "语义：“很贵”说价格高，数学题不能用价格来形容，句意不通。"}, {"text": "很远", "is_correct": false, "explanation": "语义：“很远”说距离，不用来形容数学题，句意不通。"}, {"text": "不难", "is_correct": true, "explanation": "“不难”表示事情不困难、容易做到，与“我五分钟就做完了”相符。"}, {"text": "很亮", "is_correct": false, "explanation": "语义：“很亮”说光线强，不用来形容数学题，句意不通。"}], "explanations": {"很贵": "语义：“很贵”说价格高，数学题不能用价格来形容，句意不通。", "很远": "语义：“很远”说距离，不用来形容数学题，句意不通。", "不难": "“不难”表示事情不困难、容易做到，与“我五分钟就做完了”相符。", "很亮": "语义：“很亮”说光线强，不用来形容数学题，句意不通。"}, "sentence_index": 0, "correct_answer": "不难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次胜利来之不难，我们准备了很久。", "explanation": "这里应该用〈不易〉。“来之不易”是固定说法，指得来很艰难；“不难”只说事情不困难，不能放在这个词里。"}, {"text": "冬天一冷，他的身体就不难。", "explanation": "这里应该用〈虚弱〉。“虚弱”形容身体状况；“不难”只说事情不困难，不能用来形容身体。"}, {"text": "这张桌子的颜色不难，大家都很喜欢。", "explanation": "这里应该用〈好看〉。“好看”形容颜色；“不难”只说事情不困难，不能形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很丢人", "is_correct": false, "explanation": "语义：“很丢人”说令人难堪，不用来形容去某处的路线难易，句意不通。"}, {"text": "很高", "is_correct": false, "explanation": "搭配：路程或行程不说“高”，要说“远”。"}, {"text": "不难", "is_correct": true, "explanation": "“不难”表示路不难走、去那儿容易，与“只要换一次车”相符。"}, {"text": "很香", "is_correct": false, "explanation": "语义：“很香”说气味好，与路线难易无关，句意不通。"}], "explanations": {"很丢人": "语义：“很丢人”说令人难堪，不用来形容去某处的路线难易，句意不通。", "很高": "搭配：路程或行程不说“高”，要说“远”。", "不难": "“不难”表示路不难走、去那儿容易，与“只要换一次车”相符。", "很香": "语义：“很香”说气味好，与路线难易无关，句意不通。"}, "sentence_index": 6, "correct_answer": "不难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题我把它不难了，考试时很快就交了。", "explanation": "这里应该用〈做完〉。“不难”是形容词性短语，不能作动词，不能说“把它不难了”。"}, {"text": "他把这份工作不难好了，大家都说很轻松。", "explanation": "这里应该用〈做好〉。“不难”是形容词性短语，不能作动词，不能说“把这份工作不难好”。"}, {"text": "我把这道菜不难会了，一学就会做。", "explanation": "这里应该用〈学会〉。“不难”是形容词性短语，不能作动词，不能说“把这道菜不难会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学会游泳不不难，只要每周练习两次。", "corrected_sentence": "学会游泳不难，只要每周练习两次。", "error_description": "否定词重复。“不难”本身已含否定，前面不能再加“不”，应说“学会游泳不难”；“不不难”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道菜我做得不不难，味道也不错。", "corrected_sentence": "这道菜我做得不难，味道也不错。", "error_description": "否定词重复。“不难”本身已含否定，前面不能再加“不”，应说“做得不难”；“做得不不难”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
