INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11388, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物有趣、能带来快乐或乐趣。", "primary_collocate": null, "pronunciation": "hǎo wán", "ipa": "xɑʊ˨˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "这个游戏很好玩，我们再玩一次吧。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的小猴子真好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不太好玩，我不想看。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的公园比平时更好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我的玩具特别好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这个新玩具好玩吗？", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友说，坐船很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方又干净又好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学做饭一点也不难，还很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的手机游戏一点也不好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好玩儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "事物有趣、带来乐趣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0818d17e-d628-4110-8069-5cbf9f1c9288') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指事物有趣、能带来乐趣，是目标词。"}, {"text": "考完", "is_correct": false, "explanation": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。"}, {"text": "搞完", "is_correct": false, "explanation": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。"}, {"text": "炒完", "is_correct": false, "explanation": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指事物有趣、能带来乐趣，是目标词。", "考完": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。", "搞完": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。", "炒完": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”指游戏有趣，与“我们再玩一次吧”相符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：说游戏无聊，就不会再玩一次，与后半句矛盾。"}, {"text": "难看", "is_correct": false, "explanation": "体貌：“难看”形容外表，不用来说游戏的乐趣。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：觉得痛苦就不会想再玩一次，与后半句矛盾。"}], "explanations": {"好玩": "正确：“好玩”指游戏有趣，与“我们再玩一次吧”相符。", "无聊": "语义：说游戏无聊，就不会再玩一次，与后半句矛盾。", "难看": "体貌：“难看”形容外表，不用来说游戏的乐趣。", "痛苦": "语义：觉得痛苦就不会想再玩一次，与后半句矛盾。"}, "sentence_index": 0, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事很好玩，我们必须马上处理。", "explanation": "这里应该用〈重要〉。重要说事情关系大；好玩说有趣，不能用来形容需要马上处理的事。"}, {"text": "这碗面很好玩，我吃了两碗。", "explanation": "这里应该用〈好吃〉。好吃形容味道，好玩不用来形容食物的味道。"}, {"text": "他的病很好玩，医生说要住院一个月。", "explanation": "这里应该用〈严重〉。严重说病情重；好玩说有趣，不能用来形容病情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指有趣、带来乐趣，是目标词。"}, {"text": "跑完", "is_correct": false, "explanation": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。"}, {"text": "倒完", "is_correct": false, "explanation": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。"}, {"text": "扫完", "is_correct": false, "explanation": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指有趣、带来乐趣，是目标词。", "跑完": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。", "倒完": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。", "扫完": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”形容坐船的体验有趣，与句意相符。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容味道，不用来说坐船。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外貌，不用来说坐船的感受。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容态度或气氛，不用来说坐船的感觉。"}], "explanations": {"好玩": "正确：“好玩”形容坐船的体验有趣，与句意相符。", "好吃": "语义：“好吃”形容味道，不用来说坐船。", "明亮": "体貌：“明亮”形容光线或外貌，不用来说坐船的感受。", "严肃": "语义：“严肃”形容态度或气氛，不用来说坐船的感觉。"}, "sentence_index": 6, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件大衣很好玩，要花五千块钱。", "explanation": "这里应该用〈贵〉。贵说价格高；好玩说有趣，不能用来形容价钱。"}, {"text": "这个超市离家很好玩。", "explanation": "这里应该用〈方便〉。方便说距离近、做事省力，好玩不用来说距离。"}, {"text": "这间屋子很好玩，地上全是灰。", "explanation": "这里应该用〈脏〉。脏说卫生状况差；好玩说有趣，不能用来形容屋子的卫生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
