INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次郊游一点也好玩。", "corrected_sentence": "这次郊游一点也不好玩。", "error_description": "否定缺失：“一点也”后要用“不”，应说“一点也不好玩”，不能说“一点也好玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
