INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11390, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有实际使用价值的。", "primary_collocate": null, "pronunciation": "shí yòng", "ipa": "ʂɻ̩˧˥ yʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在家做堆肥是一种很实用的自己动手项目，既能减少废弃物，又能为园艺提供好的肥料。", "target_word": "实用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这把伞很小，很实用。", "target_word": "实用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想买一个实用的礼物送给妈妈。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书教的方法很实用，我天天都用。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的功能不多，但是非常实用。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说学外语要学实用的句子。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子又大又实用，我很满意。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我的背包很好看，也很实用。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上学的知识很实用，工作中马上就能用到。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行前，我先学了一些实用的汉语。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实用性", "label": "复合"}, {"form": "实用主义", "label": "复合"}, {"form": "不实用", "label": "否定"}], "register": "中性", "sense_fingerprint": "有实际使用价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有实际使用价值的。"}, {"text": "使用", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shí（第二声）只差声调，意思是运用、用，不是有实际价值。"}, {"text": "试用", "is_correct": false, "explanation": "声调不同：shì（第四声）与 shí（第二声）只差声调，意思是先试着用，不是有实际价值。"}, {"text": "施用", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shí（第二声）只差声调，意思是施加使用，如施肥。"}], "explanations": {"实用": "实用：有实际使用价值的。", "使用": "声调不同：shǐ（第三声）与 shí（第二声）只差声调，意思是运用、用，不是有实际价值。", "试用": "声调不同：shì（第四声）与 shí（第二声）只差声调，意思是先试着用，不是有实际价值。", "施用": "声调不同：shī（第一声）与 shí（第二声）只差声调，意思是施加使用，如施肥。"}, "sentence_index": null, "correct_answer": "实用"}, "level_3": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有实际使用价值，与句中“减少废弃物”“提供肥料”的功能相符。"}, {"text": "华丽", "is_correct": false, "explanation": "体貌：“华丽”形容外观繁复漂亮，堆肥项目看的是功能，不看外观。"}, {"text": "深奥", "is_correct": false, "explanation": "语义：“深奥”指内容难懂，与“自己动手”的简单项目相矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，与“自己动手”省钱的意思不搭。"}], "explanations": {"实用": "实用：有实际使用价值，与句中“减少废弃物”“提供肥料”的功能相符。", "华丽": "体貌：“华丽”形容外观繁复漂亮，堆肥项目看的是功能，不看外观。", "深奥": "语义：“深奥”指内容难懂，与“自己动手”的简单项目相矛盾。", "昂贵": "搭配：“昂贵”说价格高，与“自己动手”省钱的意思不搭。"}, "sentence_index": 0, "correct_answer": "实用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的价钱很实用，我们每个月都来。", "explanation": "这里应该用〈实惠〉。实用说东西有使用价值，说价钱划算要用“实惠”。"}, {"text": "这部电影很实用，看得我热泪盈眶。", "explanation": "这里应该用〈感人〉。实用说东西有使用价值，电影打动人心要用“感人”来评价。"}, {"text": "这首歌很实用，我每天都听。", "explanation": "这里应该用〈动听〉。实用说东西有使用价值，歌曲好听要用“动听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有使用价值，“又大又实用”是在评价桌子的使用价值。"}, {"text": "小巧", "is_correct": false, "explanation": "语义：“小巧”与前面的“又大”相矛盾。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指不耐用，与“我很满意”的评价不符。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：“破旧”指陈旧损坏，与“我很满意”的评价相矛盾。"}], "explanations": {"实用": "实用：有使用价值，“又大又实用”是在评价桌子的使用价值。", "小巧": "语义：“小巧”与前面的“又大”相矛盾。", "脆弱": "语义：“脆弱”指不耐用，与“我很满意”的评价不符。", "破旧": "语义：“破旧”指陈旧损坏，与“我很满意”的评价相矛盾。"}, "sentence_index": 6, "correct_answer": "实用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个笑话很实用，大家都笑了。", "explanation": "这里应该用〈好笑〉。笑话的好坏用“好笑”来评价，实用说的是东西的使用价值。"}, {"text": "这首诗很实用，读起来很有味道。", "explanation": "这里应该用〈优美〉。诗的美感要用“优美”来评价，实用不用来形容文学作品。"}, {"text": "这场比赛很实用，大家看得很激动。", "explanation": "这里应该用〈精彩〉。比赛的好看程度要用“精彩”来评价，实用不用来形容比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞很实用性，我天天用。", "corrected_sentence": "这把伞很实用，我天天用。", "error_description": "错误：“实用性”；正确：“实用”。“实用性”是名词，不能直接受程度副词“很”修饰，形容词应说“很实用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工具有实用，大家都爱用。", "corrected_sentence": "这个工具很实用，大家都爱用。", "error_description": "错误：“有实用”；正确：“很实用”。“实用”是形容词，前面要用“很”这类程度副词，“有”后面应接名词，如“有实用价值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
