INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "提取精华或使用后剩下的废物或残余物。", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa˥", "syllable_count": 1, "sentences": [{"text": "很多人把厨房里的菜叶、果皮、咖啡渣等有机垃圾扔进垃圾桶，其实这些都可以变成有用的堆肥。", "target_word": "渣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "榨完果汁以后，杯子里还剩下一些渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豆浆做好了，把渣放在一边。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种油很干净，里面没有渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤里有渣，请用筷子夹出来。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "药熬好了，把汁倒出来，渣不要。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煮完中药，锅底剩下很多渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做豆腐时，豆浆和渣要分开。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过滤以后，水里的渣就少了。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用这块布，可以把汤里的渣滤掉。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "药渣", "label": "复合"}, {"form": "豆渣", "label": "复合"}], "register": "中性", "sense_fingerprint": "榨取、熬煮、过滤之后剩下的残余物，如果渣、药渣、豆渣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11397, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指提取或使用后剩下的残余物。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“爆炸”。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}], "explanations": {"渣": "正确。渣（zhā）指提取或使用后剩下的残余物。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，意思是“爆炸”。", "叉": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。", "张": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。", "遮": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。“咖啡渣”指冲泡后剩下的残渣，属于可以堆肥的有机垃圾。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“咖啡书”不成词，书本也不是冲泡或榨取后剩下的有机垃圾，句意不通。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子是器皿，不属于有机垃圾。"}, {"text": "味", "is_correct": false, "explanation": "搭配：“咖啡味”是气味，不能作为被扔掉的具体物品。"}], "explanations": {"渣": "正确。“咖啡渣”指冲泡后剩下的残渣，属于可以堆肥的有机垃圾。", "书": "搭配：“咖啡书”不成词，书本也不是冲泡或榨取后剩下的有机垃圾，句意不通。", "杯": "语义：杯子是器皿，不属于有机垃圾。", "味": "搭配：“咖啡味”是气味，不能作为被扔掉的具体物品。"}, "sentence_index": 0, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯汽水的渣特别多。", "explanation": "这里应该用〈泡沫〉。渣是提取或使用后剩下的残余，汽水表面的气泡要说“泡沫”，不能说“渣”。"}, {"text": "中药熬好后，最珍贵的是渣。", "explanation": "这里应该用〈精华〉。渣是提取后剩下的废物，被提取出来、最珍贵的是精华，不能说渣最珍贵。"}, {"text": "这碗汤的渣很鲜。", "explanation": "这里应该用〈汤〉。渣指提取或使用后剩下的残余，有鲜味的汤汁不能说成“渣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11397, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指提取或使用后剩下的残余物。"}, {"text": "榨", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}], "explanations": {"渣": "正确。渣（zhā）指提取或使用后剩下的残余物。", "榨": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。", "插": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。", "章": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。煮药后锅底剩下的是药材的残余，用“渣”正合语境。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：煮中药后锅底剩下的不会是可以喝的饮料。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是加工原料，与煮药后的残余物不相符。"}, {"text": "药片", "is_correct": false, "explanation": "搭配：煮完的中药已成汤汁和残余，不会以“药片”的完整形态留在锅底。"}], "explanations": {"渣": "正确。煮药后锅底剩下的是药材的残余，用“渣”正合语境。", "饮料": "语义：煮中药后锅底剩下的不会是可以喝的饮料。", "面粉": "语义：面粉是加工原料，与煮药后的残余物不相符。", "药片": "搭配：煮完的中药已成汤汁和残余，不会以“药片”的完整形态留在锅底。"}, "sentence_index": 6, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "碗底还剩一朵渣。", "explanation": "这里应该用〈点〉。“朵”用于花朵、云朵等，渣不能用“朵”计量。"}, {"text": "锅底还剩一只渣。", "explanation": "这里应该用〈点〉。“只”多用于动物或成对的物品，渣是细碎的残余，不用“只”来计量。"}, {"text": "碗底还剩一条渣。", "explanation": "这里应该用〈点〉。“条”用于细长的物品，渣不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "药罐里还剩下一个渣。", "corrected_sentence": "药罐里还剩下一点渣。", "error_description": "错误形式：“一个渣”；正确形式：“一点渣”。“渣”是细碎的残余，应用量词“点”计量，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煮完中药，锅底剩下渣要倒掉。", "corrected_sentence": "煮完中药，锅底剩下的渣要倒掉。", "error_description": "错误形式：“锅底剩下渣”；正确形式：“锅底剩下的渣”。“剩下”作定语修饰“渣”时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将物体用力投入某个空间内部", "primary_collocate": null, "pronunciation": "rēng jìn", "ipa": "ɻəŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "很多人把厨房里的菜叶、果皮、咖啡渣等有机垃圾扔进垃圾桶，其实这些都可以变成有用的堆肥。", "target_word": "扔进", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把空瓶子扔进了垃圾桶。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把球扔进了水里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用过的纸巾扔进垃圾桶。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧鞋子扔进箱子里，准备送人。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地把书扔进包里，走出了教室。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具都扔进了盒子里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把硬币扔进河里，许了一个愿。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把脏衣服扔进洗衣机，开始洗。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力把石头扔进了湖里。", "target_word": "扔进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔进去", "label": "趋向补语"}, {"form": "扔进来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "用力把物体投入某空间内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔进", "is_correct": true, "explanation": "扔进：用力把东西投入某处，与句中“把有机垃圾……扔进垃圾桶”相符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”指把东西珍藏起来，不说把垃圾收藏进垃圾桶。"}, {"text": "倒掉", "is_correct": false, "explanation": "配价：“倒掉”后不带处所宾语，不能说倒掉垃圾桶。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”指留存，与句中“变成有用的堆肥”的处理方式相反。"}], "explanations": {"扔进": "扔进：用力把东西投入某处，与句中“把有机垃圾……扔进垃圾桶”相符。", "收藏": "搭配：“收藏”指把东西珍藏起来，不说把垃圾收藏进垃圾桶。", "倒掉": "配价：“倒掉”后不带处所宾语，不能说倒掉垃圾桶。", "保存": "语义：“保存”指留存，与句中“变成有用的堆肥”的处理方式相反。"}, "sentence_index": 0, "correct_answer": "扔进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈轻轻地把饼干扔进了盒子里。", "explanation": "这里应该用〈放进〉。扔进表示用力投入，与“轻轻地”矛盾，放置东西要用“放进”。"}, {"text": "他小心地把毛巾扔进了包里，怕压坏了衣服。", "explanation": "这里应该用〈塞进〉。扔进强调用力抛投，与“小心地”不符，把东西塞入时要用“塞进”。"}, {"text": "他把照片整整齐齐地扔进了相册，一张也没弄坏。", "explanation": "这里应该用〈夹进〉。扔进表示用力投掷，与“整整齐齐”“一张也没弄坏”矛盾，照片要夹入相册应用“夹进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔进", "is_correct": true, "explanation": "扔进：用力投入某个空间内部，与“弟弟把玩具都……了盒子里”相符。"}, {"text": "拿出", "is_correct": false, "explanation": "语义：“拿出”表示从里面取出，与“盒子里”的位置相反。"}, {"text": "玩", "is_correct": false, "explanation": "配价：“玩”不带表示去向的“盒子里”这样的处所宾语，不能说玩了盒子里。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉”指抛弃，与“盒子里”的存放义相矛盾。"}], "explanations": {"扔进": "扔进：用力投入某个空间内部，与“弟弟把玩具都……了盒子里”相符。", "拿出": "语义：“拿出”表示从里面取出，与“盒子里”的位置相反。", "玩": "配价：“玩”不带表示去向的“盒子里”这样的处所宾语，不能说玩了盒子里。", "丢掉": "语义：“丢掉”指抛弃，与“盒子里”的存放义相矛盾。"}, "sentence_index": 6, "correct_answer": "扔进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他慢慢地把牛奶扔进了杯子里。", "explanation": "这里应该用〈倒进〉。扔进表示用力抛投，牛奶这类液体要用“倒进”，且与“慢慢地”矛盾。"}, {"text": "我把钥匙扔进了锁孔。", "explanation": "这里应该用〈插进〉。扔进是抛投，钥匙插入锁孔要用“插进”。"}, {"text": "他把汽油扔进了油箱，怕溢出来。", "explanation": "这里应该用〈灌进〉。把液体装入容器要用“灌进”，扔进不适用于汽油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把信扔进着邮筒。", "corrected_sentence": "她把信扔进了邮筒。", "error_description": "错误：“扔进着”；正确：“扔进了”。“着”表示持续的状态，这里是一次完成的动作，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把石头被扔进湖里，溅起了水花。", "corrected_sentence": "他把石头扔进湖里，溅起了水花。", "error_description": "错误：“把”与“被”叠用；正确：只用“把”，即“他把石头扔进湖里”。“把”字句与“被”字句不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
