INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11399, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来装废弃物的容器，通常放在家里或街上。", "primary_collocate": null, "pronunciation": "lā jī tǒng", "ipa": "la˥ tɕi˥ tʰʊŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "很多人把厨房里的菜叶、果皮、咖啡渣等有机垃圾扔进垃圾桶，其实这些都可以变成有用的堆肥。", "target_word": "垃圾桶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "看到这个标志，就把可回收的东西放在蓝颜色的垃圾桶里。", "target_word": "垃圾桶", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "厨房的门后面有一个垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把空瓶子扔进垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "街上每隔几十米就有一个垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾桶满了，我去倒一下。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的垃圾桶放在门口。", "target_word": "垃圾桶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子把纸团扔到了垃圾桶里。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公园里找了很久，才找到垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天垃圾桶有点臭，要常常洗。", "target_word": "垃圾桶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "家里或街上用来装垃圾的桶形容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11399, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾桶", "is_correct": true, "explanation": "正确。垃圾桶是盛放废弃物的容器，与“有机垃圾”和“扔”的语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是用来冷藏食物的电器，不是盛放废弃物的容器，与句中的“有机垃圾”不符。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包用来装钱和证件，不装菜叶和果皮，与句意冲突。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包用来装书本，装菜叶、果皮这类有机垃圾并不合适，它也不是盛放废弃物的容器。"}], "explanations": {"垃圾桶": "正确。垃圾桶是盛放废弃物的容器，与“有机垃圾”和“扔”的语境相符。", "冰箱": "语义：冰箱是用来冷藏食物的电器，不是盛放废弃物的容器，与句中的“有机垃圾”不符。", "钱包": "语义：钱包用来装钱和证件，不装菜叶和果皮，与句意冲突。", "书包": "语义：书包用来装书本，装菜叶、果皮这类有机垃圾并不合适，它也不是盛放废弃物的容器。"}, "sentence_index": 0, "correct_answer": "垃圾桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "垃圾车到了，垃圾桶把垃圾收走了。", "explanation": "这里应该用〈环卫工人〉。收走垃圾要靠人或垃圾车，垃圾桶只是盛放垃圾的容器，不会自己把垃圾收走。"}, {"text": "洗好的碗放进垃圾桶沥干。", "explanation": "这里应该用〈水槽〉。沥干要靠能排水的水槽，垃圾桶不能用来沥干碗。"}, {"text": "妈妈把买来的菜放进垃圾桶保鲜。", "explanation": "这里应该用〈冰箱〉。保鲜要靠能降温的冰箱，垃圾桶不能保存食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾桶", "is_correct": true, "explanation": "正确。“我家的”后接放在门口的容器，垃圾桶符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天上的天体，不能被放在门口，与句意不合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天上的天体，不能被放在门口，与句意不合。"}, {"text": "海洋", "is_correct": false, "explanation": "配价：“放”要求可以搬动的物体作宾语，海洋无法放在门口。"}], "explanations": {"垃圾桶": "正确。“我家的”后接放在门口的容器，垃圾桶符合句意。", "月亮": "语义：月亮是天上的天体，不能被放在门口，与句意不合。", "太阳": "语义：太阳是天上的天体，不能被放在门口，与句意不合。", "海洋": "配价：“放”要求可以搬动的物体作宾语，海洋无法放在门口。"}, "sentence_index": 6, "correct_answer": "垃圾桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里新摆了一块垃圾桶。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，垃圾桶是有整体形状的容器，量词用“个”。"}, {"text": "我们新买了一辆垃圾桶，放在门口。", "explanation": "这里应该用〈个〉。“辆”用于车辆，垃圾桶不是车，量词用“个”。"}, {"text": "他一下子买了一双垃圾桶。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，垃圾桶是单个的容器，量词用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台上放着一张垃圾桶。", "corrected_sentence": "阳台上放着一个垃圾桶。", "error_description": "量词错误：“张”用于平面的东西，垃圾桶是立体的容器，应说“一个垃圾桶”，不能说“一张垃圾桶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口有一垃圾桶。", "corrected_sentence": "门口有一个垃圾桶。", "error_description": "错误形式：“一垃圾桶”；正确形式：“一个垃圾桶”。数词“一”后面接名词时要带量词，“垃圾桶”要说“一个垃圾桶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
