INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11403, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体带有盖子，能够封闭。", "primary_collocate": null, "pronunciation": "yǒu gài", "ipa": "joʊ˨˩˦ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "首先，准备一个有盖的塑料箱，放在阳台或院子角落。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "买垃圾桶要选有盖的，这样不会有味道。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个有盖的饭盒。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有盖的锅能让热气留在里面。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时，有盖的箱子能保护里面的书。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "野餐时最好用有盖的饭盒，汤就不容易洒出来。", "target_word": "有盖", "complexity_tier": "T3", "furigana": "yě cān shí zuì hǎo yòng yǒu gài de fàn hé, tāng jiù bù róng yì sǎ chū lái.", "sentence_source": "generated"}, {"text": "实验用的瓶子一定要有盖，不然会进灰。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有盖的碗可以直接放进冰箱，不怕串味。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种有盖的杯子，放在包里也不会漏水。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的水杯最好是有盖的，喝水时不容易洒。", "target_word": "有盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有盖：物体带盖子、可封闭（多作定语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有盖", "is_correct": true, "explanation": "正确：“有盖”说箱子带有盖子，与“准备一个有盖的塑料箱”的语境相符。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音或环境，塑料箱不能说嘈杂。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不用来形容箱子。"}, {"text": "无声", "is_correct": false, "explanation": "搭配：“无声”多形容声音或场景，不与“塑料箱”搭配，句子意思不通。"}], "explanations": {"有盖": "正确：“有盖”说箱子带有盖子，与“准备一个有盖的塑料箱”的语境相符。", "嘈杂": "语义：“嘈杂”形容声音或环境，塑料箱不能说嘈杂。", "苗条": "体貌：“苗条”形容人的身材，不用来形容箱子。", "无声": "搭配：“无声”多形容声音或场景，不与“塑料箱”搭配，句子意思不通。"}, "sentence_index": 0, "correct_answer": "有盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台台灯有盖，光线很柔和。", "explanation": "这里应该用〈灯罩〉。“有盖”指容器带有盖子，台灯的遮光部分要说“灯罩”。"}, {"text": "这把刀有盖，携带很安全。", "explanation": "这里应该用〈刀鞘〉。“有盖”用于能封闭的容器，刀的护套要说“刀鞘”。"}, {"text": "这个书架有盖，灰尘进不去。", "explanation": "这里应该用〈有门〉。“有盖”指容器的盖子，书架的柜门要说“有门”，书架本身没有盖，不能说有盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有盖", "is_correct": true, "explanation": "正确：实验用的瓶子要“有盖”，才能“不然会进灰”，语义连贯。"}, {"text": "敞开", "is_correct": false, "explanation": "语义：瓶口敞开，灰就会进去，与后半句“不然会进灰”的要求相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”与防灰无关，与“不然会进灰”的逻辑不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的体态，瓶子不说瘦。"}], "explanations": {"有盖": "正确：实验用的瓶子要“有盖”，才能“不然会进灰”，语义连贯。", "敞开": "语义：瓶口敞开，灰就会进去，与后半句“不然会进灰”的要求相反。", "漂亮": "语义：“漂亮”与防灰无关，与“不然会进灰”的逻辑不通。", "瘦": "体貌：“瘦”形容人或动物的体态，瓶子不说瘦。"}, "sentence_index": 6, "correct_answer": "有盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服有盖，穿着很暖和。", "explanation": "这里应该用〈有帽子〉。“有盖”指器物的盖子，衣服上的帽子要说“有帽子”。"}, {"text": "这只螃蟹有盖，不怕敌人。", "explanation": "这里应该用〈有壳〉。“有盖”用于容器，螃蟹背上的硬壳要说“有壳”。"}, {"text": "这扇门有盖，晚上很安全。", "explanation": "这里应该用〈门闩〉。“有盖”指容器的盖子，门的插销要说“门闩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一个有盖的了水壶。", "corrected_sentence": "我昨天买了一个有盖的水壶。", "error_description": "“了”位置错误：“了”插在定语“有盖的”和中心语“水壶”之间，不能放在“的”字结构中间。应去掉“了”，说“有盖的水壶”，量词“个”不变。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个保温杯很有盖，携带时不容易洒。", "corrected_sentence": "这个保温杯有盖，携带时不容易洒。", "error_description": "程度副词误用：“有盖”表示有没有盖子，是非等级的说法，不能受“很”修饰。应删去“很”，说“有盖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
