INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料箱是一种由塑料材料制成的容器，通常用于储存或运输物品。", "primary_collocate": null, "pronunciation": "sù liào xiāng", "ipa": "su˥˩ liɑʊ˥˩ ɕiɑŋ˥", "syllable_count": 3, "sentences": [{"text": "首先，准备一个有盖的塑料箱，放在阳台或院子角落。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我用塑料箱装冬天的衣服。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料箱很轻，一个人能搬。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料箱放在床下面，不占地方。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，我们买了五个塑料箱。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料箱里装满了孩子的玩具。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透明的塑料箱，一眼就能看到里面的东西。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果店用塑料箱运苹果。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鞋子放进塑料箱，再盖好盖子。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料箱坏了，不能再装重东西了。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来储存或运输物品的塑料容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料箱", "is_correct": true, "explanation": "正确。“有盖的”修饰箱子，塑料箱符合句意，可以放在阳台或院子角落。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，没有盖子，不能说“有盖的地毯”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“有盖的”一般修饰箱、罐、盒，不修饰书包。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是坐具，没有盖子，不能当作有盖的容器放在阳台上。"}], "explanations": {"塑料箱": "正确。“有盖的”修饰箱子，塑料箱符合句意，可以放在阳台或院子角落。", "地毯": "语义：地毯是铺在地上的织物，没有盖子，不能说“有盖的地毯”。", "书包": "搭配：“有盖的”一般修饰箱、罐、盒，不修饰书包。", "沙发": "语义：沙发是坐具，没有盖子，不能当作有盖的容器放在阳台上。"}, "sentence_index": 0, "correct_answer": "塑料箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把面包放进塑料箱烤。", "explanation": "这里应该用〈烤箱〉。烤东西要用能加热的烤箱，塑料箱受热会变形，不能用来烤面包。"}, {"text": "把书装进塑料箱背去学校。", "explanation": "这里应该用〈书包〉。背在身上要用有背带的书包，塑料箱没有背带，不能背去学校。"}, {"text": "把菜倒进塑料箱里炒。", "explanation": "这里应该用〈锅〉。炒菜要用能加热的锅，塑料箱不能用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料箱", "is_correct": true, "explanation": "正确。塑料箱可以是透明的，且能让人一眼看到里面的东西，符合句意。"}, {"text": "木箱", "is_correct": false, "explanation": "体貌：木箱不透明，不能说“透明的木箱”，与句中的“透明的”矛盾。"}, {"text": "纸箱", "is_correct": false, "explanation": "体貌：纸箱不透明，不能说“透明的纸箱”，与句中的“透明的”矛盾。"}, {"text": "铁桶", "is_correct": false, "explanation": "语义：铁是不透明的金属，铁桶不可能是透明的，也看不到里面的东西。"}], "explanations": {"塑料箱": "正确。塑料箱可以是透明的，且能让人一眼看到里面的东西，符合句意。", "木箱": "体貌：木箱不透明，不能说“透明的木箱”，与句中的“透明的”矛盾。", "纸箱": "体貌：纸箱不透明，不能说“透明的纸箱”，与句中的“透明的”矛盾。", "铁桶": "语义：铁是不透明的金属，铁桶不可能是透明的，也看不到里面的东西。"}, "sentence_index": 6, "correct_answer": "塑料箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一双塑料箱，一个放客厅，一个放卧室。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，塑料箱是单个的容器，量词用“个”。"}, {"text": "我在超市买了一辆塑料箱。", "explanation": "这里应该用〈个〉。“辆”用于车辆，塑料箱不是车，量词用“个”。"}, {"text": "他帮我搬来一块塑料箱。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，塑料箱是有整体形状的容器，量词用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "床下有一块塑料箱。", "corrected_sentence": "床下有一个塑料箱。", "error_description": "量词错误：“块”用于块状的东西，塑料箱是有整体形状的容器，应说“一个塑料箱”，不能说“一块塑料箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客厅角落放着一个塑料箱们。", "corrected_sentence": "客厅角落放着一个塑料箱。", "error_description": "词尾错误：“们”表示复数，只用于人，塑料箱是物，应说“一个塑料箱”，不能说“塑料箱们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
