INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指两堵墙或类似物体相交的地方，也比喻偏僻或隐蔽的地方。", "primary_collocate": null, "pronunciation": "jiǎo luò", "ipa": "tɕjɑʊ˨˩˦ lwo˥˩", "syllable_count": 2, "sentences": [{"text": "首先，准备一个有盖的塑料箱，放在阳台或院子角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "首先，准备一个有盖子的大塑料桶，放在阳台或厨房外的角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小猫躲在房间的角落里。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在教室的角落，一句话也不说。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "角落里有一把旧椅子。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把扫把放在门后的角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光太暗，我看不清角落里的东西。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店在城市的一个安静角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的灰尘都在角落里。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李推到角落，给我们让路。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "墙或物体相交的地方，也指偏僻隐蔽的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "角落", "is_correct": true, "explanation": "正确。角落指墙相交或隐蔽的地方，放在阳台或院子的角落里符合前文的位置。"}, {"text": "室内", "is_correct": false, "explanation": "语义：“室内”指房屋里面，与前文“阳台或院子”的室外位置相反。"}, {"text": "海边", "is_correct": false, "explanation": "语义：“海边”与“阳台或院子”的家中位置不符，前文并未提到海边。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“阳台或院子”之后要接表示位置的词，“垃圾桶”是物品，不能表示放置的位置。"}], "explanations": {"角落": "正确。角落指墙相交或隐蔽的地方，放在阳台或院子的角落里符合前文的位置。", "室内": "语义：“室内”指房屋里面，与前文“阳台或院子”的室外位置相反。", "海边": "语义：“海边”与“阳台或院子”的家中位置不符，前文并未提到海边。", "垃圾桶": "搭配：“阳台或院子”之后要接表示位置的词，“垃圾桶”是物品，不能表示放置的位置。"}, "sentence_index": 0, "correct_answer": "角落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电影里演一个重要的角落。", "explanation": "这里应该用〈角色〉。角落指墙相交的地方或偏僻隐蔽的处所，演员扮演的是角色，两词都带“角”字，容易混淆。"}, {"text": "我们从不同的角落看这个问题。", "explanation": "这里应该用〈角度〉。从不同方面看问题要说角度，角落只指空间中的墙角或隐蔽处。"}, {"text": "这次会议的角落是成本控制。", "explanation": "这里应该用〈重点〉。角落不指事情的核心内容，说会议的核心要用重点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "角落", "is_correct": true, "explanation": "正确。角落里光线暗，正好与“看不清角落里的东西”相符。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：“阳光”是白天的自然光，与前文“灯光太暗”矛盾。"}, {"text": "白天", "is_correct": false, "explanation": "语义：“白天”是时间，不是能装东西的处所，“白天里的东西”与前文的语境冲突。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“工作”不是可以放东西的地方，不能与“里”组成处所短语，“工作里的东西”搭配不当。"}], "explanations": {"角落": "正确。角落里光线暗，正好与“看不清角落里的东西”相符。", "阳光": "语义：“阳光”是白天的自然光，与前文“灯光太暗”矛盾。", "白天": "语义：“白天”是时间，不是能装东西的处所，“白天里的东西”与前文的语境冲突。", "工作": "搭配：“工作”不是可以放东西的地方，不能与“里”组成处所短语，“工作里的东西”搭配不当。"}, "sentence_index": 6, "correct_answer": "角落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家客厅里有一条角落，堆着旧报纸。", "explanation": "这里应该用〈个〉。角落的量词是“个”，“条”用于长条形的东西，不能用来修饰角落。"}, {"text": "走廊尽头有一把角落，放着一个小箱子。", "explanation": "这里应该用〈个〉来修饰“角落”。“把”用于有柄的器具，不能用来计量角落；句末“一个小箱子”中的“个”修饰的是箱子，与此无关。"}, {"text": "阳台上有一只角落，摆着几盆花。", "explanation": "这里应该用〈个〉。“只”用于动物或成对物件中的一个，角落不用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卧室的一只角落里放着一把伞。", "corrected_sentence": "卧室的一个角落里放着一把伞。", "error_description": "错误：“角落”的量词用了“只”。正确应为“个”，“只”用于动物或成对物件中的一个，不能修饰角落。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把行李推到一角落里，给我们让路。", "corrected_sentence": "他把行李推到一个角落里，给我们让路。", "error_description": "错误：“一角落”缺少量词。正确应为“一个角落”，“角落”前有数词时须加量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
