INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在物体上制造孔洞，通常使用工具", "primary_collocate": null, "pronunciation": "dǎ", "ipa": "tɑ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他用电钻在墙上打孔。", "target_word": "打", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想在皮带上打一个孔。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她昨天去店里打了耳洞。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鼠在墙角打了一个洞。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅用钻头在木板上打了两个孔。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要先在纸上打孔，再用绳子穿起来。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙太硬了，打孔很费力。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我在这张卡片上打个孔。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民在院子里打了一口井。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在墙上打过孔，知道墙很硬。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了", "label": "体标（了）"}, {"form": "打过", "label": "体标（过）"}, {"form": "打孔", "label": "复合"}, {"form": "打洞", "label": "复合"}, {"form": "打井", "label": "复合"}], "register": "中性", "sense_fingerprint": "打：在物体上钻出、凿出孔洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 纸上 (Zipf 3.2), 再用 (Zipf 3.69), 绳子 (Zipf 3.86)']::text[], 'bcd5bd62-667b-408b-99e4-5d930ae38128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示在物体上制造孔洞。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“回答”。"}, {"text": "搭", "is_correct": false, "explanation": "dā（第一声）与 dǎ 声调不同，意思是“搭建”。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}], "explanations": {"打": "正确：打（dǎ），表示在物体上制造孔洞。", "大": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。", "答": "dá（第二声）与 dǎ 声调不同，意思是“回答”。", "搭": "dā（第一声）与 dǎ 声调不同，意思是“搭建”。", "胆": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“打孔”指在墙上钻出孔洞，与“电钻”搭配自然。"}, {"text": "煮", "is_correct": false, "explanation": "语义：用电钻在墙上钻孔与“煮”无关，句意不通。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”要用剪刀等工具，不能用电钻剪孔。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”要用针线，与电钻不搭配。"}], "explanations": {"打": "正确：“打孔”指在墙上钻出孔洞，与“电钻”搭配自然。", "煮": "语义：用电钻在墙上钻孔与“煮”无关，句意不通。", "剪": "搭配：“剪”要用剪刀等工具，不能用电钻剪孔。", "缝": "搭配：“缝”要用针线，与电钻不搭配。"}, "sentence_index": 0, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力打鼓，鼓声很大。", "explanation": "这里“打”是敲击的意思，不表示在物体上制造孔洞。"}, {"text": "她晚上给朋友打电话，聊了很久。", "explanation": "这里“打”表示拨打电话，不表示制造孔洞。"}, {"text": "早饭时妈妈打了两个鸡蛋。", "explanation": "这里“打”表示搅拌（鸡蛋），不表示在物体上制造孔洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11408, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示在物体上制造孔洞。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把”。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“到达”。"}, {"text": "拿", "is_correct": false, "explanation": "ná 与 dǎ 声母不同（n 与 d），声调也不同，意思是“拿”。"}], "explanations": {"打": "正确：打（dǎ），表示在物体上制造孔洞。", "把": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把”。", "哪": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。", "达": "dá（第二声）与 dǎ 声调不同，意思是“到达”。", "拿": "ná 与 dǎ 声母不同（n 与 d），声调也不同，意思是“拿”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“打孔”指在墙上钻出孔洞，与“墙太硬”的情境相符。"}, {"text": "绣", "is_correct": false, "explanation": "语义：“绣”是刺绣，墙太硬时不能用来形容在墙上做孔。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于线、布等材料，不说“织墙上的孔”。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，与墙上的孔洞无关。"}], "explanations": {"打": "正确：“打孔”指在墙上钻出孔洞，与“墙太硬”的情境相符。", "绣": "语义：“绣”是刺绣，墙太硬时不能用来形容在墙上做孔。", "织": "搭配：“织”用于线、布等材料，不说“织墙上的孔”。", "煎": "语义：“煎”指用油加热食物，与墙上的孔洞无关。"}, "sentence_index": 6, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忍不住打了一个喷嚏。", "explanation": "这里“打”表示发出（喷嚏），不表示在物体上制造孔洞。"}, {"text": "他很生气，狠狠打了一下桌子。", "explanation": "这里“打”表示拍击，不表示制造孔洞。"}, {"text": "护士给病人打了一针。", "explanation": "这里“打”表示注射，与制造孔洞无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用电钻把墙穿打了。", "corrected_sentence": "工人用电钻把墙打穿了。", "error_description": "位置错误：结果补语“穿”应紧跟动词“打”，应说“打穿了”，不能说“穿打了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人在门板上打了三只孔。", "corrected_sentence": "工人在门板上打了三个孔。", "error_description": "量词错误：“孔”应用量词“个”，“只”用于动物等，不能用于“孔”，应说“打了三个孔”，不能说“打了三只孔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
