INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体上较小的孔洞或开口。", "primary_collocate": null, "pronunciation": "xiǎo kǒng", "ipa": "ɕjɑʊ̯˨˩˦ kʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "箱底要打几个小孔，方便排水和透气。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "在箱子的底部和侧面扎一些小孔。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "盖子上有一个小孔，空气可以进去。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用针在纸上扎了一个小孔。", "target_word": "小孔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳光从墙上的小孔里照了进来。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶盖上有几个小孔，水会慢慢流出来。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠在木板上咬出了一个小孔。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子上有个小孔，米一直往外漏。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在塑料盒上钻几个小孔。", "target_word": "小孔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球上有一个小孔，气慢慢跑光了。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "物体上较小的孔洞或开口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孔", "is_correct": true, "explanation": "小孔：指物体上的小洞，箱底打出小孔才能排水透气，符合句意。"}, {"text": "盖子", "is_correct": false, "explanation": "语义：盖子是用来遮盖容器的，不能在上面打出用于排水透气的孔。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“打”通常不与“窗户”搭配，此处开窗户应说“开”。"}, {"text": "图案", "is_correct": false, "explanation": "语义：图案是图形，不是能排水透气的孔洞，句意不通。"}], "explanations": {"小孔": "小孔：指物体上的小洞，箱底打出小孔才能排水透气，符合句意。", "盖子": "语义：盖子是用来遮盖容器的，不能在上面打出用于排水透气的孔。", "窗户": "搭配：“打”通常不与“窗户”搭配，此处开窗户应说“开”。", "图案": "语义：图案是图形，不是能排水透气的孔洞，句意不通。"}, "sentence_index": 0, "correct_answer": "小孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上有一条小孔，风从那里吹进来。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，小孔是点状的洞，要说“一个小孔”。"}, {"text": "这份方案有一个小孔，需要重新修改。", "explanation": "这里应该用〈漏洞〉。小孔指实物上的小洞，方案中的缺陷要说“漏洞”。"}, {"text": "他的话有很多小孔，大家都听出了问题。", "explanation": "这里应该用〈破绽〉。小孔指实物上的小洞，话语或论证中的缺陷要说“破绽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孔", "is_correct": true, "explanation": "小孔：老鼠咬出的洞就是小孔，符合句意。"}, {"text": "管道", "is_correct": false, "explanation": "语义：管道是中空的长条形管子，老鼠不能咬出一根管道。"}, {"text": "木箱", "is_correct": false, "explanation": "语义：木箱是盛放东西的器具，不可能被老鼠咬出来，句意说不通。"}, {"text": "门", "is_correct": false, "explanation": "搭配：量词“个”不与“门”搭配，门应说“扇”，“咬出了一个门”不成立。"}], "explanations": {"小孔": "小孔：老鼠咬出的洞就是小孔，符合句意。", "管道": "语义：管道是中空的长条形管子，老鼠不能咬出一根管道。", "木箱": "语义：木箱是盛放东西的器具，不可能被老鼠咬出来，句意说不通。", "门": "搭配：量词“个”不与“门”搭配，门应说“扇”，“咬出了一个门”不成立。"}, "sentence_index": 6, "correct_answer": "小孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌面上有一把小孔，灰尘都漏下去了。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，小孔不能用“把”来计量。"}, {"text": "他的手上被划了一个小孔，血一直在流。", "explanation": "这里应该用〈伤口〉。小孔指物体上的洞，身体受伤的地方要说“伤口”。"}, {"text": "他的生意亏了一个小孔，急需资金补上。", "explanation": "这里应该用〈窟窿〉。小孔指物体上的小洞，经济上的亏空要说“窟窿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子的底部有一条小孔。", "corrected_sentence": "这个盒子的底部有一个小孔。", "error_description": "量词错误：“小孔”是点状的洞，应说“一个小孔”，不能用“一条”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "铁桶的侧面有一个很小孔，水都漏光了。", "corrected_sentence": "铁桶的侧面有一个小孔，水都漏光了。", "error_description": "程度副词错误：“小孔”是名词，前面不能直接加“很”，此处应说“一个小孔”；“很小”后面要加“的”，写作“很小的孔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
