INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11410, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水排出去。", "primary_collocate": null, "pronunciation": "pái shuǐ", "ipa": "pʰaɪ̯˧˥ ʂweɪ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "箱底要打几个小孔，方便排水和透气。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "容器可以选用市售的多层发酵箱，也可以自制木质或塑料箱体，关键是箱底要能顺利排水，顶部还要配置可以开启的盖板，以便调控温湿度。", "target_word": "排水", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "下雨以后，路边的沟可以排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆底下要有孔，才能排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的水太多，我们得马上排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用机器给地下室排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨大的时候，下水道排水很慢。", "target_word": "排水", "complexity_tier": "T3", "furigana": "yǔ dà de shí hou, xià shuǐ dào pái shuǐ hěn màn.", "sentence_source": "generated"}, {"text": "厨房的水池不排水了，可能堵住了。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有个管子，专门用来排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地排水不好，下雨后总是有水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排了水", "label": "体标"}, {"form": "排过水", "label": "体标"}, {"form": "排水沟", "label": "复合"}], "register": "中性", "sense_fingerprint": "把积水或多余的水排出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11410, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水（pái shuǐ）指把水排出去，是正确答案。"}, {"text": "白水", "is_correct": false, "explanation": "bái（第二声）与 pái（第二声）声调相同，但声母由 p 变为 b，意思是白开水。"}, {"text": "抬水", "is_correct": false, "explanation": "tái（第二声）与 pái（第二声）声调相同，声母由 p 变为 t，意思是把水抬起来或挑水。"}, {"text": "拍水", "is_correct": false, "explanation": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打水面。"}], "explanations": {"排水": "排水（pái shuǐ）指把水排出去，是正确答案。", "白水": "bái（第二声）与 pái（第二声）声调相同，但声母由 p 变为 b，意思是白开水。", "抬水": "tái（第二声）与 pái（第二声）声调相同，声母由 p 变为 t，意思是把水抬起来或挑水。", "拍水": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打水面。"}, "sentence_index": null, "correct_answer": "排水"}, "level_3": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水：把水排出去，箱底的孔可以排水，符合句意。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印与“透气”无关，箱底的孔不是用来打印的。"}, {"text": "上色", "is_correct": false, "explanation": "语义：上色是涂颜色，与“透气”搭不上，句意不通。"}, {"text": "排泄", "is_correct": false, "explanation": "语域：“排泄”多指人或动物排出废物，用在箱子上不自然，且语域偏书面和医学。"}], "explanations": {"排水": "排水：把水排出去，箱底的孔可以排水，符合句意。", "打印": "语义：打印与“透气”无关，箱底的孔不是用来打印的。", "上色": "语义：上色是涂颜色，与“透气”搭不上，句意不通。", "排泄": "语域：“排泄”多指人或动物排出废物，用在箱子上不自然，且语域偏书面和医学。"}, "sentence_index": 0, "correct_answer": "排水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早上要先给花排水，再去上班。", "explanation": "这里应该用〈浇水〉。排水是把多余的水排出去，给植物补水要说“浇水”。"}, {"text": "夏天的马路上，洒水车在排水降温。", "explanation": "这里应该用〈洒水〉。排水是把水排走，洒水车是把水喷洒出去，应说“洒水”。"}, {"text": "杯子里的水快没了，你快去排水。", "explanation": "这里应该用〈加水〉。排水是把水排走，水少了要说“加水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水：把水排走，下水道排水很慢，符合句意。"}, {"text": "飞行", "is_correct": false, "explanation": "语义：下水道不能飞行，“飞行很慢”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：下水道不会散步，与句意不符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：下水道不会拍照，“拍照很慢”句意不通。"}], "explanations": {"排水": "排水：把水排走，下水道排水很慢，符合句意。", "飞行": "语义：下水道不能飞行，“飞行很慢”说不通。", "散步": "语义：下水道不会散步，与句意不符。", "拍照": "语义：下水道不会拍照，“拍照很慢”句意不通。"}, "sentence_index": 6, "correct_answer": "排水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个喷泉每天晚上都会排水表演，很多人来看。", "explanation": "这里应该用〈喷水〉。排水是把水排走，喷泉向上喷水表演要说“喷水”。"}, {"text": "他到井边排水，准备洗菜。", "explanation": "这里应该用〈打水〉。排水是把水排走，从井里取水要说“打水”。"}, {"text": "他拿着桶在河边排水，准备洗衣服。", "explanation": "这里应该用〈取水〉。排水是把水排走，到河边取水洗衣要说“取水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个池子排水得很快。", "corrected_sentence": "这个池子排水排得很快。", "error_description": "补语错误：“排水”是动宾结构，带“得”补语时要重复动词“排”，应说“排水排得很快”，不能说“排水得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个池子正在排过水。", "corrected_sentence": "这个池子正在排水。", "error_description": "体标错误：“正在”表示动作进行中，与表示曾经经历的“过”不能同用，应说“正在排水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
