INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11412, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西展开或平放。", "primary_collocate": null, "pronunciation": "pū", "ipa": "pʰu˥", "syllable_count": 1, "sentences": [{"text": "接着，在箱里先铺一层干树叶或撕碎的纸，再放厨余垃圾。", "target_word": "铺", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "妈妈把新床单铺在床上。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在草地上铺了一块布。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地图铺在桌子上看。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上铺着一张红地毯。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，先把床铺好。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在路上铺砖。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野餐时，我们先铺垫子再坐。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，地上铺满了落叶。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在桌上铺一张干净的纸。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "铺了", "label": "体标（完成）"}, {"form": "铺着", "label": "体标（持续）"}, {"form": "铺过", "label": "体标（经历）"}, {"form": "铺开", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西展开、平放在某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11412, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺（pū），意思是把东西展开或平放。"}, {"text": "普", "is_correct": false, "explanation": "普（pǔ）与 pū 声调不同（第三声），意思是普遍、普通，与展开平放无关。"}, {"text": "葡", "is_correct": false, "explanation": "葡（pú）与 pū 声调不同（第二声），常见于“葡萄”。"}, {"text": "批", "is_correct": false, "explanation": "批（pī）与 pū 的韵母不同（i 与 u），意思是批准或批评。"}, {"text": "趴", "is_correct": false, "explanation": "趴（pā）与 pū 的韵母不同（a 与 u），意思是身体伏在某物上。"}, {"text": "夫", "is_correct": false, "explanation": "夫（fū）与 pū 声母不同（f 与 p），意思是丈夫或成年男子。"}], "explanations": {"铺": "正确答案：铺（pū），意思是把东西展开或平放。", "普": "普（pǔ）与 pū 声调不同（第三声），意思是普遍、普通，与展开平放无关。", "葡": "葡（pú）与 pū 声调不同（第二声），常见于“葡萄”。", "批": "批（pī）与 pū 的韵母不同（i 与 u），意思是批准或批评。", "趴": "趴（pā）与 pū 的韵母不同（a 与 u），意思是身体伏在某物上。", "夫": "夫（fū）与 pū 声母不同（f 与 p），意思是丈夫或成年男子。"}, "sentence_index": null, "correct_answer": "铺"}, "level_3": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺。箱底先铺一层干树叶，指把材料展开成一层平面。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆指拆开、分解，箱里还没有东西可拆，句意不通。"}, {"text": "洒", "is_correct": false, "explanation": "搭配：洒多用于液体或细粉，不说洒一层干树叶。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：倒指把成堆的东西整体倾出，不能说倒成均匀的一层。"}], "explanations": {"铺": "正确答案：铺。箱底先铺一层干树叶，指把材料展开成一层平面。", "拆": "语义：拆指拆开、分解，箱里还没有东西可拆，句意不通。", "洒": "搭配：洒多用于液体或细粉，不说洒一层干树叶。", "倒": "搭配：倒指把成堆的东西整体倾出，不能说倒成均匀的一层。"}, "sentence_index": 0, "correct_answer": "铺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把茶杯铺在桌子上。", "explanation": "这里更自然的是〈摆〉。铺指把平面的东西展开平放，茶杯是立体的器物，不能展开成一片。"}, {"text": "他把钥匙铺在桌子上。", "explanation": "这里应该用〈放〉。钥匙体积小，不能展开成一片，应说放。"}, {"text": "他把帽子铺在墙上。", "explanation": "这里应该用〈挂〉。帽子不能展开平放在墙面上，挂在墙上要说挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11412, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺（pū），意思是把东西展开或平放。"}, {"text": "谱", "is_correct": false, "explanation": "谱（pǔ）与 pū 声调不同（第三声），意思是乐谱或图谱。"}, {"text": "朴", "is_correct": false, "explanation": "朴（pǔ）与 pū 声调不同（第三声），意思是朴素。"}, {"text": "脯", "is_correct": false, "explanation": "脯（pú）与 pū 声调不同（第二声），指胸脯，与展开平放无关。"}, {"text": "披", "is_correct": false, "explanation": "披（pī）与 pū 的韵母不同（i 与 u），意思是把衣物披在身上。"}], "explanations": {"铺": "正确答案：铺（pū），意思是把东西展开或平放。", "谱": "谱（pǔ）与 pū 声调不同（第三声），意思是乐谱或图谱。", "朴": "朴（pǔ）与 pū 声调不同（第三声），意思是朴素。", "脯": "脯（pú）与 pū 声调不同（第二声），指胸脯，与展开平放无关。", "披": "披（pī）与 pū 的韵母不同（i 与 u），意思是把衣物披在身上。"}, "sentence_index": null, "correct_answer": "铺"}, "level_3": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺。路上铺砖，指把砖一块块展开平放成路面。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧砖是在窑里加热制砖，不是在路面上进行，与“路上”矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔指抛掷，不能构成路面，与“路上”的铺设动作不符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃不能用于砖，“工人在路上吃砖”句意荒谬。"}], "explanations": {"铺": "正确答案：铺。路上铺砖，指把砖一块块展开平放成路面。", "烧": "语义：烧砖是在窑里加热制砖，不是在路面上进行，与“路上”矛盾。", "扔": "语义：扔指抛掷，不能构成路面，与“路上”的铺设动作不符。", "吃": "语义：吃不能用于砖，“工人在路上吃砖”句意荒谬。"}, "sentence_index": 6, "correct_answer": "铺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用抹布把玻璃窗铺干净了。", "explanation": "这里应该用〈擦〉。擦是用布摩擦、除去污物，玻璃窗弄干净要说擦；铺表示把东西展开平放，不能表示除去污物。"}, {"text": "他在日记本上铺了一段话。", "explanation": "这里应该用〈写〉。写是用笔记录文字，一段话要写；铺只表示把平面的东西展开平放，不能用于写字。"}, {"text": "他在台上铺完了一首歌。", "explanation": "这里应该用〈唱〉。唱是用声音表演歌曲，一首歌要唱；铺只表示展开平放，不能用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把桌布铺了开，准备吃饭。", "corrected_sentence": "妈妈把桌布铺开了，准备吃饭。", "error_description": "错误形式：铺了开；正确形式：铺开了。“开”是结果补语，“了”应放在补语之后，不能插在“铺”和“开”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客厅的地板上铺了着一块地毯。", "corrected_sentence": "客厅的地板上铺着一块地毯。", "error_description": "错误形式：铺了着；正确形式：铺着。“铺”后的“了”和“着”不能同时使用，表示状态持续只用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木的叶子，通常为绿色，是植物进行光合作用的主要器官。", "primary_collocate": null, "pronunciation": "shù yè", "ipa": "ʂu˥˩ je˥˩", "syllable_count": 2, "sentences": [{"text": "接着，在箱里先铺一层干树叶或撕碎的纸，再放厨余垃圾。", "target_word": "树叶", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "树叶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "秋天到了，树叶慢慢变黄了。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有很多黄色的树叶。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，树叶就落下来了。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子捡了一片红树叶回家。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，树上长出了绿色的小树叶。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟藏在树叶后面，我们看不见它。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把树叶扫成一堆。", "target_word": "树叶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨滴落在树叶上，发出轻轻的声音。", "target_word": "树叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "树木的叶子，光合作用的主要器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。树叶指树木的叶子。"}, {"text": "书页", "is_correct": false, "explanation": "shū yè（第一声）与 shù yè（第四声）声调不同，书页指书的页面。"}, {"text": "薯叶", "is_correct": false, "explanation": "shǔ yè（第三声）与 shù yè 声调不同，薯叶指红薯等植物的叶子。"}, {"text": "数月", "is_correct": false, "explanation": "shù yuè 与 shù yè 韵母不同（yuè 与 yè），意思是几个月。"}], "explanations": {"树叶": "正确。树叶指树木的叶子。", "书页": "shū yè（第一声）与 shù yè（第四声）声调不同，书页指书的页面。", "薯叶": "shǔ yè（第三声）与 shù yè 声调不同，薯叶指红薯等植物的叶子。", "数月": "shù yuè 与 shù yè 韵母不同（yuè 与 yè），意思是几个月。"}, "sentence_index": null, "correct_answer": "树叶"}, "level_3": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。“干树叶”与“撕碎的纸”并列，都是铺在箱里的干燥材料。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是干的有机材料，也不能像纸一样撕碎，与前面的并列结构不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“撕碎”一般用于纸、布等，不说撕碎玻璃，与“撕碎的纸”并列不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不能在堆肥箱里充当干燥材料，与“干”的描述相矛盾。"}], "explanations": {"树叶": "正确。“干树叶”与“撕碎的纸”并列，都是铺在箱里的干燥材料。", "石头": "语义：石头不是干的有机材料，也不能像纸一样撕碎，与前面的并列结构不符。", "玻璃": "搭配：“撕碎”一般用于纸、布等，不说撕碎玻璃，与“撕碎的纸”并列不通。", "钢铁": "语义：钢铁不能在堆肥箱里充当干燥材料，与“干”的描述相矛盾。"}, "sentence_index": 0, "correct_answer": "树叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋天的院子里落了一只树叶。", "explanation": "这里应该用〈片〉。树叶是薄片，量词用“片”，“只”不用于树叶。"}, {"text": "我们把树叶种在花园里。", "explanation": "这里应该用〈树苗〉。种下去的是树苗或种子，树叶不能种。"}, {"text": "这块木板很结实，是用树叶做成的。", "explanation": "这里应该用〈木头〉。木板是木材加工成的，树叶是薄片，做不成结实的木板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。树叶指树木的叶子。"}, {"text": "暑夜", "is_correct": false, "explanation": "shǔ yè（第三声）与 shù yè 声调不同，暑夜指夏天的夜晚。"}, {"text": "事业", "is_correct": false, "explanation": "shì yè 与 shù yè 韵母不同（i 与 u），意思是事业或职业。"}, {"text": "书业", "is_correct": false, "explanation": "shū yè（第一声）与 shù yè 声调不同，书业指图书出版行业。"}], "explanations": {"树叶": "正确。树叶指树木的叶子。", "暑夜": "shǔ yè（第三声）与 shù yè 声调不同，暑夜指夏天的夜晚。", "事业": "shì yè 与 shù yè 韵母不同（i 与 u），意思是事业或职业。", "书业": "shū yè（第一声）与 shù yè 声调不同，书业指图书出版行业。"}, "sentence_index": null, "correct_answer": "树叶"}, "level_3": {"options": [{"text": "树叶", "is_correct": true, "explanation": "正确。“树上长出了绿色的小树叶”，树叶是树上长出的绿色叶子。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花是白色的，不会在春天树上长出来，与“绿色”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会从树上长出来，与“长出了”的描述不符。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“长出”用于植物等，不能说长出皮鞋。"}], "explanations": {"树叶": "正确。“树上长出了绿色的小树叶”，树叶是树上长出的绿色叶子。", "雪花": "语义：雪花是白色的，不会在春天树上长出来，与“绿色”矛盾。", "石头": "语义：石头不会从树上长出来，与“长出了”的描述不符。", "皮鞋": "搭配：“长出”用于植物等，不能说长出皮鞋。"}, "sentence_index": 6, "correct_answer": "树叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的树叶又高又粗。", "explanation": "这里应该用〈树干〉。形容又高又粗的是树干或树身，树叶是薄片，不能这样形容。"}, {"text": "农民把那棵老树的树叶挖了出来。", "explanation": "这里应该用〈树根〉。挖出来的是埋在土里的根，树叶长在枝上，不能挖。"}, {"text": "这棵树的树叶很重，要用起重机才能吊起来。", "explanation": "这里应该用〈原木〉。被起重机吊起的是砍倒的原木，树叶轻薄，不能说很重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只树叶被风吹走了。", "corrected_sentence": "一片树叶被风吹走了。", "error_description": "量词错误：“树叶”应用量词“片”，写成“一只树叶”是错的，应为“一片树叶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把树叶扫了成一堆。", "corrected_sentence": "我们把树叶扫成了一堆。", "error_description": "了的位置错误：“扫成”是结果补语，“了”应放在补语后面，应为“扫成了一堆”，不能说“扫了成一堆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
