INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11415, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力使物体裂开或成为碎片。", "primary_collocate": null, "pronunciation": "sī suì", "ipa": "sɨ˥ suei˥˩", "syllable_count": 2, "sentences": [{"text": "接着，在箱里先铺一层干树叶或撕碎的纸，再放厨余垃圾。", "target_word": "撕碎", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "在桶里先放一层干的材料，比如落叶或撕碎的纸箱，这样可以防止味道太大。", "target_word": "撕碎", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他生气地把信撕碎了。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把我的拖鞋撕碎了。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些旧纸撕碎，再放进桶里。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看完那张照片，慢慢把它撕碎了。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撕碎了那张没用的车票。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把面包撕碎，喂给小鸟吃。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，别把书页撕碎。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把旧报纸撕碎，放进花盆里。", "target_word": "撕碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撕碎了", "label": "体标"}, {"form": "撕碎过", "label": "体标"}], "register": "中性", "sense_fingerprint": "撕碎：用力把纸、布等物体撕成碎片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
